import React, { useCallback, useMemo, useState, useEffect } from "react";
import { Button, Checkbox, Dropdown, Form, Menu } from 'antd';
import isArray from 'lodash/isArray';
import clone from 'lodash/clone'

import { LoaderMenuItem, MenuItemGroupWrapper } from "components/shared/GlobalFilter/components/CommonComponentsV2";
import FilterApi from "services/filterApi";
import { useQuery } from "react-query";
import useDebounce from 'hooks/useDebounce';
import { showOverflowItems } from "components/shared/GlobalFilter/components/utils";
import CellOverflowTooltip from "Utils/helpers/CellOverflowTooltip";
import { useSelector } from "react-redux";
import { useEventPropertySearchPayload } from "../hooks/useEventPropertySearchPayload";
import InputPropertiesValues from "./InputPropertiesValues";
import { MenuButton, MenuListItem, NotFoundMessage, StyledSpace } from "../Style";

const arrayObj = ['in', 'not_in'];

const PropertiesValueOptions = ({ name, handleApply, filterData }) => {
  const {
    screenRenamedList,
  } = useSelector((state) => state);

  // form data
  const form = Form.useFormInstance();
  const formData = Form.useWatch('eventProperties', form);
  const formDataIndex = useMemo(()=> name[1], [name])

  const formPropertyValue = useMemo(()=> formData?.[formDataIndex]?.['value'] ?? [], [formData, formDataIndex]) ;
  const formProperty = formData?.[formDataIndex]?.['json_field'] ?? '';
  const formOperatorValue = formData?.[formDataIndex]?.['operator'] ?? '';

  // local state
  const [searchInput, setSearchInput] = useState('');
  const debouncedSearchValue = useDebounce(searchInput, 500);
  const { filters } =  useMemo(()=> filterData || {}, [filterData]) ;

  const hasEventName = useMemo(()=> filters?.length && filters?.find(filter=> filter?.attribute === 'event_name'), [ filters]);
  const newFilters = clone(filterData)

  const refactorPayload = useMemo(() => {
    if(hasEventName) {
      const eventFilter = filters.find(filter => filter?.attribute === 'event_name');
      if(eventFilter?.value?.length === 0){
        newFilters.filters = []
      } else {
        newFilters.filters =[eventFilter]
      }
    } else {
      newFilters.filters = []
    }
    return newFilters;
  } , [filters, hasEventName, newFilters])

  // API call
  const { payload } = useEventPropertySearchPayload({ filterData: refactorPayload, searchInput: debouncedSearchValue, propertyName: formProperty })
  const { data: rawData, isLoading: loadingAPI } = useQuery([`event-filter-eventPropertyValues`, debouncedSearchValue, formProperty, payload],
    () => FilterApi.getPropertiesWithCancelToken(payload));
  const remoteData = rawData?.data?.data;

  const [visible, setVisibleChange] = useState(false);
  const fetchedPropertiesValues = useMemo(() => remoteData, [remoteData]);

  const handlePropertiesSelection =
    useCallback((val) => {
      let selectedOptionsNew = [];
      if (formPropertyValue?.includes(val)) {
        selectedOptionsNew = formPropertyValue.filter((v) => v !== val);
      } else {
        selectedOptionsNew = [...formPropertyValue, val]
      }
      form.setFields([{ name, value: selectedOptionsNew }]);
      form.validateFields();
    }, [formPropertyValue, form, name])

  const handlePropertyValueInput = useCallback((value) => {
    form.setFields([{ name, value }]);
    form.validateFields();
    handleApply(value)
  }, [form, handleApply, name])

  const renderView = useMemo(() =>
    <ul>
      {!!fetchedPropertiesValues?.length >= 1
        ? fetchedPropertiesValues.map((data) => {
          const key = data; let title = data;
          if (formProperty === 'activity' || formProperty === 'screen') { // Edge case: this needs to be done as 'activity' is the reserverd key word that serves as uxcam event property which populates screen names on its selection 
            title = screenRenamedList[data] || data
          } 
          return (
            <MenuListItem key={key}>
              <Checkbox
                checked={(isArray(formPropertyValue) && formPropertyValue?.length) && formPropertyValue?.includes(key)}
                onChange={() => handlePropertiesSelection(key)}
              >
                <CellOverflowTooltip
                  width={195}
                  text={title}
                  value={title}
                />
              </Checkbox>
            </MenuListItem>
          )
        })
        : <NotFoundMessage>No matching event properties values found.</NotFoundMessage>}
    </ul>
    , [fetchedPropertiesValues, formProperty, formPropertyValue, screenRenamedList, handlePropertiesSelection]);

  const onVisibleChange = useCallback(() => {
    setVisibleChange(!visible);
  }, [visible])

  const propertiesValueMenu =
    <Menu>
      <LoaderMenuItem spinning={loadingAPI}>
        <MenuItemGroupWrapper
          placeholder='Search property value'
          onChange={(e) => setSearchInput(e.target.value)}
        >
          {renderView}
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
      <MenuButton key="button-bar">
        <Button type='primary-outline'
          onClick={() => {
            form.resetFields([`${name}`]);
            form.setFields([
              {
                name: ['eventProperties', `${formDataIndex}`, 'value'],
                value: undefined,
              },
            ]);
          }}
        >
          Clear
        </Button>
        <Button
          disabled={!formPropertyValue?.length}
          type='primary'
          onClick={() => {
            handleApply()
            onVisibleChange()
          }}
        >
          Apply
        </Button>
      </MenuButton>
    </Menu>

const handleDefaultOpen = () => {
  if(formData?.length && formPropertyValue && formPropertyValue?.length === 0){
     onVisibleChange(true)
  }
}

useEffect(()=>{
  handleDefaultOpen()
},[formData])

const formPropertyValueUpdated = useMemo(() => Array.isArray(formPropertyValue) && formPropertyValue?.length ? formPropertyValue.map(item => screenRenamedList[item] || item) : [], [formPropertyValue, screenRenamedList]);

  return (
    arrayObj.includes(formOperatorValue) ?
      <Dropdown
        overlay={propertiesValueMenu}
        overlayClassName='properties-segment-menu'
        onVisibleChange={(v) => {
          onVisibleChange(v)
          !v && formPropertyValue?.length && handleApply()
        }}
        visible={visible}
        trigger={['click']}
      >
        <span className='filter-spacing'><a href="#!" onClick={(e) => e.preventDefault()}><StyledSpace isBold = {showOverflowItems(formPropertyValueUpdated)}>{showOverflowItems(formPropertyValueUpdated) || 'Search event property value'}</StyledSpace></a></span>
      </Dropdown> :
      <InputPropertiesValues
        option={formPropertyValue}
        // operatorData={selectedPropertiesOperaors}
        placeholder='Enter property value'
        handlePropertyValueInput={handlePropertyValueInput}
      />
  )
}

export default PropertiesValueOptions;