import { useEffect, useCallback, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext';
import { useIsAppType } from './useIsAppType';

const useEventUserProperties = () => {
  const { dateSegment } = useSelector((state) => state.appFilter);
  const { appId, parentType } = useSelector((state) => state.urlReducer);
  const isHeatmapsPage = useMemo(() => parentType === 'heatmapsList', [parentType]);
  const dispatch = useDispatch();
  const isWebApp = useIsAppType( 'web' );
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext();
  const getPayload = useCallback(
    (attribute) => ({
      attribute,
      filter: [],
      search: '',
      dropdownLimit: 501,
      date_range: dateSegment,
    }),
    [dateSegment],
  )
  useEffect(() => {
    if(!appId || isHeatmapsPage) return
    dispatch(getFilterPropertyRemoteData(getPayload('event_name'), false, true));
    dispatch(getFilterPropertyRemoteData(getPayload('user_custom_property'), false, true));
    // @Note: CX-1657 Removed getPayload dependency because it was calling the API multiple times
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, dispatch]);

  useEffect(() => {
    if(!appId || !isHeatmapsPage || !isWebApp) return
    dispatch(getFilterPropertyRemoteData(getPayload('session_screen_with_property'), false, true));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, dispatch]);

  useEffect(() => {
    if(!appId || !isWebApp) return
    dispatch(getFilterPropertyRemoteData(getPayload('utm'), false, true));
    dispatch(getFilterPropertyRemoteData(getPayload('user_first_utm'), false, true));
    dispatch(getFilterPropertyRemoteData(getPayload('session_screen_with_property_list'), false, true));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, dispatch, isWebApp]);

  useEffect(() => {
    if( !appId || !noCodeEventsFeatureFlag || isHeatmapsPage ) return
    dispatch(getFilterPropertyRemoteData(getPayload('nce_name'), false, true));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, dispatch, noCodeEventsFeatureFlag]);


};
export default useEventUserProperties;
