import React from 'react';
import { compose } from 'redux'
import { connect } from 'react-redux'
import { findIndex, omit, indexOf } from 'lodash'
import {
  statsDropdownOptions,
  eventsGraph,
} from 'redux/actions/statistic'
import { getTimezoneOffset } from 'Utils/DateConversion/dateConversionUtils';

const eventsHOC = (WrappedComponent) =>
  class extends React.Component {
    callApi = async (appid, isInitialCall, isUserDetails, isWebSDK ) => {
      let filter
      if (!this.props.dropdownData && isInitialCall) {
        this.dropdownDataApi(appid, isWebSDK)
      }
      await this.callGraphApi(appid, filter, null, null, isUserDetails)
    }

    filterValues = (isUserDetails) => {
      const filter = []
      const selectedEventName = [...this.props.eventTable.selectedEvent]
      const eventNameList = [...this.props.eventTable.table]
      isUserDetails &&
        filter.push({
          table: 'event',
          attribute: 'event_user_name',
          operator: 'eq',
          value: this.props.urlQ.uxcamuserid,
        })
      if (
        selectedEventName.length &&
        selectedEventName.length !== eventNameList.length
      ) {
        const unSelectedEvent = eventNameList.filter((x) => {
          const eventIndex = indexOf(selectedEventName, x.eventname)
          if (eventIndex < 0) {
            return x
          }
        })

        let eventNameListValue = []
        let eventOperator = 'in'
        if (selectedEventName.length > unSelectedEvent.length) {
          if (unSelectedEvent.length === 0) {
            eventNameListValue = selectedEventName
            eventOperator = 'in'
          } else {
            eventNameListValue = unSelectedEvent.map((x) => x.eventname)
            eventOperator = 'notin'
          }
        } else if (selectedEventName.length < unSelectedEvent.length) {
          eventNameListValue = selectedEventName
          eventOperator = 'in'
        } else if (
          selectedEventName.length &&
          selectedEventName.length === unSelectedEvent.length
        ) {
          eventNameListValue = selectedEventName
          eventOperator = 'in'
        }
        const eventNameFilter = {
          table: 'event',
          attribute: 'event_name',
          operator: eventOperator,
          value: eventNameListValue,
        }
        filter.push(eventNameFilter)
      }
      return filter
    }

    dropdownDataApi = (appid, isWebApp = false ) => this.props.statsDropdownOptions({ appid, webApp: isWebApp })

    callGraphApi = async (
      appidArgs,
      filterData,
      grpByArr,
    ) => {
      let plotOptions
      const {
        eventDropValues,
        grpByVal,
        graphSelectedVal,
        appid,
        dateSegment,
      } = this.props
      plotOptions = graphSelectedVal
      plotOptions = omit(plotOptions, 'display', 'key', 'img')
      const groupByList = grpByArr || grpByVal
      const indexOfPeriod = findIndex(groupByList, { attribute: 'event_period_day' })
      if(indexOfPeriod > -1) groupByList[indexOfPeriod]['time_zone_offset'] = getTimezoneOffset(dateSegment.tz, new Date() )

      const res = await this.props.eventsGraph({
        appid: appidArgs || appid,
        aggregation_list:[eventDropValues],
        group_list: groupByList,
        series_plot_options: plotOptions,
      })
      return res
    }

    render() {
      return (
        <WrappedComponent
          callApi={this.callApi}
          filterValues={this.filterValues}
          dropdownDataApi={this.dropdownDataApi}
          callGraphApi={this.callGraphApi}
          {...this.props}
        />
      )
    }
  }
const mapStateToProps = (state) => ({
    appid: state.urlReducer.appId,
    eventTable: state.eventTable,
    grpByVal: state.statisticsReducer.grpByVal,
    eventDropValues: state.statisticsReducer.eventDropValues,
    dropdownData: state.statisticsReducer.dropdownData,
    graphSelectedVal: state.statisticsReducer.graphSelectedVal,
    urlQ: state.urlReducer,
    eventDateRange: state.appFilter.dateSegment,
    dateSegment: state.appFilter.dateSegment,
  })
const composedEventsHoc = compose(
  connect(mapStateToProps, {
    eventsGraph,
    statsDropdownOptions,
  }),
  eventsHOC
)
export default composedEventsHoc
