import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme'
import { getFormattedTime } from 'Utils/DateConversion/dateConversionUtils'

interface Props {
    time: string,
    isSession: boolean,
}

const P = styled.p`
font-size: ${ theme.fontSize( 1.2 ) };
line-height: ${ theme.fontSize( 2.4 ) };
`

const ConversionWindow: React.FC<Props> = ({
    time,
    isSession
}) => {

    if (isSession) return <P>1 session</P>

    return (
        <P>{getFormattedTime(time)}</P>
    )
}

export default React.memo(ConversionWindow)