import React from 'react';

export const compareSDKVersion = (
  versionToCheck: string,
  versionToMatch: string
): boolean => {
  const a = versionToCheck.split('.').map(Number);
  const b = versionToMatch.split('.').map(Number);
  let r = 0;
  const l = Math.max(a.length, b.length);

  for (let i = 0; !r && i < l; i += 1) {
    r = (a[i] || 0) - (b[i] || 0);
  }

  return r >= 0;
};

export const gestureGenerateName = (
  gestureType: string,
  viewType: string | number,
  noCodeEventsFeatureFlag: boolean,
  name?: string
) => {
  const nameIsValid =
    name && name.length > 0 && name !== 'Undefined' && name !== 'UnknownView';
  if (noCodeEventsFeatureFlag) {
    return (
      <>
        <b>
          {`${gestureType} ${
            gestureType && (nameIsValid || viewType) ? ' - ' : ''
          }`}
        </b>
        {nameIsValid && <i>{`${name} `}</i>}
        <b>{viewType}</b>
      </>
    );
  }
  return <b>{gestureType}</b>;
};

// only includes SDKs that doesnt need to check versions unlike 'native'
export const smartEventsSupportedSDK = [ 'SwiftUI' ]