import { Button, Dropdown } from "antd";
import React, { useCallback, useEffect, useMemo } from "react";
import map from "lodash/map";
import omitBy from 'lodash/omitBy'
import sortBy from 'lodash/sortBy'
import { useSelector, RootStateOrAny } from "react-redux";
import { IAppFilter } from "types/reduxStateTypes";
import { useIsAppType } from "hooks/useIsAppType";
import { ActivityFilterPayloadType } from "types/activityFilterConfigurationTypes";
import { hasActivityFilterChangedFromDefaultState } from "Utils/helpers/activityFilterUtils";
import { useIsUserV2 } from "hooks/useUserV2Filter";
import { cloneDeep } from "lodash";
import { isEqualActualSegmentVSAppliedSegment } from "Utils/helpers/segmentHelper";
import SegmentOverlay from "./SegmentOverlay";
import { SEGMENT_PLACEHOLDER, SEGMENT_TITLE } from "./variables";
import useAppFilter from "../useAppFilter";
import { useSegmentModal } from "./hooks/useModal";
import { IFilter, ISelectedSegment } from "./types";
import useSegmentAPI from "./hooks/useSegmentAPI";
import { SegmentNameSpan } from "./styles";

const NewSegmentMenu: React.FC = () => {

  const { pageType, segmentType } = useAppFilter();
  const isWebApp = useIsAppType( 'web' );
  const { segmentList } = useSegmentAPI();
  const { isSegmentDropdownVisible, appliedSegment, toggleModal, setAppliedSegment, setSearchText } = useSegmentModal();

  const { appFilter } = useSelector((state: RootStateOrAny ) => state);
  const newPageType = useMemo(() => pageType === 'event' ? 'session' : pageType, [pageType]);

  const filterSegmentNew = appFilter[segmentType as keyof IAppFilter].segment;
  const appliedActivityFilterSegmentNew = appFilter[segmentType as keyof ActivityFilterPayloadType].activityFilterList as ActivityFilterPayloadType[];
  
  const handleVisibleChange = () => toggleModal?.('reset', {});

  const isUserV2 = useIsUserV2();
  
  const hasActivityFilterChanged = useMemo(()=> hasActivityFilterChangedFromDefaultState(appliedActivityFilterSegmentNew) , [appliedActivityFilterSegmentNew])


  const applySegment = useCallback((segment: ISelectedSegment) => {
    setSearchText?.('');
    setAppliedSegment?.(segment);
  }, [setAppliedSegment, setSearchText]);

  const segmentListWithoutFalsyValues = useMemo(() => {
    const segmentWithoutFalsyValues = map(cloneDeep(segmentList), (obj) => omitBy(obj, v => v === undefined));
    const filterSegmentsForWebApp = segmentWithoutFalsyValues.filter(
      (segment) => {
        const { filter } = segment;
        return filter.every(
          (filterObj: { attribute: string }) =>
          !['session_crashed', 'session_offline_recorded'].includes(filterObj.attribute)
        );
      }
    );
    return isWebApp ? filterSegmentsForWebApp : segmentWithoutFalsyValues;
  }, [segmentList, isWebApp])

  const filteredSegmentListForWebApp = useMemo(() => cloneDeep(segmentList)?.filter(
      (segment: { filter: any; }) => {
        const { filter } = segment;
        return filter.every(
          (filterObj: { attribute: string }) =>
            !['session_crashed', 'session_offline_recorded'].includes(filterObj.attribute)
        );
      }
    ), [segmentList]);


  const isAppliedFiltersAlreadySegment = useCallback(() => {
      if ( (filterSegmentNew?.length  && segmentList?.length) || hasActivityFilterChanged) {
          const appliedSegmentWithoutFalsyValues = map(filterSegmentNew, (obj) => omitBy(obj, v => v === undefined)) as IFilter[];
          // * CX 1876: APPLYING ACTIVITY FILTERS TO SEGMENTS FOR USER LIST (ICEBERG)
          const matchedIndex = segmentListWithoutFalsyValues.findIndex((seg) => {
              let combinedFilters: Array<IFilter | ActivityFilterPayloadType> = appliedSegmentWithoutFalsyValues;
              if (isUserV2) {
                combinedFilters = combinedFilters.concat(appliedActivityFilterSegmentNew);
            }
                const rawActualSegment = seg.filter;
                const rawAppliedSegment = combinedFilters;
                return isEqualActualSegmentVSAppliedSegment(rawActualSegment, rawAppliedSegment)
        })
      if (matchedIndex > -1) { 
        const { name, filter: segmentFromSegmentList } = segmentListWithoutFalsyValues[matchedIndex];
        applySegment({
          name,
          filter: segmentFromSegmentList,
        })
      } else {
        applySegment({
          name: '',
          filter: []
        })
      }
    } else {
      applySegment({
        name: `All ${newPageType}s`,
        filter: []
      })
     }
  }, [filterSegmentNew, segmentList?.length, hasActivityFilterChanged, segmentListWithoutFalsyValues, isUserV2, appliedActivityFilterSegmentNew, applySegment, newPageType])

  useEffect(() => {
    isAppliedFiltersAlreadySegment()
  }, [filterSegmentNew, isAppliedFiltersAlreadySegment, appliedActivityFilterSegmentNew])

  return (
    <Dropdown
      overlayStyle = {{ width: '240px', minWidth: '240px' }}
      overlay={<SegmentOverlay segmentList={isWebApp ? filteredSegmentListForWebApp : segmentList || []} />}
      trigger={['click']}
      onVisibleChange={handleVisibleChange}
      visible={isSegmentDropdownVisible}
      destroyPopupOnHide
    >
      <Button>{` ${SEGMENT_TITLE} | `}<SegmentNameSpan>{appliedSegment?.name || SEGMENT_PLACEHOLDER}</SegmentNameSpan></Button>
    </Dropdown>
  )
}

export default NewSegmentMenu;