/* eslint-disable prefer-destructuring */
import { axiosInstance } from './globalInstance'

const PYTHON_API_URL_V2 = process.env.PYTHON_API_URL_V2
const PYTHON_API_URL = process.env.PYTHON_API_URL

class appFilterApi {
  
  static async getSegmentListV2(appId, page) {
    const prefix = `segment/app/${appId}/${page}/list`;
    const response = await axiosInstance({
      method: 'GET',
      url: `${PYTHON_API_URL}/${prefix}`,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }

  static async getSegmentList (appId, filter) {
    const response = await axiosInstance({
      method: 'Get',
      url: `${process.env.API_URL}/app/${appId}/${filter}`,
      withCredentials: true
    })
    return response
  }

  static async saveSegments(appId, data, page, isNewApi) {
    const prefix = `segment/app/${appId}/${page}/create`;
    const response = await axiosInstance({
      method: 'POST',
      url: `${isNewApi ? PYTHON_API_URL : PYTHON_API_URL_V2}/${prefix}`,
      data,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }

  static async editSegments(appId, data, page, segmentId) {
    const prefix = `segment/app/${appId}/${page}/edit/${segmentId}`;
    const response = await axiosInstance({
      method: 'POST',
      url: `${PYTHON_API_URL}/${prefix}`,
      data,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }

  static async deleteSaveSegment(appId, segmentId, page, isNewApi) {
    const prefix = `segment/app/${appId}/${page}/delete/${segmentId}`;
    const response = await axiosInstance({
      method: 'DELETE',
      url: `${isNewApi ? PYTHON_API_URL : PYTHON_API_URL_V2}/${prefix}`,
      responseType: 'json',
      withCredentials: true,
      validateStatus(status) {
        return status >= 200 && status < 401;
      },
    });
    return response;
  }
}

appFilterApi.appFilterApi = undefined;

appFilterApi.appFilterApi = undefined;
export default appFilterApi;
