import React, { useEffect, useState, memo, useMemo } from 'react';
import { SettingOutlined } from '@ant-design/icons';
import { useDispatch, useSelector } from 'react-redux';
import { Dropdown, Select, Menu } from 'antd';
import CustomExportGraphDropdown from 'Utils/helpers/CustomExportGraphDropdown';
import { fetchPlanHatApi } from 'redux/actions/common';
import { IconScreenflow } from 'components/svg_files';
import { screenFlowPayload, setSunBurstDepth } from 'redux/actions/screenList';
import { trackPageViews } from 'redux/actions/trackingReport';
import DebounceInputField from 'components/features/navigation/DebounceInputField';
import { sunBurstMaxMsg } from 'Utils/constants/index';
import { useAppNavigationContextContext } from './Context';
import { maxScreenPerSteps, maxDepthSunBurst } from './constants';

const { Option } = Select;
const CommonOption = (props) => {
  const { 
    chartRef,
    disabled,
    handleAPICall,
    setSelectedGraph,
    isScreenBurst
  } = props;
  const { flagCogDrop, setFlagCogDrop } = useAppNavigationContextContext()
  const [stepErrorMessage, setStepErrorMessage] = useState('');
  const [stepMessage, setStepMessage] = useState(false);
  const [screenErrorMessage, setScreenErrorMessage] = useState('');
  const [screenMessage, setScreenMessage] = useState(false);
  const dispatch = useDispatch();
  const {
    urlReducer: urlQuery,
    screenDetailReducer: chartDetail,
    appFilter,
  } = useSelector((state) => state);
  const { screenFlowPayloadData, sunburstPlotGraph, sunBurstDepth } = chartDetail;
  const { dateSegment } = appFilter;
  const { appId: appid, parentType } = urlQuery;
  const handleMaximumLength = async (val) => {
    const depthValue = +val
    let payload = {}
    setStepMessage(false);
    if (depthValue) {
      if (screenFlowPayloadData)
        payload = { ...screenFlowPayloadData, depth: depthValue }
      else {
        payload = {
          appid,
          depth: depthValue,
          max_screen_number: 12,
          date_range: dateSegment,
        };
      }
      dispatch(setSunBurstDepth(depthValue))
      dispatch(screenFlowPayload(payload));
      handleAPICall(payload);
      dispatch(
        trackPageViews(null, {
          eventName: 'appnavi_clicked_on_add_step',
          track_type: 'event',
          eventProperty: {
            page: 'app navigation',
            description: 'User clicks on add step button',
            additional: `user changed from ${
              screenFlowPayloadData.depth || 5
            } to ${depthValue}, old: ${screenFlowPayloadData.depth || 5}, new: ${depthValue}`,
          },
        })
      );
      dispatch(
        fetchPlanHatApi({
          action: 'Change length',
        })
      );
    }
  };
  const handleMaximumScreenNumber = (val) => {
    setScreenMessage(false);
    if (screenFlowPayloadData) {
      const payload = {
        ...screenFlowPayloadData,
        max_screen_number: +val,
      };
      dispatch(screenFlowPayload(payload));
      handleAPICall(payload);
    }
    dispatch(
      trackPageViews(null, {
        eventName: 'appnavi_clicked_on_add_category',
        track_type: 'event',
        eventProperty: {
          page: 'app navigation',
          description: 'User clicks on add category button',
          additional: `user changed from ${
            screenFlowPayloadData.max_screen_number || 12
          } to ${val}, old: ${
            screenFlowPayloadData.max_screen_number || 12
          }, new: ${val}`,
        },
      })
    );
    dispatch(
      fetchPlanHatApi({
        action: 'Change max screen number',
      })
    );
  };

  useEffect(() => {
    const errorText = sunburstPlotGraph?.error?.message
    if (parentType === 'screenBurst' && typeof errorText === 'string' && errorText?.includes(sunBurstMaxMsg))
      setFlagCogDrop(true);
  }, [parentType, setFlagCogDrop, sunburstPlotGraph?.error?.message]);

  const depth = useMemo(() => {
    const useSunBurstDepthValue = isScreenBurst && (screenFlowPayloadData?.depth > maxDepthSunBurst ? maxDepthSunBurst : sunBurstDepth);
    return useSunBurstDepthValue || screenFlowPayloadData?.depth || 5;
  }, [isScreenBurst, screenFlowPayloadData?.depth, sunBurstDepth]);
  const cogMenu =
  <Menu>
    <div className="dropdown-menu-body">
      <DebounceInputField
        label="Steps"
        id="valMaxLength"
        value={depth}
        onChange={handleMaximumLength}
        tooltipTitle={`Number of steps in a sequence ( Max allowed step is ${isScreenBurst ? maxDepthSunBurst : 10} )`}
        errorFlag={stepMessage}
        setMessage={setStepMessage}
        errorMessage={stepErrorMessage}
        setErrorMessage={setStepErrorMessage}
        stepMaxValue={isScreenBurst ? maxDepthSunBurst : 10}
      />
      <DebounceInputField
        label="Screens per step"
        id="valMaxScreenNumber"
        autoFocus={false}
        value={screenFlowPayloadData?.max_screen_number || 12}
        onChange={handleMaximumScreenNumber}
        tooltipTitle={`Number of screens per step ( Max allowed step is ${maxScreenPerSteps} )`}
        errorFlag={screenMessage}
        setMessage={setScreenMessage}
        errorMessage={screenErrorMessage}
        setErrorMessage={setScreenErrorMessage}
        stepMaxValue={maxScreenPerSteps}
      />
    </div>
  </Menu>
  const handleCogVisible = (flag, id) => {
    if (id) setFlagCogDrop(flag);
  };
  const handleChartChange = (value) => {
    setSelectedGraph(value);
    dispatch(
      trackPageViews(null, {
        eventName: `s${value === 'screenBurst' ? 'b' : 'f'}_view_chart`,
        track_type: 'event',
        eventProperty: {
          page: 'app navigation',
          description: `User clicks on the ${value === 'screenBurst' ? 'screen burst' : 'screenflow'} on the drop down`,
        },
      })
    )
  };
  return (
    <div className="setting-item">
      <div className="filter-item" data-intercom-target="Clog">
        <Dropdown
          disabled={disabled}
          overlay={cogMenu}
          trigger={['click']}
          overlayClassName="dropdown-menu-wrapper"
          onVisibleChange={(flag) => handleCogVisible(flag, 'close')}
          visible={flagCogDrop || false}
        >
          <SettingOutlined />
        </Dropdown>
      </div>
      {parentType === 'usersList' && (
        <div className="dropdown-options chart-dropdown-options">
          <Select
            onChange={handleChartChange}
            defaultValue="screenFlow"
            dropdownClassName="chart-dropdown-select"
          >
            <Option value="screenFlow" className="chart-dropdown-select-item">
              <IconScreenflow /> Screen flow
            </Option>
            {/* <Option
              title="Screen burst"
              value="screenBurst"
              className="chart-dropdown-select-item"
            >
              <span>
                <IconSunburst />
                Screen burst
                <Tooltip title="Beta">
                  <Tag className="beta-indication" />
                </Tooltip>
              </span>
            </Option> */}
          </Select>
        </div>
      )}
      <CustomExportGraphDropdown disabled={disabled} chartRef={chartRef} />
    </div>
  );
};

export default memo(CommonOption);
