import React, { createContext, memo, useCallback, useContext, useMemo, useState } from 'react';
import { IFilter, IModalContext, IModalProps, ISegment, ISelectedSegment, SaveModalState } from '../types';

// type IModalContext = ReturnType<typeof useModal>;
const ModalContext = createContext<IModalContext>({} as IModalContext);

export const useSegmentModal = () => useContext(ModalContext);

export const ModalProvider: React.FC<IModalProps> = memo(({ children }) => {
  const [isSegmentDropdownVisible, setSegmentDropdownVisible] = useState<boolean>(false);
  const [isDeleteModalOpen, setDeleteModalOpen] = useState<boolean>(false);
  const [saveModalOpen, setSaveModalOpen] = useState<SaveModalState>({ isModalOpen: false, modalSegment: {
    name: '',
    filter: [],
  } });
  const [appliedSegment, setAppliedSegment] = useState<ISelectedSegment>();
  const [searchText, setSearchText] = useState<string>('');

  const toggleModal = useCallback((flag: string, segment: ISegment | object, filterPayload?: IFilter[]) => {
    if (flag === 'save') {
      setSaveModalOpen({
        modalSegment: segment,
        isModalOpen: !saveModalOpen.isModalOpen,
        filterPayload,
      });
      return;
    }
    if (flag === 'delete') {
      setSaveModalOpen({ 
        ...saveModalOpen,
        isModalOpen: false,
      })
      setDeleteModalOpen(!isDeleteModalOpen);
      return;
    }
    setSegmentDropdownVisible(!isSegmentDropdownVisible)
  }, [isDeleteModalOpen, isSegmentDropdownVisible, saveModalOpen])

  const value = useMemo(() => ({
    isSegmentDropdownVisible,
    isDeleteModalOpen,
    saveModalOpen,
    appliedSegment,
    setAppliedSegment,
    toggleModal,
    searchText, 
    setSearchText,
  }), [appliedSegment, isDeleteModalOpen, isSegmentDropdownVisible, saveModalOpen, searchText, toggleModal]);

  return (
    <ModalContext.Provider value={value}>
      {children}
    </ModalContext.Provider>
  )
});