import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { Button, Form , Tooltip } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import { mappedPageType } from 'Utils/helpers/commonUtils';
import { debounce, findIndex } from 'lodash';
import { setActivityFilterSegment, updateActivityFilterConfig, updateActivityFilterSegment } from 'redux/actions/megaFilter';
import { currentTimeZone } from 'Utils/DateConversion/dateConversionUtils';
import { MinusBtnSVG } from 'components/svg_files';
import type { ActivityFilterPayloadType, ActivityPropertyType } from 'types/activityFilterConfigurationTypes';
import { getActivityDateRangeOperator, getAddPropertyDropdownConfig } from 'Utils/helpers/activityFilterUtils';
import { guardAddActivityProperty } from 'Utils/helpers/useActivityFilterValidator';
import ArrowDownSVG from 'public/static/arrow-down.svg';
import useHasSmartEvents from 'hooks/useHasSmartEvents';
import ActivityDatePicker from './ActivityDatePicker';
import useAppFilter from '../../useAppFilter';
import OperatorJSON from '../../data-structures-v2/operator.json';
import AddActivityPropertyMenuComponent from './AddActivityPropertyMenuComponent';
import { activityFilterSelector, defaultDateSegment, getActivityPropertiesListByAttribute } from './constants';
import AppliedFilter from '../AppliedFilter';
import { ActivityStyledMain, InputWrapper, RowWrapper, SelectWrap, StyledFormItem, StyledActivityFilterCol } from './styles';

const isInteger = /^[0-9]+$/;

const atLeastOperatorOptions = [
    { value: 'greater_or_equal', label: 'at least' },
    { value: 'less_or_equal', label: 'at most' },
    { value: 'equal', label: 'exactly' },
];
const recordedOperatorOptions = [
    { value: 'device_time', label: 'recorded' },
    { value: 'upload_time', label: 'uploaded' },
]
const DebouncedInputNumber = ({ value, onChange, delay = 300 }: {
    value?: number;
    onChange?: (val: number) => void;
    delay?: number;
}) => {
    const [internalValue, setInternalValue] = useState(value); 
    const [width, setWidth] = useState(50);

    const updateWidth =useCallback((val:any)=>{       
        const {length} = String(val || "1");
        setWidth(Math.min(50 + length * 6, 80));    
    } ,[])

    useEffect(() => {
        setInternalValue(value);
        updateWidth(value);
    }, [updateWidth, value]);
    const debouncedChange = useCallback(
        debounce((val) => {
            onChange?.(val);
        }, delay),
        [onChange, delay]
    );

    const handleChange = (val:any) => {
        let inpValue = val; 
        if (inpValue < 0) inpValue = 0; 
        updateWidth(inpValue);
        setInternalValue(inpValue);
        debouncedChange(inpValue);
    };

    return (
        <InputWrapper
            min={0}
            style={{ width: `${width}px`, transition: "width 0.2s ease-in-out" }}
            type="number"
            value={internalValue}
            onChange={handleChange}
        />
    );
};

  
const initialValues = {
    atLeastOperator: 'greater_or_equal',
    countOperator: 1,
    recordedOperator: 'device_time',
    dateRange: defaultDateSegment
}
const getEventType = (data: ActivityPropertyType):
    'eventName' | 'smartEventName' | 'screenName' | 'smartEventProperties' | 'screenProperties' | 'eventProperties' | null => {
    if (data.attribute === 'event_name' && !data.property) {
        return 'eventName';
    }   
    if (data.attribute === 'event_name' && data.property && data.isLocal || data.attribute === 'event_custom_property') {
        return 'eventProperties';
    } 
    if (data.attribute === 'nce_name') {
        return 'smartEventName';
    }
    if (data.attribute === 'viewid' || data.attribute === 'viewname' || data.attribute === 'viewtype') {
        return 'smartEventProperties';
    }
    if (data.attribute === 'screen_name' && !data.property ) {
        return 'screenName';
    } 
    if ((data.attribute === 'screen_name' && data.property && data.isLocal)
          || (data.attribute === 'session_screen_with_property_list')
    ) { // *isLocal is used to show screen_name with properties in single line for redirected filters
        return 'screenProperties';
    }
    return null;
}

const getActivityFilterLabel = (rawLabel:string, countOperator:number, hasSmartEvents:boolean) => {
    let label
    if(rawLabel.includes('event')){
        label = hasSmartEvents ? rawLabel : 'event'
    } else {
        label = rawLabel
    }
    return label.concat(Number(countOperator) > 1 ? 's' : '')
}
function ActivityFilter({
    filterIndex
}:{
    filterIndex: number
}) {
    const hasSmartEvents = useHasSmartEvents()
    const { segmentType, activityCallListApi: callListApi } = useAppFilter()
    const [form] = Form.useForm();
    const dateRangeValueWatch = Form.useWatch('dateRange', form);
    const countOperatorWatch = Form.useWatch('countOperator', form);
    const dateRangeOperatorDerivedValue = useMemo(() =>   {
       return getActivityDateRangeOperator(
        dateRangeValueWatch?.labelId
        )
    }
    , [dateRangeValueWatch])

    const {
        //@ts-ignore
        urlReducer,
        //@ts-ignore
        appFilter
    } = useSelector((state) => state);

    const { parentType }: { parentType: keyof typeof mappedPageType } = urlReducer
    const dispatch = useDispatch();

    const pageType = mappedPageType[parentType]
    const activityFilter = appFilter[segmentType]?.activityFilterList[filterIndex] as ActivityFilterPayloadType;
    const activityFilterConfigurations = activityFilterSelector?.[activityFilter.attribute as keyof typeof activityFilterSelector];
    const getDefaultValue = (type:string )=> {
        switch (type) {
            case 'bool':
                return OperatorJSON['bool'][0].attribute
            case 'device_platform':
                return OperatorJSON['device_platform'][0].attribute
            default:
                return ''
    }}
    function findLastEventName(events: ActivityPropertyType[] , attribute:'event_name' | 'screen_name'): ActivityPropertyType | null {
        // Iterate in reverse order to find the last event_name occurrence
        // eslint-disable-next-line no-plusplus
        for (let i = events.length - 1; i >= 0; i--) {
          if (events[i].attribute === attribute && !events[i].property) {
            return events[i]; 
          }
        }
        return null; // Return null if no event_name is found
      }
    const handleAddProperty = useCallback((value: string) => {
        // * before adding new property check if the previous property is valid
        // * if not valid then trigger error message for that particular property
        const isValid = guardAddActivityProperty(appFilter[segmentType]?.activityFilterList);
        if(!isValid) return;
        const AllAttributeList = getActivityPropertiesListByAttribute(activityFilter?.attribute)
        const findActivityIndex = findIndex(AllAttributeList, { attribute: value });
        const findActivity = AllAttributeList[findActivityIndex];
        //* find a default operator for the attribute
        const findOperator = OperatorJSON[findActivity.type as keyof typeof OperatorJSON] || [];
        
        //* update all other segment open to false 
        const activityFilterSegmentList = activityFilter?.filters?.map((data)=>{
            return {
                ...data,    
                open: false
        }})
        let currentFilter:any = {};
        if(value === 'event_custom_property'){
            // * find latest event name filter
            const recentEventNameFilter = findLastEventName(activityFilterSegmentList ,'event_name')
            if(recentEventNameFilter){
                currentFilter = {
                    attribute: 'event_name',
                    operator: findOperator[0]?.attribute,
                    table: findActivity.table,
                    open: true,
                    property:{
                        operator: 'in'
                    },
                    isLocal: true,
                }
                currentFilter.value = recentEventNameFilter.value;
                currentFilter.operator = recentEventNameFilter.operator;
            }
            else{
                currentFilter =   {
                    attribute: findActivity.attribute,
                    operator: findOperator[0]?.attribute,
                    table: findActivity.table,
                    isLocal: true,
                    open: true
                  }
                }
        }
        else if (value === 'event_name'){
            currentFilter = {
                attribute: 'event_name',
                operator: findOperator[0]?.attribute,
                table: 'event',
                open: true, 
                isLocal: true,
            }
        }
        else if (value === 'nce_name'){
            currentFilter = {
                attribute: 'nce_name',
                operator: findOperator[0]?.attribute,
                table: findActivity.table,
                open: true,
                isLocal: true,
            }
        }
        else if (value === 'screen_name'){
            currentFilter={
                attribute: 'screen_name',
                operator: findOperator[0]?.attribute,
                table: findActivity.table,
                open: true,
                isLocal: true,
            }
        }
        else if (value === 'session_screen_with_property_list'){
              // * find latest event name filter
              const recentEventNameFilter = findLastEventName(activityFilterSegmentList , 'screen_name')
              if(recentEventNameFilter){
                currentFilter = {
                    attribute: 'screen_name',
                    operator: findOperator[0]?.attribute,
                    table: findActivity.table,
                    open: true,
                    property:{
                        operator: 'in'
                    },
                    isLocal: true
                }
                currentFilter.value = recentEventNameFilter.value;
                currentFilter.operator = recentEventNameFilter.operator;
              }else{
                currentFilter =   {
                    attribute: findActivity.attribute,
                    operator: findOperator[0]?.attribute,
                    table: findActivity.table,
                    isLocal: true,
                    open: true
                  }
                }
        }
        else{
            currentFilter= {
                attribute: findActivity.attribute,
                operator: findActivity.type === 'bool' || findActivity.type === 'device_platform' ? 'equal' : findOperator[0]?.attribute,
                value: getDefaultValue( findActivity.type ),
                table: findActivity.table,
                open: true, 
                isLocal: true,
            }
        }
        const updatedActivityFilterSegment = [...activityFilterSegmentList, currentFilter ]
        dispatch(updateActivityFilterSegment(updatedActivityFilterSegment,filterIndex, true))  // * either updates or append property for that particular segment
        callListApi()
    } , [appFilter, segmentType, activityFilter?.attribute, activityFilter?.filters, dispatch, filterIndex, callListApi])

    const handlePropertyDelete = async (filterData: ActivityPropertyType) => {
        const index = activityFilter.filters.indexOf(filterData)
        const segment = activityFilter.filters.filter((_: any, i: number) => i !== index)
        dispatch(updateActivityFilterSegment(segment, filterIndex))
        callListApi() 
    }

    const onFinish = (values: any) => {
        // console.log('Received values of form: ', values);
    }
    const handleActivityFilterDelete = () => {
        const filteredActivity = appFilter[segmentType]?.activityFilterList.filter((_: any, i: number) => i !== filterIndex);
        dispatch(setActivityFilterSegment(filteredActivity, 'user'));
        callListApi();
    }
  
    const defaultDateRange = useMemo(() => {
        const now = new Date()
        const from = new Date()
        from.setDate(now.getDate() - 30)

        // eslint-disable-next-line camelcase
        const { value: { lower, upper }, tz, labelId } = activityFilter.activity_attribute_date_range;
        return {
            from: new Date(lower) || from,
            to: new Date(upper) || now,
            timezone: tz || currentTimeZone,
            source:  'UPLOAD_TIME',
            preset: labelId,
        }
    }, [activityFilter?.activity_attribute_date_range]);    

    // * Initializing Form From Url Data
    useEffect(() => {
            form.setFieldsValue({
                atLeastOperator: activityFilter?.operator,
                countOperator: activityFilter?.value,
                recordedOperator: activityFilter.activity_attribute_date_range?.attribute,
                dateRange: {
                    ...activityFilter.activity_attribute_date_range,
                    labelId: activityFilter.activity_attribute_date_range?.labelId || ''
                }
            });
    }, [activityFilter, form ]);


    return (
        <StyledActivityFilterCol span={24} className='filter-item'>
            <Form
                form={form}
                name="user_activity_filter"
                initialValues={initialValues}
                onFinish={onFinish}
                onValuesChange={(changedValues, allValues) => {
                    if (!isInteger.test(allValues?.countOperator)) return;
                    dispatch(updateActivityFilterConfig({
                            attribute: activityFilter.attribute ,
                            activity_attribute_date_range:{
                                ...allValues.dateRange,
                                operator: "between_dates",
                                attribute: allValues.recordedOperator
                            },
                            operator: allValues.atLeastOperator,
                            value: allValues.countOperator,
                        }, filterIndex));
                        callListApi();
                }}
            >
                <ActivityStyledMain>
                    <span className="activity-filter-spacing">
                        User who had
                    </span>
                    <StyledFormItem
                        name="atLeastOperator"

                    >
                        <SelectWrap
                            suffixIcon={<ArrowDownSVG/>}
                            options={atLeastOperatorOptions}
                            width="70px"
                        />
                    </StyledFormItem>
                    <StyledFormItem
                        name="countOperator"
                    >
                        <DebouncedInputNumber />
                    </StyledFormItem>
                    <span className="activity-filter-spacing activity-filter-type">
                        { getActivityFilterLabel(activityFilterConfigurations?.configuration?.label, countOperatorWatch, hasSmartEvents) } 
                    </span>
                    <StyledFormItem
                        name="recordedOperator"
                    >
                        <SelectWrap
                            options={recordedOperatorOptions}
                            suffixIcon={<ArrowDownSVG/>}
                            width="75px"
                        />
                    </StyledFormItem>
                    <span className="activity-filter-spacing">
                    {dateRangeOperatorDerivedValue}
                    </span>
                    <StyledFormItem name="dateRange">
                        <ActivityDatePicker defaultDateRange={defaultDateRange} />
                    </StyledFormItem>
                    <Tooltip placement="topLeft" title="Delete filter" arrowPointAtCenter>
                        <Button
                            onClick={() => handleActivityFilterDelete()}
                            ghost
                            type="text"
                            icon={<MinusBtnSVG />}
                            className="delete-btn"
                        />
                    </Tooltip>
                </ActivityStyledMain>
            </Form>


            <RowWrapper>
                {activityFilter.filters?.map((data, index: number, list) => {
                    return (
                         <AppliedFilter
                            callListApi={callListApi}
                            // eslint-disable-next-line react/no-array-index-key
                            key={`activity_filter_property_${data?.attribute}-${index}`}
                            filterData={data}
                            handleFilterDelete={handlePropertyDelete}
                            filterSegment={list}
                            pageType={pageType}
                            segmentType={segmentType}
                            isActivityFilter
                            activityFilterConfiguration={{
                                activityPropertyIndex:index,
                                activityFilterIndex:filterIndex,
                                type:getEventType(data),
                                activityFilterAttribute: activityFilter.attribute,
                            }}
                        />
                    )
                })
                }
            </RowWrapper>
            <AddActivityPropertyMenuComponent onAddProperty={handleAddProperty}
                currentAttribute={activityFilter.attribute}
                dropdownId={getAddPropertyDropdownConfig(activityFilter.attribute, filterIndex).dropdownId}
            />

        </StyledActivityFilterCol>
    )
}

export default ActivityFilter