/* eslint-disable arrow-body-style */
/* eslint-disable no-param-reassign */
/* eslint-disable react/jsx-props-no-spreading */
/* eslint-disable import/no-cycle */
import React, { useState, useEffect, useCallback, memo, useMemo } from 'react'
import { useSelector } from 'react-redux'
import map from 'lodash/map'
import uniqBy from 'lodash/uniqBy'
import pick from 'lodash/pick';
import omit from 'lodash/omit';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { Menu } from 'antd'

import { noMatchingFilterMenu } from 'components/shared/GlobalFilter/components'
import smartEventProps from 'components/shared/GlobalFilter/components/data-structures-v2/Event/SmartEventProps.json';
import {
  matchAttribute,
  filterTextByOption,
  excludedFilterList as excludedFilterRaw,
  isArrayObject,
  keyLabelMap,
} from 'components/shared/GlobalFilter/components/utils'
import { EventMenuItemGroupWrapper, MenuItemGroupWrapper } from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import useCustomLabels from 'hooks/useCustomLabels';
import TabsMenuItem from 'components/shared/GlobalFilter/components/CommonComponentsV2/TabsMenuItem';
import isObject from 'lodash/isObject';
import { useUserCohorts } from 'components/common/Contexts/UserCohortsContext';
import { useIsAppType } from 'hooks/useIsAppType';
import {useFilterOptionType, useIsUserV2} from 'hooks/useUserV2Filter';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { optionsWithoutAll as optionsWithoutAllProps, optionsWithoutAllWithNocode, categoriesExtra } from '../../data-structures-v2'
import CommonMapping from './CommonMapping'
import { withContextProps } from '../FilterContextProvider'
import { filterStrategyIncluded } from "."
import EventMenuTab from '../EventMenuTab';
import CohortsMenu from './CohortsMenu';

const { ItemGroup: MenuItemGroup } = Menu

const isArrayCheck = ['Events', 'Custom user properties', 'Event properties', 'SmartEvents', 'Cohorts', "Tara's watchlist batches", 'Landing UTM', 'Screen visit properties', 'Custom screen properties', 'Initial landing UTM']
const SecondLevelMenu = memo((props) => {
  const {
    pageType,
    segmentType,
    selectedKey,
    dropdownOptions: dropdownOptionsProps,
    // context props
    fetchedList,
    handleSearchInputProps,
    searchAttrInputText,
    inputRef,
    activeEventTab,
    setActiveEventTab,
    resetEventsAndCallApi,
    ...rest
  } = props

  // eslint-disable-next-line react/jsx-no-useless-fragment
  let renderList = <></>;
    let attribute;
    let isCustomLabel;
    let matchedFilter;
  const {
    appFilter,
    megaFilterReducer,
    screenDetailReducer: {
      noCodeFlag,
    },
    urlReducer: urlQuery,
  } = useSelector((state) => state)
  const { advancedFiltersAllowed, allowedCategoriesInFreePlan, retentionFeatureAllowed, aiSessionFeatureAllowed: isAISession } = useRestrictionContext() || {}

  const isWebSDK = useIsAppType( 'web' );
  const useFeatures = React.useMemo( () => {
    let features = [ 'default' ]

    if ( isWebSDK ) {
      features = [ 'websdk' ]
    }

    if ( isAISession ) {
      features = [ ...features, 'aisession' ]
    }

    return features
  }, [ isWebSDK, isAISession ] )
  const newScreensFilter = useFeatureFlag( 'new-screens-filter' ) 

  const isCohort = selectedKey === 'Cohorts'
  const isBatchId = selectedKey === "Tara's watchlist batches"
  const { selectedAttributeProps } = megaFilterReducer
  const { fetchProperty: rawfetchProperty } = appFilter

  const { userCohorts } = useUserCohorts()
  const cohortsEnabled = retentionFeatureAllowed
  const isUserV2 = useIsUserV2();
  // * CX-1857 For FeatureFlag user use user_v2 key for filtering
  const pageTypeForExcludedFilterList =  isUserV2  && pageType === 'user' ? 'user_v2' : pageType;
  const fetchProperty = useMemo(() => {
    return {
      ...rawfetchProperty,
      uxcamuserid_cohort: {
        data: userCohorts.map( ( { id, name, isUserCohort, description } ) => ( {
          id,
          name,
          isUserCohort,
          description,
        } ) )
      }
    }
  }, [ rawfetchProperty, userCohorts ] )

  const { parentType, issueType } = urlQuery;
  const showSessionLabels = useMemo(
    () =>
      [
        'sessionsList',
        'sessionStatistics',
        'aiSessionsList',
        'aiSessionStatistics',
        'eventsList',
        'statistics',
        'screenFlow',
        'screenBurst',
        'heatmapsList',
        'issues',
        'nocodeEventsList',
      ].includes(parentType),
    [parentType]
  );
  const showUserLabels = useMemo(
    () =>
      [
        'sessionsList',
        'sessionStatistics',
        'aiSessionsList',
        'aiSessionStatistics',
        'usersList',
        'statistics',
        'eventsList',
        'issues',
        'nocodeEventsList'
      ].includes(parentType),
    [parentType]
  );
  const labelsTitle = useMemo(() => {
    if (showSessionLabels && showUserLabels) return 'Labels';
    if (showSessionLabels) return 'Session Labels';
    if (showUserLabels) return 'User Labels';
    return '';
  }, [showSessionLabels, showUserLabels])

  const [filterText, setFilterText] = useState('')
  const [filteredOptions, setFilteredOptions] = useState([])
  const isAllSelected = selectedKey === 'All'
  const eventProperties = fetchProperty.event_custom_property.data
  const events = fetchProperty.event_name.data
  const userProperties = fetchProperty.user_custom_property.data
  const utmProperties = useMemo(() => fetchProperty?.utm?.data || [], [fetchProperty])
  const firstUtmProperties = useMemo(() => fetchProperty?.user_first_utm?.data || [], [fetchProperty])
  const customScreenProperties = useMemo(() => fetchProperty?.session_screen_with_property?.data || [], [fetchProperty])
  const sessionScreenProperties = useMemo(() => fetchProperty?.session_screen_with_property_list?.data || [], [fetchProperty])
  const smartEvents = fetchProperty.nce_name.data
  const { filteredUserLabels, megaFilteredSessionLabels, labelSearch, setLabelSearch, resetSearch } = useCustomLabels();
  const [selectedTabKey, setSelectedTabKey] = useState('session');

  const filterOptionType = useFilterOptionType(parentType);

  const labelTabsList = useMemo(() => [
    {
      key: 'session',
      name: 'Session label',
      options: megaFilteredSessionLabels, // includes filtered labels
      showSearch: true,
    },
    {
        key: 'user',
        name: 'User label',
        options: filteredUserLabels, // includes filtered labels
        showSearch: true,
      }
  ], [filteredUserLabels, megaFilteredSessionLabels]);

  const filteredLabelTabsList = useMemo(() => labelTabsList.filter((tab) => {
    if (showSessionLabels && tab.key === 'session') {
      return true;
    }
    if (showUserLabels && tab.key === 'user') {
      return true;
    }
    return false;
  }), [showSessionLabels, showUserLabels, labelTabsList]);

 let extra
  extra = {
    'Landing UTM': utmProperties,
    'Initial landing UTM': firstUtmProperties,
    'Session Labels': megaFilteredSessionLabels,
    'User Labels': filteredUserLabels,
    Events: events,
    SmartEvents: smartEvents,
    'Custom user properties': userProperties,
    'Screen visit properties': sessionScreenProperties,
  }
  if (segmentType === 'event')
    extra = {
      'Session Labels': megaFilteredSessionLabels,
      'User Labels': filteredUserLabels,
      'Event properties': eventProperties,
      'Custom user properties': userProperties,
      'Landing UTM': utmProperties,
      'Initial landing UTM': firstUtmProperties,
      'Custom screen properties': customScreenProperties,
    }
  if (segmentType === 'user')
    extra = {
      'User Labels': filteredUserLabels,
      Events: events,
      'Custom user properties': userProperties,
      'Screen visit properties': sessionScreenProperties,
    }
  if (segmentType === 'heatmap') extra = {
    'Session Labels': megaFilteredSessionLabels,
    'Custom user properties': userProperties,
    'Landing UTM': utmProperties,
    'Initial landing UTM': firstUtmProperties,
    'Custom screen properties': customScreenProperties,
  }
  if (segmentType === 'screenFlow')
    extra = {
      'Session Labels': megaFilteredSessionLabels,
      Events: events,
      'Custom user properties': userProperties,
      'Screen visit properties': sessionScreenProperties,
    }

  const handleTabsChange = (key) => {
    setSelectedTabKey(key);
  }

  useEffect(() => {
    if (segmentType === 'user') {
      setSelectedTabKey('user');
    }
  }, [segmentType])

  const handleSearchChange = (e) => {
    const { value } = e.target;
    switch (selectedTabKey) {
      case 'session':
        setLabelSearch({
          ...labelSearch,
          sessionLabels: value,
        });
        break;
      case 'user':
        setLabelSearch({
          ...labelSearch,
          userLabels: value,
        });
        break;
      default:
        break;
    }
  }

  const dropdownOptions = useMemo( () =>{
    return Object.entries( dropdownOptionsProps )
    .reduce( (acc, [key, value]) => {
      // * CX-2200 - RENAME USER SESSION COUNT > SESSION NUMBER (ONLY:ICEBERG)
      const options = value?.map(option => {
        if (option.attribute === "session_number_of_user") {
          return { ...option, title: "Session number" };
        }
        // * PF-1098 - RENAME CODED EVENT COUNT > EVENT COUNT (BASED ON SMART EVENTS)
        if ((option.attribute === "session_with_event" || option.attribute === "user_event_count") && !noCodeFlag) {
          return { ...option, title: "Event count" };
        }
        return option;
      })

      if ( !options?.length ) return acc
      acc[ key ] = options
      return acc
    }, {} )
  }, [dropdownOptionsProps, noCodeFlag]);

  const optionsWithoutAll = useMemo( () => noCodeFlag ? optionsWithoutAllWithNocode : optionsWithoutAllProps, [ noCodeFlag ] )
  let allOptions = useMemo( () => {
    const allOptionsCopy = ( { ...optionsWithoutAll[filterOptionType], ...extra } );
    if (issueType === 'crashes') {
      return {
        ...allOptionsCopy,
        'UX issues': allOptionsCopy['UX issues'].filter( option => option.attribute !== 'session_crashed')
      }
    }
    if (issueType === 'freezes') {
      return {
        ...allOptionsCopy,
        'UX issues': allOptionsCopy['UX issues'].filter( option => option.attribute !== 'UI Freeze')
      }
    }
    if (parentType === 'nocodeEventsList') {
      return {
        ...allOptionsCopy,
        'UX issues': allOptionsCopy['UX issues'].filter( option => option.attribute === 'session_crashed')
      }
    }
    if (parentType === 'heatmapsList'){ // filtering out smart events here, not checking flag because custom events is only listed for heatmaps where when flag is enabled, a completely different component is rendered
      const tempData = allOptionsCopy['Custom events']?.filter(item => item.table === 'event')
      return {
        ...allOptionsCopy,
        ...(tempData?.length > 0 && { 'Custom events': tempData })
      }
    }

 
    return allOptionsCopy
  } , [extra, issueType, optionsWithoutAll, filterOptionType, parentType] )

  allOptions = useMemo(() => {
    return Object.entries( allOptions )
      .reduce( (acc, [key, value]) => {
        // * CX-2200 - RENAME USER SESSION COUNT > SESSION NUMBER (ONLY:ICEBERG)
        const options = value?.map(option => {
          if (option.attribute === "session_number_of_user") {
            return { ...option, title: "Session number" };
          }
          // * PF-1098 - RENAME CODED EVENT COUNT > EVENT COUNT (BASED ON SMART EVENTS)
          if ((option.attribute === "session_with_event" || option.attribute === "user_event_count") && !noCodeFlag) {
            return { ...option, title: "Event count" };
          }
          return option;
        }).filter( option => !option.features || option.features.some(feature => useFeatures.includes(feature) ) );

        if ( !options?.length ) return acc
        acc[ key ] = options
        return acc
      }, {} )
  }, [allOptions, noCodeFlag, useFeatures]);
  
  if (categoriesExtra.includes(selectedKey)) {
    attribute = matchAttribute(selectedKey)
    isCustomLabel = attribute === 'sessionlabels' || attribute === 'userlabels'
    if ( attribute === 'cohorts' ) attribute = 'uxcamuserid_cohort'
    if ( attribute === "tara'swatchlistbatches" ) attribute = 'batch_id'
    if (attribute === 'landingutm') attribute = 'utm'
    if (attribute === 'initiallandingutm') attribute = 'user_first_utm'
    if (attribute === 'screenvisitproperties') attribute = 'session_screen_with_property_list'
    if (attribute === 'customscreenproperties') attribute = 'session_screen_with_property'
    if (attribute === 'customuserproperties') attribute = 'user_custom_property'
    if (attribute === 'eventproperties') attribute = 'event_custom_property'
    if (attribute === 'events') {
      attribute = activeEventTab === 'codedEvents' ? 'event_name' : 'nce_name'
    }
    if (filterStrategyIncluded.includes(selectedKey)) {
      if (isArrayObject(fetchedList)) matchedFilter = null
      else matchedFilter = fetchedList
    }
    else if (isCustomLabel) {
      if (attribute === 'sessionlabels') matchedFilter = megaFilteredSessionLabels;
      if (attribute === 'userlabels') matchedFilter = filteredUserLabels;
    }
    else {
      matchedFilter = fetchProperty[attribute]?.['data'] ?? []
    }
  }
  if (selectedKey === 'Coded events' && noCodeFlag) {
    const codedEventsOptions = dropdownOptions[selectedKey].filter(({table}) => table === 'event');
    const filteredCodedEventsOptions = codedEventsOptions.filter((data) => data.title.toLowerCase().includes(filterText.toLowerCase()));
    const smartEventsOptions = dropdownOptions[selectedKey].filter(({table}) => table === 'no_code_event');
    const filteredSmartEventsOptions = smartEventsOptions.filter((data) => data.title.toLowerCase().includes(filterText.toLowerCase()));
    matchedFilter = activeEventTab === 'codedEvents' ? filteredCodedEventsOptions : filteredSmartEventsOptions;
  }

  const extensiveFilterCases = (filterTxt) => {
    let filterTxtCopy = filterTxt
    const patternMatch = (pattern) => pattern.split('.').includes(filterTxtCopy);

    if (patternMatch('android.ios')) filterTxtCopy = 'platform';
    if (patternMatch('wifi.mobile.network')) filterTxtCopy = 'network';
    if (patternMatch('sunday.monday.tuesday.wednesday.friday.saturday.day.sun.mon.tues.wed.fri.sat.satur.wednes')) filterTxtCopy = 'week'

    return filterTxtCopy
  }

  const structureData = React.useCallback( (attributeKey, category) => {
    if ( category === 'Cohorts' ) {
      return {
        ...attributeKey,
        isSearchable: true,
        type: 'string',
        category,
        isUserCohort: true,
      }
    }
    if ( category === "Tara's watchlist batches" ) {
      return {
        ...attributeKey,
        isSearchable: true,
        type: 'string',
        category,
        isBatchId: true,
      }
    }
    return category?.includes('Labels')
      ? {
          ...attributeKey,
          isSearchable: true,
          type: 'string',
          category,
          isCustomLabel: true,
        }
      : {
          attribute: attributeKey,
          title: keyLabelMap[attributeKey] || attributeKey,
          info: attributeKey,
          isSearchable: true,
          type: 'string',
          category,
        };
  }, [] )
  const getDataModified = useCallback(({ inputText, filterType }) => {
    const categoryMap = {
      utmProperties: 'Landing UTM',
      firstUtmProperties: 'Initial landing UTM',
      userProperties: 'Custom user properties',
      eventProperties: 'Event properties',
      customScreenProperties: 'Custom screen properties',
      sessionScreenProperties: 'Screen visit properties',
      events: 'Events',
      smartEvents: 'SmartEvents',
      customLabels: 'Session Labels',
      userCustomLabels: 'User Labels',
      userCohorts: 'Cohorts',
      batchIds: "Tara's watchlist batches",
    }
    const getCustomLabel = () => megaFilteredSessionLabels
    const getUserCustomLabel = () => filteredUserLabels;
    const batchIdData = fetchProperty.batch_id?.data || [];
    const propertiesObjMap = {
      utmProperties,
      firstUtmProperties,
      userProperties,
      eventProperties,
      customScreenProperties,
      sessionScreenProperties,
      events: isObject(events) ? [ ...events ] : [],
      smartEvents: isObject(smartEvents) ? [ ...smartEvents ]: [],
      customLabels: getCustomLabel(),
      userCustomLabels: getUserCustomLabel(),
      userCohorts,
      batchIds: batchIdData,
    }

    const properties = propertiesObjMap[filterType]
      ? propertiesObjMap[filterType]
          .filter((el) => filterTextByOption(  [ 'customLabels', 'userCustomLabels', 'userCohorts'].includes( filterType ) ? el.name : ( filterType === 'batchIds' ? el.batch_name : el ), inputText))
          .map((attributeKey) => structureData(attributeKey, categoryMap[filterType]))
      : [];
    // quickfix: to filter out custom events from filtered properties list
    const returnedProperties = pageType === 'event' ? properties.filter(item => !['rageTap', 'UI Freeze'].includes(item?.attribute)) : properties;

    return returnedProperties
  }, [ utmProperties, firstUtmProperties, userProperties, eventProperties, customScreenProperties, sessionScreenProperties, events, smartEvents, userCohorts, pageType, megaFilteredSessionLabels, filteredUserLabels, structureData, fetchProperty.batch_id ]);

  const filterServerProperties = useCallback((inputText, filterType) => getDataModified({ inputText, filterType }), [getDataModified])

  const changeInputCase = (inputText) => inputText.toLowerCase()

  const noCodeCheck = useMemo(() => parentType === 'nocodeEventsList' && noCodeFlag, [noCodeFlag, parentType])
  
  const excludedScreenFilter = useMemo(() => newScreensFilter ? 'session_screen_list' : 'screen_name', [newScreensFilter])
  const excludedFilterList = useMemo(() => {
    const updatedExcludedFilterList = { ...excludedFilterRaw };
    Object.keys(updatedExcludedFilterList).forEach(key => {
      updatedExcludedFilterList[key].push(excludedScreenFilter);
    });
    return updatedExcludedFilterList;
  }, [excludedScreenFilter]);

  const allOptionsFilterHandler = useCallback((inputText) => {
    let inputTextCopy = changeInputCase(inputText)
    let mutatedFilterOptions = []
    let filteredEventProperties = [];
    let filteredEventNames = [];
    let filteredCustomLabels = [];
    let filteredUserCustomLabels = [];
    let filteredLandingUtm = [];

    inputTextCopy = extensiveFilterCases(inputTextCopy)

    const optionWithoutAllFilteredOut = optionsWithoutAll
    const categoryKeys = Object.keys(optionWithoutAllFilteredOut[pageType]);
    const filteredSelectedKey = dropdownOptions[selectedKey]
      .filter((data) => (noCodeCheck || (data.table !== 'no_code_event')))
      .filter((data) => (noCodeCheck || !smartEventProps.map((item) => item.attribute).includes(data.attribute)))
      .filter(({ attribute: a }) => !excludedFilterList[pageTypeForExcludedFilterList].includes(a))
      .filter((data) => filterTextByOption(data.title, inputTextCopy))      
      .filter(option => !option.features || option.features.some(feature => useFeatures.includes(feature)));

    const filteredUserProperties = filterServerProperties(inputTextCopy, 'userProperties')
    const filteredUserCohorts =  cohortsEnabled ? filterServerProperties(inputTextCopy, 'userCohorts') : []
    const filteredSmartEvents = noCodeFlag ? filterServerProperties(inputTextCopy, 'smartEvents') : []
    const filteredBatchIds = isAISession ? filterServerProperties(inputTextCopy, 'batchIds') : []

    if (segmentType === 'event') filteredEventProperties = filterServerProperties(inputTextCopy, 'eventProperties')
    if(['session', 'user', 'screenFlow', 'event'].includes(segmentType)) filteredEventNames = filterServerProperties(inputTextCopy, 'events')
    if (['session', 'event', 'heatmap', 'screenFlow', 'issue'].includes(segmentType)) filteredCustomLabels = filterServerProperties(inputTextCopy, 'customLabels')
    if (['session', 'user', 'event', 'issue'].includes(segmentType)) filteredUserCustomLabels = filterServerProperties(inputTextCopy, 'userCustomLabels')
    if (['session', 'event'].includes(segmentType)) filteredLandingUtm = filterServerProperties(inputTextCopy, 'utmProperties')

    mutatedFilterOptions = [ ...filteredSelectedKey, ...filteredUserProperties, ...filteredEventNames, ...filteredUserCustomLabels, ...filteredCustomLabels, ...filteredEventProperties, ...filteredUserCohorts, ...filteredSmartEvents, ...filteredLandingUtm, ...filteredBatchIds ];
    if (categoryKeys.includes(inputText)) mutatedFilterOptions = optionWithoutAllFilteredOut[pageType][inputText];

    // get uniq by attribute (for user identity) and ignore for custom labels
    mutatedFilterOptions = uniqBy(mutatedFilterOptions, (obj) => {
      if (obj.isCustomLabel) {
        return obj;
      }
      if (obj.isUserCohort) {
        return obj;
      }
      if (obj.isBatchId) {
        return obj;
      }
      return obj.attribute;
    });
    if (['screenFlow', 'issue', 'event'].includes(segmentType)) {
      mutatedFilterOptions = mutatedFilterOptions.filter(item => item.attribute !== 'rage_quit');
    }
    return mutatedFilterOptions
  }, [optionsWithoutAll, pageType, dropdownOptions, selectedKey, useFeatures, filterServerProperties, cohortsEnabled, noCodeFlag, segmentType, noCodeCheck, pageTypeForExcludedFilterList, excludedFilterList, isAISession]);

  const handleInputChange = (e) => {
    const filterTxt = e.target.value.toLowerCase()
    let filteredOptionsNew = [];

    setFilterText(e.target.value)

    if (filterTxt.length) {
      if (selectedKey === 'All') filteredOptionsNew = allOptionsFilterHandler(e.target.value)
      else if (categoriesExtra.includes(selectedKey)) {
          filteredOptionsNew = matchedFilter?.filter((data) =>
            isCustomLabel || isCohort
              ? filterTextByOption(data.name, filterTxt)
              : isBatchId
                ? filterTextByOption(data.batch_name, filterTxt)
                : filterTextByOption(data, filterTxt)
          )
          // eslint-disable-next-line no-self-assign
          if ( isCohort || isBatchId ) filteredOptionsNew = filteredOptionsNew
          else if (isCustomLabel) filteredOptionsNew = filterServerProperties(filterTxt, 'customLabels')
          else filteredOptionsNew = filteredOptionsNew?.map((attributeKey) => structureData(attributeKey, selectedKey))
      } else {
          filteredOptionsNew = dropdownOptions[selectedKey]
            .filter(
              ({ attribute: a }) =>
                !excludedFilterList[pageTypeForExcludedFilterList].includes(a)
            )
            .filter((data) => filterTextByOption(data.title, filterTxt))
      }
    }
    setFilteredOptions(filteredOptionsNew)
  }

  useEffect(() => {
    setFilteredOptions([])
    setFilterText('')
    resetSearch();
  }, [selectedAttributeProps, selectedKey])

  if (filterText.length) {
    renderList = filteredOptions?.length ? (
      <CommonMapping
        key="list_of_filtered_options"
        listOfAttribute={filteredOptions}
        isArray
        category={selectedKey}
        {...rest}
      />
    ) : (
      noMatchingFilterMenu
    )
  } else if (isAllSelected) {
      let allOptionsConditional = allOptions
      if ( !advancedFiltersAllowed ) allOptionsConditional = pick(allOptions, allowedCategoriesInFreePlan.filter( category => category !== 'All' ) );
      let allOptionsNew = allOptionsConditional;
      if (parentType === 'nocodeEventsList') {
          allOptionsNew = omit(allOptionsNew, ['Event properties'])
        }
        if (parentType === 'eventsList') {
            allOptionsNew = omit(allOptionsNew, ['Smart event properties'])
        }
        if (!noCodeFlag) {
            allOptionsNew = omit(allOptionsNew, ['SmartEvents'])
        }
        if ( cohortsEnabled ) {
            allOptionsNew = {
                ...allOptionsNew,
                Cohorts: userCohorts,
            }
        }
        if ( isAISession && fetchProperty.batch_id?.data?.length && pageType !== 'user' ) {
            allOptionsNew = {
                ...allOptionsNew,
                "Tara's watchlist batches": fetchProperty.batch_id.data.map( b => ({ ...b, isBatchId: true }) ),
            }
        }
    renderList = map(allOptionsNew, (list, key) => {
      const listNew = list?.filter(
        ({ attribute: a }) => !excludedFilterList[pageTypeForExcludedFilterList].includes(a)
      )

      return (
        <MenuItemGroup
          className='menu-list'
          key={key}
          title={
            <div>
              <h4>
                <span>{key}</span>
              </h4>
            </div>
          }
        >
          <CommonMapping
            listOfAttribute={listNew}
            isArray={
              !!isArrayCheck.includes(
                key
              )
            }
            isCustomLabel={key === 'User Labels' || key === 'Session Labels'}
            isUserCohort={key === 'Cohorts'}
            isBatchId={key === "Tara's watchlist batches"}
            category={key}
            isAllSelected={isAllSelected}
            {...rest}
          />
        </MenuItemGroup>
      )
    })
  } else if (categoriesExtra.includes(selectedKey)) {
      renderList = (
        <CommonMapping
          key="list_with_mapped_category_key"
          listOfAttribute={matchedFilter}
          category={selectedKey}
          isAllSelected={isAllSelected}
          isArray={!isCustomLabel}
          isCustomLabel={isCustomLabel}
          {...rest}
        />
      )
    } else {
      // eslint-disable-next-line consistent-return
      renderList = map(dropdownOptions, (options, key) => {
        if (selectedKey === key) {
          const optionsNew = options.filter(
            ( opt ) => !excludedFilterList[pageTypeForExcludedFilterList].includes(opt.attribute ) && ( !Array.isArray( opt.features ) || opt.features.some( feature => useFeatures.includes( feature ) ) )
          )
          return (
            <CommonMapping
              key="list_of_fetched_properties"
              listOfAttribute={optionsNew}
              category={selectedKey}
              {...rest}
            />
          )
        }
      })
    }
  if ( selectedKey === 'Cohorts' ) {
    return (
      <EventMenuItemGroupWrapper
        title={ selectedKey }
        { ...rest }
        id="cohort"
        appId={ urlQuery?.appId }
        parentType={parentType}
      >
        <CohortsMenu
          inputRef={ inputRef }
          value={ searchAttrInputText }
          selectedKey={selectedKey}
          id="menu-selected-key"
          searchText={ searchAttrInputText }
          onChange={ handleInputChange }
          options={ filterText ? filteredOptions : matchedFilter }
          { ...rest }
        />
      </EventMenuItemGroupWrapper>
    )
  }

  if ( selectedKey === "Tara's watchlist batches" ) {
    return (
      <EventMenuItemGroupWrapper
        title={ selectedKey }
        { ...rest }
        id="batch-id"
        appId={ urlQuery?.appId }
        parentType={parentType}
      >
        <CohortsMenu
          inputRef={ inputRef }
          value={ searchAttrInputText }
          selectedKey={selectedKey}
          id="menu-selected-key"
          searchText={ searchAttrInputText }
          onChange={ handleInputChange }
          options={ filterText ? filteredOptions : matchedFilter }
          isBatchId
          { ...rest }
        />
      </EventMenuItemGroupWrapper>
    )
  }

  if (selectedKey === 'Coded events' && noCodeFlag) {
    return (
      <EventMenuItemGroupWrapper
        title={!isAllSelected && selectedKey === 'Coded events' ? 'Events' : selectedKey}
        appId={ urlQuery?.appId }
        parentType={parentType}
        {...rest}
      >
        <EventMenuTab
          eventList={matchedFilter}
          selectedKey={selectedKey}
          id="menu-selected-key"
          inputRef={inputRef}
          value={searchAttrInputText}
          activeEventTab={activeEventTab}
          setActiveEventTab={setActiveEventTab}
          onChange={(e) => {
            handleSearchInputProps(e.target.value);
            setFilterText(e.target.value);
          }}
          handleEventTab={() => {
            resetEventsAndCallApi({ isSearchable: true })
            setFilterText('')
          }}
          {...rest}
        />
      </EventMenuItemGroupWrapper>
    );
  }

  if (selectedKey === 'Events' && noCodeFlag) {
    return (
      <EventMenuItemGroupWrapper
        title={!isAllSelected && selectedKey}
        appId={ urlQuery?.appId }
        parentType={parentType}
        {...rest}
      >
        <EventMenuTab
          eventList={matchedFilter}
          selectedKey={selectedKey}
          id="menu-selected-key"
          inputRef={inputRef}
          value={searchAttrInputText}
          activeEventTab={activeEventTab}
          setActiveEventTab={setActiveEventTab}
          onChange={(e) => {handleSearchInputProps(e.target.value)}}
          handleEventTab={(() => resetEventsAndCallApi({ isSearchable: true }))}
          {...rest} />
      </EventMenuItemGroupWrapper>
    )
  }

  if(selectedKey === 'Session Labels' || selectedKey === 'User Labels') {
    return (
      <TabsMenuItem
        tabs={filteredLabelTabsList}
        selectedKey={selectedKey}
        title={labelsTitle}
        searchInput={{
          placeholder: 'Search',
          value: selectedTabKey === 'session' ? labelSearch.sessionLabels : labelSearch.userLabels,
          onChange: handleSearchChange,
        }}
        handleTabChange={handleTabsChange}
        id="menu-selected-key"
        value={searchAttrInputText}
        {...rest}
      />
    )
  }

  return (
    <MenuItemGroupWrapper
      placeholder="Search"
      value={
        filterStrategyIncluded.includes(selectedKey)
          ? searchAttrInputText
          : filterText
      }
      onChange={(e) => {
        if (filterStrategyIncluded.includes(selectedKey))
          handleSearchInputProps(e.target.value)
        else handleInputChange(e)
      }}
      title={!isAllSelected && selectedKey}
      id="menu-selected-key"
      inputRef={inputRef}
      {...rest}
    >
      {renderList}
    </MenuItemGroupWrapper>
  )
})
export default withContextProps(SecondLevelMenu)
