import React, {
  createContext,
  useContext,
  useState,
  ReactNode,
  useMemo,
} from 'react';

export type cohortFilterType = {
  attribute: string;
  operator: string;
  value: any;
  table: string;
}[];

interface MassUserIdFilterContextType {
  showPartialCohortSaved: boolean;
  setShowPartialCohortSaved: (v: boolean) => void;
  showNoCohortSaved: boolean;
  setShowNoCohortSaved: (v: boolean) => void;
  showCohortLimitReached: boolean;
  setShowCohortLimitReached: (v: boolean) => void;
  totalIds: number;
  setTotalIds: (v: number) => void;
  addedIds: number;
  setAddedIds: (v: number) => void;
  cohortFilter: cohortFilterType;
  setCohortFilter: (v: cohortFilterType) => void;
  showMassUserIdFilterCtx: boolean;
  setShowMassUserIdFilterCtx: (v: boolean) => void;
  reset: () => void;
}

const MassUserIdFilterContext = createContext<
  MassUserIdFilterContextType | undefined
>(undefined);

export const useMassUserIdFilterContext = () => {
  const ctx = useContext(MassUserIdFilterContext);
  if (!ctx)
    throw new Error(
      'useMassUserIdFilterContext must be used within MassUserIdFilterProvider'
    );
  return ctx;
};

export const MassUserIdFilterProvider = ({
  children,
}: {
  children: ReactNode;
}) => {
  const [showPartialCohortSaved, setShowPartialCohortSaved] = useState(false);
  const [showNoCohortSaved, setShowNoCohortSaved] = useState(false);
  const [showCohortLimitReached, setShowCohortLimitReached] = useState(false);
  const [totalIds, setTotalIds] = useState(0);
  const [addedIds, setAddedIds] = useState(0);
  const [cohortFilter, setCohortFilter] = useState<cohortFilterType>([]);
  const [showMassUserIdFilterCtx, setShowMassUserIdFilterCtx] = useState(false);
  const reset = () => {
    setShowPartialCohortSaved(false);
    setShowNoCohortSaved(false);
    setShowCohortLimitReached(false);
    setTotalIds(0);
    setAddedIds(0);
    setCohortFilter([]);
    setShowMassUserIdFilterCtx(false);
  };
  const contextValue = useMemo(
    () => ({
      showPartialCohortSaved,
      setShowPartialCohortSaved,
      showNoCohortSaved,
      setShowNoCohortSaved,
      showCohortLimitReached,
      setShowCohortLimitReached,
      totalIds,
      setTotalIds,
      addedIds,
      setAddedIds,
      cohortFilter,
      setCohortFilter,
      showMassUserIdFilterCtx,
      setShowMassUserIdFilterCtx,
      reset,
    }),
    [showPartialCohortSaved, showNoCohortSaved, showCohortLimitReached, totalIds, addedIds, cohortFilter, showMassUserIdFilterCtx]
  );
  return (
    <MassUserIdFilterContext.Provider value={contextValue}>
      {children}
    </MassUserIdFilterContext.Provider>
  );
};
