import { useMemo } from "react";
import { useSelector } from "react-redux";

const DROPDOWNLIMIT = 501;

export const useEventPropertySearchPayload = ({ filterData, searchInput, propertyName }) => {
  const {
    urlReducer: { appId },
    appFilter: { dateSegment },
  } = useSelector((state) => state);

  const { filters } = filterData;

  const filter = useMemo(() => filters?.length ? filters.map(data => ({...data, 'table': 'event'})): [], [filters]);

  const payload = useMemo(() => ({
    appid: appId,
    date_range: dateSegment,
    search: searchInput,
    filter,
    attribute: 'event_custom_property',
    property_name: propertyName || '',
    dropdownLimit: DROPDOWNLIMIT,
    table: 'event'
  }), [appId, dateSegment, filter, propertyName, searchInput])


  return { payload };
}