import React, { memo } from 'react';
import { useSelector } from 'react-redux'
import Link from 'next/link'
import { Button } from 'antd'
import { SettingOutlined } from '@ant-design/icons'

const ConfigureNotificationsButton = () => {
  const { orgId: org, _id: app } = useSelector(
    (state) => state.currentAppReducer
  )
  return (
    <Link
      href={{
        pathname: '/integration',
        query: {
          parentType: 'settings',
          setting: 'app_setting',
          org,
          app,
          app_tab: 'issue_notification',
        },
      }}
      as={`/settings/app/${org}/${app}/issue_notification`}
      passHref
    >
      <Button type='text' icon={<SettingOutlined />} className='configure-btn'>
        Configure notifications
      </Button>
    </Link>
  )
}
export default memo(ConfigureNotificationsButton)
