import { useMemo } from "react";
import { useSelector } from "react-redux";
import clone from 'lodash/clone';
import { mappedSegmentType } from "Utils/helpers/commonUtils";

export const useGestureAttribute = ({ attribute, searchInput }) => {
  const {
    urlReducer: { appId , parentType },
    appFilter,
  } = useSelector((state) => state);

  const { dateSegment } = appFilter;
  const segmentType = mappedSegmentType[parentType];

  const filterSegment = clone(appFilter[segmentType].segment)
  const { filters } = filterSegment;

  const filter = useMemo(() => filters?.length ? filters.map(data => ({...data, 'table': 'session'})): [], [filters]);

  const payload = useMemo(() => ({
    appid: appId,
    date_range: dateSegment,
    dropdownLimit: 501,
    search: searchInput,
    filter,
    attribute,
    table: 'gesture'
  }), [appId, attribute, dateSegment, filter, searchInput]);

  return { payload };
}