/* eslint-disable camelcase */
import React, { useState, useMemo, useRef, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import invert from 'lodash/invert';
import Highcharts from 'highcharts';
import HighchartsSankey from 'highcharts/modules/sankey';
import HCExporting from 'highcharts/modules/exporting';
import HighchartsOfflineExporting from 'highcharts/modules/offline-exporting';
import HCExportingData from 'highcharts/modules/export-data';
import HighchartsReact from 'highcharts-react-official';

import { exportingConfig } from 'components/features/navigation/utils';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import { compactNotation } from 'Utils/helpers/commonUtils';
import { useAppNavigationContextContext } from 'components/features/navigation/Context'
import { trackPageViews } from 'redux/actions/trackingReport';
import { useIsAppType } from 'hooks/useIsAppType';

export const NO_SCREEN_URL =
  'https://s3.amazonaws.com/static.uxcam.com/staticscreenshots/screen-404.png';

if (typeof Highcharts === 'object') {
  HCExporting(Highcharts);
  HCExportingData(Highcharts);
  HighchartsSankey(Highcharts);
  HighchartsOfflineExporting(Highcharts);
}

// on top
if (typeof Highcharts === 'object') {
  (function (H) {
    H.wrap(H?.seriesTypes?.sankey?.prototype, 'createNodeColumn', function (p) {
      const column = p.apply(this, Array.prototype.slice.call(arguments, 1));

      column.top = function () {
        return 0;
      };
      return column;
    });
  })(Highcharts);
  const H = Highcharts;
  H.seriesTypes.sankey.prototype.pointAttribs = function (point, state) {
    let opacity = this.options.linkOpacity;
    let { color } = point;

    if (state) {
      opacity = this.options.states[state].linkOpacity || opacity;
      color = this.options.states[state].color || point.color;
    }

    return {
      fill: point.isNode
        ? color
        : {
            linearGradient: {
              x1: 0,
              x2: 1,
              y1: 0,
              y2: 0,
            },
            stops: [
              [0, H.color(color).setOpacity(opacity).get()],
              [1, H.color(point.toNode.color).setOpacity(opacity).get()],
            ],
          },
    };
  };
}
const launchQuitOthers = ['Launch', 'Others'];

const useScreenFlow = () => {
  const dispatch = useDispatch()
  const { inverted } = useAppNavigationContextContext()
  const { appId } = useSelector((state) => state.urlReducer);
 
  const { screenFlowPlotGraph: plotGraph } = useSelector( (state) => state.screenDetailReducer );
  const screenRenamedList = useSelector((state) => state.screenRenamedList);
  const { screenFlow: { segment },  dateSegment: dateRange } = useSelector((state) => state.appFilter);
  const { credits, title, series, plotOptions } = plotGraph || {};
  const [toggleFlag, setToggleFlag] = useState(false);

  const isWebApp = useIsAppType('web')

  const nodePointRef = useRef(null);
  const htmlPointRef = useRef(null);

  const collapseTooltipEl = useMemo(
    () => `
      <p style='border-top: 1px solid #C0CAD9; margin: 5px -8px 5px; padding-top: 10px; text-align: center;'>
        Click to ${toggleFlag ? 'collapse' : 'show'} screenshot
      </p>`,
    [toggleFlag]
  );

  const getURL = useCallback(
    (key, screenName, nextScreen) => {
      let currentScreenName = screenName;
      let nextScreenName = nextScreen?.trim();
      if (nextScreenName === 'Quit') nextScreenName = 'Exit';
      if (currentScreenName === 'Quit') currentScreenName = 'Exit';
      const originalScreen =
        invert(screenRenamedList)[currentScreenName] || currentScreenName;
      const originalNextScreen =
        invert(screenRenamedList)[nextScreenName] || nextScreenName;

      if (!originalScreen) return '';
      const isLaunchOrQuitOrOthers =
        launchQuitOthers.includes(originalNextScreen);
      let screenNameWithoutSlash = originalScreen?.includes('/')
        ? originalScreen.split('/').join('')
        : originalScreen;
      screenNameWithoutSlash = screenNameWithoutSlash.includes(' ')
        ? screenNameWithoutSlash.split('/').join('')
        : originalScreen;
      let url = `${
        process.env.REDIRECT_URL
      }/app/${appId}/screens/details/${encodeURIComponent(
        screenNameWithoutSlash
      )}/${key}?`;
      url = urlSegmentEncoder(url, [
        ...segment,
        ...(originalNextScreen && !isLaunchOrQuitOrOthers
          ? [
              {
                attribute: 'next_screen_name',
                operator: 'in',
                value: [originalNextScreen],
              },
            ]
          : []),
          ...[{ ...dateRange }]
      ]);
      url = `${url}&screenname=${encodeURIComponent(originalScreen)}`;
      return url;
    },
    [appId, dateRange, screenRenamedList, segment]
  );

  const links = useCallback(
    (screenName, nextScreen) => {
      let screenNameCopy = screenName;
      let nextScreenCopy = nextScreen;
      if (inverted && nextScreen) {
        screenNameCopy = nextScreen;
        nextScreenCopy = screenName;
      }
      const isLaunchOrQuitOrOthers = launchQuitOthers.includes(screenNameCopy);
      const disableHeatmapRedirection = segment?.some((seg) => seg?.attribute === 'screen_name');
      const disableClass = isLaunchOrQuitOrOthers || disableHeatmapRedirection ? 'disabled' : '';
      const sessionURL = getURL(
        'screenvisits',
        screenNameCopy,
        !isLaunchOrQuitOrOthers ? nextScreenCopy : null
      );
      const heatmapURL = getURL(
        'heatmaps',
        screenNameCopy,
        !isLaunchOrQuitOrOthers ? nextScreenCopy : null
      );
      return `<div><div class='screen-redirect-links'>
                    ${sessionURL
          ? `<div class="sunburst-chart-tooltip-btn">
                        <a id="btn-stop" class="${disableClass}" href=${disableClass ? "" : sessionURL} target="_blank">
                            <button id="btn-stop" class="btn screen-flow-tooltip-btn replay-sessions ${disableClass}">
                                <svg
                                  xmlns="http://www.w3.org/2000/svg"
                                  width="11"
                                  height="10"
                                  fill="none"
                                  viewBox="0 0 11 10"
                                  class="btn-icon"
                                >
                                <path
                                  fill="#fff"
                                  d="M9.642 4.421L.938.067A.65.65 0 000 .65v8.7a.65.65 0 00.938.584L9.642 5.58a.646.646 0 000-1.159z"
                                />
                                </svg> Replay Sessions
                            </button>
                            ${ disableHeatmapRedirection ? `<span class="screenname-tooltip disabled left">
                                The screen name filter isn’t supported on the Heatmaps page,<span>please remove it and try again.</span>
                            </span>` : '' }
                          </a>
                    </div>`
          : ''
        }
                    ${heatmapURL
          ? `<div class="sunburst-chart-tooltip-btn">
                          <a id="btn-stop" class="${disableClass}" href=${disableClass ? "" : heatmapURL} target="_blank">
                            <button id="btn-stop" class="btn screen-flow-tooltip-btn show-heatmap ${disableClass}">
                              <svg
                                xmlns="http://www.w3.org/2000/svg"
                                width="8"
                                height="12"
                                fill="none"
                                viewBox="0 0 8 12"
                                class="btn-icon"
                              >
                              <path
                                fill="#fff"
                                d="M6.5 0h-5A1.5 1.5 0 000 1.5v9A1.5 1.5 0 001.5 12h5A1.5 1.5 0 008 10.5v-9A1.5 1.5 0 006.5 0zM4 11.235a.5.5 0 110-1 .5.5 0 010 1zM7 9a.5.5 0 01-.5.5h-5A.5.5 0 011 9V1.765a.5.5 0 01.5-.5h5a.5.5 0 01.5.5V9z"
                              />
                              </svg> Show Heatmap
                              </button>
                              ${ disableHeatmapRedirection ? `<span class="screenname-tooltip disabled right">
                                The screen name filter isn’t supported on the Heatmaps page,<span>please remove it and try again.</span>
                            </span>` : '' }
                          </a>
                    </div>`
          : ''
        }
                </div>
                </div>`;
    },
    [getURL, inverted, segment]
  );

  const screenTooltip = useCallback(
    (screenname) => {
      const length = toggleFlag ? 26 : 20;
      const showTooltip = screenname?.length > length;
      return `<h3>${screenname}</h3>
              <span class=${showTooltip ? 'screenname-tooltip' : ''}>
                 ${showTooltip ? screenname : ''}
              </span>`;
    },
    [toggleFlag]
  );

  const nodeFormatter = useCallback(
    function () {
      nodePointRef.current = this;
      const { id, link, sum, linksTo } = this;
      let imgSrc = link;
      if (!imgSrc) imgSrc = linksTo[0]?.to_link ? linksTo[0].to_link  : '';
      const screenname = id.trim();
      const buttons = `
        <div class='screen-flow-btn'>
          ${links(screenname)}
          ${collapseTooltipEl}
        </div>
      `;
      if( isWebApp ) {
        return `
          <div class="sankey-tooltip-box web">
            <div class="tooltip-head">${screenTooltip(screenname)}</div>
            <div class="tooltip-foot">
              <h4>${compactNotation(sum)}</h4>
              <p>Visits</p>
            </div>
          </div>
        `
      }
      return toggleFlag
        ? `<div class="sankey-tooltip-box">
            <div class="screen-item">
              <div class="tooltip-head">${screenTooltip(screenname)}</div>
              ${
                imgSrc ? (
                    `<div class="tooltip-img">
                      <img src=${imgSrc} loading='lazy' />
                    </div>`
                  ) : `
                    <div class="tooltip-img-loading" >
                      <img src=${NO_SCREEN_URL} loading='lazy' fetchpriority="high"/>
                    </div>
                  `
                }
              <div class="tooltip-foot">
                <h4>${compactNotation(sum)}</h4>
                <p>Visits</p>
              </div>
            </div>
            ${buttons}
          </div>`
        : `<div class="mini-tooltip">
            <h3>${screenname}</h3>
            <h4 class='screen-visits-sum'>Visits: ${compactNotation(sum)}</h4>
            ${buttons}
          </div>`;
    },
    [collapseTooltipEl, isWebApp, links, screenTooltip, toggleFlag]
  );

  const pointFormatter = useCallback(
    function () {
      htmlPointRef.current = this;
      const {
        to_name: nextScreen,
        from_name,
        // to_step,
        // from_step,
        to_link,
        from_link,
        to_visits,
        from_visits,
        to_trans_rel,
        from_trans_rel,
        weight,
      } = this;

      const screenname = from_name.trim();
      const from_image = from_link ? from_link : '';
      const to_image = to_link ? to_link : '';
      const buttons = `
        <div class='screen-flow-btn'>
          ${links(screenname, nextScreen)}
          ${collapseTooltipEl}
        </div>
      `;

      if( isWebApp ) {
        return `
          <div class="sankey-tooltip-box web">
            <div class="tooltip-head">${screenTooltip(screenname)}</div>
            <div class="tooltip-foot">
              <h4>${from_visits}</h4>
              <p>Visits</p>
            </div>
          </div>
          <div class="sankey-tooltip-body web ${ inverted ? 'inverted' : ""}">
            <svg width="6" height="120" viewBox="0 0 6 120" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M3.00001 120L5.88676 115L0.113254 115L3.00001 120ZM2.5 2.18557e-08L2.50001 115.5L3.50001 115.5L3.5 -2.18557e-08L2.5 2.18557e-08Z" fill="#32BF8A"/>
            </svg>
            <div class="tooltip-content-wrapper">
              <h3>${(inverted ? to_trans_rel : from_trans_rel)}</h3>
              <p>${(inverted ? to_trans_rel : from_trans_rel)} of visits continued to next screen</p>
              <h4>${compactNotation(weight)} transitions</h4>
            </div>
          </div>
          <div class="sankey-tooltip-box web">
            <div class="tooltip-head">${nextScreen}</div>
            <div class="tooltip-foot">
              <h4>${to_visits}</h4>
              <p>Visits</p>
            </div>
          </div>
          </div>
        `;
      }
      return toggleFlag
        ? `<div id="toggle-tooltip" class="sankey-tooltip-box ${
            inverted ? 'reverse-flow' : ''
          }">
            <div class="point-tooltip-wrapper">
              <div class="screen-item">
                <div class="tooltip-head">
                  ${screenTooltip(screenname)}
                </div>
                ${
                  from_image ? (
                      `<div class="tooltip-img">
                        <img src=${from_image} loading='lazy' />
                      </div>`
                    ) : `
                      <div class="tooltip-img-loading" >
                        <img src=${NO_SCREEN_URL} loading='lazy' fetchpriority="high" />
                      </div>
                    `
                  }
                <div class="tooltip-foot">
                  <h3>${from_visits}</h3>
                  <p>Visits</p>
                </div>
              </div>
              <div class="screen-item screen-item-separator">
                <div class="arrow-top">
                  <div class="block-vertical">
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="5"
                      height="56"
                      viewBox="0 0 5 56"
                    >
                      <path d="M0,0H0A5,5,0,0,1,5,5V51a5,5,0,0,1-5,5H0a0,0,0,0,1,0,0V0A0,0,0,0,1,0,0Z" />
                    </svg>
                  </div>
                  <div class="arrow-content">
                    <p>${
                      plotGraph && (inverted ? to_trans_rel : from_trans_rel)
                    }</p>
                    <svg
                      width="46"
                      height="11"
                      viewBox="0 0 46 11"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                    >
                      <path
                        d="M39.842 9.36206L42.663 6H0V4H42.12L39.843 1.28601L41.374 0L45.656 5.09998L45.873 5.28198L45.841 5.31995L45.873 5.35803L45.656 5.54004L41.374 10.64L39.842 9.36206Z"
                        fill="black"
                      />
                    </svg>
                  </div>
                </div>
                <div class="arrow-bottom">
                  <div class="block-vertical">
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="5"
                      height="56"
                      viewBox="0 0 5 56"
                    >
                      <path d="M5,0H5A0,0,0,0,1,5,0V56a0,0,0,0,1,0,0H5a5,5,0,0,1-5-5V5A5,5,0,0,1,5,0Z" />
                    </svg>
                  </div>
                  <div class="arrow-content">
                    <p> ${
                      plotGraph && (inverted ? from_trans_rel : to_trans_rel)
                    } </p>
                    <svg
                      width="46"
                      height="11"
                      viewBox="0 0 46 11"
                      fill="none"
                      xmlns="http://www.w3.org/2000/svg"
                    >
                      <path
                        d="M39.842 9.36206L42.663 6H0V4H42.12L39.843 1.28601L41.374 0L45.656 5.09998L45.873 5.28198L45.841 5.31995L45.873 5.35803L45.656 5.54004L41.374 10.64L39.842 9.36206Z"
                        fill="black"
                      />
                    </svg>
                  </div>
                </div>
                <div class="arrow-transition">
                  <h4>${compactNotation(weight)}</h4>
                  <svg
                    width="46"
                    height="11"
                    viewBox="0 0 46 11"
                    fill="none"
                    xmlns="http://www.w3.org/2000/svg"
                  >
                    <path
                      d="M39.842 9.36206L42.663 6H0V4H42.12L39.843 1.28601L41.374 0L45.656 5.09998L45.873 5.28198L45.841 5.31995L45.873 5.35803L45.656 5.54004L41.374 10.64L39.842 9.36206Z"
                      fill="black"
                    />
                  </svg>
                  <p>Transitions</p>
                </div>
              </div>
              <div class="screen-item">
                <div class="tooltip-head">
                  ${screenTooltip(nextScreen)}
                </div>
                ${
                  to_image ? (
                      `<div class="tooltip-img">
                        <img src=${to_image} loading='lazy' />
                      </div>`
                    ) : `
                      <div class="tooltip-img-loading" >
                       <img src=${NO_SCREEN_URL} loading='lazy' fetchpriority="high" />
                      </div>
                    `
                  }
                <div class="tooltip-foot">
                  <h3>${to_visits}</h3>
                  <p>Visits</p>
                </div>
              </div>
            </div>
            ${buttons}
          </div>`
        : `<div id="toggle-tooltip" class="mini-tooltip">
              <div class="box-wrapper">
                <div class="left-box">${screenTooltip(screenname)}</div>
                <div class="middle-box">
                  <h5>${compactNotation(weight)}</h5>
                  <span class=${inverted ? 'arrow-reserved-sm' : ''}>
                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="40"
                      height="10.648"
                      viewBox="0 0 63.873 10.648"
                    >
                      <path
                        style="fill:#161E35;"
                        d="M42.842-1050.638,45.663-1054H-15v-2h60.12l-2.277-2.714L44.374-1060l4.282,5.1.217.182-.032.038.032.038-.217.182-4.282,5.1Z"
                        transform="translate(15 1060)"
                      />
                    </svg>
                  </span>
                </div>
                <div class="left-box">${screenTooltip(nextScreen)}</div>
              </div>
              ${buttons}
            </div>`;
    },
    [collapseTooltipEl, inverted, isWebApp, links, plotGraph, screenTooltip, toggleFlag]
  );
  const plotOptionsMutated = useMemo(
    () => ({
      ...plotOptions,
      series: {
        ...plotOptions?.series,
        dataLabels: {
          ...plotOptions?.series.dataLabels,
          allowOverlap: true,
          padding: 1,
          align: 'center',
          style: {
            fontSize: 11,
            fontWeight: 400,
            ...(isWebApp && {
              textOverflow: 'ellipsis',
              overflow: 'hidden',
              whiteSpace: 'nowrap',
              width: '200px',
            })
          },
          nodeFormatter() {
            const { point } = this;
            return `${point.name} : ${compactNotation(point.sum)}`;
          },
        },
        point: {
          cursor: 'pointer',
          events: {
            click() {
              setToggleFlag((flag) => !flag);
            },
          },
        },
      },
    }),
    [plotOptions, isWebApp]
  );

  const tooltip = useMemo(() => ({
    useHTML: true,
    // style: { opacity: !toggleFlag ? '1' : '0.7' },
    borderWidth: 0,
    backgroundColor: '#fff',
    nodeFormatter,
    pointFormatter,
    followTouchMove: true,
    animation: true,
    followPointer: false,
    stickOnContact: true,
    hideDelay: 500,
  }), [nodeFormatter, pointFormatter])

  const options = useMemo(() => {
    const chart = {
      events: {
        click(e) {
          if (e.target.className === 'btn screen-flow-tooltip-btn replay-sessions ') {
            dispatch(
              trackPageViews(null, {
                eventName: 'click_on_view_sessions',
                track_type: 'event',
                eventProperty: {
                  page: 'app navigation',
                  description: 'User clicks on view sessions in screenflow',
                },
              })
            );
          }
          if (e.target.className === 'btn screen-flow-tooltip-btn show-heatmap ') {
            dispatch(
              trackPageViews(null, {
                eventName: 'clicke_on_show_heatmap',
                track_type: 'event',
                eventProperty: {
                  page: 'app navigation',
                  description: 'User clicks on show heatmap in screenflow',
                },
              })
            );
          }
          if (e.target.id === 'btn-stop') return;
          setToggleFlag((flag) => !flag);
        },
      },
    };
    return {
      chart,
      credits,
      plotOptions: plotOptionsMutated,
      series,
      title,
      tooltip,
      ...exportingConfig,
    };
  }, [credits, plotOptionsMutated, series, title, tooltip]);
  return options
}

const ScreenFlowGraph = ({ chartRef }) => {
  const { parentType } = useSelector((state) => state.urlReducer);
  const { bottomBarClassFlag } = useSelector((state) => state.commonReducer)

  const options = useScreenFlow()

  const defaultClass = useMemo(
    () =>
      bottomBarClassFlag && parentType !== 'usersList'
        ? 'screen-flow-chart-classic'
        : 'screen-flow-chart',
    [bottomBarClassFlag, parentType]
  );

  const className = useMemo(
    () =>
      parentType === 'usersList' ? 'screen-flow-chart-user' : defaultClass,
    [defaultClass, parentType]
  );

  return (
    <div className="screen-flow-wrapper">
      <HighchartsReact
        ref={chartRef}
        constructorType="chart"
        highcharts={Highcharts}
        options={options}
        containerProps={{ className }}
      />
    </div>
  );
};
export default ScreenFlowGraph
