/* eslint-disable import/no-cycle */
import React, { useState, memo, useEffect } from 'react';
import { useSelector, useDispatch } from 'react-redux'
import { Button } from 'antd'
import { SearchOutlined } from '@ant-design/icons'
import { clone, findIndex } from 'lodash'
import { trackPageViews } from 'redux/actions/trackingReport';
import useAppFilter from './useAppFilter'
import { DebounceInputComponent } from './CommonComponentsV2'

const placeholder = `Search users`
const FilterSearch = () => {
  const dispatch = useDispatch()
  const { callListApi, segmentType } = useAppFilter()
  const appFilter = useSelector((state) => state.appFilter)
  const [inputVisible, setInputVisible] = useState(false)
  const filterSegment = appFilter[segmentType].segment
  const [filterInputText, setFilterInputText] = useState('')
  const callApi = async (segment) => {
    callListApi(segment)
    setFilterInputText('')
    setInputVisible(false)
    dispatch(trackPageViews(null, {
      eventName: `search_users`,
      track_type: 'event',
      eventProperty: {
        searchTerm: filterInputText,
      }
    }))
  }
  const handleInputChange = (e) => {
    const segmentCloned = clone(filterSegment)
    const attribute = 'uxcamuserid'
    const indexCopy = findIndex(segmentCloned, { attribute })
    setFilterInputText(e.target.value)
    if (indexCopy > -1 && !e.target.value) onPressEnter(e)
  }
  const onPressEnter = (e) => {
    let segmentCloned = clone(filterSegment)
    const attribute = 'uxcamuserid'
    const indexCopy = findIndex(segmentCloned, { attribute })
    if (!e.target.value) {
      if (indexCopy > -1) segmentCloned = segmentCloned.filter(v => v.attribute !== attribute)
    } else {
      const inputSegment = {
        attribute: 'uxcamuserid',
        operator: 'contains',
        value: e.target.value,
        table: 'appuser'
      }
      if (indexCopy > -1) segmentCloned[indexCopy] = inputSegment
      else segmentCloned = [...segmentCloned, ...[inputSegment]]
    }
    callApi(segmentCloned)
  }
  useEffect(() => {
    setFilterInputText('')
    return () => {
      setFilterInputText('')
    }
  }, [])
  if (inputVisible) {
    return (
      <span className='mega-filter-search'>
        <DebounceInputComponent
          suffix={<SearchOutlined />}
          placeholder={placeholder}
          onChange={handleInputChange}
          value={filterInputText}
          onPressEnter={onPressEnter}
          onBlur={() => inputVisible && setInputVisible(false)}
        />
      </span>
    )
  }
    return (
      <Button
        onClick={() => setInputVisible(true)}
        ghost
        size='large'
        type='text'
        icon={<SearchOutlined />}
        className='filter-search-btn'
      />
    )
}
export default memo(FilterSearch)
