import React from 'react'
import { Cell } from "components/features/aiSessions/hooks/useAISessionColumns"
import styled from 'styled-components'
import GesturesIcon from 'public/static/sessions/gesturesIcon.svg'
import RageTapsIcon from 'public/static/sessions/rageTapsNoBackground.svg'
import AppCrashIcon from 'public/static/sessions/appCrashNoBackground.svg'
import UIFreezeIcon from 'public/static/sessions/uiFreezesNoBackground.svg'
import WebClickIcon from 'public/static/sessions/webClickIcon.svg'
import WebPageRefreshIcon from 'public/static/sessions/webPageRefresh.svg'
import DeadClickIcon from 'public/static/sessions/deadclickIcon.svg'
import { useIsAppType } from 'hooks/useIsAppType'
import { themeCommon } from 'theme/theme'

interface IProps {
	gestures?: number
	isRageTap?: boolean
	isAppCrash?: boolean
	isUIFreeze?: boolean
}

const Interactions = styled.div`
	display: flex;
	gap: 8px;
`

const InteractionWithValue = styled.div`
	width: 50px;
	display: flex;
	gap: 2px;
`

const Interaction = styled.div`
	display: flex;
	gap: 2px;
`

const Icon = styled.div`
	height: 16px;
	width: 16px;
	&[ data-inactive='true' ] {
		svg path {
			fill: #E8E8EB80 !important;
		}
	}
`

const Value = styled.span``

const InteractionsCell = ( { gestures, isRageTap, isAppCrash, isUIFreeze }: IProps ) => {
	const isWeb = useIsAppType( 'web' )

	return (
		<Cell>
			<Interactions>
				<InteractionWithValue>
					<Icon>
						{ isWeb ? <WebClickIcon /> : <GesturesIcon /> }
					</Icon>
					<Value>
						{ gestures !== undefined ? gestures : '-' }
					</Value>
				</InteractionWithValue>
				<Interaction>
					<Icon data-inactive={ !isRageTap }>
						<RageTapsIcon />
					</Icon>
				</Interaction>
				<Interaction>
					<Icon data-inactive={ !isAppCrash }>
						{ isWeb
							? <WebPageRefreshIcon style={ { color: '#DC4F44' } } />
							: <AppCrashIcon />
						}
					</Icon>
				</Interaction>
				<Interaction>
					<Icon data-inactive={ !isUIFreeze }>
						{ isWeb
							? <DeadClickIcon style={ { color: themeCommon.color.Surface400 } } />
							: <UIFreezeIcon />
						}
					</Icon>
				</Interaction>
			</Interactions>
		</Cell>
	)
}

export default InteractionsCell