/* eslint-disable no-prototype-builtins */
import React, { useState, useEffect, useMemo, memo, useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { findIndex, clone } from 'lodash';
import { Button, Col, Tooltip } from 'antd';
import styled from 'styled-components';
import { InfoCircleOutlined, PlusOutlined } from '@ant-design/icons';
import { OperatorMenu } from 'components/shared/GlobalFilter/components/CommonComponentsV2';
import {
  mappedOperator,
  notInOperators,
  singleValueType,
} from 'components/shared/GlobalFilter/components/utils';
import {
  allFilters,
  operator,
} from 'components/shared/GlobalFilter/components/data-structures-v2';
import { MinusBtnSVG } from 'components/svg_files';
import {useFilterOptionType, useUserV2Properties} from 'hooks/useUserV2Filter';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { useIsAppType } from 'hooks/useIsAppType';
import { updateActivityFilterSegment } from 'redux/actions/megaFilter';
import { getActivityFilterPropertyId } from 'Utils/helpers/useActivityFilterValidator';
import screenVisitProperties from "../../data-structures-v2/Heatmaps/ScreenVisit.json";
import FilterValue from './FilterValue';
import { EventOperator , ActivityFilterEventOperator} from './EventOperator';
import ScreenFilterWithSequence from './ScreenFilterWithSequence';
import EventFilterOperator from './NestedFiltering/EventProperties/EventFilterOperator';
import EventFilterBlock from './NestedFiltering/EventFilterBlock';
import GestureFilterBlock from './NestedFiltering/GestureFilterBlock';
import EventActivityFilterValue from '../ActivityFilter/EventActivityFilterValue';
import { getActivityPropertiesListByAttribute } from '../ActivityFilter/constants';

const StyledEventNestedDiv = styled.div`
  margin-bottom: 2px;
`;

const WHEREAND = styled.div`
 border-radius: 3px;
 background-color: #F3F4F5;
 padding: 2px 4px;
 display: inline-block;
 font-size:12px !important;
` 
const InfoCircleOutlinedSpan = styled(InfoCircleOutlined)`
  svg {
    color: #5D97FF;
    margin-left: 6px;
    font-size: 16px;
  }
`;

const AppliedFilter = (props) => {
  const {
    filterData,
    callListApi,
    handleFilterDelete,
    pageType,
    segmentType,
    filterSegment,
    isActivityFilter,
    activityFilterConfiguration = {}
  } = props;
  const {
    appFilter,
    screenRenamedList,
    commonReducer: { eventPropertyList },
    urlReducer: { parentType },
    screenDetailReducer: { noCodeFlag },
  } = useSelector((state) => state);
  const {activityFilterIndex , activityPropertyIndex, activityFilterAttribute} = activityFilterConfiguration;
  const filterSegmentBySegmentType = isActivityFilter ?
  appFilter[segmentType].activityFilterList[activityFilterIndex].filters :
  appFilter[segmentType].segment;

  const filterSegmentDuplicate = filterSegment;

  const {
    attribute,
    operator: filterOperator,
    value,
    property,
    property_name: propertyName,
    has_sequence: hasSequence,
    table
  } = filterData;

  const isSequence = hasSequence === 'true';
  const isNestedEvent = useMemo(()=> 
    attribute === 'event_count_per_screen_visit' ||
    attribute === 'smart_event_count_per_screen_visit', 
  [attribute] ) ;
  const isNestedGesture = useMemo(()=> attribute === 'gesture_count_per_screen_visit', [attribute] ) ;
  const [eventPropertyVisibility, toggleEventPropertyVisibility] =
    useState(false);
  const [whereClicked, setWhereClicked] = useState(false);
  const [operatorType, setOperatorType] = useState('');
  const [operatorData, setOperatorData] = useState({});
  const [propName, setPropertyName] = useState();
  const [propValue, setPropertyValue] = useState();
  const [editFieldVisibility, toggleEditFieldVisibility] = useState(false);
  const [propFieldVisibility, togglePropFieldVisibility] = useState(false);
  const [propertyOperator, setPropertyOperator] = useState({
    attribute: attribute === 'screen_name' ? 'in' : filterOperator,
    isSearchable: true,
  });
  const [eventFilterOperator, setEventFilterOperator] = useState({
    attribute: filterOperator,
    isSearchable: true,
  });
  const [operatorChangeData, setOperatorChangeData] = useState();
  const [attributeProps, setAttributeProps] = useState({});

  const allFiltersCloned = JSON.parse(JSON.stringify(allFilters));
  const filterOptionType = useFilterOptionType(parentType)
  const mappedAllFilters = useMemo(()=> isActivityFilter ? getActivityPropertiesListByAttribute(activityFilterAttribute) : allFiltersCloned[filterOptionType], 
    [isActivityFilter, activityFilterAttribute, allFiltersCloned, filterOptionType]);
  const dispatch = useDispatch()
  const filterIndex = isActivityFilter ? activityPropertyIndex : filterSegmentBySegmentType.indexOf(filterData);
  const isWeb = useIsAppType('web')

  const showAddCondition = useMemo(() => 
    attribute === 'event_name' || ( attribute === 'screen_name' && isWeb ), 
  [attribute, isWeb]);

  const {getQueryPrefix} = useUserV2Properties();
  const handleEventOperatorChange = useCallback(
    (valueData) => {
      setPropertyOperator((prevValue) => ({ ...prevValue, attribute: valueData }));
      filterSegmentBySegmentType[filterIndex].operator = valueData;

      if(isActivityFilter){
        dispatch(updateActivityFilterSegment(filterSegmentBySegmentType, activityFilterIndex))
        callListApi();
      }else{
          callListApi(filterSegmentBySegmentType);
        }
    },
    [activityFilterIndex, callListApi, dispatch, filterIndex, filterSegmentBySegmentType, isActivityFilter]
  );
  const handleEventNameOperatorChange = useCallback(
    (valueData) => {
      setPropertyOperator((prevValue) => ({ ...prevValue, attribute: valueData }));
      filterSegmentBySegmentType[filterIndex].filters[0].operator = valueData?.attribute;
      callListApi(filterSegmentBySegmentType, callListApi);
    },
    [callListApi, filterIndex, filterSegmentBySegmentType]
  );

  const handleEventFilterOperatorChange = useCallback(
    (valueData) => {
      setEventFilterOperator((prevValue) => ({
        ...prevValue,
        attribute: valueData,
      }));
      filterSegmentBySegmentType[filterIndex].operator = valueData;
      callListApi(filterSegmentBySegmentType);
    },
    [callListApi, filterIndex, filterSegmentBySegmentType]
  );
  const handleWithOrWithoutEventChange = useCallback(
    (valueData) => {
      filterSegmentBySegmentType[filterIndex].operator = valueData === 'with_out' ? 'equal': 'greater_or_equal' ;
      filterSegmentBySegmentType[filterIndex].value = valueData === 'with_out' ? 0 : 1;
      callListApi(filterSegmentBySegmentType);
    },
    [callListApi, filterIndex, filterSegmentBySegmentType]
  );

  const handleEventFilterValueChange = useCallback(
    (valueData) => {
      setEventFilterOperator((prevValue) => ({
        ...prevValue,
        attribute: valueData,
      }));
      filterSegmentBySegmentType[filterIndex].value = valueData;
      callListApi(filterSegmentBySegmentType);
    },
    [callListApi, filterIndex, filterSegmentBySegmentType]
  );

  const handleEventFilterDelete = useCallback(
    (valueData) => {
      setEventFilterOperator((prevValue) => ({
        ...prevValue,
        attribute: valueData,
      }));
      filterSegmentBySegmentType[filterIndex].filters = valueData;
      callListApi(filterSegmentBySegmentType);
    },
    [callListApi, filterIndex, filterSegmentBySegmentType]
  );

  const handleOperatorMenuClick = useCallback(
    (itemProps, customOperatorType, isScreenProp = false) => {
      const { key } = itemProps;
      const operatorTypeNew = customOperatorType || operatorType;
      const indexOfOperator = findIndex(operator[operatorTypeNew], {
        attribute: key,
      });
      const operatorDataByTypeIndex =
        operator[operatorTypeNew][indexOfOperator];
      if (isScreenProp) {
        setPropertyOperator(operatorDataByTypeIndex);
        if (propName && !propValue) {
          togglePropFieldVisibility(true);
          return;
        }
        if (operatorDataByTypeIndex.format !== propertyOperator?.format) {
            delete filterSegmentBySegmentType[filterIndex].property;
            togglePropFieldVisibility(true);
            setPropertyValue();
            return;
        }
        if (filterData.hasOwnProperty('property') && filterData.property) {
          filterSegmentBySegmentType[filterIndex].property.operator = key;
        }
        togglePropFieldVisibility(false);
        if(isActivityFilter){
            dispatch(updateActivityFilterSegment(filterSegmentBySegmentType, activityFilterIndex))
            callListApi();
        }else{
            callListApi(filterSegmentBySegmentType);
        }
        return;
      }
      if (operatorDataByTypeIndex.format !== operatorData?.format) {
        toggleEditFieldVisibility(true);
        setOperatorChangeData(operatorDataByTypeIndex);
        if( attribute === 'screen_name' && filterData.hasOwnProperty('property') && filterData.property ) {
          delete filterSegmentBySegmentType[filterIndex].property;
          setPropertyName();
          setPropertyValue();
          togglePropFieldVisibility(false);
          setPropertyOperator({
            attribute: 'in',
            isSearchable: true,
          });
        }
        if(!(isActivityFilter && ['bool', 'device_platform'].includes(operatorTypeNew))){ // * CX-1876:for activity filter support
            return;
        }
      }
      if (propName && !propValue) {
          setOperatorData(operatorDataByTypeIndex);
          toggleEditFieldVisibility(true);
          return;
      }
      if (attribute !== 'screen_name' && filterData.hasOwnProperty('property') && filterData.property)
        filterSegmentBySegmentType[filterIndex].property.operator = key;
      else if (singleValueType.indexOf(operatorTypeNew) > -1) {
        filterSegmentBySegmentType[filterIndex].operator = 'equal';
        filterSegmentBySegmentType[filterIndex].value = key;
      } else filterSegmentBySegmentType[filterIndex].operator = key;
      if (customOperatorType) setOperatorType(customOperatorType);
      setOperatorData(operatorDataByTypeIndex);
      setOperatorChangeData(null);
      toggleEditFieldVisibility(false);
      if(isActivityFilter){
            dispatch(updateActivityFilterSegment(filterSegmentBySegmentType, activityFilterIndex))
            callListApi();
        }else{
            callListApi(filterSegmentBySegmentType);
        }
    },
    [
      attribute,
      propertyOperator,
      callListApi,
      filterData,
      filterIndex,
      filterSegmentBySegmentType,
      operatorData?.format,
      operatorType,
      propName,
      propValue,
      dispatch,
      activityFilterIndex,
      isActivityFilter
    ]
  );

  const mappedTitle = useMemo(() => {
    // * CX-2200 FOR ICEBERG USER ONLY:Check if attribute is session_number_of_user, if it is then rename to Session number
    let title;
    const attributeIndex = findIndex(mappedAllFilters, { attribute });

    if (attributeIndex > -1) {
      const mapped = mappedAllFilters[attributeIndex];
      title = mapped && mapped.title;
    } else title = attribute;
    // * PF-1098 - RENAME CODED EVENT COUNT > EVENT COUNT (BASED ON SMART EVENTS)
    if ((attribute === "session_with_event" || attribute === "user_event_count") && !noCodeFlag) {
      title = "Event count";
    }
    return title;
  }, [attribute, mappedAllFilters, noCodeFlag]);

  const selectedOperator = operatorChangeData || operatorData;
  const selectedPropOperator = propertyOperator || operatorData;

  const isEvent = ['event_name'].includes(attribute);
  const handleSmartEventPropertyChange = useCallback(
    (valueData) => {
        filterSegmentBySegmentType[filterIndex].operator = selectedOperator.attribute ||  filterSegmentBySegmentType[filterIndex].operator ;
        filterSegmentBySegmentType[filterIndex].attribute = valueData;
        filterSegmentBySegmentType[filterIndex].value = undefined // * Reset
        dispatch(updateActivityFilterSegment(filterSegmentBySegmentType, activityFilterIndex))
        callListApi();
    }, [activityFilterIndex, callListApi, dispatch, filterIndex, filterSegmentBySegmentType, selectedOperator])
  const handleEffects = useCallback(() => {
    let operatorTypeByAttribute;
    let operatorDataByPropertyOperator;
    const indexOfFilter = findIndex(mappedAllFilters, { attribute });
    const filterProps = mappedAllFilters[indexOfFilter];
    operatorTypeByAttribute = filterProps?.type;
    setAttributeProps([filterProps][0]);
    setOperatorType(operatorTypeByAttribute);
    let indexOfOperator = findIndex(operator[operatorTypeByAttribute], {
      attribute: singleValueType.includes(operatorTypeByAttribute)
        ? String(value)
        : filterOperator,
    });
    if (filterData?.hasOwnProperty('property') && property) {
      let opIndx;
      if (filterProps?.attribute === 'event_name') {
        opIndx = findIndex(eventPropertyList, {
          property_name: property?.name,
        });
        if (opIndx > -1)
          operatorTypeByAttribute = eventPropertyList[opIndx]['propertyType'];
      }
      setPropertyName(property?.name);
      setPropertyValue(property?.value);
      toggleEventPropertyVisibility(true);
      indexOfOperator = findIndex(operator[operatorTypeByAttribute], {
        attribute: property?.operator,
      });
    } else if (
      filterData?.hasOwnProperty('property_name') &&
      filterData?.property_name
    ) {
      let opIndx;
      if (filterProps?.attribute === 'event_custom_property') {
        opIndx = findIndex(eventPropertyList, {
          property_name: filterData?.property_name,
        });
        if (opIndx > -1)
          operatorTypeByAttribute = eventPropertyList[opIndx]['propertyType'];
      }
      if( filterData?.attribute === "session_screen_with_property_list" && !operatorTypeByAttribute ) {        
        operatorTypeByAttribute = 'session_screen_string';
        const tempOperator = operator[operatorTypeByAttribute].find( item => item.attribute === filterData?.operator );
        if( tempOperator ) operatorDataByPropertyOperator = tempOperator;
        setOperatorType( operatorTypeByAttribute )
      }
      indexOfOperator = findIndex(operator[operatorTypeByAttribute], {
        attribute: filterData?.operator,
      });
      if (
        opIndx > -1 &&
        operatorTypeByAttribute === 'integer' &&
        notInOperators.includes(operatorDataByPropertyOperator.attribute)
      )
        operatorDataByPropertyOperator.isSearchable = true;
      // might be removed later
      setPropertyName(filterData?.property_name);
      setPropertyValue(filterData?.value);
    } else {
      setPropertyName();
      setPropertyValue();
    }
    if (indexOfOperator > -1) {
      try {
        operatorDataByPropertyOperator = clone(
          operator[operatorTypeByAttribute][indexOfOperator]
        );
      } catch (error) {
        /* */
      }
    }
    if ((attribute === 'event_name' || attribute === 'nce_name') && !filterData.hasOwnProperty('property')) {
      setPropertyOperator((prevValue) => ({
        ...prevValue,
        attribute: filterOperator,
      }));
      isActivityFilter && setOperatorData(operatorDataByPropertyOperator); // * CX-2094: for activity filter event name
    } else if ((attribute === 'screen_name') && filterData.hasOwnProperty('property') && property) {
      setOperatorData(operator['screen_name_string'].find((item) => item.attribute === filterData.operator));
      setPropertyOperator(operatorDataByPropertyOperator);
    } else {
      setOperatorData(operatorDataByPropertyOperator);
    }
  }, [
    attribute,
    eventPropertyList,
    filterData,
    filterOperator,
    mappedAllFilters,
    property,
    value,
    isActivityFilter
  ]);

  useEffect(() => {
    handleEffects();
  }, [filterSegmentBySegmentType, filterData.property_name , filterData.property ]); 

  let firstOperatorOrValue;
  // * CX-2094: for event activity filter
  if(isActivityFilter && ( activityFilterConfiguration?.type ) ) {
    return (
      <EventActivityFilterValue
        activityFilterConfiguration={activityFilterConfiguration}
        activityFilterIndex={activityFilterIndex}
        activityPropertyIndex={activityPropertyIndex}
        attribute={attribute}
        callListApi={callListApi}
        filterData={filterData}
        mappedTitle={mappedTitle}
        operatorData={operatorData}
        operatorType={operatorType}
        propName={propName}
        propValue={propValue}
        selectedOperator={selectedOperator}
        propertyOperator={propertyOperator}
        setPropertyOperator={setPropertyOperator}
        whereClicked={whereClicked}
        handleOperatorMenuClick={handleOperatorMenuClick}
        setPropertyName={setPropertyName}
        setPropertyValue={setPropertyValue}
        setWhereClicked={setWhereClicked}
        toggleEventPropertyVisibility={toggleEventPropertyVisibility}
        setOperatorData={setOperatorData}
        toggleEditFieldVisibility={toggleEditFieldVisibility}
        editFieldVisibility={editFieldVisibility}
        operatorChangeData={operatorChangeData}
        setOperatorChangeData={setOperatorChangeData}
        attributeProps={attributeProps}
        handleFilterDelete={handleFilterDelete}
        handleSmartEventPropertyChange={handleSmartEventPropertyChange}
        selectedPropOperator={selectedPropOperator}
      />
    );
  }
  
  if (attribute === 'event_name' || attribute === 'nce_name') {
    if(isActivityFilter){
        firstOperatorOrValue = (
            <ActivityFilterEventOperator
                eventOperator={filterOperator}
                handleActivityFilterEventOperatorChange={handleEventOperatorChange}
                title={mappedTitle}
            />
        );
    } else {
        firstOperatorOrValue = (
            <EventOperator
                attribute={attribute}
                eventOperator={filterOperator}
                handleEventOperatorChange={handleEventOperatorChange}
            />
        );
    }
  } else if (propertyName || attribute === "user_custom_property" && isActivityFilter) {
    firstOperatorOrValue = (
      <>
      {/* // * CX-1858: Adds 'user where' prefix for iceberg user */}
      {!isActivityFilter && getQueryPrefix(attribute)}
      <FilterValue
        value={propName}
        propValue={propValue}
        callListApi={callListApi}
        attribute={attribute}
        filterIndex={filterIndex}
        setPropertyName={setPropertyName}
        setPropertyValue={setPropertyValue}
        isUserPropertyName={attribute === 'user_custom_property'}
        operatorData={
          attribute === 'user_custom_property' ||
          attribute === 'event_custom_property' ||
          attribute === 'utm' ||
          attribute === 'user_first_utm' ||
          attribute === 'session_screen_with_property' ||
          attribute === 'session_screen_with_property_list' ? {
                isSearchable: true,
                attribute: operatorData?.attribute,
              }
            : operatorData
        }
        id={
          attribute === 'user_custom_property' ? 'userpropertyname' : attribute
        }
        key={
          attribute === 'user_custom_property' ? 'userpropertyname' : attribute
        }
        keyName={
          attribute === 'user_custom_property' ||
          attribute === 'event_custom_property' ||
          attribute === 'utm' ||
          attribute === 'user_first_utm' ||
          attribute === 'session_screen_with_property' ||
          attribute === 'session_screen_with_property_list' ? 'property_name' : 'value'
        }
        filterData={filterData}
        toggleEditFieldVisibility={toggleEditFieldVisibility}
        filterTitle={mappedTitle}
        attributeProps={attributeProps}
        isActivitySegment={isActivityFilter}
        activityPropertyIndex={activityPropertyIndex}
        activityFilterIndex={activityFilterIndex}
      />
      </>
    );
  } else firstOperatorOrValue = !isSequence && <span>{isActivityFilter ? mappedTitle :  getQueryPrefix(attribute, mappedTitle)}</span>;
  return (
    <Col span={24} key={`${filterIndex}-${attribute}`} className={!isActivityFilter && "filter-item"}>
      {isActivityFilter &&
         <WHEREAND className='filter-spacing'>
            {activityPropertyIndex === 0 ? 'WHERE' : 'AND'} 
        </WHEREAND>
      }
      {isSequence && (
        <ScreenFilterWithSequence
          screenRenamedList={screenRenamedList}
          callListApi={callListApi}
          filterSegmentDuplicate={filterSegmentDuplicate}
          filterIndex={filterIndex}
          value={value}
          attributeProps={attributeProps}
        />
      )}
        {!isNestedEvent && !isNestedGesture && !isSequence ? (
        <span className="filter-spacing">{firstOperatorOrValue}</span>
      ): null}
      
      {isNestedGesture && (
        <StyledEventNestedDiv>
          <EventFilterOperator
            eventOperator={filterOperator}
            filterData={filterData}
            handleEventFilterOperatorChange={handleEventFilterOperatorChange}
            handleFilterDelete={() => handleFilterDelete(filterData)}
            handleEventFilterValueChange={handleEventFilterValueChange}
            handleWithOrWithoutEventChange={handleWithOrWithoutEventChange}
          />
        </StyledEventNestedDiv>
      )}
    
         {isNestedEvent && (
        <StyledEventNestedDiv>
          <EventFilterOperator
            eventOperator={filterOperator}
            filterData={filterData}
            handleEventFilterOperatorChange={handleEventFilterOperatorChange}
            handleWithOrWithoutEventChange={handleWithOrWithoutEventChange}
            handleFilterDelete={() => handleFilterDelete(filterData)}
            handleEventFilterValueChange={handleEventFilterValueChange}
          />
        </StyledEventNestedDiv>
      )}
      {isNestedEvent && (
        <span>
          <EventFilterBlock
            filterData={filterData}
            handleEventNameOperatorChange={handleEventNameOperatorChange}
            setOperatorData={setOperatorData}
            operatorData={operatorData}
            callListApi={callListApi}
            toggleEditFieldVisibility={toggleEditFieldVisibility}
            editFieldVisibility={editFieldVisibility}
            attributeProps={attributeProps}
            handleEventFilterDelete={handleEventFilterDelete}
            filterSegment={filterSegment}
          />
        </span>
      )}
      {isNestedGesture && (
        <span>
          <GestureFilterBlock
            filterData={filterData}
            attributeProps={attributeProps}
            filterSegment={filterSegment}
          />
        </span>
      )}
      {attribute === 'nce_name' ||
      attribute === 'event_name' ||
      attribute === 'event_custom_property' ||
      isNestedEvent ||
      isNestedGesture ||
      isSequence ? null : (
        <span className="filter-spacing">
          <OperatorMenu
            selectedAttribute={ attribute }
            selectedOperator={
             !isActivityFilter ? selectedOperator || 
              (
                table === 'no_code_event' && { 
                title: filterOperator === 'not_in' ? `does not equal` : 'equals' 
              }) : 
              selectedOperator || {
                title: 'select_activity',
                }
            }
            operatorType={operatorType}
            handleOperatorMenuClick={handleOperatorMenuClick}
            isFilterDisplayBar
            propertyName={value}
            activityFilterProperty={isActivityFilter ? {
                id: ['bool', 'device_platform'].includes(operatorType) && getActivityFilterPropertyId(
                        attribute,
                        activityFilterIndex,
                        activityPropertyIndex
                        ),
            } : null}
          />
        </span>
      )}
      {!['bool', 'device_platform', 'user_device_platform'].includes(operatorType) &&
        !isSequence &&
        attribute !== 'event_custom_property' &&
        attribute !== 'event_count_per_screen_visit' &&
        attribute !== 'smart_event_count_per_screen_visit' &&
        attribute !== 'gesture_count_per_screen_visit' && (
          <FilterValue
            callListApi={callListApi}
            value={attribute === 'user_custom_property' ? propValue : value}
            attribute={
              attribute === 'user_custom_property'
                ? 'userpropertyvalue'
                : attribute
            }
            isUserPropertyValue={attribute === 'user_custom_property'}
            propertyName={propName}
            operatorData={
              (attribute === 'event_name' || attribute === 'nce_name') ? propertyOperator : operatorData
            }
            eventOperator={propertyOperator}
            setPropertyName={setPropertyName}
            setPropertyValue={setPropertyValue}
            key={attribute}
            id={attribute}
            keyName="value"
            filterData={filterData}
            toggleEditFieldVisibility={toggleEditFieldVisibility}
            editFieldVisibility={isEvent ? false : editFieldVisibility}
            operatorChangeData={isEvent ? null : operatorChangeData}
            setOperatorChangeData={setOperatorChangeData}
            setOperatorData={setOperatorData}
            isMultiSelect
            isUserName={attribute === 'uxcamuserid'}
            filterTitle={mappedTitle}
            setWhereClicked={setWhereClicked}
            toggleEventPropertyVisibility={toggleEventPropertyVisibility}
            attributeProps={attributeProps}
            isActivitySegment={isActivityFilter}
            activityPropertyIndex={activityPropertyIndex}
            activityFilterIndex={activityFilterIndex}
          />
        )}
      {showAddCondition && (
        <span className="filter-spacing">
          {eventPropertyVisibility ? (
            'where'
          ) : (
            <Button
              size="small"
              icon={<PlusOutlined />}
              onClick={() => {
                toggleEventPropertyVisibility(true);
                setWhereClicked(true);
                if( attribute === 'event_name' )
                setOperatorData(operator[operatorType][0]);
              }}
              className="where-btn"
            >
              Add condition
            </Button>
          )}
        </span>
      )}
      {eventPropertyVisibility && (
        <FilterValue
          eventPropertyVisibility={eventPropertyVisibility}
          propertyOperator={propertyOperator}
          callListApi={callListApi}
          value={propName}
          propValue={propValue}
          attribute={attribute}
          setPropertyName={setPropertyName}
          setPropertyValue={setPropertyValue}
          whereClicked={whereClicked}
          setWhereClicked={setWhereClicked}
          operatorData={{
            isSearchable: true,
            attribute: operatorData?.attribute,
          }}
          id="eventpropertyname"
          key="event-property-value"
          eventValue={value}
          isEventProperty={attribute === 'event_name'}
          isScreenProperty={attribute === 'screen_name'}
          filterData={filterData}
          keyName="property"
          filterTitle={mappedTitle}
          attributeProps={attributeProps}
          setOperatorData={setOperatorData}
        />
      )}
      {propName &&
        (attribute === 'screen_name' ||
          attribute === 'event_name' ||
        attribute === 'nce_name' ||
          attribute === 'event_custom_property') && (
          <>
            <span className="filter-spacing">
              <OperatorMenu
                selectedAttribute={ attribute }
                selectedOperator={
                  // eslint-disable-next-line no-nested-ternary
                  attribute === 'screen_name' ?
                  {
                    attribute: selectedPropOperator.attribute,
                    title: mappedOperator[selectedPropOperator.attribute],
                  } : selectedOperator?.attribute ? 
                  {
                    attribute: selectedOperator.attribute,
                    title: mappedOperator[selectedOperator.attribute],
                  }
                    : { attribute: 'in', title: 'equals' }
                }
                isFilterDisplayBar
                operatorType="json"
                handleOperatorMenuClick={handleOperatorMenuClick}
                isEventProperty={attribute === 'event_name'}
                isScreenProperty={attribute === 'screen_name'}
                propertyOperator={propertyOperator}
                propertyName={propName}
              />
            </span>
            <FilterValue
              eventPropertyVisibility={eventPropertyVisibility}
              propertyOperator={propertyOperator}
              setPropertyOperator={setPropertyOperator}
              callListApi={callListApi}
              value={propValue}
              attribute={attribute}
              setPropertyValue={setPropertyValue}
              setPropertyName={setPropertyName}
              propertyName={propName}
              whereClicked={whereClicked}
              operatorData={operatorData}
              filterData={filterData}
              eventValue={attribute === 'event_custom_property' ? null : value}
              id="eventpropertyvalue"
              key="event-property-value"
              isMultiSelect
              isEventProperty={attribute === 'event_name'}
              isScreenProperty={attribute === 'screen_name'}
              keyName="property"
              toggleEditFieldVisibility={toggleEditFieldVisibility}
              editFieldVisibility={editFieldVisibility}
              togglePropFieldVisibility={togglePropFieldVisibility}
              propFieldVisibility={propFieldVisibility}
              operatorChangeData={operatorChangeData}
              setOperatorChangeData={setOperatorChangeData}
              setOperatorData={setOperatorData}
              filterTitle={mappedTitle}
              attributeProps={attributeProps}
              isActivitySegment={isActivityFilter}
              activityPropertyIndex={activityPropertyIndex}
              activityFilterIndex={activityFilterIndex}
            />
          </>
        )}
      {isNestedEvent || isNestedGesture ? null :
      (
          <>
            <Tooltip placement="topLeft" title="Delete filter" arrowPointAtCenter>
              <Button
                onClick={() => handleFilterDelete(filterData)}
                ghost
                type="text"
                icon={<MinusBtnSVG />}
                className="delete-btn"
              />
            </Tooltip>
            {!isActivityFilter && screenVisitProperties.map(item => item.attribute === attribute ?
              <Tooltip placement="top" title='Screen visit filters show data of all the screen visits that meet the filter criteria'>
                <InfoCircleOutlinedSpan />
              </Tooltip> : null)}
          </>
        )}
    </Col>
  );
};
export default memo(AppliedFilter);
