import React from 'react';
import { useSelector } from 'react-redux';
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import ReactLoader from 'components/common/reactLoading';

import { ErrorBox } from 'components/common/Customary/ErrorBox';
import ScreenFlowGraph from 'components/features/navigation/ScreenFlow/ScreenFlowGraph';
import PendingLoaderInfo from 'components/common/PendingLoaderInfo';

const LoadingMessage = () => (
  <>
    <PendingLoaderInfo preText="Computing flow data" />
    <ReactLoader />
  </>
);

const ScreenFlowGraphContent = ({ chartRef }) => {
  const { screenFlowPlotGraph, screenFlwLoader } = useSelector( (state) => state.screenDetailReducer );
  const { series } = screenFlowPlotGraph || {};
  const graphContent =
    series && series[0]?.data.length !== 0 ? (
      <ScreenFlowGraph chartRef={chartRef} />
    ) : (
      <ErrorBox displayIcon errorText="There is either no data to display or it is possible that the step limits have been exceeded." isNoData />
    );
  return (
    <div className="stat-graph-box" data-intercom-target="Screen Flow Stats">
      <LoaderAdvanced
        show={screenFlwLoader || false}
        message={<LoadingMessage />}
        backgroundStyle={{ backgroundColor: 'rgba(255,255,255,0.6)' }}
        style={{ position: 'initial' }}
      >
        {typeof screenFlowPlotGraph === 'object'
          ? graphContent
          : !screenFlwLoader && (
              <ErrorBox displayIcon errorText={screenFlowPlotGraph} isNoData />
            )}
      </LoaderAdvanced>
    </div>
  );
};
export default ScreenFlowGraphContent;
