import React, { memo } from 'react';
import { WarningOutlined } from '@ant-design/icons';
import { Alert } from 'antd';
import { showIntercom } from 'Utils/constants/index'

const eventLimitText = (isMobileEventLimitReached, isWebEventLimitReached) => {
  let limitText = 'Event recording stopped.'
  if( isMobileEventLimitReached && !isWebEventLimitReached ){
    limitText = 'Event recording stopped because your organization reached its monthly mobile event limit.'
  }
  if( !isMobileEventLimitReached && isWebEventLimitReached ){
    limitText = 'Event recording stopped because your organization reached its monthly web event limit.'
  }
  if( isMobileEventLimitReached && isWebEventLimitReached ){
    limitText = 'Event recording stopped because your organization reached its monthly mobile and web event limit.'
  }
  return `${limitText} This may impact any data or reports that contain event information.`
}


const EventLimitStatusModal = ({
  isMobileEventLimitReached,
  isWebEventLimitReached
}) => {
  const handleGotItAction = () => {
    try {
      sessionStorage.setItem("storeHideEventLimitReached", true);
    } catch (err) {
      // silent fail
    }
  }

  const eventLimitInfo = (
    <div className="event-limit-info">
        <p>
         {eventLimitText(isMobileEventLimitReached, isWebEventLimitReached)}{' '}
          <a href="#!" className="text-link" onClick={() => showIntercom()}>
            Contact us
          </a>
            {' '} to increase your limit
        </p>
      </div>
  );

  return (
    <Alert
      message={eventLimitInfo}
      type="warning"
      icon={<WarningOutlined />}
      showIcon
      closable
      onClose={() => handleGotItAction()}
      className="event-limit-alert"
    />
  );
};

export default memo(EventLimitStatusModal);
