import React from 'react';
import { useSelector, useDispatch } from 'react-redux'
import { Button } from 'antd'
import {
  mappedElements,
  mappedLinks,
} from 'Utils/constants/FeatureProps'
import { getOrgCsrf } from 'redux/actions/common'
import { showIntercom } from 'Utils/constants/index'
import NewRequestQuoteForm from 'components/features/setting/Quote/PlanBasedPricingPopup/NewRequestQuoteForm';

import orgListPaying from 'Utils/constants/orgListPaying.json'

const NoFeatureOverlay = ({ children, isFeatureAvailable, page }) => {
  const dispatch = useDispatch()
  const currentOrgReducer = useSelector((state) => state.currentOrgReducer)
  const orgId = currentOrgReducer?.orgId
  const isPayingOrgId = orgListPaying.includes(orgId)
  const [requestQuoteVisible, showHideQuoteModal] = React.useState(false)
  const [orgCsrf, _getOrgCsrf] = React.useState(false)
  return (
    <>
      <div
        className='upgrade-msg-box'
        style={{ display: isFeatureAvailable ? 'none' : 'flex' }}
      >
        <div className='body-box'>
          <div className='body-box-content'>
            <div className='icon-box'>
              <img src='/static/icon-upgrade.svg' alt='icon' />
            </div>
            <div className='message-content'>
              {mappedElements[page]}{' '}
              <a href={mappedLinks[page]} target='_blank' rel="noopener noreferrer">
                Learn more
              </a>
              <br />
              <Button
                type='primary'
                onClick={async () => {
                  if (isPayingOrgId && page === 'issues') showIntercom()
                  else {
                    const orgCsrf = await dispatch(getOrgCsrf())
                    orgCsrf && (await _getOrgCsrf(orgCsrf))
                    showHideQuoteModal(true)
                  }
                }}
              >
                {`Get in touch with ${
                  isPayingOrgId && page === 'issues' ? 'customer support' : 'sales'
                }`}
              </Button>
            </div>
          </div>
        </div>
      </div>
      {children}
      <NewRequestQuoteForm
        setShowPricingModal={showHideQuoteModal}
        showPricingModal={requestQuoteVisible}
      />
    </>
  )
}
export default NoFeatureOverlay
