interface CreateCohortParams {
  appId: string
  isMassUserId: boolean
  filters: Array<{
    attribute: string
    operator: string
    value: string[]
    table: string
  }>
  name: string
  description: string
}

interface CreateCohortResponseData {
  cohort_id: string
  s3_path: string
  status: string
  total_users_provided: number
  actual_users_in_database: number
}

interface CreateCohortResponse {
  message: string
  data: CreateCohortResponseData
}

const createCohort = async ({ appId, isMassUserId, filters, name, description }: CreateCohortParams): Promise<{ data: CreateCohortResponse }> => {
    const response = await axiosInstance({
      method: 'POST',
      url: `${process.env.PYTHON_API_URL}/retention/cohort/create`,
      data: {
        appid: appId,
        is_mass_user_id: isMassUserId,
        filters,
        name,
        description,
      },
      withCredentials: true,
      responseType: 'json',
    })
    return response
  }

const SaveCohortModal = memo<SaveCohortModalProps>(({ visible, onClose, values, filterContext, onSave }) => {
  const [cohortName, setCohortName] = useState('')
  const [description, setDescription] = useState('')
  const inputRef = useRef<InputRef>(null)
  const dispatch = useDispatch()

  const { userCohorts, refetchCohorts } = useUserCohorts()
  const { currentAppReducer, urlReducer, currentOrgReducer: { planLimit }, } = useSelector((state: IReduxState) => state)

  const [cohortNameError, setCohortNameError] = useState('')

  const checkCohortNameExists = useCallback((name: string) => {
    const trimmedName = name.trim().toLowerCase()
    if (!trimmedName) return false
    return userCohorts.some(cohort => cohort.name.toLowerCase() === trimmedName)
  }, [userCohorts])

  const {
    setShowPartialCohortSaved,
    setShowNoCohortSaved,
    setShowCohortLimitReached,
    setTotalIds,
    setAddedIds,
    setCohortFilter
  } = useMassUserIdFilterContext();

  const getCohortSavedStatus = (
    actualUsersInDatabase: number,
    totalUsersProvided: number
  ): CohortSuccessStatus => {
    if (actualUsersInDatabase === totalUsersProvided) {
      return CohortSuccessStatus.SUCCESS;
    }
    if (
      actualUsersInDatabase > 0 &&
      actualUsersInDatabase < totalUsersProvided
    ) {
      return CohortSuccessStatus.PARTIAL_SAVED;
    }
    return CohortSuccessStatus.FAILED;
  };

  const createCohortMutation = useMutation<{ data: CreateCohortResponse }, Error, { name: string; desc: string }>({
    mutationFn: async ({ name, desc }: { name: string; desc: string }) => {
      // eslint-disable-next-line no-underscore-dangle
      const appId = currentAppReducer?._id || urlReducer?.appId

      if (!appId) {
        throw new Error('Unable to get app ID')
      }

      const filters = [
        {
          attribute:  filterContext?.attribute || 'uxcam_user_id',
          operator: filterContext?.operator || 'in',
          value: values,
          table: filterContext?.table || 'session',
          property_name: filterContext?.property_name || ''
        }
      ]

      return createCohort({
        appId,
        isMassUserId: true,
        filters,
        name,
        description: desc
      })
    },
    onSuccess: (response, variables) => {
    //* Apply filter
     const cohortFilter = [{
        attribute: 'uxcamuserid_cohort',
        operator: filterContext?.operator || 'in',
        value: [response.data.data.cohort_id],
        table: filterContext?.table || 'appuser'
      }]

      // Track wa_save_cohort event
      dispatch(trackPageViews(null, {
        eventName: 'wa_save_cohort',
        track_type: 'event',
        eventProperty: {
          type: 'Manual user IDs',
          cohort_name: variables.name,
          total_users: values.length,
          status: getCohortSavedStatus(response.data.data.actual_users_in_database, response.data.data.total_users_provided)
        },
        pageName: urlReducer?.parentType
      }))

      setCohortFilter(cohortFilter)
      setTotalIds(response.data.data.total_users_provided)
      setAddedIds(response.data.data.actual_users_in_database)
      refetchCohorts()

      onClose()
      if (response.data.data.actual_users_in_database === 0) {
        setShowNoCohortSaved(true)
      } else if (response.data.data.actual_users_in_database < response.data.data.total_users_provided) {
        setShowPartialCohortSaved(true)
      } else {
        message.success(`Cohort "${variables.name}" saved successfully and applied as filter.`)
        onSave?.(cohortFilter)
      }
    },
    onError: (error:any) => {
        // eslint-disable-next-line no-underscore-dangle
        const appId = currentAppReducer?._id || urlReducer?.appId
        rollbar.error( 'Error creating cohort from SaveCohortModal', { appId })
        if(error?.response?.data?.error?.message.toLowerCase().includes('reached') || error?.response?.data?.error?.errorType === 'cohortLimitReached'){
            onClose()
            setShowCohortLimitReached(true)
            dispatch(trackPageViews(null, {
                eventName: 'wa_cohort_limit_reached',
                track_type: 'event',
                eventProperty: {
                cohortLimit: planLimit?.cohortLimit,
                cohortType: "Manual user IDs"
                },
                pageName: urlReducer?.parentType
            }))
        }else{
            message.error('There was an error saving the cohort.')
        }
    }
  })

  useEffect(() => {
    if (visible) {
      setCohortName('')
      setDescription('')
      setCohortNameError('')
      setTimeout(() => {
        inputRef.current?.focus()
      }, 300)
    }
  }, [visible])

  const handleSave = useCallback(() => {
    if (cohortName.trim()) {
      if (checkCohortNameExists(cohortName)) {
        setCohortNameError('Cohort name already exists')
        return
      }
      setCohortNameError('')
      createCohortMutation.mutate({
        name: cohortName.trim(),
        desc: description.trim()
      })
    }
  }, [cohortName, description, createCohortMutation, checkCohortNameExists])

  return (
    <StyledModal
      title={createCohortMutation.isLoading ? null : "Save cohort"}
      visible={visible}
      onCancel={onClose}
      width={600}
      destroyOnClose
      zIndex={100000}
      centered
      closable={!createCohortMutation.isLoading}
      padding={!createCohortMutation.isLoading ? '0px 32px 32px 32px' : '0px'}
    >
      {createCohortMutation.isLoading ? (
        <LoadingWrapper>
          <LoadingImageContainer>
            {/* @ts-expect-error - Loader is a JS component without type definitions */}
            <Loader isLoading style={{ left: 0, top: 0 }}/>
          </LoadingImageContainer>
          <LoadingText>Saving your cohort and applying as filter ...</LoadingText>
        </LoadingWrapper>
      ) : (
        <>
          <ContentWrapper>
            <NoticeBox>
              <div>
                <p>Your user ID list exceeded {COHORT_THRESHOLD_LIMIT.toLocaleString()} characters, so it cannot be applied directly as a filter.</p>
                <p>Save it as a cohort now to apply it as a filter.</p>
              </div>
            </NoticeBox>

            <FieldWrapper>
              <FieldLabel>Cohort name</FieldLabel>
              <StyledInput
                ref={inputRef}
                value={cohortName}
                onChange={(e) => {
                  setCohortName(e.target.value)
                  if (cohortNameError) setCohortNameError('')
                }}
                placeholder=""
                maxLength={100}
                $hasError={!!cohortNameError}
              />
              {cohortNameError && <ErrorMessage>{cohortNameError}</ErrorMessage>}
            </FieldWrapper>

            <FieldWrapper>
              <FieldLabel>Description</FieldLabel>
              <StyledTextArea
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder=""
                maxLength={500}
                rows={5}
              />
            </FieldWrapper>
          </ContentWrapper>

          <ActionsWrapper>
            <CancelButton onClick={onClose} disabled={createCohortMutation.isLoading}>Cancel</CancelButton>
            <SaveButton disabled={!cohortName.trim() || createCohortMutation.isLoading} onClick={handleSave} loading={createCohortMutation.isLoading}>
              Save and apply
            </SaveButton>
          </ActionsWrapper>
        </>
      )}
    </StyledModal>
  )
})

SaveCohortModal.displayName = 'SaveCohortModal'

export default SaveCohortModal
