import React, { useCallback, useEffect, useMemo, useState } from "react";
import { findIndex } from 'lodash';
import styled from 'styled-components';
import { Button, Row, Form } from "antd";

import { MinusCircleOutlined } from "@ant-design/icons";

import { OperatorMenu } from "components/shared/GlobalFilter/components/CommonComponentsV2";
import {
  operator,
} from 'components/shared/GlobalFilter/components/data-structures-v2'
import { FilterCountSvg } from "components/shared/GlobalFilter/components/FilterSvgs";
import FilterValue from "./FilterValueEvent";
import EventFilterProperties from "./EventProperties/EventFilterProperties";

const FormItem = Form.Item

const StyledFormItem = styled(FormItem)`
 margin-bottom: 0;
 .ant-col{
  margin-bottom: 0;
 }
 .ant-form-item-control-input {
  min-height: auto;
}
`
const EventBlockWrapper = styled.div`
  display: flex;
  flex-direction: column;
  margin-bottom: 2px;
`

const EventNameStyle = styled.div`
  display: flex;
  gap: 10px;
  align-items: center;
`

const EventNameSpan = styled.span` 
  a {
    font-size: 14px;
    color: #161E35;
  }
`

const EventDeleteButton = styled(Button)`
border: none;
box-shadow: none;
.anticon svg {
  font-size: 13px;
  color: #DC4F44;
}
`

const defaultSelectedOperator = {
  "attribute": "in",
  "title": "equals",
  "format": "list_of_string",
  "display": true,
  "isSearchable": true
};

const defaultOperatorType = 'string';

const EventFilterBlock = ({ filterData, handleEventNameOperatorChange, callListApi, attributeProps, handleEventFilterDelete, filterSegment }) => {
  const [selectedOperator, setSelectedOperator] = useState(defaultSelectedOperator);
  const [operatorType, setOperatorType] = useState(defaultOperatorType);

  const { filters } = filterData || {}

  const handleOperatorMenuClick = useCallback(
    (itemProps, customOperatorType) => {
      const { key } = itemProps
      const operatorTypeNew = customOperatorType || operatorType
      const indexOfOperator = findIndex(operator[operatorTypeNew], {
        attribute: key,
      })
      const operatorDataByTypeIndex = operator[operatorTypeNew][indexOfOperator]

      if (customOperatorType) setOperatorType(customOperatorType)
      if (selectedOperator?.format === operatorDataByTypeIndex?.format) {
        handleEventNameOperatorChange(operatorDataByTypeIndex)
      }
      setSelectedOperator(operatorDataByTypeIndex)
    },
    [handleEventNameOperatorChange, operatorType, selectedOperator],
  )

  const hasEventNameFilter = useMemo(() => filters?.length > 0 && filters.some(filter => filter?.attribute === 'event_name'), [filters])
  const hasSmartEventNameFilter = useMemo(() => filters?.length > 0 && filters.some(filter => filter?.attribute === 'nce_name'), [filters])

  const eventNameFilter = useMemo(() => filters.find(filter => filter?.attribute === 'event_name'), [filters])
  const smartEventNameFilter = useMemo(() => filters.find(filter => filter?.attribute === 'nce_name'), [filters])

  const handleDeleteEvent = () => {
    const newFilters = hasSmartEventNameFilter ? 
      filters.filter(obj => obj?.attribute !== 'nce_name') :
      filters.filter(obj => obj?.attribute !== 'event_name')
    handleEventFilterDelete(newFilters)
  }

  useEffect(() => {
    const indexOfOperator = findIndex(operator['string'], {
      attribute: hasSmartEventNameFilter ? smartEventNameFilter?.operator : eventNameFilter?.operator,
    })
    const operatorDataByTypeIndex = operator['string'][indexOfOperator]
    operatorDataByTypeIndex && setSelectedOperator(operatorDataByTypeIndex)
  }, [eventNameFilter, smartEventNameFilter, hasSmartEventNameFilter])

  return (
    <>
      {(hasEventNameFilter || hasSmartEventNameFilter) &&
        <EventBlockWrapper>
          <Row>
            <EventNameStyle>
              <FilterCountSvg />
              <EventNameSpan> <a href="#!">Event name</a> </EventNameSpan>
              <StyledFormItem>
                <span className="filter-spacing">
                  <OperatorMenu
                    selectedOperator={selectedOperator}
                    operatorType={operatorType}
                    handleOperatorMenuClick={handleOperatorMenuClick}
                    isFilterDisplayBar
                    propertyName=''
                  />
                </span>
              </StyledFormItem>

              <FilterValue
                callListApi={callListApi}
                value={eventNameFilter?.value}
                attribute={filterData?.attribute}
                operatorData={selectedOperator}
                key={filterData?.attribute}
                id={filterData?.attribute}
                keyName='value'
                filterData={filterData}
                editFieldVisibility
                setOperatorData={setSelectedOperator}
                isMultiSelect
              />
              <EventDeleteButton onClick={() => handleDeleteEvent()} icon={<MinusCircleOutlined />} />
            </EventNameStyle>
          </Row>

        </EventBlockWrapper>
      }

      <EventFilterProperties attributeProps={attributeProps} filterData={filterData} filterSegment={filterSegment} />
    </>
  )
}

export default EventFilterBlock;