import { Modal } from "antd"
import React, { useCallback, useEffect, memo } from "react"
import styled, { createGlobalStyle } from "styled-components"
import { useRestrictionContext } from "components/IntegratePages/layout/context/restrictionContext"
import Illustration from 'public/static/lock-features/filters-locked-illustration.svg'
import CloseIcon from 'public/static/close-bold.svg'
import { useDispatch } from "react-redux"
import { trackPageViews } from 'redux/actions/trackingReport'

const GlobalStyles = createGlobalStyle`
	.filters-locked-modal {
		z-index: 999999;
		display: flex;
		justify-content: center;
		align-items: center;
		.ant-modal {
			top: initial;
			transform-origin: center !important;
			width: fit-content !important;
		}
		.ant-modal-content {
			border-radius: 8px;
		}
	}
`

const Wrapper = styled.div`
	display: flex;
	position: relative;
`

const CloseButton = styled.button`
	position: absolute;
	top: 16px;
	right: 16px;
	height: 16px;
	width: 16px;
	border: none;
	background: transparent;
	margin: 0;
	padding: 0;
	cursor: pointer;
	transition: all 0.2s ease-in-out;
	&:hover {
		svg {
			path {
				stroke: #989898;
			}
		}
	}
`

const Left = styled.div`
	margin-right: 32px;
`

const Right = styled.div`
	display: flex;
	flex-direction: column;
	max-width: 304px;
	justify-content: center;
`

const Title = styled.h2`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 500;
	font-size: 18px;
	line-height: 24px;
	color: #161E35;
	margin-bottom: 4px;
`

const SubTitle = styled.h3`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 500;
	font-size: 14px;
	line-height: 24px;
	margin-bottom: 16px;
`

const List = styled.ul`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 400;
	font-size: 12px;
	line-height: 24px;
	color: #161E35;
	margin-bottom: 16px;
	margin-left: 20px;
	li {
		list-style: outside;
	}
`

const Button = styled.button`
	font-weight: 400;
	font-size: 14px;
	line-height: 24px;
	color: #FFFFFF;
	padding: 4px 55px;
	background-color: #5D97FF;
	border-radius: 6px;
	cursor: pointer;
	border: none;
	outline: none;
	width: fit-content;
	transition: all 0.2s ease-in-out;
	&:hover {
		background-color: #4A79CC;
	}
`

const FiltersLockedModal = () => {
	const { filtersLockedModal, setFiltersLockedModal, selfServeFlag, setShowPricingModal } = useRestrictionContext()
	const dispatch = useDispatch()

	const handleClose = useCallback( () => {
		setFiltersLockedModal( false )
	}, [ setFiltersLockedModal ] )

	const handlePricingClick = useCallback(() => {
		setFiltersLockedModal( false )
		setShowPricingModal(true)

		dispatch( trackPageViews( null, {
			eventName: selfServeFlag ? 'wa_see_pricing_clicked' : 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'Advanced Filters modal',
				self_chekout: selfServeFlag,
			},
		} ) )
	}, [ setShowPricingModal, setFiltersLockedModal, selfServeFlag, dispatch ])
	
	useEffect( () => {
		if ( filtersLockedModal ) {
			dispatch( trackPageViews( null, {
				eventName: 'wa_blocked_feature_pop_up_displayed',
				track_type: 'event',
				eventProperty: {
					source: 'Advanced Filters modal',
					self_chekout: selfServeFlag,
				},
			} ) )
		}
	}, [ filtersLockedModal, dispatch, selfServeFlag ] )

	return (
		<>
			<GlobalStyles />
			<Modal
				wrapClassName='filters-locked-modal'
				visible={ filtersLockedModal }
				maskStyle={ { zIndex: '99998', background: 'rgba(22, 30, 53, 0.3)' } }
				getContainer={ () => document.body.querySelector( '.ant-layout-content' )}
				footer={ null }
				closable={ false }
				onCancel={ handleClose }
			>
				<Wrapper>
					<CloseButton onClick={ handleClose }>
						<CloseIcon alt="Cross" height="16" width="16" />
					</CloseButton>
					<Left>
						<Illustration alt="Illustration of three windows with app features" width="350" height="320" />
					</Left>
					<Right>
						<Title>
							Advanced filters
						</Title>
						<SubTitle>
							Relevant data for faster insights
						</SubTitle>
						<List>
							<li>Save time - filter out irrelevant data.</li>
							<li>Do targeted analysis - filter by event name, user ID, screen, platform, app version, country, device model - and many other criteria.</li>
							<li>Make better decisions - gain deeper insights into user behavior and segments.</li>
						</List>
							<Button onClick={handlePricingClick}>
								{ selfServeFlag ? "See pricing" : "Request pricing" }
							</Button>
					</Right>
				</Wrapper>
			</Modal>
		</>
	)
}

export default memo( FiltersLockedModal )