/* eslint-disable no-prototype-builtins */
/* eslint-disable no-nested-ternary */
/* eslint-disable import/no-cycle */
import React, { memo, useEffect, useCallback, useState, useRef, useMemo } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { Checkbox, message, Radio, Tooltip, Input } from 'antd'
import { SearchOutlined } from '@ant-design/icons'
import styled from 'styled-components'
import isArray from 'lodash/isArray'
import isObject from 'lodash/isObject'

import {
  SelectWithTags,
  DateType,
  DebounceInputComponent,
  LoaderMenuItem,
  SelectAllAndClear,
  OverThresholdText,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import { noMatchingFilterMenu } from 'components/shared/GlobalFilter/components'
import { onlyNumber, setPlaceholder, screenNameAttributes, getEnvTooltip } from 'components/shared/GlobalFilter/components/utils'
import { operator } from 'components/shared/GlobalFilter/components/data-structures-v2'
import { withContextProps } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/FilterContextProvider'
import { fetchPlanHatApi } from 'redux/actions/common'
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import { mapPageNames } from 'Utils/constants/index'
import { addSecondsSuffix } from 'Utils/helpers/addSecondsSuffix'
import { getRenamedDeviceName } from 'Utils/helpers/commonUtils'

import isEqual from 'lodash/isEqual';
import { ViewportList } from 'react-viewport-list';
import { capitalizeEnvString } from 'components/features/setting/AppSetting/NewRecordingSection/DebounceSearch'
import { NoCustomUserIdMessage } from 'Utils/helpers/userIdUtils'
import { useSegmentModal } from 'components/shared/GlobalFilter/components/SegmentMenu/hooks/useModal'
import MultiUsersIcon from 'public/static/multi-users-icon.svg'
import { useUserCohorts } from 'components/common/Contexts/UserCohortsContext'
import MenuFooter from './MenuFooter'
import { webScreenAttribtues } from '..'
import MassUserIdFilter from '../../../MassUserIdFilter'

const MassUserIdTriggerButton = styled.button`
  background: #F3F4F5;
  cursor: pointer;
  padding: 4px 8px;
  font-size: 18px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  border-radius: 6px;
  border: none;
  height: 28px;

  svg{
    filter: brightness(0) saturate(100%) invert(47%) sepia(5%) saturate(854%) hue-rotate(187deg) brightness(98%) contrast(90%);
}

  /* Active state when modal is open */
  ${props => props.$active && `
    color: #fff;
    background-color: #F7FAFF;
    svg{
      filter: none;
    }
  `}

  &:hover {
    color: #fff;
    background-color: #F7FAFF;
    svg{
        filter: none;
    }
  }

  &:focus {
    outline: none;
  }
`
const InputWrapper = styled.div`
    display: flex;
    align-items: center;
    justify-content: space-between;

    .debounce-input-menu-item {
      ${props => props.hasMassUserIdTrigger ? `
        width: 177px;
      `: `
        width: 100%;
      `}
    }
`
const MenuBody = memo((props) => {
  const dispatch = useDispatch()
  const {  getPayload } = useAppFilter()
  const { toggleModal } = useSegmentModal()
  const {
    selectedOperator,
    isOperatorRadio,
    handleOperatorMenuClick,
    onVisibleChange,
    resetCategorySelect,
    callApi,
    isEmptyMessage,
    searchAttrInputText,
    loading,
    fetchedList,
    handleSearchInputProps,
  } = props
  const {
    attribute: operatorAttribute,
    format: operatorFormat,
    isSearchable,
    propertyName,
  } = selectedOperator
  const { screenRenamedList, megaFilterReducer, urlReducer: urlQ } = useSelector((state) => state)
  const { selectedAttributeProps } = megaFilterReducer
  const [groupingOptions, setGroupingOptions] = useState([])
  const [inputtedValue, setInputtedValue] = useState('')
  const [isMassUserIdModalVisible, setIsMassUserIdModalVisible] = useState(false)
  const firstAndPreviousKey = screenNameAttributes?.filter(value => value !== 'session_screen_list' && value !== 'event_activity_name' && value !== 'screen_name');
  const {
    attribute,
    title,
    type: operatorType,
  } = selectedAttributeProps || {}
  let controlledInput; let fetchedListOptions; let disabledProps
  let attributeNew = attribute; 
  const listRef = useRef(null);
  const {refetchCohorts, isCohortsRefetching} = useUserCohorts();

  const showMassUserIdModalTrigger = useMemo(()=>{
    if (['uxcam_user_id','kUXCam_UserIdentity'].includes(attribute)) {
        return true
    }
    return false
  } ,[attribute])
  
  // NOTE: Previous code
  // const fetchedList = firstAndPreviousKey?.includes(attribute) && isSearchTextExitOrLaunch ? 
  //  isSearchTextExitOrLaunch ? [...([screenInitialValue]), ...fetchedList] 
  //  :  searchAttrInputText ? fetchedList  
  //   :  [...([screenInitialValue]), ...fetchedList] : 
  //    fetchedList

  if (attribute === 'user_custom_property') attributeNew = 'userpropertyvalue'
  else if (attribute === 'event_custom_property') attributeNew = 'eventpropertyvalue'
  else if (attribute === 'utm') attributeNew = 'utmpropertyvalue'
  else if (attribute === 'user_first_utm') attributeNew = 'userfirstutmvalue'
  else if (attribute === 'session_screen_with_property') attributeNew = 'sessionscreenwithproperty'
  else if (attribute === 'session_screen_with_property_list') attributeNew = 'sessionscreenwithpropertylist'
  if (
    groupingOptions?.length ||
    (!isArray(inputtedValue) && inputtedValue) ||
    (isArray(inputtedValue) && inputtedValue?.length)
  )
    disabledProps = false
  else disabledProps = true
  const resetFields = () => {
    groupingOptions.length && setGroupingOptions([])
    setInputtedValue('')
  }
  const onDateChange = (date) => setInputtedValue(date)

  const handleGroupingOptions = (value) =>
    setGroupingOptions(groupingOptions.includes(value)
      ? groupingOptions.filter((v) => v !== value)
      : [...groupingOptions, value])


  // Handle modal open
  const handleOpenMassUserIdModal = useCallback((e) => {
    if (e) {
      e.preventDefault()
      e.stopPropagation()
    }
    setIsMassUserIdModalVisible(true)
  }, [])

  // Handle modal close
  const handleCloseMassUserIdModal = useCallback(() => {
    setIsMassUserIdModalVisible(false)
  }, [])


  const processArrayChildren = (arr) => {
      return arr.map((child) => {
        if (isObject(child)) {
          return child.uxcamuserid;
        }
        return child;
      });
    };
  const handleSelectAllOptions = useCallback(() => {
    setGroupingOptions(processArrayChildren(fetchedList));
  } , [fetchedList]);

  const handleMassUserIdApply = useCallback((values) => {
    const localGroupOption  = processArrayChildren(values);
    const newFilterPayload = getPayload(localGroupOption, inputtedValue, selectedOperator)

    if (newFilterPayload && newFilterPayload.length > 0) {
      newFilterPayload[0] = {
        ...newFilterPayload[0],
        multi_id_filter: true,
        multi_id_count: values.length
      }
    }

    callApi(newFilterPayload)
    dispatch(fetchPlanHatApi({ action: `Filtered ${mapPageNames[urlQ.parentType]} page`, info: { 'Filtered names': JSON.stringify(newFilterPayload) }}))
  }, [callApi, dispatch, getPayload, inputtedValue, selectedOperator, urlQ.parentType])

  const checkSelectDisabled = useCallback(() => {
    return isEqual(groupingOptions, fetchedList)
  }, [groupingOptions, fetchedList]);

  const handleApplyGrouping = async (e) => {
    e.preventDefault()
    if (
      (isSearchable && !groupingOptions.length) ||
      (!isSearchable && !inputtedValue && !isOperatorRadio)
    ) {
      message.error(!isSearchable && !inputtedValue
        ? 'Value is required!'
        : 'No Filter Selected!')
      return
    }
    const newFilterPayload = getPayload(groupingOptions, inputtedValue, selectedOperator)
    callApi(newFilterPayload)
    dispatch(fetchPlanHatApi({ action: `Filtered ${mapPageNames[urlQ.parentType]} page`, info: { 'Filtered names': JSON.stringify(newFilterPayload) }}))
  }
  const handleInputChange = (event) => {
    const { value } = event.target;
    if(operatorFormat === 'float' && value) onlyNumber?.test(value) && setInputtedValue(value)
    else setInputtedValue(value)
  }
  const secondsUnit = addSecondsSuffix(attributeNew, inputtedValue)

  useEffect(() => {
    resetFields()
    if (isOperatorRadio) setInputtedValue(operator[operatorType][0].attribute)
  }, [selectedOperator.format])

  const handleMassUserIdSaveAsCohort = useCallback(async (cohortFilter) => {
    await refetchCohorts();
    onVisibleChange()
    setTimeout(()=>{
        if(!isCohortsRefetching) callApi(cohortFilter);
    },[500]);
  }, [refetchCohorts, onVisibleChange, isCohortsRefetching, callApi])

  if (isSearchable) {
    controlledInput = (
        <InputWrapper hasMassUserIdTrigger={showMassUserIdModalTrigger}>
      <div className='debounce-input-menu-item'>
        <SearchOutlined />
        <DebounceInputComponent
          placeholder={setPlaceholder('Search')}
          onChange={(e) => handleSearchInputProps(e.target.value)}
          value={searchAttrInputText}
          />
      </div>
      {showMassUserIdModalTrigger &&
            <Tooltip title="Filter multiple user IDs" placement="bottom">
            <MassUserIdTriggerButton
            onClick={handleOpenMassUserIdModal}
            type="button"
            $active={isMassUserIdModalVisible}
            >
                <MultiUsersIcon />
            </MassUserIdTriggerButton>
            </Tooltip>
        }
        </InputWrapper>
    )
    fetchedListOptions = (
      <LoaderMenuItem style={{ left: 0 }} spinning={loading}>
        {fetchedList.length > 500 && (
          <OverThresholdText
            text="Not all results are displayed - type to search for more."
          />
        )}

        <SelectAllAndClear
          operatorAttribute={operatorAttribute}
          isOperatorRadio={isOperatorRadio}
          fetchedList={fetchedList}
          operatorType={operatorType}
          handleSelectAllOptions={handleSelectAllOptions}
          handleClearAllOptions={resetFields}
          disableSelect={checkSelectDisabled()}
          disableClear={groupingOptions.length <= 0}
        />
        <ul
          ref={listRef}
          className="viewport-list-container"
        >
          
          { loading ? null 
            : (!isEmptyMessage && fetchedList?.length ) || firstAndPreviousKey?.includes(attribute)  ? (
            <ViewportList
              viewportRef={listRef}
              items={fetchedList}
              className="viewport-list"
            >
            {
              (value,index) => {
                let key; let checkboxTitle;
                if (value?.uxcamuserid) {
                    key = value.uxcamuserid
                    const hasNameProperty = value.hasOwnProperty('name')
                    const hasCustomUserIdProperty = value.hasOwnProperty('hasCustomUserId')
  
                    let attributeType = ''
                    if (hasNameProperty && value.uxcamuserid) {
                        // If value has minimum of 2 properties name and uxcamuserid then its a uxcamuserid attribute
                        attributeType = 'uxcamuserid'
                    } else if (hasCustomUserIdProperty && value.uxcamuserid) {
                        // If value has minimum of 2 properties hasCustomUserId and uxcamuserid then its a uxcam_user_id attribute
                        attributeType = 'uxcam_user_id'
                    }
  
                    const hasNoCustomUserId = attributeType === 'uxcam_user_id' ? !value?.hasCustomUserId : value?.name === value?.uxcamuserid 
                    
                    if (hasNoCustomUserId) {
                        checkboxTitle = (
                            <Tooltip
                                placement='topLeft'
                                overlayClassName="undefined_tooltip_content"
                                title={NoCustomUserIdMessage}
                            >
                                <em>{`${value.uxcamuserid} *`}</em>
                            </Tooltip>
                        )
                    } else {
                        checkboxTitle = attributeType === 'uxcam_user_id' ? value.uxcamuserid : value.name
                    }
                } else {
                  key = value
                  checkboxTitle = value
                  if (screenNameAttributes.includes(attributeNew) || attributeNew === 'eventpropertyvalue') {
                    checkboxTitle =
                      screenRenamedList[value] || value
                  }
                  if (webScreenAttribtues.includes(attributeNew)) {
                    checkboxTitle = <Tooltip placement='topLeft' title={value}>{value}</Tooltip>;
                  }
                  if (['device_class', 'device_model'].includes(attribute)) {
                    checkboxTitle =
                      getRenamedDeviceName(value)
                  }

                  if( attribute === 'environment'){
                    checkboxTitle = <Tooltip placement='right' overlayClassName="undefined_tooltip_content" title={getEnvTooltip(value)}>{capitalizeEnvString(value)}</Tooltip>
                  }
                }
                if(value === '__undefined__'){
                  let tooltiptitle = '';
                  if (attribute === 'kUXCam_UserIdentity' || (attribute === 'user_custom_property' && propertyName === 'kUXCam_UserIdentity')) {
                    tooltiptitle = 'Users without an ID set by the API at the time of session.';
                  } else {
                    tooltiptitle = 'Users without specified value for the custom property at the time of session.';
                  }
                  checkboxTitle = <Tooltip overlayClassName="undefined_tooltip_content" title={tooltiptitle}><em>{value}</em></Tooltip>
                }
                return (
                  <li key={key+index}>
                      <Checkbox
                        checked={groupingOptions.includes(key)}
                        onChange={() => handleGroupingOptions(key)}
                      >
                        <Tooltip placement='rightTop' title={ checkboxTitle.length > 25 ? checkboxTitle : '' }>
                            <span className='checkbox-label'>{checkboxTitle}</span>
                        </Tooltip>
                      </Checkbox>
                  </li>
                )
              }
            }
          </ViewportList>) : (
            noMatchingFilterMenu
          )}
        </ul>
      </LoaderMenuItem>
    )
  } else if (isOperatorRadio) {
    controlledInput = (
      <Radio.Group
        onChange={(e) => {
          setInputtedValue(e.target.value)
          handleOperatorMenuClick({ key: e.target.value })
        }}
        value={inputtedValue}
      >
        {operator[operatorType].map((data) => (
          <Radio
            key={data.attribute}
            className="filter-radio-operator"
            value={data.attribute}
          >
            {data.title}
          </Radio>
        ))}
      </Radio.Group>
    )
  } else if (['float', 'integer', 'list_of_integer'].includes(operatorFormat)) {
    switch (operatorFormat) {
      case 'list_of_integer':
        controlledInput = (
          <SelectWithTags
            // placeholder={setPlaceholder('Input', `${title}s`)}
            placeholder='Enter value'
            value={isArray(inputtedValue) ? inputtedValue : []}
            handleChange={(values) => setInputtedValue(values.length
              ? values?.filter((x) => onlyNumber.test(x))
              : [])
            }
            maxTagCount={2}

          />
        )
        break
      default:
        controlledInput = (
          <Input
            autoFocus
            value={inputtedValue}
            onChange={handleInputChange}
            placeholder="1"
            className="width-100 filter-input-integer"
            suffix={secondsUnit}
          />
        )
        break
    }
  } else if (operatorType === 'date') {
    controlledInput = (
      <DateType
        selectedOperator={selectedOperator}
        onDateChange={onDateChange}
        fromMegaFilter
      />
    )
  } else if (['contains', 'not_contains', 'contains_any_in', 'not_contains_any_in'].includes(operatorAttribute)) {
    controlledInput = (
      <DebounceInputComponent
        autoFocus
        value={inputtedValue}
        onChange={(e) => setInputtedValue(e.target.value)}
        // placeholder={setPlaceholder(
        //   `Input${
        //     ['eventpropertyvalue', 'userpropertyvalue'].includes(attributeNew)
        //       ? ' value of'
        //       : ''
        //   }`,
        //   title
        // )}
        placeholder='Enter value'
        className="filter-input-string"
      />
    )
  } else if ( [ 'contains_any', 'not_contains_any' ].includes(operatorAttribute) ) {
      controlledInput = (
        <SelectWithTags
          placeholder='Enter value and press enter'
          numeric={ false }
          value={isArray(inputtedValue) ? inputtedValue : []}
          handleChange={(values) => setInputtedValue(values.length
            ? values?.filter((x) => values.length )
            : [])
          }
          maxTagCount={10}
          tokenSeparators={[',']}
        />
      )
  }

  return (
    <>
      {controlledInput}
      <div className='main-body-container'>
       {fetchedListOptions}
      </div>
        <MenuFooter
          resetFields={resetFields}
          onVisibleChange={onVisibleChange}
          disabled={disabledProps}
          handleApplyGrouping={handleApplyGrouping}
          resetCategorySelect={resetCategorySelect}
        />
        <MassUserIdFilter
          visible={isMassUserIdModalVisible}
          onClose={handleCloseMassUserIdModal}
          onApply={handleMassUserIdApply}
          onSaveAsCohort={handleMassUserIdSaveAsCohort}
          initialValues={[]}
          title="Filter multiple user IDs"
          placeholder="Enter user IDs (Comma or new line separated)"
          subtitle='Type or paste user IDs, separated by commas, or copy them directly from CSV files.'
          filterContext={{
            attribute: selectedAttributeProps?.attribute === 'kUXCam_UserIdentity' ? 'user_custom_property' : selectedAttributeProps.attribute,
            operator: selectedOperator?.attribute,
            table:selectedAttributeProps?.table,
            property_name: selectedAttributeProps?.attribute === 'kUXCam_UserIdentity' ? 'kUXCam_UserIdentity' : '',
          }}
        />
    </>
  )
})
export default withContextProps(MenuBody)
