  sessiondate: 'sessionDate',
  sessionhash: 'userSessionRun',
  eventcount: 'totalEvent',
  timeforuser: 'deviceLocalDateTime',
  devicemodel: 'deviceModel',
  appversion: 'appVersion',
  deviceclass: 'deviceClass',
  deviceheight: 'deviceHeight',
