const ColumnSelection = memo(({ cell, row }) => {
  const {
    urlReducer: urlQuery,
  } = useSelector((state) => state);

  const { sessionid: sessionIdURL } = urlQuery;
  
  const {
    column: { id, isCustomUserProperty }
  } = cell;

  const {
    sessionid,
    userProperty: user,
    sessionDuration,
    city,
    country,
    countryCode,
    totalEvent,
    totalGesture,
    rageGestureCount,
    video,
    isViewed,
    onItemPlay,
    onItemPause,
    sessionLocked,
    handleUserClick,
    getUserPageUrl,
    sessionanalyzedbyai,
    relevance_score: relevanceScore,
    short_description: shortDescription,
    platform,
    deviceModel,
    crashed,
    deviceClass,
    deviceHeight,
    deviceWidth,
    uniqueScreensCount,
    osVersion,
    recordedon,
    deviceLocalDateTime,
    isRageTap,
    ispagerefresh,
    isdeadclick,
    isuifreeze,
    userTimezone,
    sessionUploadedDateTime,
    browserName,
    browserVersion,
    deviceType,
    deviceOsName,
  } = row.original;

  if(has(user, removeUxCamCustomProperty(id))){
    return <Cell>
        <EllipseText>
        {user[removeUxCamCustomProperty(id)] || 'N/A'}
        </EllipseText>
      </Cell>
  }

  switch ( id ) {
    case 'sessionhashofuser':
      return (
        <SessionListItem
          key={sessionid}
          user={ user }
          city={city}
          country={country}
          duration={sessionDuration}
          sessionId={sessionid}
          onPlay={onItemPlay}
          onPause={onItemPause}
          selectedItem={sessionIdURL}
          video={video}
          isViewed={isViewed}
          sessionLocked={ sessionLocked }
          aiAnalyzed={ sessionanalyzedbyai }
          timeZoneDiff={ userTimezone }
          deviceLocalDateTime={ deviceLocalDateTime }
          handleUserClick={ handleUserClick }
          getUserPageUrl={ getUserPageUrl }
        />
      )
    case 'relevance':
      return (
        <RelevanceCell score={ relevanceScore } />
      )
    case 'recordedon':
      return (
        <TimeCell time={ recordedon } format="MMMM D, HH:mm"/>
      )
    case 'interactions':
      return (
        <InteractionsCell 
          gestures={ totalGesture }
          isRageTap={ isRageTap }
          isAppCrash={ ispagerefresh || crashed }
          isUIFreeze={ isdeadclick || isuifreeze }
        />
      )
    case 'aisummary':
      return (
        <AISummaryCell summary={ shortDescription }/>
      )
    case 'sessiondate':
      return <HorizontalCell>
        <div className="when-date title">
          {getDifferenceFromNow(sessionUploadedDateTime)}
          <StyledSpan className="subtitle">
            {formatDisplayTime(
              sessionUploadedDateTime,
              'ddd, MMMM DD, hh:mm A' // Format derived from useSessionColumns
            )}
          </StyledSpan>
        </div>
      </HorizontalCell>
    case 'timeforuser':
      return <Cell className="user-date title">
        {moment(deviceLocalDateTime).format('MMM DD, YYYY')}
        <StyledSpan className="subtitle">
          {moment(deviceLocalDateTime).format('ddd, hh:mm  a')}
        </StyledSpan>
      </Cell>
    case 'city':
      return <HorizontalCell>
        <div className="city title">
          {city}
          <StyledSpan className="subtitle">{country}</StyledSpan>
        </div>
        <div className="flag">
          {countryCode ? <ReactCountryFlag svg countryCode={countryCode} /> : null}
        </div>
      </HorizontalCell>
    case 'devicemodel': {
        const tempDeviceType = platformMapper[platform];
        const deviceModelFormatted = deviceModel?.includes('iPhone') || deviceModel?.includes('iPad')
          ? getRenamedDeviceName(deviceModel)
          : deviceModel?.toUpperCase();
  
        return <HorizontalCell>
          <div className="platform-icon">
            {
              tempDeviceType === 'desktop' ? <p>D</p>
              : <Icon type={tempDeviceType} />
            }
          </div>
  
          <StyleSpan>{deviceModelFormatted}</StyleSpan>
        </HorizontalCell>
      }
    case 'country':
      return <HorizontalCell>
        <StyledSpanCountry>{country}</StyledSpanCountry>
      </HorizontalCell>
    case 'uniquescreenscount':
      return <Cell>{containsOnlyNumbers(uniqueScreensCount)}</Cell>
    case 'crashed':
      return <Cell>{crashed ? 'Yes' : 'No'}</Cell>
    case 'eventcount':
      return <Cell>{containsOnlyNumbers(totalEvent)}</Cell>
    case 'totalgesture':
      return <Cell>{containsOnlyNumbers(totalGesture)}</Cell>
    case 'ragegesturecount':
      return <Cell>{containsOnlyNumbers(rageGestureCount)}</Cell>
    case 'osversion':
      return <Cell>
        {osVersion}{platform === 3 ? '' :`(${platformDisplayMapper[platform]})`}
      </Cell>
    case 'duration': {
      const sessionDurationFormatted = sessionDuration < 60 ? `${Math.round(sessionDuration)} sec` : convertGetTime({durationInSecs: sessionDuration});
      return <Cell>{sessionDurationFormatted}</Cell>
    }
    case 'userdevice': {
      const userCell = getUserName(user);
      return <Cell>
        <a
          href={getUserPageUrl(user?.uxcamuserid)}
          onClick={(e) => handleUserClick(e, user?.uxcamuserid)}
        >
          {userCell}
        </a>
      </Cell>
    }
    case 'platform':
      return <Cell>{platformDisplayMapper[platform]}</Cell>
    case 'deviceclass': {
      const deviceClassUpdated = deviceClass?.includes('iPhone') || deviceClass?.includes('iPad')
        ? getRenamedDeviceName(deviceClass)
        : deviceClass;
      return <Cell>{deviceClassUpdated}</Cell>
    }
    case 'sessionid':
      return <HorizontalCell><StyleSpan>{sessionid}</StyleSpan></HorizontalCell>
    case 'deviceheight':
      return <Cell>{deviceHeight}</Cell>
    case 'devicewidth':
      return <Cell>{deviceWidth}</Cell>
    case 'browsername':
      return <Cell>{browserName || 'N/A'}</Cell>
    case 'browserversion':
      return <Cell>{browserVersion || 'N/A'}</Cell>
    case 'devicetype':
      return <Cell>{deviceType || 'N/A'}</Cell>
    case 'deviceosname':
      return <HorizontalCell>{deviceOsName || 'N/A'} {getOsIcon(deviceOsName)}</HorizontalCell>
    default:
      return (
        <Cell>
          { isCustomUserProperty ? 'N/A' : containsOnlyNumbers(row.original[keyMap[id]]) || containsOnlyNumbers(row.original[id]) || '-' }
        </Cell>
      )
  }
} )

const getSize = ( attribute ) => {
  switch( attribute ) {
    case 'sessionhashofuser':
      return 272
    case 'relevance':
      return 115
    case 'interactions':
      return 150
    case 'aisummary':
      return 460
    default:
      return undefined
  }
}

const getMaxSize = ( attribute ) => {
  switch( attribute ) {
    case 'sessionhashofuser':
      return 272
    case 'relevance':
      return 115
    default:
      return undefined
  }
}

const tryToParseTooltip = ( tooltip ) =>  {
  if ( !tooltip ) {
    return undefined
  }

  try {
    const html = JSON.parse(tooltip);
    // eslint-disable-next-line react/no-danger
    return <div dangerouslySetInnerHTML={{ __html: html }} />
  } catch {
    return tooltip
  }
}

export default function useAISessionColumns( headers ) {
  const { aiSessionFeatureAllowed } = useRestrictionContext() || {}
  const batchesEnabled = aiSessionFeatureAllowed
  const columnHelper = createColumnHelper(
  );

  const columns = useMemo(() => 
    headers.map( ( { attribute, isVisible, titleInfo, title, isCustomUserProperty, isSortable, isDraggable } ) => {
      if ( !isVisible || attribute === 'video' ) {
        return null
      }
      return (
        columnHelper.accessor( attribute, {
          header: isCustomUserProperty ? (
            <UFCTooltip placement="top" title={ tryToParseTooltip( titleInfo ) } align={{ offset: [ 0, -10 ] }}>
              <EllipseTitle>
                <em>{stripCustomPropertyAndMapLabel(title)}</em>
              </EllipseTitle>
            </UFCTooltip>
          ) : (
            <UFCTooltip placement="top" title={ tryToParseTooltip( titleInfo ) } align={{ offset: [ 0, -10 ] }}>
              <EllipseTitle>{ title }</EllipseTitle>
            </UFCTooltip>
          ),
          cell: ( { cell, row } ) => <ColumnSelection cell={ cell } row={ row } />,
          accessor: attribute,
          titleInfo: title,
          enableSorting: isSortable,
          enableResizing: isDraggable,
          size: getSize( attribute ),
          minSize: getSize( attribute ),
          maxSize: getMaxSize( attribute ),
          sortDescFirst: true,
        }, 
      ) )
    }
  ), [ columnHelper, headers ] )
    .filter( column => column )

  const columnsWithSelect = useMemo(() => [
    {
      id: 'select',
      disableResizing: true,
      minWidth: batchesEnabled ? 35 : 10,
      width: batchesEnabled ? 35 : 10,
      maxWidth: batchesEnabled ? 35 : 10,
      header: batchesEnabled ? ({ table }) => (
        <CheckBoxWrapper>
          <TableCheckbox
            {...{
              checked: table.getIsAllRowsSelected(),
              indeterminate: table.getIsSomeRowsSelected(),
              onChange: table.getToggleAllRowsSelectedHandler(),
            }}
          />
        </CheckBoxWrapper>
      ) : () => null,
      cell: ({ row }) => (
        <AITableRowCheckCell
          row={row}
          expanded
          showCheckbox={batchesEnabled}
        />
      ),
    },
    ...columns,
  ], [columns, batchesEnabled])
    .filter( column => column )
  return columnsWithSelect;

}