import React, { memo, useCallback } from 'react'
import styled from 'styled-components'
import { showIntercom } from 'Utils/constants'

export const Wrapper = styled.div`
	height: 100%;
	width: 100%;
	display: flex;
	justify-content: center;
	align-items: center;
	padding: 32px;

`
export const Left = styled.div`
	margin-right: 100px;
	img, svg {
		max-width: 100%;
		min-width: 250px;
		object-fit: contain;
	}
	@media only screen and (max-width: 780px) {
		margin-right: 0px;
	}
	@media only screen and (max-width: 850px) {
		margin-right: 48px;
	}
`

export const Right = styled.div`
	display: flex;
	flex-direction: column;
	max-width: 455px;
	justify-content: center;
`

export const Title = styled.h2`
	font-weight: 500;
	font-size: 28px;
	line-height: 35px;
	color: #161E35;
	margin-bottom: 4px;
`

export const SubTitle = styled.h3`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 500;
	font-size: 18px;
	color: #161E35;
	line-height: 24px;
	margin-bottom: 16px;
`

export const List = styled.ul`
	font-family: 'Roboto';
	font-style: normal;
	font-weight: 400;
	font-size: 14px;
	line-height: 24px;
	color: #161E35;
	margin-bottom: 16px;
	margin-left: 20px;
	li {
		list-style: outside;
	}
`

export const Button = styled.button`
	font-weight: 400;
	font-size: 14px;
	line-height: 24px;
	color: #FFFFFF;
	padding: 4px 32px;
	background-color: #5D97FF;
	border-radius: 6px;
	cursor: pointer;
	border: none;
	outline: none;
	width: fit-content;
	transition: all 0.2s ease-in-out;
	min-width: 153px;
	&:hover {
		background-color: #4A79CC;
	}

	&[data-variant='secondary'] {
		background-color: #FFFFFF;
		color: #5D97FF;
		border: 1px solid #5D97FF;

		&:hover{
			background-color: #f7faff;
		}
	}
`

const ButtonWrapper = styled.div`
	display: flex;
	gap: 16px;
	align-items: center;
`

const LockedPage = ( { 
	image: Image, 
	imageSrc,
	imageAlt = "Illustration of statistics", 
	imageWidth = 500, 
	imageHeight = 500, 
	selfServeFlag, 
	handleClickRequestPricing = () => null, 
	handleClickSeePricing = () => null,
	title = "",
	subTitle = "",
	list,
	learnMoreLink = null,
	openIntercom = false,
	dataIntercomTarget = null
} ) => {

	const CtaRender = useCallback(() => {
		if( openIntercom ) {
			return (
				<Button onClick={ () => showIntercom() } data-intercom-target={dataIntercomTarget}>
					Request a trial
				</Button>
			)
		}

		return  selfServeFlag ? (
			<Button onClick={ handleClickSeePricing }>
				See pricing
			</Button>
		) : (
			<Button onClick={ handleClickRequestPricing }>
				Request pricing
			</Button>
		) 
	}, [dataIntercomTarget, handleClickRequestPricing, handleClickSeePricing, openIntercom, selfServeFlag])

	return(
		<Wrapper>
			<Left>
				{ Image && <Image alt={ imageAlt } width={ imageWidth } height={ imageHeight } /> }
				{ imageSrc && <img src={ imageSrc } alt={ imageAlt } width={ imageWidth } height={ imageHeight } /> }
			</Left>
			<Right>
				<Title>
					{ title }
				</Title>
				<SubTitle>
					{ subTitle }
				</SubTitle>
				{ list && (
					<List>
						{ list }
					</List>
				) }
				<ButtonWrapper>
				<CtaRender />
				{
					learnMoreLink && (
						<Button data-variant='secondary' type='button' onClick={ () => window.open(learnMoreLink, '_blank') }>
							Learn more
						</Button>
					)
				}
				</ButtonWrapper>
			</Right>
		</Wrapper>
	)}

export default memo( LockedPage )