import React, { createContext, useContext, useMemo, useState } from 'react'

type TFloatingToolbarContext = {
	open: boolean
	setOpen: React.Dispatch<React.SetStateAction<boolean>>
	content: React.ReactNode | null
	setContent: React.Dispatch<React.SetStateAction<React.ReactNode>>
	onClose: (() => void) | null
	setOnClose: React.Dispatch<React.SetStateAction<(() => void) | null>>
	close: () => void
}

const DefaultValues: TFloatingToolbarContext = {
	open: false,
	setOpen: () => null,
	content: null,
	setContent:  () => null,
	onClose: null,
	setOnClose: () => null,
	close: () => null,
}

const FloatingToolbarContext = createContext<TFloatingToolbarContext>( DefaultValues )

export const FloatingToolbarContextProvider = ( { children }: { children: React.ReactNode} ) => {
	const [ open, setOpen ] = useState( true )
	const [ content, setContent ] = useState<React.ReactNode | null>( null )
	const [ onClose, setOnClose ] = useState<(() => void) | null>( null )

	const close = React.useCallback(() => {
		onClose?.()
		setOnClose(null)
		setOpen( false )
	}, [onClose])

	const value: TFloatingToolbarContext = useMemo( () => (	{
		open,
		setOpen,
		content,
		setContent,
		onClose,
		setOnClose,
		close,
	} ), [
		open,
		setOpen,
		content,
		setContent,
		onClose,
		setOnClose,
		close,
	] )

	return (
		<FloatingToolbarContext.Provider value={ value }>
			{ children }
		</FloatingToolbarContext.Provider>
	)
}

export const useFloatingToolbarContext = () => useContext( FloatingToolbarContext )