import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Select, Spin, Tooltip } from 'antd';
import debounce from 'lodash/debounce';
import { useSelector } from 'react-redux';
import styled from 'styled-components';
import {startOfDay, endOfDay, format } from 'date-fns';

import videoApi from 'services/videoApi';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { subtractMonths } from 'components/features/setting/commonUtils';
import { getEnvTooltip } from 'components/shared/GlobalFilter/components/utils';
import { useRenamedScreenOptions } from './utils';

const isoDateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'"

const attributeDataRaw  = {
  deviceModel: 'device_model_and_marketing_name',
  appVersion:'app_version',
  country: 'device_country',
  event: 'session_event_list',
  osVersion: 'device_os_version',
  screen:'screen_name'
  }

const StyledSelectField = styled(Select)`
  min-width: 100% !important;
  .ant-select-item-empty {
    font-size: 12px;
  }
  .ant-select-selector {
    border: 1px solid #ecebec !important;
    border-radius: 0 !important;
  }
`;

const DebounceSelect = ({
  fetchOptions,
  filterOptionData,
  debounceTimeout = 1000,
  placeholder,
  value,
  disabled,
  onChange,
}) => {
  const [fetching, setFetching] = useState(false);
  const [options, setOptions] = useState([]);
  const fetchRef = useRef(0);

  const debounceFetcher = useMemo(() => {
    const loadOptions = (searchName) => {
      fetchRef.current += 1;
      const fetchId = fetchRef.current;
      if (!filterOptionData?.length) {
        setFetching(true);
        setOptions([]);
        fetchOptions(searchName).then((newOptions) => {
          if (fetchId !== fetchRef.current) {
            return;
          }
          setOptions(newOptions);
          setFetching(false);
        });
      } else {
        const newOption = filterOptionData
          .map((obj) =>
            obj?.value
              ?.toLowerCase()
              ?.includes(searchName?.length ? searchName.toLowerCase() : '')
              ? obj
              : null
          )
          .filter((obj) => obj?.value);
        setOptions(newOption);
      }
    };

    return debounce(loadOptions, debounceTimeout);
  }, [fetchOptions, debounceTimeout, filterOptionData]);

  return (
    <StyledSelectField
      labelInValue
      mode="multiple"
      showArrow
      onChange={onChange}
      filterOption={false}
      value={value?.map((v) => ({ key: v.value, label: v.label }))}
      disabled={disabled}
      onSearch={debounceFetcher}
      onFocus={debounceFetcher}
      notFoundContent={
        fetching || filterOptionData?.length ? (
          <Spin size="small" />
        ) : (
          'Not Available'
        )
      }
      options={options}
      placeholder={placeholder}
    />
  );
};

export function capitalizeEnvString(input) {
  const valuesToCapitalize = ['.alpha', '.beta', '.release'];

  if(input === '__undefined__') return 'Undefined'

  if (typeof input !== 'string' || input.length === 0 || !valuesToCapitalize.includes(input)) {
    return input;
  }

  const modified =
    input.replace(/^\./, '').charAt(0).toUpperCase() + input.slice(2);
  return modified;
}

const DebounceSearch = ({
  filterOptionData,
  defaultValues,
  handleSelect,
  attribute,
  attributeType,
  placeholder,
  disabled,
}) => {
  const [value, setValue] = useState([]);
  const { urlReducer: urlQuery, currentOrgReducer: activeSubscription } = useSelector((state) => state);
  const dataRetentionMonths = activeSubscription?.planLimit?.dataRetentionTime
  const { app } = urlQuery;
  const { getRenamedScreenName } = useRenamedScreenOptions();

  const fromDate = useMemo(()=> {
    const currentDate = new Date();
    return format(startOfDay(subtractMonths(dataRetentionMonths, currentDate)), isoDateFormat)
  }  , [dataRetentionMonths])
  const toDate = format(endOfDay(new Date()), isoDateFormat);
  const dateRange =  {from: fromDate, to: toDate};
  const newScreensFilter = useFeatureFlag( 'new-screens-filter' ) 
  const attributeData = newScreensFilter ? attributeDataRaw : { ...attributeDataRaw, screen: 'session_screen_list' }

  const fetchUserList = async (data) => {
    const searchValue = typeof data === 'string' ? data : '';
    const newAttribute = attributeData[attribute]
    if(attribute === 'sdkVersion'){
      return [];
    }
    const dataField = {
      attribute:  newAttribute || attribute,
      search: searchValue,
      table: 'session',
      dropdownLimit:501,
      appid: app,
      dateRange,
      ...(attributeType &&
        (attribute === 'appVersion' || attribute === 'osVersion') && { filter: [{
          attribute: 'device_platform',
          operator: "equal",
          value: attributeType !== 'ios' ?  1 : 2,
          table: "session"
      }] }),
    };
    
    return videoApi.fetchData(dataField)
    .then((response) => response?.data)
    .then((res) => res?.data?.map((field) => {
      if (attribute === 'deviceModel') {
        const parsedField = JSON.parse(field);
          // * CX-2113 For DeviceModal and non-iphone devices, label should be of model_Name (model_id). Eg. Samsung S24 (SM-S911B)
          // * CX-2113 For Iphone devices, label should only include model_Name Eg. iPhone 12 Pro
          const excludeIdOnLabel = ['iphone', 'ipad', 'ipod']; // * This List is used to exclude id from label 

          return {
              label: excludeIdOnLabel?.some(prefix => parsedField[0].toLowerCase().startsWith(prefix)) ?
                  parsedField[0]:
                  `${parsedField[0]} (${parsedField[1]})`
              ,
              value: `${parsedField[0]}+${parsedField[1]}`, // * NOTE Operator `+` is used to create a unique key for each option, and this value is used in `handleSelect->handleRestructure` to split and get key and value on submission
          }
      }
      if (attribute === 'screen') {
        // update with renamed screen names
        return {
          label: getRenamedScreenName(field),
          value: field,
        }
      }
      if (attribute === 'environment') {
        return {
          label: <Tooltip title={getEnvTooltip(field)} placement='right'>{capitalizeEnvString(field)}</Tooltip>,
          value: field,
        }
      }
      return {
        label: field,
        value: field,
      }  
  }))
  };

  useEffect(() => {
      if (attribute === 'environment') {
      setValue(defaultValues?.map((val) => ({
        label: capitalizeEnvString(val.key),
        ...val,
      })));
    }
    if (attribute === 'screen') {
      // update with renamed screen names
      setValue(defaultValues?.map((val) => ({
        label:  getRenamedScreenName(val.key),
        ...val,
      })));
    }
    else setValue(defaultValues || []);
  }, [defaultValues, attribute]);

  return (
    <DebounceSelect
      value={value}
      placeholder={
        attribute === 'deviceModel' ? 'Search device model' : placeholder
      }
      fetchOptions={(data) => fetchUserList(data, attribute)}
      filterOptionData={filterOptionData}
      disabled={disabled}
      onChange={(newValue) => {
        setValue(newValue);
        handleSelect(newValue);
      }}
    />
  );
};

export default DebounceSearch;
