import { Checkbox, CheckboxOptionType, Dropdown, Menu, Tabs } from 'antd'
import React, { memo, useMemo } from 'react'
import { DebounceInput } from 'react-debounce-input'
import styled, { createGlobalStyle } from 'styled-components'
import IconSearch from 'public/static/sessions/search.svg'
import { SelectAllAndClear } from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import { IEventCount } from 'types/sessionTypes'
import { CheckboxValueType } from 'antd/lib/checkbox/Group'
import { IEventType } from 'components/features/events/types'
import ButtonNew from '../ButtonNew'
import VirtualizedCheckboxGroup from './VirtualizedCheckboxGroup'

interface IProps {
	tabs: {
		key: string,
		name: React.JSX.Element,
	}[]
	searchValue: string
	isLoading: boolean
	handleSearchChange: (e: React.ChangeEvent<HTMLInputElement>) => void
	handleSelectAll: () => void
	handleClearAllOptions: () => void
	data: IEventCount[]
	selectAllDisabled: boolean
	clearAllDisabled: boolean
	checkboxOptions: CheckboxOptionType[]
	handleCheckboxChange: (checkedValue: CheckboxValueType[]) => void
	checkboxValues: string[]
	handleReset: () => void
	handleApply: () => Promise<void>
	activeEventTabType: IEventType
	handleTabChange: (activeKey: string) => void
	dropdownOpen: boolean
	handleDropdownChange: (visible: boolean) => void
	type: 'events' | 'gestures' | 'screens'
	barContent: React.ReactNode
}

const GlobalStyles = createGlobalStyle<{ type: IProps[ 'type' ] }>`
	.${ ( { type } ) => type }-dropdown {
		.ant-tabs-ink-bar.ant-tabs-ink-bar-animated {
			background-color: #5D97FF;
		}
		.ant-tabs-tab {
			font-weight: 500;
			font-size: 12px;
			line-height: 16px;
			color: #161E35;
			margin: 0;
			&.ant-tabs-tab-active {
				color: #5D97FF;
			}
		}
		.ant-tabs-nav {
			margin-bottom: 10px;
		}
		.ant-tabs-nav-list {
			width: 100%;
			justify-content: space-between;
		}
		.ant-tabs-nav-operations {
			display: none !important;
		}
		.ant-tabs-nav::before {
			border-bottom-width: 2px;
		}
		.ant-tabs {
			width: 234px;
		}
		.ant-tabs-tab {
			width: 50%;
			justify-content: center;
			padding: 8px 0;
			user-select: none;
		}
		.ant-tabs-tab-btn {
			font-weight: 400;
			&[aria-selected="true"] {
				font-weight: 500;
				color: #5D97FF;
			}
		}
		.ant-dropdown-menu {
			padding: 10px;
			border-radius: 8px;
			box-shadow: none;
			border: 1px solid #E3E3E6;
		}
		.ant-checkbox-group {
			display: flex;
			flex-direction: column;
			max-height: 190px;
			overflow: auto;
			margin-bottom: 20px;
			&::-webkit-scrollbar {
				width: 5px;
				height: 5px;
			}
			&::-webkit-scrollbar-track{
					border-radius: 6px;
			}

			&::-webkit-scrollbar-thumb {
				background-color: #babec5;
				border-radius: 6px;
				transition: background-color 1s;
				&:hover{
					background-color: #747c8b;
				}
			}
			.ant-checkbox-group-item {
				margin: 0;
				padding: 9px 9px 9px 10px;
				font-weight: 400;
				font-size: 12px;
				line-height: 13px;
				color: #4F4F4F;
				display: inline-flex;
				.ant-checkbox {
					margin-right: 2px;
				}
				> span:not(.ant-checkbox) {
					flex: 1;
				}
			}
		}
	}
`

const SearchWrapper = styled.div`
	position: relative;
	margin-bottom: 8px;
	svg {
		position: absolute;
		top: 50%;
		left: 10px;
		transform: translateY( -50% );
	}
`

const Search = styled( DebounceInput )`
	font-weight: 400;
	font-size: 12px;
	line-height: 24px;
	padding: 2px 2px 2px 32px;
	background-color: #F3F4F5;
	border: none;
	border-radius: 6px;
	outline: none;
	color: #161E35;
	width: 100%;
	::placeholder {
		color: #737886;
		opacity: 1;
	}
`

const InfoWrapper = styled.div`
	font-style: italic;
	font-weight: 400;
	font-size: 12px;
	line-height: 19px;
	color: #161E35;
	padding: 4px 16px;
	margin-bottom: 16px;
`

export const SelectAllAndClearWrapper = styled.div`
	margin-left: 10px;
`

const Buttons = styled.div`
	display: flex;
	gap: 8px;
	button {
		flex: 1;
		padding: 0;
		justify-content: center;
	}
`

const NoDataText = styled.div`
	font-size: 12px;
	line-height: 24px;
	margin-bottom: 16px;
	color: #737886;
	text-align: center;
	text-transform: capitalize;
	margin-top: 10px;
`

export const AdjustedSelectAllAndClear = SelectAllAndClear as React.FC<{
	handleSelectAllOptions: unknown,
	handleClearAllOptions: unknown,
	disableSelect: unknown,
	disableClear: unknown,
}>

const EventsDropdownCommon: React.FC<IProps> = ( { 
	tabs,
	searchValue,
	isLoading,
	data,
	selectAllDisabled,
	clearAllDisabled,
	checkboxOptions,
	checkboxValues,
	activeEventTabType,
	dropdownOpen,
	type,
	barContent,
	handleCheckboxChange,
	handleReset,
	handleApply,
	handleTabChange,
	handleDropdownChange,
	handleSearchChange,
	handleSelectAll,
	handleClearAllOptions,
} ) => {
	const tabContent = useMemo( () => tabs.map( tab => (
		<Tabs.TabPane tab={ tab.name } key={ tab.key } active={ false }>
			<SearchWrapper>
				<Search 
					placeholder={ `Search ${ tab.key.toLowerCase() }`}
					value={ searchValue }
					onChange={ isLoading ? () => null : handleSearchChange }
					debounceTimeout={ 500 }
				/>
				<IconSearch />
			</SearchWrapper>
			{ data?.length > 499 && (
				<InfoWrapper>
					Not all results are shown. Use search to find more.
				</InfoWrapper>
			) }
			<SelectAllAndClearWrapper>
				<AdjustedSelectAllAndClear
					handleSelectAllOptions={ handleSelectAll }
					handleClearAllOptions={ handleClearAllOptions }
					disableSelect={ selectAllDisabled }
					disableClear={ clearAllDisabled }
				/>
			</SelectAllAndClearWrapper>
			{ data?.length > 0 && !isLoading && (
				data.length > 1000 ? (
					<VirtualizedCheckboxGroup
						options={ checkboxOptions }
						onChange={ handleCheckboxChange }
						value={ checkboxValues }
					/>
				) : (
					<Checkbox.Group
						options={ checkboxOptions }
						onChange={ handleCheckboxChange }
						value={ checkboxValues }
					/>
				)
			) }
			{ !data?.length && searchValue?.length && !isLoading ? (
				<NoDataText>
					No search results
				</NoDataText>
			) : null }
			{ !data?.length && !searchValue?.length && !isLoading ? (
				<NoDataText>
					{ type } list is empty
				</NoDataText>
			) : null }
			{ isLoading ? (
				<NoDataText>
					Loading { type }...
				</NoDataText>
			) : null }
			<Buttons>
				<ButtonNew
					size='big'
					width='wide'
					variant='ghost'
					onClick={ handleReset }
					disabled={ isLoading }
				>
					Reset
				</ButtonNew>
				<ButtonNew
					size='big'
					width='wide'
					onClick={ handleApply }
					disabled={ isLoading }
				>
					Apply
				</ButtonNew>
			</Buttons>
		</Tabs.TabPane>
	) ), [ checkboxValues, checkboxOptions, clearAllDisabled, selectAllDisabled, data, searchValue, isLoading, tabs, type, handleClearAllOptions, handleSelectAll, handleReset, handleSearchChange, handleCheckboxChange, handleApply, ] )

	const menu = useMemo( () => (
		<Menu>
			<Tabs activeKey={ activeEventTabType } onChange={ handleTabChange }>
				{ tabContent }
			</Tabs>
		</Menu>
	), [ tabContent, activeEventTabType, handleTabChange ] )

	return (
		<>
			<GlobalStyles type={ type } />
			<Dropdown 
				overlay={ menu }
				trigger={ [ 'click' ] }
				visible={ dropdownOpen }
				onVisibleChange={ handleDropdownChange }
				overlayClassName={ `${ type }-dropdown` }
				align={ { offset: [ -1, 6 ] } }
			>
				{ barContent }
			</Dropdown>
		</>
	)
}

export default memo( EventsDropdownCommon )