import React, { memo } from 'react';
import { Spin } from 'antd';
import styled from 'styled-components';
import ReactLoader from 'components/common/reactLoading';

const Spinner = styled(Spin)`
  position: absolute;
  z-index: 999;
  left: 50%;
  top: 50%;
  .ant-spin-dot {
    font-size: ${props => props.fontSize}
  }
  svg {
    path {
      fill: #5d97ff;
    }
  }
`;

const Loader = memo(({ isLoading, fontSize = '60px', style }) => <Spinner fontSize={fontSize} spinning={isLoading} indicator={<ReactLoader />} style={style} />);

export default Loader;
