import { useEffect, useRef, useState, useCallback } from 'react'

type UseIntervalCheckOptions<T> = {
	checkInterval: number // How often to check if main interval passed (in ms)
	mainInterval: number // Main interval duration (in ms)
	onCheck: (isManualTrigger: boolean) => Promise<T> // Function to call every mainInterval
	onSuccess?: (data: T) => void // Callback on successful check
	shouldStopOnEmptyData?: (data: T) => boolean // Function to determine if data is empty
	runOnMount?: boolean // Whether to run check on initial mount
	enabled?: boolean // Whether the hook is enabled (default: true)
}

type UseIntervalCheckReturn = {
	timeLeft: number // Seconds left until next check
	isChecking: boolean // Whether currently checking
	triggerManualCheck: () => void // Trigger manual check and reset timer
	stop: () => void // Stop the interval check
	start: () => void // Start the interval check
}

export const useIntervalCheck = <T>({
	checkInterval = 1000,
	mainInterval = 60000,
	onCheck,
	onSuccess,
	shouldStopOnEmptyData,
	runOnMount = true,
	enabled = true,
}: UseIntervalCheckOptions<T>): UseIntervalCheckReturn => {
	const [timeLeft, setTimeLeft] = useState<number>(Math.floor(mainInterval / 1000))
	const [isChecking, setIsChecking] = useState<boolean>(false)
	const [isActive, setIsActive] = useState<boolean>(true)

	const checkIntervalRef = useRef<ReturnType<typeof setTimeout> | null>(null)
	const lastCheckTimeRef = useRef<number>(Date.now())
	const hasRunOnMountRef = useRef<boolean>(false)

	const performCheck = useCallback(async (skipActiveCheck = false, isManualTrigger = false) => {
		if (isChecking || (!skipActiveCheck && !isActive)) {
			return
		}
		setIsChecking(true)
		try {
			const data = await onCheck(isManualTrigger)

			onSuccess?.(data)

			// Check if we should stop based on empty data
			if (shouldStopOnEmptyData && shouldStopOnEmptyData(data)) {
				setIsActive(false)
				if (checkIntervalRef.current) {
					clearInterval(checkIntervalRef.current)
					checkIntervalRef.current = null
				}
			}
		} catch (error) {
			// quiet fail
		} finally {
			setIsChecking(false)
		}
	}, [isChecking, isActive, onCheck, onSuccess, shouldStopOnEmptyData])

	const triggerManualCheck = useCallback(() => {
		setIsActive(true) // Reactivate if stopped
		lastCheckTimeRef.current = Date.now()
		setTimeLeft(Math.floor(mainInterval / 1000))
		performCheck(true, true) // Skip active check for manual triggers, mark as manual
	}, [performCheck, mainInterval])

	const stop = useCallback(() => {
		setIsActive(false)
		if (checkIntervalRef.current) {
			clearInterval(checkIntervalRef.current)
			checkIntervalRef.current = null
		}
	}, [])

	const start = useCallback(() => {
		setIsActive(true)
		lastCheckTimeRef.current = Date.now()
		setTimeLeft(Math.floor(mainInterval / 1000))
	}, [mainInterval])

	useEffect(() => {
		if (!isActive || !enabled) {
			hasRunOnMountRef.current = false // Reset when disabled
			return
		}

		// Run on mount if specified
		if (runOnMount && !hasRunOnMountRef.current) {
			hasRunOnMountRef.current = true
			performCheck()
		}

		// Set up interval to check time every checkInterval
		checkIntervalRef.current = setInterval(() => {
			const elapsed = Date.now() - lastCheckTimeRef.current
			const remaining = Math.max(0, Math.floor((mainInterval - elapsed) / 1000))

			setTimeLeft(remaining)

			// If time's up, perform check and reset
			if (elapsed >= mainInterval) {
				lastCheckTimeRef.current = Date.now()
				setTimeLeft(Math.floor(mainInterval / 1000))
				performCheck()
			}
		}, checkInterval)

		// eslint-disable-next-line consistent-return
		return () => {
			if (checkIntervalRef.current) {
				clearInterval(checkIntervalRef.current)
			}
		}
	}, [isActive, enabled, checkInterval, mainInterval, performCheck, runOnMount])

	return {
		timeLeft,
		isChecking,
		triggerManualCheck,
		stop,
		start,
	}
}
