import React from 'react'
import ConversionSequence from './ConversionSequence'
import FunnelSequence from './FunnelSequence'
import { IConversionStepFilter } from './ConversionSequence/utils';
import { IFunnelStepFilter } from './FunnelSequence/utils';

function AppliedSequenceFilter({
    filterData,
    hasMoreFilters
}:{
    filterData: IConversionStepFilter | IFunnelStepFilter;
    hasMoreFilters: boolean;
}) {
    const {attribute} = filterData;
   if( attribute === 'action_sequence_conversion') {
     return (
       <ConversionSequence 
         filterData={ filterData as IConversionStepFilter }
         hasMoreFilters={ hasMoreFilters }
       />
     )
   }
   if ( [ 'action_sequence_ordered', 'action_sequence' ].includes( attribute ) ) {
     return (
       <FunnelSequence
       filterData={ filterData as IFunnelStepFilter }
       hasMoreFilters={ hasMoreFilters }
       />
       )
    }
    return null;
}

export default AppliedSequenceFilter