import React, {memo, useMemo} from 'react';
import { Select, Tooltip } from 'antd'
import _ from 'lodash'
import { compactNotation } from 'Utils/helpers/commonUtils';
import FunnelListChevron from 'public/static/funnel/funnel-list-chevron.svg'

const {Option} = Select
const OptionLabel = ({ value, count }) => (
    <Tooltip title={value}>
      <div style={{display: 'flex'}}>
        <span className='event-name'>{value}</span>{' '}
      {count && (
        <span role='count' className='event-count' style={{marginLeft:'auto'}}>
          {compactNotation(count)}
        </span>
      )}
      </div>
    </Tooltip>
  )
const SelectDropdownWithCount = memo(({
  id,
  placeholder,
  onChange,
  selectedList,
  originalList,
  loader,
  eventTable,
  dropdownVisible,
  onDropdownVisibleChange,
  disabled,
  parentType
}) => {
  const tooltipTitle = useMemo(
    () =>
      selectedList?.length > 1 &&
      selectedList.join('')?.length > 30 &&
      !dropdownVisible
        ? selectedList.map((value) => (
            <span key={value}>
              {value} <br />
            </span>
          ))
        : '',
    [dropdownVisible, selectedList]
  );
  return  (
    <Tooltip title={parentType === 'eventsList' ? tooltipTitle : ''}>
      <Select
        mode='multiple'
        showSearch
        showArrow
        placeholder={placeholder}
        dropdownClassName='event-list-dropdown'
        className='dropdown-input-btn select-normal'
        maxTagCount={2}
        maxTagTextLength={selectedList?.length !== 1 && selectedList.join('')?.length > 30 ? 11 : ''}
        onChange={(list) => {
          onChange(list, id)
        }}
        loading={loader}
        optionLabelProp='label'
        value={
          !loader && _.isEqual(selectedList, originalList)
            ? []
            : selectedList
        }
        notFoundContent={!originalList?.length && loader ? 'loading...' : 'No data found'}
        open={dropdownVisible}
        onDropdownVisibleChange={onDropdownVisibleChange}
        disabled={disabled}
        suffixIcon={<FunnelListChevron />}
      >
        {eventTable
          ? _.map(eventTable, ({ eventname = '', count = '' }) => (
              <Option value={eventname} label={eventname} key={eventname}>
                <OptionLabel value={eventname} count={count} />
              </Option>
            ))
          : (id === 'gestureTypes' || id === 'allAppVersion') &&
          originalList.map((v) => (
            <Option value={v} label={v} key={v}>
              <OptionLabel value={v} key={v} />
            </Option>
          ))}
      </Select>
    </Tooltip>
  )
})
export default SelectDropdownWithCount
