import React, { memo, useMemo } from 'react';
import { Button, Select, Tooltip } from 'antd';
import { CloseCircleOutlined, InfoCircleOutlined } from '@ant-design/icons';
import styled from 'styled-components';
import NumberFieldWrapper from './NumberFieldWrapper'

const EventFilterWrapper = styled.div`
  display: flex;
  gap: 10px;
  align-items: center;
  margin-left: 5px;
  color: #161E35;
`;

const DeleteButton = styled(Button)`
  border: none !important;
  box-shadow: none;
  .anticon svg {
    font-size: 14px;
    color: #dc4f44;
  }
`;

const SelectWrap = styled(Select)`
  .ant-select-selector {
    height: 18px !important;
    border: 0 !important;
    border-bottom: 1px dashed #a1a8c2 !important;
    border-radius: 0 !important;
    padding: 0 !important;
   
    .ant-select-selection-item {
      font-size: 14px !important;
      line-height: normal !important;
    }
  }
`;


const SpanWrap = styled.span`
  font-size: 14px;
`;

const InfoCircleOutlinedSpan = styled(InfoCircleOutlined)`
  svg {
    color: #5D97FF;
    font-size: 16px;
  }
`;

const FiltersOperators = [
  {
    options: [
      { value: 'greater_or_equal', label: 'at least' },
      { value: 'less_or_equal', label: 'at most' },
      { value: 'equal', label: 'exactly' },
    ],
  },
];
const eventOperators = [
  {
    options: [
      { value: 'with', label: 'Screen visits with' },
      { value: 'with_out', label: 'Screen visits without' },
    ],
  },
];

const EventFilterOperator = ({
  eventOperator,
  filterData,
  handleEventFilterOperatorChange,
  handleFilterDelete,
  handleEventFilterValueChange,
  handleWithOrWithoutEventChange
}) => {
  const { value: count, filters } = filterData;
  const filterType = useMemo(() => filterData.attribute.includes('event') ? 'event' : 'gesture', [filterData]);
  const isSmartEvent = useMemo(() => filterData.attribute.includes('smart_event'), [filterData]);
  
  const isEventFilterApplied = filters.some(obj => obj.attribute === 'event_name' || obj.attribute === 'nce_name');
  const withOperator = useMemo(() => eventOperator === 'equal' && count === 0 ? 'with_out' :'with' ,[eventOperator, count])

  const handleInputValue = (value) => {
    handleEventFilterValueChange(+value)
  }
  return (
  <EventFilterWrapper>
    <SelectWrap
      onChange={handleWithOrWithoutEventChange}
      value={withOperator}
      dropdownClassName="event-filter-default"
      showArrow={false}
      options={eventOperators}
    />
    {withOperator !== 'with_out' && <>
    <SelectWrap
      onChange={handleEventFilterOperatorChange}
      value={eventOperator}
      dropdownClassName="event-filter-default"
      showArrow={false}
      options={FiltersOperators}
    />
    <NumberFieldWrapper
      callApi={handleInputValue}
      defaultValue={count}
    />
    </>  }
   
    <SpanWrap>{isSmartEvent ? 'smart' : ''} {count === 0 || count > 1 ? `${filterType}s` : filterType } {isEventFilterApplied || filterType === 'gesture' ? 'where:' : ':'}</SpanWrap>
    <DeleteButton icon={<CloseCircleOutlined />} onClick={handleFilterDelete} />
    <Tooltip placement="top" title='Screen visit filters show data of all the screen visits that meet the filter criteria'>
                <InfoCircleOutlinedSpan />
              </Tooltip>
  </EventFilterWrapper>
)};
export default memo(EventFilterOperator);
