import React, { useEffect } from 'react'
import { ActivityFilterPayloadType } from 'types/activityFilterConfigurationTypes'

export const getActivityFilterPropertyId = (attribute: string, activityFilterIndex: number, activityPropertyIndex: number) => {
    return `activity-${attribute}-${activityFilterIndex}-${activityPropertyIndex}`
}
export function useActivityFilterValidator({
    filterSelectedValues,
    attribute,
    activityFilterIndex,
    activityPropertyIndex,
}: {
    filterSelectedValues: string | undefined,
    attribute: string,
    activityFilterIndex: number,
    activityPropertyIndex: number
}) {
    const [isValid, setIsValid] = React.useState<boolean>(false)
    useEffect(() => {
        // * check if the field is valid or not,
        // * if valid then remove required class from DOM
        if(filterSelectedValues){
            document.getElementById(getActivityFilterPropertyId(
                attribute,
                activityFilterIndex,
                activityPropertyIndex
            ))?.classList.remove('required')
            setIsValid(true)
        }
    }, [activityFilterIndex, activityPropertyIndex, attribute, filterSelectedValues])

    //* watcher for the filterSelectedValues
    useEffect(() => {
        if(filterSelectedValues){
            setIsValid(true)
        }
    }, [filterSelectedValues])

    return isValid
}

export function guardAddActivityProperty(activityFilters: ActivityFilterPayloadType[]) {
    // * checks validity 
    // * if invalid then add required class to the DOM
    const isValid = activityFilters.map((activityFilter, filterIndex) => {
        const invalidProperties = activityFilter.filters.filter((data) => {
            if(data?.property){
                return !data.property?.value
            }
            return !data.attribute || !data.operator || !data.value 
        })
        if(invalidProperties.length > 0){
            const listOfIds = invalidProperties.map((data) => {
                return getActivityFilterPropertyId(data.attribute, filterIndex, activityFilter.filters.indexOf(data))
            })
            // * find ids from dom and add required class
            listOfIds.forEach((id) => {
                const element = document.getElementById(id)
                if(element){
                    if(!element.classList.contains('required')){
                        // element.setAttribute('tabindex', '-2'); // Make the element focusable
                        // element.focus();
                        element.classList.add('required')
                    }
                }
            })
        }
        return invalidProperties.length === 0
    });
    return isValid.every((data) => data === true)
}