import { useQuery } from 'react-query';
import { axiosInstance } from 'services/globalInstance';
import EventApi from 'services/eventApi'
import { defaultRefetchInterval } from 'Utils/constants/index';

const getEventList = async ({ postBody }) =>
  EventApi.getV2EventListTable(postBody)

const getNocodeEventList = async ({ postBody }) =>
  EventApi.getV2NocodeEventListTable(postBody)

export const useEventList = ( { postBody, enabled } ) =>
  useQuery(['eventList', postBody], () => getEventList({ postBody }), {
    refetchInterval: defaultRefetchInterval,
    retry: 3,
    cacheTime: 0,
    // keepPreviousData: true,
    enabled,
    keepPreviousData: true,
  });
  
export const useNocodeEventList = ( { postBody, enabled } ) =>
  useQuery(['nocodeEventList', postBody], () => getNocodeEventList({ postBody }), {
    refetchInterval: defaultRefetchInterval,
    retry: 3,
    cacheTime: 0,
    // keepPreviousData: true,
    enabled,
    keepPreviousData: true,
});

const getEventNamesWithCount = async (postBody) =>
  axiosInstance.post(`${process.env.PYTHON_API_URL}/events/event_count`, postBody, {
    withCredentials: true,
    credentials: 'include',
  })

export const useEventNamesWithCount = (postBody) => useQuery('eventNamesWithCount', () => getEventNamesWithCount(postBody));

const getNocodeEventNamesWithCount = async (postBody) =>
  axiosInstance.post(`${process.env.PYTHON_API_URL}/no_code_event/event_count`, postBody, {
    withCredentials: true,
  })

export const useNocodeEventNamesWithCount = (postBody) => useQuery('nocodeEventNamesWithCount', () => getNocodeEventNamesWithCount(postBody));

const getSortedList = (postBody) =>
  axiosInstance.post(`${process.env.PYTHON_API_URL}/preference/column-sort-order`, postBody, {
    withCredentials: true,
});

export const getEventSortedItems = (postBody) => getSortedList(postBody);

