"use client";

// eslint-disable-next-line import/no-extraneous-dependencies
import type { LottieComponentProps, LottieRef } from 'lottie-react'
import dynamic from 'next/dynamic'
import React, { memo, useEffect, useRef } from 'react'

// lottie-web touches `document` at module scope, so it must never load during SSR
const Lottie = dynamic(() => import('lottie-react'), { ssr: false })

type LottieProps = {
    animationData: unknown
    active: boolean
    dependencies?: unknown[]
} & LottieComponentProps

const style = {
    height: 24,
    width: 24
};

const LottieIcon : React.FC<LottieProps> = (props) => {
    const { animationData, active, dependencies, ...rest } = props;
    const lottieRef = useRef(null) as LottieRef;

    useEffect(() => {
            if (active) {
                lottieRef.current?.play()
            } else {
                lottieRef.current?.stop()
            }
    }, [active, dependencies])

    // eslint-disable-next-line react/jsx-props-no-spreading
    return <Lottie style={style} lottieRef={lottieRef} animationData={animationData} loop={false} autoplay={false} {...rest} />
}

export default memo(LottieIcon)