function getLastSeenLabel(lastSeenOn: string): string {
    if (!lastSeenOn) return '';
    const timeDiffLabel = getDifferenceFromNow(lastSeenOn)
    return `${getUtcDate(lastSeenOn, 'd MMM, yyyy')} (${timeDiffLabel})`;
}

const SessionDetailsHeaderV2: React.FC = () => {
    const {utils , activeSessionList: dataWithSessionLocked, activeUserSessionList: userDataBody, isActiveUserSessionLoading:isLoading} = useAISessionUtils();
    const {
        urlReducer: {
            secondarysessionid,
            sessionid,
            appId,
            parentType,
        },
        currentOrgReducer: { planLimit },
    } = useSelector((state: any) => state);
    
    const queryClient = useQueryClient();
    const aiSessionsListReqBody = useMemo(() => {
        try {
            return JSON.parse(localStorage.getItem('aiSessionsListReqBody') || '{}');
        } catch {
            return {};
        }
    }, []);
    const { monthsOfVideosAccessible } = useRestrictionContext() as any;
        
    const query = queryClient.getQueryState(['aiSessionItems',aiSessionsListReqBody]);
   
    const isWebApp = useIsAppType( 'web' );

    const { mutate:mutateAIUserSession } = useAIUserSessions()
    const queryKey = useMemo(() => getAIDetailsKey(secondarysessionid), [secondarysessionid]);
    const getDetailsQueryData = queryClient.getQueryState(queryKey)?.data as any
    const isMounted = useRef(false)

    const activeSession = useMemo(() => {
        const primary = dataWithSessionLocked?.data?.data?.body || []; // *primary
        const fallback1 = userDataBody?.data?.data?.body || []; // *fallback1
        const fallback2 = getDetailsQueryData // *fallback2

        const checkPrimary = primary.find((item) => item.sessionid === secondarysessionid);
        if( checkPrimary ) {
            return {
                sessionid: checkPrimary.sessionid,
                userSessionRun: checkPrimary?.userSessionRun,
                userProperty: checkPrimary?.userProperty,
            } as ActiveSession;
        }
        const checkFallback1 = fallback1.find((item) => item.sessionid === secondarysessionid);
        if( checkFallback1 ) {
            return {
                sessionid: checkFallback1.sessionid,
                userSessionRun: checkFallback1?.userSessionRun,
                userProperty: checkFallback1?.userProperty,
            } as ActiveSession;
        }
        if (fallback2) {
            return {
                sessionid: secondarysessionid,
                userSessionRun: fallback2?.sessionNumber,
                userProperty: fallback2?.userProperty,
            } as ActiveSession;
        }
        return undefined;
    }, [dataWithSessionLocked?.data?.data?.body, userDataBody?.data?.data?.body, getDetailsQueryData, secondarysessionid]);

    useEffect(()=>{
        if(!isMounted.current && getDetailsQueryData){
            mutateAIUserSession({
                appid:appId,
                recordedon:getDetailsQueryData?.time?.sessionRecordedDateTime,
                session_per_page:101,
                usersessionrun:getDetailsQueryData?.sessionNumber,
                uxcamuserid:getDetailsQueryData?.userProperty?.uxcamuserid,
                webApp: isWebApp
            })
            isMounted.current = true
        }
    },[appId, getDetailsQueryData, isWebApp, mutateAIUserSession])
    
    const userDataWithSessionLocked = useMemo(() => {
        if (!userDataBody) return undefined;
        const { data } = userDataBody;
        return {
            ...userDataBody,
            data: {
                ...data,
                data: {
                    ...data.data,
                    body: data.data?.body?.map((item) => ({
                        ...item,
                        sessionLocked:
                            monthsOfVideosAccessible &&
                            isDateOlderThanMonths(item.sessionUploadedDateTime, monthsOfVideosAccessible) &&
                            planLimit?.videoRetentionTime !== planLimit?.videoPlaybackAccessibleTime
                    }))
                }
            }
        };
    }, [userDataBody, monthsOfVideosAccessible, planLimit]);

    const userListPaginationMetaData = useMemo(()=>{
        return {
            hasPrev: userDataWithSessionLocked?.data.data?.prev || false,
            hasNext: userDataWithSessionLocked?.data.data?.next || false,
        }
    },[ userDataWithSessionLocked?.data.data?.prev, userDataWithSessionLocked?.data.data?.next ]);
      
    const {
        appFilter,
        urlReducer: urlQuery,
    } = useSelector((state: any) => state);
    const pageSegment = useMemo(() => {
        if (parentType === 'issues') {
            return appFilter.issue?.segment || [];
        }
        return appFilter.session?.segment || [];
    }, [appFilter, parentType]);
    const {
        megaFilterCustomLabels: customLabels,
    } = useCustomLabels();
    const customLabelsArray = useMemo(() => customLabels.map((item: CustomLabel) => item.name), [customLabels]);
    const { sessionDetail, sessionBugInfo } = useSessionTimeLine();

    const [labelSession, setLabelSession] = useState<string[]>([]);
    const [showCustomLabel, setShowCustomLabel] = useState(false);

    const userActiveSession = useMemo(() => {
        const primaryBody = userDataWithSessionLocked?.data?.data?.body;
        const fallbackBody = dataWithSessionLocked?.data?.data?.body;
        const checkPrimary = primaryBody?.find(item => item.sessionid === secondarysessionid);
        if (checkPrimary) {
            return checkPrimary;
        }
        const checkFallback = fallbackBody?.find(item => item.sessionid === secondarysessionid);
        if (checkFallback) {
            return checkFallback;
        }
        if (getDetailsQueryData) {
            return getDetailsQueryData;
        }
        return undefined;
    }, [userDataWithSessionLocked?.data?.data?.body, dataWithSessionLocked?.data?.data?.body, getDetailsQueryData, secondarysessionid]);

    const sessionDetails = useMemo(
        () => getNewSessionData(userActiveSession, parentType) as SessionDetails,
        [userActiveSession, parentType]
    );
    
    const {data: replayInfoResponse  ,isLoading: isReplayInfoLoading}:{
        data: ReplayInfo | undefined;
        isLoading: boolean;
    } = useReplayInfo(
        {
            appid: appId,
            uxcamuserid: activeSession?.userProperty?.uxcamuserid,
        },
        {
            enabled: !!activeSession?.userProperty?.uxcamuserid && !!appId,
        },
    )

    const sessionLabel = sessionDetails?.customLabel;
    const isCrashLog = (sessionDetail as SessionDetail)?.isCrashedLog || false;
    const totalBugs = sessionBugInfo || [];
    const anrMenu = useMemo(() => getAnrMenu(sessionDetail) || [], [sessionDetail]);

    useEffect(() => {
        if (['sessionsList', 'eventsList', 'aiSessionsList'].includes(parentType)) {
            const result = sessionLabel?.filter(
                (label: string) => customLabelsArray.indexOf(label) >= 0
            );
            setLabelSession(result || []);
        } else {
            setLabelSession(sessionLabel || []);
        }
    }, [sessionLabel, customLabels, parentType, customLabelsArray]);
    return (<>
        <Header>
            <Row isTopRow>
                {query?.isFetching || !activeSession ?
                    <SpinnerWrapper>
                        <Spinner data-size="xs" />
                    </SpinnerWrapper>
                    :
                    <>
                        <UserName data-intercom-target="Session User Id" isActive={utils.activePlaylist === PLAYLIST_STATUS.USER_PLAYLIST}>
                            <div className="user-icon">
                                <UserIcon/>
                            </div>
                            <UserNameComponentV2 
                                session={activeSession}
                                appId={appId}
                                urlQuery={urlQuery}
                                parentType={parentType}
                            />
                        </UserName>
                        
                        <UserListDropdown 
                            activeSession={activeSession} 
                            userSessionListData={userDataWithSessionLocked} 
                            isLoading={isLoading} 
                            replayInfo={replayInfoResponse}
                            paginationInfo={userListPaginationMetaData} 
                        />
                        
                        {
                        isReplayInfoLoading ?
                            <SpinnerWrapper>
                                <Spinner data-size="xs" />
                            </SpinnerWrapper>
                            :
                            <LastSeenWrapper>
                                <Clock />
                                <span>
                                    Last seen: {replayInfoResponse && replayInfoResponse?.lastseenon ? getLastSeenLabel(replayInfoResponse?.lastseenon) : 'N/A'}
                                </span>
                            </LastSeenWrapper>
                        }
                    </>                
                }
            </Row>
            <StyledDivider />

            <Row justifyContent="space-between">
                { query?.isFetching || !sessionDetails ?
                    <SpinnerWrapper>
                        <Spinner data-size="xs" />
                    </SpinnerWrapper>
                    : <>
                        <Space size={12}>
                            <LocationHeaderComponent 
                                sessionDetails={sessionDetails}
                                pageSegment={pageSegment}
                                isClickableLink={false}
                            />
                            
                            <DateHeaderComponent 
                                sessionDetails={sessionDetails}
                                pageSegment={pageSegment}
                                isClickableLink={false}
                                parentType={parentType}
                                isV2
                            />
                            
                            <LabelsComponent 
                                labelSession={labelSession}
                                showCustomLabel={showCustomLabel}
                                setShowCustomLabel={setShowCustomLabel}
                            />
                            
                            <IssueInfoComponent 
                                isCrashLog={isCrashLog}
                                totalBugs={totalBugs}
                                anrMenu={anrMenu}
                            />
                        </Space>

                        <ActionButtons>
                            <ShareSessionModal 
                                alternativeStyle 
                                hidePublicLink 
                                shareMultiple={false}
                                selectedSession={sessionDetails}
                            />
                            <SessionOption alternativeStyle passedSessionId={sessionDetails?.sessionid} />
                        </ActionButtons>
                    </>}
            </Row>
        </Header>
        {showCustomLabel && (
            <SessionCustomLabels
                setShowCustomLabel={setShowCustomLabel}
            />
        )}
    </>)
}

export default SessionDetailsHeaderV2 