import React from 'react'
import { Cell, StyledSpan } from "components/features/aiSessions/hooks/useAISessionColumns"
import { getDifferenceFromNow } from 'Utils/DateConversion/dateConversionUtils'
import { formatDisplayTime } from 'Utils/constants'

interface IProps {
	time?: string
	format?: string
}

const TimeCell = ( { time, format = 'ddd, MMMM DD, hh:mm A' }: IProps ) => {
	if ( !time ) {
		return 'N/A'
	}

	return (
		<Cell>
			{ getDifferenceFromNow( time ) }
			<StyledSpan className="subtitle">
			{ formatDisplayTime( time, format ) }
			</StyledSpan>
		</Cell>
	)
}

export default TimeCell