const hasPermission = (permissionCode, userRole, rolesPermissions) => {
  let isAuthorized = false;
  const permissions = rolesPermissions ? rolesPermissions[`${userRole}`] : [];
  Array.isArray(permissionCode) &&
    permissionCode.forEach((code) => {
      if (Array.isArray(permissions) && permissions.includes(code)) {
        isAuthorized = true;
      }
    });
  return isAuthorized;
};

export default hasPermission;