import React, { memo, useCallback, useMemo } from "react";
import { Form } from 'antd';
import findIndex from 'lodash/findIndex';
import { operator } from 'components/shared/GlobalFilter/components/data-structures-v2';
import {
  OperatorMenu,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2'

const PropertiesOperator = ({ name }) => {

  const form = Form.useFormInstance();
  const formData = Form.useWatch('eventProperties', form);
  const formDataIndex = name[1];
  const formOperatorValue = formData?.[formDataIndex]?.['operator'] ?? '';

  const indexOfOperator = findIndex(operator['json'], {
    attribute: formOperatorValue || 'in',
  })
  const operatorDataByTypeIndex = useMemo(() => operator['json'][indexOfOperator], [indexOfOperator]);

  const handleOperatorChange = useCallback(() => {
    form.setFields([
      {
        name: ['eventProperties', `${formDataIndex}`, 'value'],
        value: undefined,
      },
    ]);
  }, [form, formDataIndex])

  return (
    <span className="filter-spacing">
     <OperatorMenu
      selectedOperator={operatorDataByTypeIndex}
      isFilterDisplayBar
      operatorType="json"
      handleOperatorMenuClick={(data) => {
        form.setFields([{ name, value: data.key }]);
        handleOperatorChange(data.key);
      }}
      isEventProperty
      propertyName=''
    />
    </span>
   
  )
}

export default memo(PropertiesOperator)