import { UserSessionData, SessionData } from 'components/features/aiSessions/components/types';
import React, { createContext, useContext, useState, ReactNode } from 'react';

// eslint-disable-next-line no-shadow
export enum PLAYLIST_STATUS {
    SESSION_PLAYLIST = 'SESSION_PLAYLIST',
    USER_PLAYLIST = 'USER_PLAYLIST',
    INACTIVE = 'INACTIVE'
}

interface AISessionUtilsContextType {
    utils: {
        activePlaylist: PLAYLIST_STATUS
    };
    setUtils: React.Dispatch<React.SetStateAction<{
        activePlaylist: PLAYLIST_STATUS;
    }>>;
    activeSessionList: SessionData | null;
    setActiveSessionList: React.Dispatch<React.SetStateAction<SessionData | null>>;
    activeUserSessionList: UserSessionData | null;
    setActiveUserSessionList: React.Dispatch<React.SetStateAction<UserSessionData | null>>;
    isActiveUserSessionLoading?: boolean;
    setIsActiveUserSessionLoading?: React.Dispatch<React.SetStateAction<boolean>>;
    rowselection: unknown[]
    setRowSelection: React.Dispatch<React.SetStateAction<unknown[]>>
}

const AISessionUtilsContext = createContext<AISessionUtilsContextType | undefined>(undefined);
const initialUtils = {
    activePlaylist: PLAYLIST_STATUS.INACTIVE,
};
export const AISessionUtilsProvider = ({ children }: { children: ReactNode }) => {
    const [utils, setUtils] = useState(initialUtils);
    const [activeSessionList, setActiveSessionList] = useState<SessionData | null>(null);
    const [activeUserSessionList, setActiveUserSessionList] = useState<UserSessionData | null>(null);
    const [isActiveUserSessionLoading, setIsActiveUserSessionLoading] = useState<boolean>(false);
    const [rowselection, setRowSelection] = useState<unknown[]>([]);

    const value = React.useMemo(() => ({ 
        utils, 
        setUtils, 
        activeSessionList, 
        setActiveSessionList,
        activeUserSessionList,
        setActiveUserSessionList,
        isActiveUserSessionLoading,
        setIsActiveUserSessionLoading,
        rowselection,
        setRowSelection,
     }), [utils, activeSessionList, activeUserSessionList, isActiveUserSessionLoading, rowselection, setRowSelection]);

    return (
        <AISessionUtilsContext.Provider value={value}>
            {children}
        </AISessionUtilsContext.Provider>
    );
};

export const useAISessionUtils = () => {
    const context = useContext(AISessionUtilsContext);
    if (!context)  {
        throw new Error('useAISessionUtils must be used within an AISessionUtilsProvider');
    }
    return context;
};