const LoaderContainer = styled.div`
    height: 308px;
    margin-top: auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 16px;

    .loader {
        width: 94px;
        height: 94px;
        display: flex;
        justify-content: center;
        align-items: center;

        svg {
            transform: scale(3.8) !important;
        }
    }

    color: ${theme.colors.surface500.toString()};
    font-size: 12px;
    font-family: 'Roboto', sans-serif;

    p {
        margin: 0;
        padding: 0;
        float: left;
        overflow: hidden;
        position: relative;
        height: 16px;

        .inner-text {
            display: inline-block;
            position: relative;
            white-space: nowrap;
            text-align: center;
            top: 0;
            left: 0;
            transition: top 0.4s;

            /*animation*/
            -webkit-animation:move 2s forwards;
            animation:move 2s forwards;

            animation-iteration-count: 1;

            /*animation-delay*/
            -webkit-animation-delay: 1s;
            animation-delay: 1s;

            @keyframes move{
                0%  { top: 0px; }
                40% { top: -18px }
                100% { top: -38px }
            }
        }
    }
`

