import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { useQueryClient } from 'react-query';

import {
  EyeOutlined,
  SettingOutlined,
  DownOutlined,
  UpOutlined,
} from '@ant-design/icons';
import {
  Dropdown,
  Button,
  message,
} from 'antd';
import { deleteCustomLabelFilterFetchProperty } from 'redux/actions/filter';
import Cookies from 'universal-cookie';
import { trackPageViews } from 'redux/actions/trackingReport';
import CustomLabelModal, {
  getSessionsUserId,
  getSessionsUploadDate,
} from 'components/common/CustomLabelModal';
import { gotUserDetail } from 'redux/actions/userList/actionObjects';
import CustomLabelMangeModal from 'components/common/CustomLabelManageModel';
import CheckMarkIcon from 'public/static/sessions/checkmark.svg';

import LabelsDropdownOverlay from 'components/common/LabelsDropdownOverlay';
import useCustomLabels, { useCustomLabelApi } from 'hooks/useCustomLabels';
import find from 'lodash/find';
import keys from 'lodash/keys';
import pickBy from 'lodash/pickBy';
import { addSessionId, addUserId } from 'redux/actions/common';
import { ActionButton, FooterWrpper } from './styles';

const cookies = new Cookies();

const MarkMultipleLabel = () => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const {
    urlReducer: urlQuery,
    selectedSessionReducer: selectedSession,
    selectedUserReducer: selectedUser,
    currentAppReducer,
    userDetailReducer
  } = useSelector((state) => state);
  const { parentType, uxcamuserid } = urlQuery;
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let sessionBodyKeyVal = ''
  try {
    sessionBodyKeyVal = localStorage.getItem(sessionBodyKey)
  } catch (err) {
    // silent fail
  }
  const sessionQueryKey = [sessionKey, JSON.parse(sessionBodyKeyVal)]
  const { _id } = currentAppReducer;
  const isUserList = parentType === 'usersList';

  const {
    megaFilterCustomLabels: customLabels,
    megaFilteredSessionLabels,
    filteredUserLabels,
    labelSearch,
    setLabelSearch,
    resetSearch,
    compareLabels,
    getLabelTypeFromValue,
  } = useCustomLabels();
  const { markUserLabel, addUserLabel, addSessionLabel, markSessionLabel } = useCustomLabelApi();
  const [selectedCustomLabelTab, setSelectedCustomLabelTab] = useState(isUserList ? 'user' : 'session');
  const hasCustomLabels = useMemo(
    () =>
      isUserList
        ? filteredUserLabels?.length > 0
        : megaFilteredSessionLabels?.length > 0,
    [filteredUserLabels, megaFilteredSessionLabels, isUserList]);

  const sessionListData = queryClient.getQueryData(sessionQueryKey) || {};
  let usersListReqBody = ''
  try {
    usersListReqBody = localStorage.getItem('usersListReqBody')
  } catch (err) {
    // silent fail
  }
  const userListData = queryClient.getQueryData(['userList', JSON.parse(usersListReqBody)]) || {};

  const selectedData =
    [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ? selectedSession : selectedUser;
  const tableData =
    [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) 
      ? sessionListData?.data?.data?.body
      : userListData?.data?.data?.body;

  const [iconChange, setIconChange] = useState(false);
  const [watch, setWatch] = useState(false);
  const [isModalVisible, setIsModalVisible] = useState(false);
  const [state, setState] = useState({});
  const [isEditModalVisible, setIsEditModalVisible] = useState(false);
  const { data: userDetails } = userDetailReducer;
  const selectedKeys = useMemo(() => keys(pickBy(state, value => value === true)), [state]);

  const labelTabs = useMemo(() => isUserList ? [
    {
        key: 'user',
        name: 'User label',
        options: 
        filteredUserLabels.sort((a, b) => compareLabels(selectedKeys, a, b)), // includes filtered labels
        showSearch: true,
    }
  ] : [
    {
        key: 'session',
        name: 'Session label',
        options: 
        megaFilteredSessionLabels.sort((a, b) => compareLabels(selectedKeys, a, b)), // includes filtered labels
        showSearch: true,
    },
  ], [isUserList, filteredUserLabels, megaFilteredSessionLabels, compareLabels, selectedKeys])

  const handleTracking = (payload) => {
    dispatch(
      trackPageViews(null, payload)
    )
  }

  const showModal = () => {
    setIsModalVisible(true);
  };
  const showEditModal = () => {
    setIsEditModalVisible(true);
  };
  const hideModal = () => {
    setIsModalVisible(false);
    setIsEditModalVisible(false);
  };
  let usersListReqBody2 = ''
  try {
    usersListReqBody2 = localStorage.getItem('usersListReqBody')
  } catch (err) {
    // silent fail
  }
  const userQueryKey = ['userList', JSON.parse(usersListReqBody2)]
  const { customLabel: userCustomLabel } = userDetails;

  const labelOnUserDetail = useMemo(
    () => userCustomLabel || [],
    [userCustomLabel]
  );

  const updateUserDetail = (labelName) => {
    const newUserDetail = { ...userDetails };
    if (labelOnUserDetail?.includes(labelName)) {
      newUserDetail.customLabel = labelOnUserDetail?.filter(
        (label) => label !== labelName
      );
    } else {
      labelOnUserDetail.push(labelName);
      newUserDetail.customLabel = labelOnUserDetail;
    }
    dispatch(gotUserDetail(newUserDetail));
  };

  const handleWatched = (value) => {
      const payload = {
        customLabelName: 'isViewed',
        isTagged: value,
        uxcamuserIds: selectedUser,
        appid: _id,
        labelType: 'user',
        debugSource: 6
      }
      queryClient.setQueryData(userQueryKey, (old) => {
        const newBody = old.data.data.body.map((el) => {
          if (selectedUser.includes(el.uxcamuserid)) {
              return {
                  ...el,
                  isViewed: value,
              };
          }

          return el;
      });
      return {
          ...old,
          data: {
              ...old.data,
              data: {
                  ...old.data.data,
                  body: newBody,
              },
          },
      };
    });
      markUserLabel(payload)
   
  };

  const handleMarkMultipleSession = (label, value) => {
    const requestData = {
      customLabelName: label,
      isTagged: value,
      labelType: getLabelTypeFromValue(label),
      sessionIds: selectedSession,
    };
    const sessionResponse = queryClient.getQueryData(sessionQueryKey);
    const queryList = sessionResponse?.data?.data?.body || [];

    const sessionUserIds = getSessionsUserId(
      selectedSession,
      queryList,
      'sessionid'
    );
    const sessionUploadDate = getSessionsUploadDate(
      selectedSession,
      queryList,
      'sessionid'
    );
    const payload = {
      ...requestData,
      appid: _id,
      uxcamuserIds: sessionUserIds,
      uploadedOn: sessionUploadDate,
      labelType: getLabelTypeFromValue(label)
    };
   
    markSessionLabel(payload)

    let newBody;
    queryClient.setQueryData(sessionQueryKey, (old) => {
      let sessionObjsArr = [];
      selectedSession.forEach((id) => {
        const sessionIndex = old.data?.data?.body.findIndex(
          (el) => el.sessionid === id
        );
        let sessionObjCopy = { ...old.data?.data?.body[sessionIndex] };
        const sessionLabelsArr = sessionObjCopy.customLabel;
        const indexOfLabelInLabels = sessionLabelsArr?.indexOf(label);
        if (indexOfLabelInLabels > -1) {
          const sessionLabelsArrCopy =
            value === false
              ? [...sessionLabelsArr]
              : [...sessionLabelsArr, label];
          sessionLabelsArrCopy.splice(indexOfLabelInLabels, 1);
          sessionObjCopy = {
            ...sessionObjCopy,
            customLabel: sessionLabelsArrCopy,
          };
        } else {
          sessionObjCopy = {
            ...sessionObjCopy,
            customLabel: [...sessionLabelsArr, label].sort((a, b) => a - b),
          };
        }

        sessionObjsArr = [...sessionObjsArr, sessionObjCopy];
      });

      newBody = old.data.data.body.map((el) => {
        let obj = { ...el };

        sessionObjsArr.forEach((session) => {
          if (session.sessionid === obj.sessionid) {
            obj = {
              ...obj,
              customLabel: session.customLabel,
            };
          }
        });

        return obj;
      });

      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });
    selectedSession.forEach((sessionId) => {
      let obj;
      const prevData = queryClient.getQueryData(sessionId);
      if (prevData) {
        const sessionCustomLabel = prevData?.customLabel || [];
       if(!sessionCustomLabel?.includes(label) || !value){
        if (sessionCustomLabel.indexOf(label) > -1) {
          obj = sessionCustomLabel.filter((item) => item !== label);
        } else {
          obj = [...sessionCustomLabel, label];
        }
        queryClient.setQueryData(sessionId, (previousData) => ({
          ...previousData,
          customLabel: obj,
        }));
       }
        
      }
    });

    // handles selected rows clearing after one label added to retain default behaviour
    dispatch(addUserId([]))
    dispatch(addSessionId([]))
  };

  const handleLabelAddOnUser = (values) => {
    const payload = {...values, appid: _id, labelType: 'user'}
    addUserLabel(payload)
    handleTracking({
      eventName: 'add_label',
      track_type: 'event',
      eventProperty: {
        'label name': payload?.customLabelName,
        'user ids': payload?.uxcamuserIds,
        'label_type': 'user',
      },
    });
    let usersListReqBody3 = ''
    try {
      usersListReqBody3 = localStorage.getItem('usersListReqBody')
    } catch (err) {
      // silent fail
    }
    queryClient.setQueryData(['userList', JSON.parse(usersListReqBody3)], (old) => {
      const ids = values?.uxcamuserIds || [];
      const newBody = old.data.data.body.map((el) => {
        if (ids.length && ids.includes(el.uxcamuserid)) {
          return {
            ...el,
            customLabel: [...el.customLabel, values.customLabelName],
          };
        }
        return el;
      });
      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });
    updateUserDetail(values.customLabelName)

    // handles selected rows clearing after one label added to retain default behaviour
    dispatch(addUserId([]))
  };

  const handleCustomLabel = async (label, value) => {
    if ([ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ) {
      handleTracking({
        eventName: value ? 'add_label' : 'remove_label',
        track_type: 'event',
        eventProperty: {
          'label name': label,
          'session ids': selectedSession,
          'label_type': getLabelTypeFromValue(label),
        },
      })
    
      handleMarkMultipleSession(label, value);
    } else {
      const payload = {
        customLabelName: label,
        isTagged: value,
        uxcamuserIds: selectedUser,
        appid: _id,
        labelType: 'user'
      };
      handleTracking({
        eventName: value ? 'add_label' : 'remove_label',
        track_type: 'event',
        eventProperty: {
          'label name': label,
          'user ids': selectedUser,
          'label_type': 'user',
        },
      })
      markUserLabel(payload)
      let newBody ;
      queryClient.setQueryData(userQueryKey, (old) => {
        if (label === 'isViewed') {
            newBody = old.data.data.body.map((el) => {
                if (selectedUser.includes(el.uxcamuserid)) {
                    return {
                        ...el,
                        isViewed: value,
                    };
                }

                return el;
            });
            return {
                ...old,
                data: {
                    ...old.data,
                    data: {
                        ...old.data.data,
                        body: newBody,
                    },
                },
            };
        }

        let userObjsArr = [];

        selectedUser.forEach((id) => {
            const userIndex = old.data?.data?.body.findIndex(
                (el) => el.uxcamuserid === id
            );
            let userObjCopy = { ...old.data?.data?.body[userIndex] };

            const userLabelsArr = userObjCopy.customLabel;
            const indexOfLabelInLabels = userLabelsArr?.indexOf(label);
            if (indexOfLabelInLabels > -1) {
                const userLabelsArrCopy = value === false ? [...userLabelsArr] : [...userLabelsArr, label] ;
                userLabelsArrCopy.splice(indexOfLabelInLabels, 1);
                userObjCopy = {
                    ...userObjCopy,
                    customLabel: userLabelsArrCopy,
                };
            } else {
                userObjCopy = {
                    ...userObjCopy,
                    customLabel: [...userLabelsArr, label].sort((a, b) => a - b),
                };
            }

            userObjsArr = [...userObjsArr, userObjCopy];
        });

        newBody = old.data.data.body.map((el) => {
            let obj = { ...el };

            userObjsArr.forEach((user) => {
                if (user.uxcamuserid === obj.uxcamuserid) {
                    obj = {
                        ...obj,
                        customLabel: user.customLabel,
                    };
                }
            });

            return obj;
        });

        return {
            ...old,
            data: {
                ...old.data,
                data: {
                    ...old.data.data,
                    body: newBody,
                },
            },
        };
    });

      if(!labelOnUserDetail.includes(label) || !value){
        selectedUser?.map(userId => userId === uxcamuserid && updateUserDetail(label))
      }
      // handles selected rows clearing after one label added to retain default behaviour
      dispatch(addUserId([]))
    }
  };

  const handleLabelAddOnSession = (dataBody) => {
    const sessionResponse = queryClient.getQueryData(sessionQueryKey);
    const queryList = sessionResponse?.data?.data?.body || [];
    const sessionIds = dataBody?.sessionIds || [];

    const sessionUserIds = getSessionsUserId(
      sessionIds,
      queryList,
      'sessionid'
    );

    const sessionUploadDate = getSessionsUploadDate(
      sessionIds,
      queryList,
      'sessionid'
    );

    const dataReloaded = {
      ...dataBody,
      appid: _id,
      uxcamuserIds: sessionUserIds,
      uploadedOn: sessionUploadDate,
    };
    addSessionLabel(dataReloaded);

    handleTracking({
      eventName: 'add_label',
      track_type: 'event',
      eventProperty: {
        'label name': dataReloaded?.customLabelName,
        'session ids': sessionIds,
        'label_type': dataReloaded?.labelType || 'session',
      },
    });

    queryClient.setQueryData(sessionQueryKey, (old) => {
      const ids = dataBody?.sessionIds || [];
      const newBody = old.data.data.body.map((el) => {
        if (ids.length && ids.includes(el.sessionid)) {
          const labelsData = el.customLabel ? [...el.customLabel] : [];
          return {
            ...el,
            customLabel: [...labelsData, dataBody.customLabelName],
          };
        }
        return el;
      });
      return {
        ...old,
        data: {
          ...old.data,
          data: {
            ...old.data.data,
            body: newBody,
          },
        },
      };
    });
    dataBody.sessionIds.forEach((sessionId) => {
      const prevData = queryClient.getQueryData(sessionId);
      if (prevData) {
        const customLabel = prevData?.customLabel || [];
        const newLabel = [...customLabel, dataBody.customLabelName];
        queryClient.setQueryData(sessionId, (previousData) => ({
          ...previousData,
          customLabel: newLabel,
        }));
      }
    });

    // handles selected rows clearing after one label added to retain default behaviour
    dispatch(addSessionId([]))
  };

  const addMultipleCustomLabelBeta = async (value) => {
    const obj =
      [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) 
        ? {
            name: value.customLabelName,
            icon: value.labelIcon,
            sessioncount: selectedSession.length,
          }
        : {
            name: value.customLabelName,
            icon: value.labelIcon,
            usercount: selectedUser.length,
          };

    const newCustomLabels = [...customLabels, obj];
    newCustomLabels.sort((a, b) =>
      a.name.localeCompare(b.name)
    );

    const combinedData = {
      ...value,
      sessionIds: selectedSession,
      labelType: getLabelTypeFromValue(value.customLabelName),
    };
    const userCombinedData = {
      ...value,
      uxcamuserIds: selectedUser,
      labelType: 'user',
    };
    if ([ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ) {
      handleLabelAddOnSession(combinedData);
      // labelMutate({ appID: _id, data: combinedData, parentType });
    } else {
      // userLabelMutate({ appID: _id, data: userCombinedData, parentType });
      handleLabelAddOnUser(userCombinedData);
    }
    dispatch(deleteCustomLabelFilterFetchProperty());
    return null;
  };

  const modalProps = {
    isModalVisible,
    modelHide: hideModal,
    addMultipleCustomLabel: addMultipleCustomLabelBeta,
    markMultiple: true,
  };

  const editModalProps = {
    isModalVisible: isEditModalVisible,
    modelHide: hideModal,
  };
  const loginInFromGuest = cookies.get('loggedInType');

  const handleIconDisplay = () => {
    setIconChange(!iconChange);
  };

  const handleCustomLabelTabChange = (key) => {
    setSelectedCustomLabelTab(key);
  }

  const handleCustomLabelClick = (key, label) => {
    const selectedLabel = find(label.options, { name: key });
    const keyAlreadyExists = selectedKeys.includes(key);
    if (loginInFromGuest !== 'guest') {
      handleCustomLabel(selectedLabel.name, !keyAlreadyExists);
      setState({ ...state, [selectedLabel.name]: !keyAlreadyExists });
    } else {
      message.info(
        'You are not allowed to perform this action from the guest login.'
      );
    }
  }

  const handleLabelSearch = useCallback((e) => {
    const { value } = e.target;
    if(selectedCustomLabelTab === 'session') {
      setLabelSearch({
        ...labelSearch,
        sessionLabels: value
      })
    } else {
      setLabelSearch({
        ...labelSearch,
        userLabels: value
      })
    }
  }, [labelSearch, selectedCustomLabelTab, setLabelSearch])

  const handleWatchChange = async (e) => {
    const value = !e
    if (loginInFromGuest !== 'guest') {
      setWatch(value);
      if ([ 'sessionsList', 'aiSessionsList' ].includes( urlQuery?.parentType ) ) {
        const requestData = {
          customLabelName: 'isViewed',
          isTagged: value,
          labelType: 'session',
          sessionIds: selectedSession,
        };
        const sessionResponse = queryClient.getQueryData(sessionQueryKey);
        const queryList = sessionResponse?.data?.data?.body || [];
    
        const sessionUserIds = getSessionsUserId(
          selectedSession,
          queryList,
          'sessionid'
        );
        const sessionUploadDate = getSessionsUploadDate(
          selectedSession,
          queryList,
          'sessionid'
        );
        const payload = {
          ...requestData,
          appid: _id,
          uxcamuserIds: sessionUserIds,
          uploadedOn: sessionUploadDate,
          labelType: 'session',
        };
        markSessionLabel(payload)
       
        queryClient.setQueryData(sessionQueryKey, (old) => {
       const newBody = old.data.data.body.map((el) => {
            if (selectedSession.includes(el.sessionid)) {
              return {
                ...el,
                isViewed: value,
              };
            }
            return el;
          });
  
          return {
            ...old,
            data: {
              ...old.data,
              data: {
                ...old.data.data,
                body: newBody,
              },
            },
          };

        });
      } else {
        handleWatched(value);
      }
      // handles selected rows clearing after one label added to retain default behaviour
      dispatch(addUserId([]))
      dispatch(addSessionId([]))
    } else {
      message.info(
        'You are not allowed to perform this action from the guest login.'
      );
    }
  };

  const tableDataFilter = useMemo(()=>
  tableData instanceof Array &&
  tableData.filter((obj) =>
    selectedData.includes(
      [ 'sessionsList', 'aiSessionsList' ].includes( parentType ) ? obj.sessionid : obj.uxcamuserid
    )
  ), [selectedData, tableData]);

const handleSelectedSessionsAreViewed = useMemo(()=>tableDataFilter && tableDataFilter.every((obj) => obj.isViewed === true)
, [tableDataFilter])

const handleSetView = (value) => {
  setWatch(value)
}

useEffect(()=> {
  handleSetView(handleSelectedSessionsAreViewed)
}, [handleSelectedSessionsAreViewed])

  useEffect(() => {
    customLabels instanceof Array &&
      customLabels.map((label) => {
        let count = 0;
        tableDataFilter &&
          tableDataFilter.map((obj) => {
            const labelArray = obj.customLabel;
            if (labelArray && labelArray.includes(label.name)) {
              count += 1;
            }
          });
        if (count === selectedData.length) {
          setState((stateValue) => ({ ...stateValue, [label.name]: true }));
        } else {
          setState((stateValue) => ({ ...stateValue, [label.name]: false }));
        }
      });
  }, [selectedData.length]);

  const renderHeader = useMemo(() => (
    <ActionButton onClick={() => handleWatchChange(watch)}>
       {watch ? <CheckMarkIcon /> : <EyeOutlined />}  <em>Viewed</em>
    </ActionButton>
  ), [watch, selectedSession, selectedUser])

  const renderFooter = useMemo(
    () =>
      loginInFromGuest !== 'guest' ? (
        <FooterWrpper>
          <ActionButton onClick={showModal}>
            <i
              className="anticon"
              style={{ fontWeight: '500', fontSize: '20px' }}
            >
              +
            </i>{' '}
            Add label
          </ActionButton>
          {hasCustomLabels && (
            <ActionButton onClick={showEditModal}>
              <SettingOutlined /> Manage label
            </ActionButton>
          )}
        </FooterWrpper>
      ) : null,
    [loginInFromGuest]
  );

  const handeEmptyMessageDisplay = useMemo(() => {
    if (isUserList && !hasCustomLabels) {
      return 'You haven’t created any label.';
    }
    if (customLabels && customLabels.length <= 0) {
      return 'You haven’t created any label.';
    }
    return null;
  }, [customLabels, hasCustomLabels, isUserList]);

  return (
    <>
      <Dropdown
        overlay={
          <LabelsDropdownOverlay
              tabs={labelTabs}
              selectedKeys={selectedKeys}
              handleItemClicked={handleCustomLabelClick}
              handleTabChange={handleCustomLabelTabChange}
              searchInput={{
                placeholder: 'Search label',
                value: selectedCustomLabelTab === 'session' ? labelSearch.sessionLabels : labelSearch.userLabels,
                onChange: handleLabelSearch,
              }}
              emptyMessage={handeEmptyMessageDisplay}
              hideFooter
              header={renderHeader}
              footer={renderFooter}
            />
        }
        trigger={['click']}
        overlayStyle={{ width: '240px' }}
        onVisibleChange={(visible) => {
            handleIconDisplay(visible);
            if(!visible) {
                resetSearch();
            }
        }}
      >
        <div style={{ fontSize: '16px' }}>
          <Button>
            Mark as{' '}
            {iconChange ? (
              <UpOutlined style={{ fontSize: '10px', opacity: '.6' }} />
            ) : (
              <DownOutlined style={{ fontSize: '10px', opacity: '.6' }} />
            )}
          </Button>
        </div>
      </Dropdown>
      <CustomLabelModal {...modalProps} />
      <CustomLabelMangeModal {...editModalProps} />
    </>
  );
};
export default MarkMultipleLabel;
