import { hasActivityFilter } from 'Utils/helpers/activityFilterUtils';
import { ACTIVITY_FILTER_CATEGORY } from 'types/activityFilterConfigurationTypes';
import { sortBy } from 'lodash';
import UserPropertiesGrouped from '../../data-structures-v2/UserV2/UserPropertiesGrouped.json';
import UserWho from '../../data-structures-v2/UserV2/UserWho.json';
import { activityFilterSelector, getActivityFilterAttributeByType } from '../../FilterDisplayBar/ActivityFilter/constants';

const UserPropertiesGroupLabels = Object.keys(UserPropertiesGrouped)
const ActivityFilterPropertiesJSONGroupLabels = Object.keys(UserWho)

export const groupLabelsByCategory = (
    categoriesFiltered: string[],
    excludedAndCategorizedExtraFilter: string[],
    getAvailableActivityFilterList: string[],
    isUserV2: boolean,
    isWebApp: boolean,
) => {
    if (!isUserV2) return categoriesFiltered.concat(excludedAndCategorizedExtraFilter);
    const webExclusionList = ['App properties','Events', 'Screen visit properties'];
    const mobileExclusionList: string[] = ['Events'];
    const group: Record<string, string[]> = {
        'All': [],
        'User properties': [],
        'Users who...': [],
        'others': [],
    };

    const priority = isWebApp
        ? ['Initial landing UTM', 'Acquisition', 'Custom user properties', 'User Labels', 'Cohorts']
        : ['Custom user properties', 'User Labels', 'Cohorts'];

    const allFilters = [...categoriesFiltered, ...excludedAndCategorizedExtraFilter, ...Object.keys(UserWho)].filter(
        item => isWebApp ? !webExclusionList.includes(item) : !mobileExclusionList.includes(item)
    );
    const [ListToBeSorted, ListWithoutSorted] = allFilters.reduce<[string[], string[]]>(
        ([sorted, unsorted], item) => priority.includes(item) ? [[...sorted, item], unsorted] : [sorted, [...unsorted, item]],
        [[], []]
    );

    const sortedList = sortBy(ListToBeSorted, item => priority.indexOf(item)).filter(item => item !== 'Events');
    const sortedMergeListWithPriority = [...ListWithoutSorted, ...sortedList];

    sortedMergeListWithPriority.forEach(item => {
        if ([...UserPropertiesGroupLabels, 'Custom user properties', 'User Labels', 'Cohorts', 'Initial landing UTM'].includes(item)) {
            group['User properties'].push(item);
        } else if (ActivityFilterPropertiesJSONGroupLabels.includes(item)) {
            const attribute = (UserWho as Record<string, any>)?.[item]?.attribute;
            if (getAvailableActivityFilterList.includes(attribute)) {
                group['Users who...'].push(item);
            }
        } else if (item === 'All') {
            group['All'].push(item);
        } else {
            group['others'].push(item);
        }
    });

    return group;
};


export const shouldImplementActivityFilter = (
    selectedKeyNew: string, 
    dropdownCategory: string,
    dropdownAttribute: string, 
    getAvailableActivityFilterList: string[], 
    dropdownId:  'isFirstLevel' | 'isSecondLevel' ,
    isUserV2: boolean) => {

    if (!isUserV2) return null
    let testAttribute = dropdownAttribute 
    if(selectedKeyNew && Object.keys(UserWho).includes(selectedKeyNew)) { // * triggered from the first level
        testAttribute = (UserWho as Record<string, any>)?.[selectedKeyNew].attribute
    }
    const isActivityFilterAttribute = hasActivityFilter([{ attribute: testAttribute }]) || Object.keys(UserWho).includes(testAttribute)
    const isRageUIEvents = ['UI Freeze', 'rageTap'].includes(testAttribute);
    const isCrashedSession = ['session_crashed'].includes(dropdownAttribute);

    // * CX-1876 - Adds Activity Filter Segment
    const hasSelectedActivityAttrs = isActivityFilterAttribute
    const hasCodedActivityFilter = dropdownId === 'isSecondLevel' && getAvailableActivityFilterList.includes(getActivityFilterAttributeByType(ACTIVITY_FILTER_CATEGORY.CODED_EVENT)) && (isRageUIEvents || ['Events'].includes(selectedKeyNew)) 
    const hasSmartActivityFilter = dropdownId === 'isSecondLevel' && getAvailableActivityFilterList.includes(getActivityFilterAttributeByType(ACTIVITY_FILTER_CATEGORY.SMART_EVENT)) && ['SmartEvents'].includes(selectedKeyNew) 
    const hasSessionActivityFilter = dropdownId === 'isSecondLevel' && getAvailableActivityFilterList.includes(getActivityFilterAttributeByType(ACTIVITY_FILTER_CATEGORY.SESSION)) && (isCrashedSession) 
    // Check if we should use activity filter
    const shouldImplement = hasSelectedActivityAttrs || hasCodedActivityFilter || hasSmartActivityFilter || hasSessionActivityFilter
    if (shouldImplement) {
        let attributeCategory
        if (selectedKeyNew === 'Events' || isRageUIEvents) attributeCategory = ACTIVITY_FILTER_CATEGORY.CODED_EVENT
        if (selectedKeyNew === 'SmartEvents') attributeCategory = ACTIVITY_FILTER_CATEGORY.SMART_EVENT
        if (activityFilterSelector[testAttribute]) {
            attributeCategory = activityFilterSelector[testAttribute].configuration.type
        }
        if (isCrashedSession) attributeCategory = ACTIVITY_FILTER_CATEGORY.SESSION
        const activityFilterConfig = {
            selectedKey: selectedKeyNew,
            attribute: testAttribute,
            attributeCategory,
            triggeredFrom: dropdownCategory
        }
        return activityFilterConfig
    }
    return null
    
}