import React, { useCallback } from 'react';
import styled from 'styled-components';
import { Modal } from 'antd';
import { theme } from 'theme';
import { showIntercom } from 'Utils/constants';
import Router from 'next/router';
import { useSelector } from 'react-redux';
import { IReduxState } from 'types/reduxStateTypes';
import { useMassUserIdFilterContext } from './MassUserIdFilterContext';

const StyledModal = styled(Modal)`
  .ant-modal-content {
    border-radius: 8px;
    padding: 32px;
    text-align: left;
  }
  .ant-modal-header {
    border-bottom: none;
    padding: 0;
  }
  .ant-modal-title {
    font-size: 18px;
    font-style: normal;
    color: #161e35;
    font-weight: 500;
    line-height: 24px;
    margin-bottom: 16px;
  }
  .ant-modal-body {
    padding: 0;
  }
  .ant-modal-footer {
    border-top: none;
    padding: 0;
  }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
`;

const Title = styled.h2`
  font-size: ${theme.fontSize(1.8)};
  line-height: ${theme.fontSize(2.4)};
  font-weight: 500;
  color: ${theme.colors.surface500.toString()};
  margin-bottom: ${theme.spacing(2)};
`;

const Description = styled.p`
  font-size: ${theme.fontSize(1.2)};
  line-height: ${theme.fontSize(2.4)};
  font-weight: 400;
  color: ${theme.colors.surface400.toString()};
  margin-bottom: ${theme.spacing(4)};
  b {
    font-weight: 700;
  }
`;

const Buttons = styled.div`
  width: 100%;
  display: flex;
  justify-content: flex-end;
  gap: ${theme.spacing(2)};
`;

const IntercomBtn = styled.button`
  background: none;
  border: none;
  padding: 0;
  color: ${theme.colors.primary500.toString()};
  cursor: pointer;
  font-size: inherit;
  font-weight: inherit;
  text-decoration: underline;

  &:hover {
    color: ${theme.colors.primary600.toString()};
  }
`;

const NewButtonStyled = styled.button<{ 'data-variant': 'ghost' | 'primary' }>`
  height: 32px;
  padding: 4px 29px;
  border-radius: 4px;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  cursor: pointer;
  border: none;

  ${(props) =>
    props['data-variant'] === 'ghost' &&
    `
    background: transparent;
    color: ${theme.colors.primary500.toString()};
    &:hover {
      color: ${theme.colors.primary600.toString()};
    }
  `}

  ${(props) =>
    props['data-variant'] === 'primary' &&
    `
    background-color: ${theme.colors.primary500.toString()};
    color: #ffffff;
    &:hover {
      background-color: ${theme.colors.primary600.toString()};
    }
  `}
`;

interface CohortLimitReachedModalProps {
  maxCohortsCount?: number;
}

const CohortLimitReachedModal: React.FC<CohortLimitReachedModalProps> = ({
  maxCohortsCount = 10,
}) => {
  const { showCohortLimitReached, setShowCohortLimitReached } =
    useMassUserIdFilterContext();
  const { parentType, appId } = useSelector((state: IReduxState) => state.urlReducer)

  const handleClose = useCallback(() => {
    setShowCohortLimitReached(false);
  }, [setShowCohortLimitReached]);

  const handleManageCohorts = useCallback(() => {
    const query = `appId=${appId}&parentType=retention`;
    const urlCohort = `/app/${appId}/retention/cohorts#manage?redirect_from_filter=${parentType}`;
    Router.push(`/integration?${query}`, urlCohort);
    setShowCohortLimitReached(false);
  }, [appId, parentType, setShowCohortLimitReached]);

  const openIntercom = useCallback(() => {
    showIntercom();
    setShowCohortLimitReached(false);
  }, [setShowCohortLimitReached]);

  return (
    <StyledModal
      visible={showCohortLimitReached}
      onCancel={handleClose}
      footer={null}
      centered
      width={570}
      closable={false}
    >
      <Wrapper>
        <Title>Cohort limit reached</Title>
        <Description>
          You have reached the limit of saved cohorts in your
          plan.
          <br />
          Consider deleting some of your existing cohorts to continue saving, or{' '}
          <IntercomBtn onClick={openIntercom} type="button">
            contact us.
          </IntercomBtn>{' '}
          to learn how to raise your limit of saved cohorts.
        </Description>
        <Buttons>
          <NewButtonStyled data-variant="ghost" onClick={handleClose}>
            Close
          </NewButtonStyled>
          <NewButtonStyled data-variant="primary" onClick={handleManageCohorts}>
            Manage cohorts
          </NewButtonStyled>
        </Buttons>
      </Wrapper>
    </StyledModal>
  );
};

export default CohortLimitReachedModal;
