/* eslint-disable no-undef */
import React, { useEffect, useState, createRef, useCallback, useMemo, memo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { InfoCircleOutlined } from '@ant-design/icons';
import { Tooltip, Checkbox } from 'antd';
import styled from 'styled-components';
import AppFlowsPageLocked from 'components/features/navigation/AppFlowsPageLocked'

import {
  screenFlowPayload,
  getScreenFlow,
  getScreenBurst,
  flagSetForScreenFlow,
  keyByValueOfScreenList,
} from 'redux/actions/screenList';
import {
  fetchPlanHatApi,
} from 'redux/actions/common';
import { trackPageViews } from 'redux/actions/trackingReport';

import { useQueryClient } from 'react-query';
import { screenFlowDummyGraph } from 'Utils/constants/dummyData';
import NoFeatureOverlay from 'components/common/NoFeatureOverlay';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import ScreenDropdown from 'components/features/navigation/ScreenFlow/ScreenDropdown';
import CommonOption from 'components/features/navigation/CommonOptions';
import Sunburst from 'components/features/navigation/Sunburst';
import useEventUserProperties from 'hooks/useEventUserProperties';
import map from 'lodash/map';
import useCustomLabels from 'hooks/useCustomLabels';
import { useAppText } from 'Utils/helpers/commonUtils';
import { useIsAppType } from 'hooks/useIsAppType';
import { getFilterPropertyRemoteData } from 'redux/actions/filter';
import { AppNavigationContextProvider, useAppNavigationContextContext } from './Context';
import ScreenFlowGraphContent from './ScreenFlow';

import { useScreenFlowImages } from '../heatmaps/hooks';

const chartRef = createRef();

const ScreenPageWrapperStyled = styled.div`
  margin-top: ${({ isScreenFlow }) => (isScreenFlow ? '80px' : 0)};
  pointer-events: ${( {isGlobalFilterVisible}) => isGlobalFilterVisible ?  `none` : ''};
`;
export const getScreenPayload = (dateSegment, searchInput = '') => ({
    attribute: 'screen_name',
    filter: [],
    search: searchInput,
    dropdownLimit: 501,
    date_range: dateSegment,
})

const AppFlow = ({ isUserDetails, userDetails }) => {
  const { showAppFlowsPageLockScreen } = useRestrictionContext()
  const { appFilter: {
    dateSegment,
    fetchProperty: {
      screen_name: {
        data: screenList
      } = {}
    }
  }} = useSelector((state) => state)
  const dispatch = useDispatch();
  const [isLoading, setIsLoading] = useState(false);

  // reset fetchProperty in redux after appid changes
  const { appId } = useSelector((state) => state.urlReducer);
  
  useEffect(() => {
    async function fetchScreenList() {
      setIsLoading(true);
      try {
        await dispatch(getFilterPropertyRemoteData(getScreenPayload(dateSegment), false, true));
      } finally {
        setIsLoading(false);
      }
    }
    
    fetchScreenList();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, dispatch]);
   
  if ( showAppFlowsPageLockScreen ) {
    return <AppFlowsPageLocked />
  }

  return (
    <AppNavigationContextProvider>
      <AppFlowPageContent 
        isUserDetails={isUserDetails} 
        userDetails={userDetails} 
        screenList={screenList}
        isLoading={isLoading}
      />
    </AppNavigationContextProvider>
  )
};

const AppFlowPageContent = memo(({ isUserDetails, userDetails, screenList, isLoading }) => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  const { customLabelQueryKey } = useCustomLabels();
  const [selectedKey, setSelectedGraph] = useState('screenFlow');

  const { appId, parentType, uxcamuserid } = useSelector( (state) => state.urlReducer );
  const { sunBurstDepth, screenFlowPayloadData } = useSelector((state) => state.screenDetailReducer);
  const {
    screenFlow: { segment: screenFlowSegment },
    dateSegment,
  } = useSelector((state) => state.appFilter);
  const currentOrg = useSelector((state) => state.currentOrgReducer);
  const { megaDropdownVisible, megaBottomDropdownVisible } = useSelector(
    (state) => state.megaFilterReducer
  )

  const isGlobalFilterVisible = useMemo(() => megaDropdownVisible || megaBottomDropdownVisible, [megaDropdownVisible, megaBottomDropdownVisible])
  const { inverted } = useAppNavigationContextContext()
  const planFeature = currentOrg?.planFeature;
  const screenFlowFlag = planFeature?.screenFlow;

  const disabled = screenFlowFlag === 0;
  const isScreenBurst = selectedKey === 'screenBurst';
  const screenNameArray = useMemo(() => screenList?.map((item) => item) || [], [screenList]);

  const imgReqBody = useMemo(
    () => ({
      appid: appId,
      date_range: dateSegment,
      filters: [],
      screen_names: screenNameArray && screenNameArray.length > 0 &&  [...screenNameArray, 'Launch', 'Quit', 'Others'],
    }),
    [appId, dateSegment, screenNameArray]
  );
  const { data: screenImageData, isSuccess: screenImageSuccess } = useScreenFlowImages(imgReqBody, 0, '');
  const screenRenamedList = useSelector((state) => state.screenRenamedList);

  const updatedScreenFlowImageArray = useMemo(() => map(screenImageData?.data, obj => {
      const updatedScreenName = screenRenamedList[obj.screenName] || obj.screenName;
      return { ...obj, updatedScreenName }
  }, [screenRenamedList]), [screenImageData, screenRenamedList]);

  const callFlowApis = useCallback(
    (payload) => {
      const screenFlowKey = {
        type: 'screenFlowPlotGraph',
      };
      const sunFlowKey = {
        type: 'sunburstPlotGraph',
      };
      const screenFlowImageData = updatedScreenFlowImageArray || [];
      dispatch(getScreenFlow(payload, screenFlowKey, isUserDetails, screenFlowImageData));
      dispatch(
        getScreenBurst(
          { ...payload, depth: sunBurstDepth},
          sunFlowKey,
          isUserDetails
        )
      );
    },
    [dispatch, isUserDetails, sunBurstDepth, updatedScreenFlowImageArray]
  );

  React.useEffect(() => {
    if ( screenFlowPayloadData === undefined ) { return }
    dispatch( trackPageViews( null, {
      eventName: 'wa_display_screenflow_plot',
      track_type: 'event',
      eventProperty: {
        plot_type: selectedKey,
      },
    } ) )
  }, [ dispatch, selectedKey, screenFlowPayloadData ] )

  const callGraphApi = useCallback(async () => {
    // let segment = [...screenFlowSegment, ...[{ ...dateSegment }]];
    let segment = [...screenFlowSegment];
    if(parentType === 'usersList' && uxcamuserid) {
      segment = [
        ...segment,
        ...[
          {
            table: 'appuser',
            attribute: 'uxcamuserid',
            operator: 'in',
            value: [uxcamuserid],
          },
        ],
      ];
    }
    const payload = {
      appid: appId,
      depth: screenFlowPayloadData?.depth || 5,
      max_screen_number: screenFlowPayloadData?.max_screen_number || 12,
      invert: inverted,
      filters: segment,
      date_range: dateSegment
    };
    dispatch(screenFlowPayload(payload));
    callFlowApis(payload);
    dispatch(flagSetForScreenFlow(false));
  }, [appId, callFlowApis, dateSegment, dispatch, inverted, parentType, screenFlowPayloadData?.depth, screenFlowPayloadData?.max_screen_number, screenFlowSegment, uxcamuserid]);

  const callApi = useCallback(async () => {
    callGraphApi();
    if(parentType === 'usersList') {
      return queryClient.invalidateQueries(customLabelQueryKey);
    }
  }, [callGraphApi, dispatch, parentType]);

  useEventUserProperties()

  const initialPhase = useCallback(async () => {
    screenFlowFlag !== 0 ? callApi() : dispatch( keyByValueOfScreenList('screenFlowPlotGraph', screenFlowDummyGraph) );
    dispatch(
      fetchPlanHatApi({
        action: 'Entered Screen flow page',
        info: {
          'From where': isUserDetails ? 'User Details' : 'Screen flow page',
          uxcamuserid: isUserDetails ? userDetails?.uxcamuserid : undefined,
        },
      })
    );
  }, [callApi, dispatch, isUserDetails, screenFlowFlag, userDetails?.uxcamuserid]);

  useEffect(() => {
    if(!['screenFlow', 'screenBurst', 'usersList'].includes(parentType)) return
    initialPhase();
  }, [appId, uxcamuserid, screenImageSuccess]);

  useEffect(() => {
    setSelectedGraph(parentType)
  }, [parentType])

  return (
    <NoFeatureOverlay isFeatureAvailable={screenFlowFlag} page="screenFlow">
      <div className="screen-flow-main-page">
        <ScreenPageWrapperStyled
          isScreenFlow={
            !disabled && ['screenBurst', 'screenFlow'].includes(parentType)
          }
          isGlobalFilterVisible={isGlobalFilterVisible}
          className="screen-page-wrapper"
        >
          <div className="screen-big-box">
            <FilterContents 
              callFlowApis={callFlowApis} 
              isScreenBurst={isScreenBurst} 
              disabled={disabled} 
              setSelectedGraph={setSelectedGraph} 
              screenList={screenList} 
              isLoading={isLoading} 
            />
            <GraphContent isScreenBurst={isScreenBurst} />
          </div>
        </ScreenPageWrapperStyled>
      </div>
    </NoFeatureOverlay>
  );
});

const GraphContent = memo(({ isScreenBurst }) => (
  <div
    className={isScreenBurst ? 'stat-full-box sunburst-chart' : 'stat-full-box'}
  >
    {!isScreenBurst ? (
      <ScreenFlowGraphContent chartRef={chartRef} />
    ) : (
      <Sunburst chartRef={chartRef} />
    )}
  </div>
));

const FilterContents = memo(({ callFlowApis, isScreenBurst, disabled, setSelectedGraph, screenList, isLoading }) => {
  const dispatch = useDispatch();
  const { screenFlowPayloadData } = useSelector((state) => state.screenDetailReducer);
  const { appId } = useSelector( (state) => state.urlReducer );
  const endScreen = screenFlowPayloadData?.end_screen;
  const startScreen = screenFlowPayloadData?.start_screen;
  const isWebSDK = useIsAppType('web');
  const { setInverted, inverted } = useAppNavigationContextContext()
  const {
    dateSegment,
  } = useSelector((state) => state.appFilter);

  const {
    dropdownLaunchText: launchText,
    exitText,
  } = useAppText()

  const handleInvertedToggle = useCallback((e) => {
    const payload = {
      ...screenFlowPayloadData,
      invert: e.target.checked
    };
    dispatch(screenFlowPayload(payload));
    callFlowApis(payload);
    setInverted(e.target.checked);
    dispatch(
      trackPageViews(null, {
        eventName: 'sf_reverse',
        track_type: 'event',
        eventProperty: {
          page: 'app navigation',
          description: 'User selects reverse in the screenflow',
        },
      })
    );
  }, [callFlowApis, dispatch, screenFlowPayloadData, setInverted] )

  const handleSTART = useCallback((val) => {
    if (screenFlowPayloadData) {
      if (val === 'Launch' || val === launchText) delete screenFlowPayloadData.start_screen;
      else screenFlowPayloadData.start_screen = val;
      dispatch(screenFlowPayload(screenFlowPayloadData));
    }
    callFlowApis(screenFlowPayloadData);
    dispatch(
      fetchPlanHatApi({
        action: 'Change start with',
      })
    );
    dispatch(
      trackPageViews(null, {
        eventName: 'sf_edit_start_end',
        track_type: 'event',
        eventProperty: {
          screen_changed: 'start',
          start_screen: screenFlowPayloadData?.start_screen || launchText,
          end_screen: screenFlowPayloadData?.end_screen || exitText,
        }
      })
    );
  }, [callFlowApis, dispatch, exitText, launchText, screenFlowPayloadData])

  const handleEND = useCallback((val) => {
    if (screenFlowPayloadData) {
      if (val === 'App Closed' || val === exitText) {
        delete screenFlowPayloadData.end_screen;
      } else screenFlowPayloadData.end_screen = val;
      dispatch(screenFlowPayload(screenFlowPayloadData));
    } else {
      dispatch(screenFlowPayload({
        appid: appId,
        end_screen: val,
        date_range: dateSegment,
      }));
    }
    callFlowApis(screenFlowPayloadData);
    dispatch(
      fetchPlanHatApi({
        action: 'Change end with',
      })
    );
    dispatch(trackPageViews(null, {
      eventName: 'sf_edit_start_end',
      track_type: 'event',
      eventProperty: {
        screen_changed: 'end',
        start_screen: screenFlowPayloadData?.start_screen || launchText,
        end_screen: screenFlowPayloadData?.end_screen || exitText,
      },
    }));
  }, [appId, callFlowApis, dateSegment, dispatch, exitText, launchText, screenFlowPayloadData])

  return (
    <div className="screen-filter-bar">
      <div className="filter-left-box">
        {!inverted ? (
          <>
            <ScreenDropdown
              onChangeHandler={handleSTART}
              initOption={launchText}
              value={startScreen || launchText}
              screenList={screenList}
              isLoading={isLoading}
            />
            <span className="flow-arrow">
              <img alt="" src="/static/icon-flow-arrow.svg" />
            </span>
            <ScreenDropdown
              onChangeHandler={handleEND}
              initOption={exitText}
              value={endScreen || exitText}
              screenList={screenList}
              isLoading={isLoading}
            />
          </>
        ) : (
          <>
            <ScreenDropdown
              onChangeHandler={handleEND}
              initOption={exitText}
              value={endScreen || exitText}
              screenList={screenList}
              isLoading={isLoading}
            />
            <span
              className="flow-arrow"
              style={{ transform: 'rotate(180deg)' }}
            >
              <img alt="" src="/static/icon-flow-arrow.svg" />
            </span>
            <ScreenDropdown
              onChangeHandler={handleSTART}
              initOption={launchText}
              value={startScreen || launchText}
              screenList={screenList}
              isLoading={isLoading}
            />
          </>
        )}
        <div className="filter-item" data-intercom-target="Reverse flow">
          <div className="combo-box" style={{ marginLeft: '10px' }}>
            <Checkbox
              checked={inverted || false}
              onChange={handleInvertedToggle}
              disabled={disabled}
            >
              Reverse flow
            </Checkbox>
          </div>
          <Tooltip title={isWebSDK ? "Reverse the flow to see the paths users take before exiting." : "Invert the screen flow and understand how users navigate through your app before they quit."}>
            <InfoCircleOutlined />
          </Tooltip>
        </div>
      </div>
      <div className="filter-right-box">
        <CommonOption
          chartRef={chartRef}
          disabled={disabled}
          handleAPICall={callFlowApis}
          setSelectedGraph={setSelectedGraph}
          isScreenBurst={isScreenBurst}
        />
      </div>
    </div>
)});

export default memo(AppFlow);
