/* eslint-disable camelcase */
import { useMutation, useQueryClient } from "react-query";
import SessionTableApi from "services/sessionTableApi";
import { useAISessionUtils } from "components/shared/GlobalFilter/components/aiSessionFilter/AISessionUtilsContext";
import { UserSessionData, UserSessionDataPayload } from "./types";

const getAIUserSessions = async ( postBody: UserSessionDataPayload ) => SessionTableApi.getV2AIUserSessions(postBody)
export const useAIUserSessions = (options?:any) => {
  const { setActiveUserSessionList, setIsActiveUserSessionLoading } = useAISessionUtils();
  const queryClient = useQueryClient();
  return useMutation(
    async ({ uxcamuserid,appid,usersessionrun,session_per_page,webApp,recordedon }: UserSessionDataPayload) => {
      const cacheKey = ['aiUserSessions', { uxcamuserid,appid,usersessionrun,session_per_page,webApp,recordedon }];
      const cachedData = queryClient.getQueryData(cacheKey);
      
      if (cachedData) {
        return cachedData;
      }
      
      return getAIUserSessions({ 
        uxcamuserid,
        appid,
        usersessionrun,
        session_per_page,
        webApp,
        recordedon
      });
    },
    {
      ...options,
      onMutate: () => {
        setIsActiveUserSessionLoading?.(true);
        if (options && typeof options.onMutate === 'function') {
          return options.onMutate();
        }
        return undefined;
      },
      onSuccess: (data, variables, context) => {
        setIsActiveUserSessionLoading?.(false);
        queryClient.setQueryData(['aiUserSessions', variables], data);
        setActiveUserSessionList(data as UserSessionData);
        if (options && typeof options.onSuccess === 'function') {
          options.onSuccess(data, variables, context);
        }
      },
      onError: (error, variables, context) => {
        setIsActiveUserSessionLoading?.(false);
        if (options && typeof options.onError === 'function') {
          options.onError(error, variables, context);
        }
      },
    }
  );
};
