/* eslint-disable no-plusplus */

const DANGEROUS_CHARS = ['=', '+', '-', '@'];

const sanitizeXlsCell = (value) => {
  if (value === null || value === undefined) return '';

  const strValue = value instanceof Date ? value.toLocaleString() : value.toString();

  // Sanitize cells that start with dangerous characters to prevent formula injection
  if (DANGEROUS_CHARS.some(char => strValue.trimStart().startsWith(char))) {
    // Prefix with apostrophe to make Excel treat it as text
    return `'${strValue}`;
  }

  return strValue;
};

const exportToXls = (filename, rows) => {
  // Create Excel-specific HTML template
  const template = `
    <html xmlns:o="urn:schemas-microsoft-com:office:office" 
          xmlns:x="urn:schemas-microsoft-com:office:excel" 
          xmlns="http://www.w3.org/TR/REC-html40">
      <head>
        <!--[if gte mso 9]>
          <xml>
            <x:ExcelWorkbook>
              <x:ExcelWorksheets>
                <x:ExcelWorksheet>
                  <x:Name>Sheet1</x:Name>
                  <x:WorksheetOptions>
                    <x:DisplayGridlines/>
                  </x:WorksheetOptions>
                </x:ExcelWorksheet>
              </x:ExcelWorksheets>
            </x:ExcelWorkbook>
          </xml>
        <![endif]-->
        <style>
          td, th {
            border: 1px solid #ddd;
            padding: 8px;
            font-family: Calibri, sans-serif;
          }
          th {
            background-color: #f2f2f2;
            font-weight: bold;
          }
          .number { mso-number-format:"0.00"; }
          .text { mso-number-format:"\\@"; }
        </style>
        <meta name=ProgId content=Excel.Sheet>
        <meta charset=UTF-8>
      </head>
      <body>
        <table>
          ${rows.map(row => `
            <tr>
              ${row.map(cell => {
                const sanitizedCell = sanitizeXlsCell(cell);
                const isNumber = !Number.isNaN(parseFloat(sanitizedCell)) && Number.isFinite(parseFloat(sanitizedCell)) && sanitizedCell.trim() !== '';
                const className = isNumber ? 'number' : 'text';
                return `<td class="${className}">${sanitizedCell}</td>`;
              }).join('')}
            </tr>
          `).join('')}
        </table>
      </body>
    </html>
  `;

  // Convert to base64
  const base64 = window.btoa(unescape(encodeURIComponent(template)));
  const uri = `data:application/vnd.ms-excel;base64,${base64}`;

  // Create download link
  const link = document.createElement('a');
  link.href = uri;
  link.download = filename;
  link.style.visibility = 'hidden';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
};

export default exportToXls;
