import React from 'react'
import { Cell } from "components/features/aiSessions/hooks/useAISessionColumns"

interface IProps {
	score: string
}

const getStringScore = ( score?: string ) => {
	if ( !score ) {
		return '-'
	}

	const scoreFloat = Number( score )

	switch( true ) {
		case ( scoreFloat >= 4 ):
			return 'Very high'
		case ( scoreFloat >= 3 ):
			return 'High'
		case ( scoreFloat >= 2 ):
			return 'Medium'
		case ( scoreFloat >= 1 ):
			return 'Low'
		default:
			return 'Very low'
	}
}

const RelevanceCell = ( { score }: IProps ) => {
	return (
		<Cell>
			{ getStringScore( score ) }
		</Cell>
	)
}

export default RelevanceCell