import React, { useEffect } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import dynamic from 'next/dynamic'
import styled from 'styled-components'
import { IReduxState } from 'types/reduxStateTypes'
import ReactLoader from 'components/common/reactLoading'
import { setActiveTab } from 'redux/actions/sessionStatistics'
import SessionDetailsAndVideo from '../SessionDetailsAndVideo'

const OverviewBoxesWrapper = styled.div`
  padding: 0 16px;
`

const SessionStatisticsWrapper = styled.div`
  padding: 12px 16px 0;
`

const SessionStatistics = dynamic( import( 'components/features/sessions/SessionStatistics' ), { loading: () => <ReactLoader /> } )
const NewOverviewBoxes = dynamic( import( 'components/common/Analytics/NewOverviewBoxes' ), { loading: () => <ReactLoader /> } )

const AISessionList = () => {
  const dispatch = useDispatch()
  const {
    urlReducer: { parentType },
  } = useSelector( ( state: IReduxState ) => state )

  useEffect( () => {
    dispatch( setActiveTab( parentType ) )
  }, [ dispatch, parentType ] )

  if ( parentType && ![ 'aiSessionStatistics', 'aiSessionsList' ].includes( parentType ) ) {
    return null
  }

  if ( parentType === 'aiSessionStatistics' ) {
    return (
      <>
        <OverviewBoxesWrapper>
          <NewOverviewBoxes />
        </OverviewBoxesWrapper>
        <SessionStatisticsWrapper>
          <SessionStatistics
            isNewSession
          />
        </SessionStatisticsWrapper>
      </>
    )
  }

  return (
    <SessionDetailsAndVideo />
  )
}

export default AISessionList
