/* eslint-disable arrow-body-style */
import { IFunnel } from "../../types"

interface TooltipProps {
	funnelType: 'user' | 'session',
	metric: 'total_count' | 'total_conversion' | 'conversion_rate' | 'avg_conversion_time',
	value: number
}

export const dispalyPercentage = ( value: number, isTooltip?: boolean ) => {
	const numericValue = Number( value ) * 100
	const isInt = Number.isInteger( numericValue )
	return Number.isNaN( numericValue ) ? '---' : `${ isInt ? numericValue : ( numericValue ).toFixed( isTooltip ? 3 : 2 )  }%`
}

export const displayNumeric = ( numericValue: number ): string => {
	if ( numericValue > 1_000_000 ) {
		return `${ ( numericValue / 1_000_000 ).toFixed( 2 ) }M`
	}
	if ( numericValue > 1_000 ) {
		return `${ ( numericValue / 1_000 ).toFixed( 2 ) }K`
	}
	return numericValue.toString()
}

export const displayDuration = ( duration: number ): string => {
	// eslint-disable-next-line no-param-reassign
	duration = Math.round( duration )
	if ( duration < 60 ) {
		return `${ duration }s`
	}
	if ( duration < 3600 ) {
		return `${ Math.floor( duration / 60 ) }m ${ duration % 60 }s`
	}
	if ( duration < 86400 ) {
		return `${ Math.floor( duration / 3600 ) }h ${ Math.floor( ( duration % 3600 ) / 60 ) }m ${ duration % 60 }s`
	}
	return `${ Math.floor( duration / 86400 ) }d ${ Math.floor( ( duration % 86400 ) / 3600 ) }h ${ Math.floor( ( duration % 3600 ) / 60 ) }m ${ duration % 60 }s`
}

export const displayTooltipDuration = (duration: number): string => {
	// eslint-disable-next-line no-param-reassign
	duration = Math.round( duration )

	if ( duration < 60 ) {
		return `${ duration } seconds`
	}
	if ( duration < 3600 ) {
		return `${ Math.floor( duration / 60 ) } minutes, and ${ duration % 60 } seconds`
	}
	if ( duration < 86400 ) {
		return `${ Math.floor( duration / 3600 ) } hours, ${ Math.floor( ( duration % 3600 ) / 60 ) } minutes, and ${ duration % 60 } seconds`
	}
	return `${ Math.floor( duration / 86400 ) } days, ${ Math.floor( ( duration % 86400 ) / 3600 ) } hours, ${ Math.floor( ( duration % 3600 ) / 60 ) } minutes, and ${ duration % 60 } seconds`
};

export const getTooltipText = (funnelType: TooltipProps['funnelType'], metric: TooltipProps['metric'], value: TooltipProps['value']): string => {
	const formattedValue = value.toLocaleString();
	const fixedValue = dispalyPercentage( value / 100, true )
	const formattedTime = displayTooltipDuration(value)
  
	if (funnelType === 'user') {
	  switch (metric) {
		case 'total_count':
			return `${formattedValue} users entered the funnel.`;
		case 'conversion_rate':
			return `${fixedValue} of users that entered the funnel completed it.`;
		case 'total_conversion':
			return `${formattedValue} users completed the funnel.`;
		case 'avg_conversion_time':
			return `On average, it took ${formattedTime} to complete the funnel.`;
		default:
			return '';
	  }
	} else if (funnelType === 'session') {
	  switch (metric) {
		case 'total_count':
			return `There were ${formattedValue} sessions where users entered the funnel.`;
		case 'conversion_rate':
			return `In ${fixedValue} of sessions where users entered the funnel, they completed it.`;
		case 'total_conversion':
			return `There were ${formattedValue} sessions where users completed the funnel.`;
		case 'avg_conversion_time':
			return `On average, it took ${formattedTime} to complete the funnel.`;
		default:
			return '';
	  }
	}
  
	return '';
};

export const extractFilterAttributes = ( funnel: IFunnel ): string[] => {
	return ( funnel.fb_d_l || [] ).map( ( { attribute } ) => attribute )
}

export const extractStepAttributes = ( funnel: IFunnel ): string[] => {
	// eslint-disable-next-line camelcase
	return ( funnel.step_d_l || [] ).map( ( { fb_l = [] } ) => {
		// eslint-disable-next-line camelcase
		return fb_l?.length ? fb_l[ 0 ].attribute : 'app_launched'
	} )
}

const intl = new Intl.NumberFormat( 'en-US', {
	maximumFractionDigits: 2,
} )

export const formatNumericValue = ( value: number ): string => {
	return intl.format( value )
}

export const formatSteps = ( items: string[] ) => {
	if ( !items ) return ''

	const firstItem = items[0];
	const secondItem = items[ 1 ];
	const thirdItem = items[2];

	switch(items?.length){
		case 3:
			return ( `${ firstItem }, ${ secondItem }, or ${ thirdItem }` ); 

		case 2:
			return ( `${ firstItem }, or ${ secondItem }` );

		case 1:
			return ( `${ firstItem }` );

		default:
			return ( `${ firstItem }, ${ secondItem }, ${ thirdItem }, or ${ items.length - 3 } more` );

	}
}

// check if value is primitive
function isPrimitive( obj: unknown ) {
	return ( obj !== Object( obj ) );
}

export function deepEqual( obj1: unknown, obj2: unknown ) {

	if ( obj1 === obj2 ) { return true; } // it's just the same object. No need to compare.

	if ( isPrimitive( obj1 ) && isPrimitive( obj2 ) ) { return obj1 === obj2; } // compare primitives

	if ( Object.keys( obj1 as Record<string, unknown> ).length !== Object.keys( obj2 as Record<string, unknown> ).length ) { return false; }

	// compare objects with same number of keys
	// eslint-disable-next-line no-restricted-syntax, guard-for-in
	for ( const key in ( obj1 as Record<string, unknown> ) ) {
		if ( !( key in ( obj2 as Record<string, unknown> ) ) ) return false; // other object doesn't have this prop
		if ( !deepEqual( ( obj1 as Record<string, unknown> )[ key ], ( obj2 as Record<string, unknown> )[ key ] ) ) return false;
	}

	return true;
}
