/* eslint-disable no-shadow */
/* eslint-disable react/no-array-index-key */
/* eslint-disable arrow-body-style */
import React from 'react'
import styled from 'styled-components'
import { theme } from 'theme/index'
import { useSelector } from 'react-redux'
import { Col, Tooltip } from 'antd'
import { IReduxState } from 'types/reduxStateTypes'
import { IFunnelStepFilter, mapFunnelFilterStep, StepType } from './utils'
import FunnelStepItem from './FunnelStepItem'
import ConversionFilterItem from '../ConversionSequence/ConversionSteps/ConversionFilterItem'
import { mapConversionFilter } from '../ConversionSequence/utils'

const Container = styled.div`
	display: flex;
	flex-direction: column;
	color: ${ theme.colors.surface400.toString() };
	margin-bottom: ${ theme.spacing( -0.5 ) };
`

const Section = styled.div`
	display: flex;
	flex-direction: column;
	&[aria-hidden="true"] {
		display: none;
	}
`

const Heading = styled.div`
	display: flex;
	font-weight: 700;
	font-size: ${ theme.fontSize( 1.4 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	margin: ${ theme.spacing( 0, 0, 1 ) };
`

const SectionTitle = styled.div`
	display: flex;
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	font-weight: 500;
	margin: ${ theme.spacing( 0, 0, 1 ) };
`

const ConversionTimeContainer = styled.div`
	display: flex;
`

const ConversionTime = styled.div`
	display: inline-flex;
	font-size: ${ theme.fontSize( 1.2 ) };
	line-height: ${ theme.fontSize( 2.4 ) };
	margin: ${ theme.spacing( 0, 0, 1 ) };
`
const FilterWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0px 4px 8px 4px;
`
const GroupingFilterWrapper = styled.div`
  margin: 4px 0px 8px 0px;
  > div {
    margin-left: 0px;
    min-height: 24px;
  }
`
interface Props {
	filterData: IFunnelStepFilter
	hasMoreFilters: boolean
}

const FunnelSequence: React.FC<Props> = ( { filterData, hasMoreFilters } ) => {
    const { urlReducer: {parentType} } = useSelector((state) => state as IReduxState);
    
	const {
		screenRenamedList: renamedScreens = {},
		batchData = [],
	} = useSelector(({ screenRenamedList, appFilter }: any) => ({
		screenRenamedList: screenRenamedList as Record<string, string>,
		batchData: appFilter?.fetchProperty?.batch_id?.data || [],
	}));

	const [conversionSteps, groupingFilters] = React.useMemo( () => {
		const {
			value: {
				completed_steps: completedSteps,
                grouping_funnel_filter: groupingFunnelFilter
			}
		} = filterData

		return [
            completedSteps.map( ( step ) => mapFunnelFilterStep( step, renamedScreens ) ),
            groupingFunnelFilter ? mapConversionFilter([groupingFunnelFilter], renamedScreens, batchData) : null
        ]
	}, [ filterData, renamedScreens, batchData ] )

	const dropOffSteps = React.useMemo( () => {
		const {
			value: {
				drop_off_step: dropOffStep
			}
		} = filterData

		return dropOffStep ? [ mapFunnelFilterStep( dropOffStep, renamedScreens ) ] : []

	}, [ filterData, renamedScreens ] )

	const heading = React.useMemo( () => {
		const {
			attribute
		} = filterData

		if ( attribute === 'action_sequence' ) {
			return 'Completed steps in any order:'
		}
		return 'Completed steps in order:'
	}, [ filterData ] )

	const conversionFilterDisplay = React.useMemo( () => {
		const {
			value: {
				conversion_filter: conversionFilter = [],
			}
		} = filterData

		if ( !conversionFilter || !conversionFilter.length ) {
			return `1 session`
		}

		const conversionFilterData = conversionFilter[0]

		const {
			attribute,
			value,
		} = conversionFilterData

		switch ( attribute ) {
			case 'session_period_second':
				return `${ value } seconds`
			case 'session_period_minute':
				return `${ value } minutes`
			case 'session_period_hour':
				return `${ value } hours`
			case 'session_period_day':
				return `${ value } days`
			case 'session_period_week':
				return `${ value } weeks`
			default:
				return ''
		}

	}, [ filterData ] )

    const funnelFilters = React.useMemo(() => {
        const { value: {
            funnel_filter: funnelAnalyticsFilters
        } } = filterData
        if( !funnelAnalyticsFilters ) return []
        return mapConversionFilter(funnelAnalyticsFilters, renamedScreens, batchData)
    }, [filterData, renamedScreens, batchData])
		
    const isFunnelFilterVisible = parentType === 'usersList' && funnelFilters?.length > 0;

	return (
		<Col span={24}>
			<Container>
				<Heading>Based on funnel:</Heading>
				<Section>
					<SectionTitle>{ heading }</SectionTitle>
					{
						conversionSteps.map( ( step, index ) => {
							return (
								<FunnelStepItem
									step={ step }
									index={ index + 1 }
									key={ index }
									type="conversion"
								>
                                  {
                                        index === 0 && isFunnelFilterVisible && (
                                            <FilterWrapper>
                                                {
                                                    funnelFilters.map((filter, index) => (
                                                        <ConversionFilterItem filter={filter} index={index } key={index}/>
                                                    ))
                                                }
                                            </FilterWrapper>
                                        )
                                    }    
                                </FunnelStepItem>
							)
						} )
					}
				</Section>
				<Section aria-hidden={ !dropOffSteps.length }>
					<SectionTitle>Not completed steps:</SectionTitle>
					{
						dropOffSteps.map( ( step, index ) => {
							return (
								<FunnelStepItem
									step={ step }
									index={ conversionSteps.length + index + 1 }
									key={ index }
									type="dropoff"
								/>
							)
						} )
					}
				</Section>
				<Section>
					<SectionTitle>Converted within:</SectionTitle>
					<ConversionTimeContainer>
						<Tooltip placement="bottom" overlay="You can change this filter attribute from the funnel builder.">
							<ConversionTime>
								{ conversionFilterDisplay }
							</ConversionTime>
						</Tooltip>
					</ConversionTimeContainer>
				</Section>
               {groupingFilters && ( <Section>
					<SectionTitle>Grouped Filter:</SectionTitle>
                        <GroupingFilterWrapper>
                            {
                                groupingFilters?.map((filter, index) => (
                                    <ConversionFilterItem filter={filter} index={index } key={index} showPreText={false}/>
                                ))
                            }
                        </GroupingFilterWrapper>
				</Section>)}
				<Section aria-hidden={ !hasMoreFilters }>
					<SectionTitle>Filters:</SectionTitle>
				</Section>
			</Container>
		</Col>
	)
}

export default React.memo( FunnelSequence )