/* eslint-disable no-nested-ternary */
/* eslint-disable react/jsx-props-no-spreading */
import React, { useMemo } from 'react';
import { Button, Col, Select, Tooltip } from 'antd';
import { OperatorMenu } from 'components/shared/GlobalFilter/components/CommonComponentsV2';
import { mappedOperator } from 'components/shared/GlobalFilter/components/utils';
import { MinusBtnSVG } from 'components/svg_files';
import ArrowDownSVG from 'public/static/arrow-down.svg';
import useHasSmartEvents from 'hooks/useHasSmartEvents';
import FilterValue from '../AppliedFilter/FilterValue';
import SmartEventPropsJSON from "../../data-structures-v2/Event/SmartEventProps.json";
import { PlaceHolder, SelectWrap, WHEREAND } from './styles';
import { getActivityPropertiesListByAttribute } from './constants';

const EventActivityFilterValue = (props) => {
    const {
        activityFilterConfiguration,
        activityFilterIndex,
        activityPropertyIndex,
        attribute,
        callListApi,
        filterData,
        mappedTitle,
        operatorData,
        operatorType,
        propName,
        propValue,
        selectedOperator,
        propertyOperator,
        whereClicked,
        handleOperatorMenuClick,
        setPropertyName,
        setPropertyValue,
        setWhereClicked,
        toggleEventPropertyVisibility,
        setOperatorData,
        toggleEditFieldVisibility,
        editFieldVisibility,
        operatorChangeData,
        setOperatorChangeData,
        attributeProps,
        setPropertyOperator,
        handleFilterDelete,
        handleSmartEventPropertyChange,
        selectedPropOperator
    } = props;

    // Common props for FilterValue component
    const commonFilterValueProps = {
        callListApi,
        attribute,
        setPropertyName,
        setPropertyValue,
        filterData,
        attributeProps,
        isActivitySegment: true,
        activityPropertyIndex,
        activityFilterIndex,
        setOperatorData,
        toggleEditFieldVisibility,
        operatorChangeData,
        setOperatorChangeData,
        setWhereClicked,
        toggleEventPropertyVisibility,
    };

    const allSupportedAttributes = getActivityPropertiesListByAttribute(activityFilterConfiguration?.activityFilterAttribute);
    const hasSmartEvents = useHasSmartEvents();
    const getTitle = useMemo(()=>{
        const selectedFilter= allSupportedAttributes?.find(item=>item.attribute === attribute);
        return !hasSmartEvents && selectedFilter?.alternativeTitle ? selectedFilter?.alternativeTitle : selectedFilter?.title;    
    }
    ,[allSupportedAttributes, hasSmartEvents, attribute])

    const renderWhereAnd = () => (
        <WHEREAND className='filter-spacing'>
            {activityPropertyIndex === 0 ? 'WHERE' : 'AND'}
        </WHEREAND>
    );
    if (['eventName','smartEventName','screenName'].includes(activityFilterConfiguration?.type)) {
        return (
            <Col span={24} key={`${attribute}-${activityPropertyIndex}-${attribute}`}>
                {renderWhereAnd()}
                <span className="filter-spacing">
                  {getTitle}
                </span>
                <span className="filter-spacing">
                    <OperatorMenu
                        selectedAttribute={attribute}
                        selectedOperator={selectedOperator}
                        isFilterDisplayBar
                        operatorType={operatorType}
                        handleOperatorMenuClick={handleOperatorMenuClick}
                    />
                </span>
                <FilterValue
                    {...commonFilterValueProps}
                    value={attribute === 'user_custom_property' ? propValue : filterData.value}
                    isUserPropertyValue={attribute === 'user_custom_property'}
                    operatorData={operatorData}
                    key={`activity-event-name-value-${activityPropertyIndex}${activityFilterIndex}`}
                    id={attribute}
                    keyName="value"
                    editFieldVisibility={editFieldVisibility}
                    isMultiSelect
                    filterTitle={mappedTitle}
                />
                <Tooltip placement="topLeft" title="Delete filter" arrowPointAtCenter>
                    <Button
                        onClick={() => handleFilterDelete(filterData)}
                        ghost
                        type="text"
                        icon={<MinusBtnSVG />}
                        className="delete-btn"
                    />
                </Tooltip>
            </Col>
        );
    }

    if ( ['eventProperties', 'screenProperties'].includes(activityFilterConfiguration?.type) ) {
        return (
            <Col span={24} key={`${attribute}-${activityPropertyIndex}-${attribute}`}>
                {renderWhereAnd()}
                <FilterValue
                    {...commonFilterValueProps}
                    eventPropertyVisibility
                    propertyOperator={propertyOperator}
                    value={propName}
                    propValue={propValue}
                    whereClicked={whereClicked}
                    operatorData={{
                        isSearchable: true,
                        attribute: operatorData?.attribute,
                    }}
                    id="eventpropertyname"
                    key={`activity-event-property-name${activityPropertyIndex}${activityFilterIndex}`}
                    eventValue={filterData.value}
                    isEventProperty={attribute === 'event_name'}
                    isScreenProperty={attribute === 'screen_name'}
                    keyName="property"
                    filterTitle={mappedTitle}
                    isActivitySegment
                />

                <span className="filter-spacing">
                    <OperatorMenu
                        selectedAttribute={attribute}
                        selectedOperator={
                            // eslint-disable-next-line no-nested-ternary
                            attribute === 'screen_name' ?
                                {
                                    attribute: selectedPropOperator.attribute,
                                    title: mappedOperator[selectedPropOperator.attribute],
                                } : selectedOperator?.attribute ?
                                    {
                                        attribute: selectedOperator.attribute,
                                        title: mappedOperator[selectedOperator.attribute],
                                    }
                                    : { attribute: 'in', title: 'equals' }
                        }
                        isFilterDisplayBar
                        operatorType="json"
                        handleOperatorMenuClick={handleOperatorMenuClick}
                        isEventProperty={attribute === 'event_name'}
                        isScreenProperty={attribute === 'screen_name'}
                        propertyOperator={propertyOperator}
                        propertyName={propName}
                    />
                </span>
                {!propName ?
                    <Tooltip
                        placement="bottomLeft"
                        overlayClassName="tooltip-new-design"
                        title="Please select property name first"
                    >
                        <PlaceHolder>
                            select property value
                        </PlaceHolder>
                    </Tooltip>
                    :
                    <FilterValue
                        {...commonFilterValueProps}
                        eventPropertyVisibility
                        propertyOperator={propertyOperator}
                        setPropertyOperator={setPropertyOperator}
                        value={propValue}
                        propertyName={propName}
                        whereClicked={whereClicked}
                        operatorData={operatorData}
                        eventValue={attribute === 'event_custom_property' ? null : filterData.value}
                        id="eventpropertyvalue"
                        key={`activity-event-property-value${activityPropertyIndex}${activityFilterIndex}`}
                        isMultiSelect
                        isEventProperty={attribute === 'event_name'}
                        isScreenProperty={attribute === 'screen_name'}
                        keyName="property"
                        editFieldVisibility={editFieldVisibility}
                        filterTitle={mappedTitle}
                    />}
                <Tooltip placement="topLeft" title="Delete filter" arrowPointAtCenter>
                    <Button
                        onClick={() => handleFilterDelete(filterData)}
                        ghost
                        type="text"
                        icon={<MinusBtnSVG />}
                        className="delete-btn"
                    />
                </Tooltip>
            </Col>
        );
    }

    if ( ['smartEventProperties'].includes(activityFilterConfiguration?.type) ) {
        return (
            <Col span={24} key={`${attribute}-${activityPropertyIndex}-${attribute}`}>
                {renderWhereAnd()}
                <span className="filter-spacing">
                    <SelectWrap
                        onChange={handleSmartEventPropertyChange}
                        value={attribute}
                        suffixIcon={<ArrowDownSVG />}
                        width='120px'
                    >
                        {SmartEventPropsJSON.map((filter) => (
                            <Select.Option key={filter.attribute}>{filter.title}</Select.Option>
                        ))}
                    </SelectWrap>
                </span>
                <span className="filter-spacing">
                    <OperatorMenu
                        selectedAttribute={attribute}
                        selectedOperator={selectedOperator}
                        isFilterDisplayBar
                        operatorType={operatorType}
                        handleOperatorMenuClick={handleOperatorMenuClick}
                        isEventProperty
                    />
                </span>
                <FilterValue
                    {...commonFilterValueProps}
                    value={filterData.value}
                    operatorData={operatorData}
                    key={`activity-smart-event-property-value${activityPropertyIndex}${activityFilterIndex}`}
                    id={attribute}
                    keyName="value"
                    editFieldVisibility={editFieldVisibility}
                    isMultiSelect
                    filterTitle={mappedTitle}
                    isActivitySegment
                />
                <Tooltip placement="topLeft" title="Delete filter" arrowPointAtCenter>
                    <Button
                        onClick={() => handleFilterDelete(filterData)}
                        ghost
                        type="text"
                        icon={<MinusBtnSVG />}
                        className="delete-btn"
                    />
                </Tooltip>
            </Col>
        );
    }

    return null;
};

export default EventActivityFilterValue;