import React, { memo } from 'react'
import { useSelector } from 'react-redux'
import { OperatorMenu } from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import { useIsAppType } from 'hooks/useIsAppType'

const MenuHeader = memo(({
  isOperatorRadio,
  handleOperatorMenuClick,
  selectedOperator,
}) => {
  const { selectedAttributeProps } = useSelector(
    (state) => state.megaFilterReducer
  )

  const isWeb = useIsAppType('web')
  const { info: attributeInfo, webInfo, type: operatorType, propertyName, title, attribute: selectedAttribute } = selectedAttributeProps || {}

  const attrInfo = isWeb ? webInfo ?? attributeInfo : attributeInfo

  return (
    <>
     <h4 className='user-properties-title'><span>{title}</span></h4>
      <div>
        {attrInfo || ''}
      </div>
      {!isOperatorRadio && (
        <OperatorMenu
          selectedAttribute={ selectedAttribute }
          selectedOperator={selectedOperator}
          operatorType={operatorType}
          handleOperatorMenuClick={handleOperatorMenuClick}
          className="width-100"
          propertyName={propertyName}
        />
      )}
    </>
  )
})
export default MenuHeader
