import React, { useCallback, useState } from "react";
import { rollbar } from "components/common/rollbar";
import { useSegmentModal } from "../hooks/useModal";
import { SegmentDeleteBtnText, SegmentDeleteText, SegmentDeleteTitle } from "../variables";
import useSegmentAPI from "../hooks/useSegmentAPI";
import { ISegment, SaveModalState } from "../types";
import { DeleteModalWrapper } from "../styles";

const DeleteSegmentModal:React.FC = () => {

  const [showLoader, setShowLoader] = useState<boolean>(false);

  const { saveModalOpen, isDeleteModalOpen, toggleModal } = useSegmentModal();
  const { deleteSegment } = useSegmentAPI();

  const { modalSegment } = saveModalOpen as SaveModalState;
  const { id: segmentId } = modalSegment as ISegment || {};

  const handleCancel = useCallback(() => {
    toggleModal?.('delete', [])
  }, [toggleModal]);

  const handleOk = useCallback( async () => {
    setShowLoader(true);
    try {
      await deleteSegment(segmentId);
      handleCancel();
      setShowLoader(false);
    } catch (error: any) {
      setShowLoader(false);
      rollbar.error(error)
    }
  }, [deleteSegment, handleCancel, segmentId]);
 
  return (
    <DeleteModalWrapper 
      closable = {false} 
      confirmLoading={showLoader}
      title={SegmentDeleteTitle} 
      visible={isDeleteModalOpen} 
      okText={SegmentDeleteBtnText} 
      onOk={handleOk} 
      onCancel={handleCancel}>
      <p>{SegmentDeleteText}</p>
    </DeleteModalWrapper>
  );
};

export default DeleteSegmentModal;