import { Button, Dropdown } from 'antd'
import React, { memo, useCallback, useEffect, useMemo, useState } from 'react';
import styled from 'styled-components';
import { getDateSegment } from 'redux/actions/megaFilter';
import { useDispatch, useSelector } from 'react-redux';
import { trackPageViews } from 'redux/actions/trackingReport';
import DateRangePicker from 'dashboard-builder/dist/cjs/DateRangePicker';
import { currentTimeZone, datePresetsAbsolute, getDisplayRangeDate } from 'Utils/DateConversion/dateConversionUtils';
import CalendarIcon from 'public/static/customisable-dashboard/calendar.svg'
import useAppFilter from './useAppFilter';

const ButtonWrap = styled(Button)`
  border: 1px solid rgb(192, 202, 217) !important;
  display: flex;

  svg {
    margin: 0 10px 0 0;
  }
`

const minDate = new Date( '2022-03-15' );

const DefaultTrigger = ({btnLabel})=>{
        return <ButtonWrap><CalendarIcon /> {btnLabel}</ButtonWrap>
}
const CalendarDateRangePicker = ({
    disabled = false,
    children = DefaultTrigger
}) => {

  const dispatch = useDispatch();

  const { callListApi } = useAppFilter();

  const {
    appFilter: { dateSegment },
    urlReducer: {
      parentType
    }
  } = useSelector((state) => state);

  const value = useMemo(() => {
    const now = new Date()
    const from = new Date()
    from.setDate(now.getDate() - 30)

    const { value: { lower, upper }, tz, attribute, labelId } = dateSegment;
    const defaultSource = [ 'aiSessionsList', 'aiSessionStatistics' ].includes( parentType ) ? 'device_time' : 'upload_time'
    return {
      from: new Date(lower) || from,
      to: new Date(upper) || now,
      timezone: tz || currentTimeZone,
      source: attribute.toUpperCase() || defaultSource,
      preset: labelId,
    }
  }, [dateSegment, parentType]);

  const [open, setOpen] = useState(false)
  const handleClose = useCallback(() => setOpen(false), [])
  const [dateRange, setDateRange] = useState(value);

  useEffect(() => {
    setDateRange(value);
  }, [value])

  const { from, to, timezone, preset: selectedLabelId } = dateRange || {};

  const handleChange = useCallback((newRange, preset) => {
    const { from: newRangeFrom, to: newRangeTo, timezone: newRangeTz, source: newRangeSource } = newRange;
    const { id: labelId } = preset || {};
    const newDate = {
      ...newRange,
      preset: preset?.id || undefined
    }
    setDateRange(newDate);
    setOpen(false);

    const utcRangeFrom = newRangeFrom.toISOString();
    const utcRangeTo = newRangeTo.toISOString();

    dispatch(getDateSegment({
      attribute: (newRange.source).toLowerCase(),
      operator: "between_dates",
      value: {
        lower: utcRangeFrom,
        upper: utcRangeTo
      },
      tz: newRangeTz,
      labelId,
    }));

    dispatch(
      trackPageViews(null, {
        eventName: 'wa_update_calendar',
        track_type: 'event',
        eventProperty: {
          rolling_range: preset?.label,
          start_date: newRangeFrom,
          end_date: newRangeTo,
          timezone: newRangeTz,
          time_type: newRangeSource,
        },
      })
    )
    callListApi(null, 'Select date range');
  }, [callListApi, dispatch, ]);

  const fromDate = useMemo(() => getDisplayRangeDate(from, timezone), [from, timezone]);

  const toDate = useMemo(() => getDisplayRangeDate(to, timezone), [to, timezone]);

  const dateLabel = useMemo(() => datePresetsAbsolute.find(item => item.id === selectedLabelId), [selectedLabelId]);

  const btnLabel = useMemo(() => {
    if(open) {
      return `${fromDate} - ${toDate}`;
    }
    return dateLabel?.label || `${fromDate} - ${toDate}`},
  [open, dateLabel, fromDate, toDate])

  return (
    <Dropdown
      trigger={['click']}
      onVisibleChange={setOpen}
      visible={open}
      destroyPopupOnHide
      disabled={disabled}
      overlay={(
        <DateRangePicker
          enableSource
          minDate={ minDate }      
          onClose={handleClose}
          value={dateRange}
          onChange={handleChange}
          disablePopupContainer
        />
      )}
    >
      {typeof children === 'function' ? children({ btnLabel }) : children}
    </Dropdown>
  )
}

export default memo(CalendarDateRangePicker)
