/* eslint-disable no-lone-blocks */
import React from 'react';

// packages
import { Tabs, Menu } from 'antd';
import { SearchOutlined } from '@ant-design/icons';

// components
import CommonMapping from '../../MegaFilterDropdownV2/MainMenu/CommonMapping';

// styles
import {
    LabelOverlayWrapper, 
    HeaderContainer, 
    TabContainer, 
    TabWrapper, 
    StyledMenuWrapper,
    CustomLabelsSearchWrapper,
    CustomLabelsSearchInput,
    CustomLabelsSearchIcon,
} from './styles';

// types
import { TLabelsDropdownOverlay } from './types';

const { ItemGroup: MenuItemGroup } = Menu;

const TabsMenuItem:React.FC<TLabelsDropdownOverlay> = (props) => {
    const { 
        title,
        selectedKey,
        tabs,
        searchInput,
        handleTabChange,
        headerStyle,
        containerStyle,
        emptyMessage,
        ...rest
     } = props;

  return (
    <LabelOverlayWrapper style={containerStyle}>
      {title ? (
        <HeaderContainer style={headerStyle}>
          <span className='title'>{title}</span>
        </HeaderContainer>
      ) : null}

      {emptyMessage ? (
        <i className="empty-message">{emptyMessage}</i>
      ) : (
        <TabContainer
          onClick={(e) => {
            e.stopPropagation();
          }}
        >
          <TabWrapper
            centered
            defaultActiveKey={tabs[0]?.key || ''}
            moreIcon={null}
            onChange={handleTabChange}
            tabCount={tabs.length}
          >
            {tabs.map((tab) => {
              const { name, key, options, showSearch } = tab;
              return (
                <Tabs.TabPane tab={name} key={key}>
                  <StyledMenuWrapper hasTitle={showSearch}>
                    <MenuItemGroup
                      key={selectedKey}
                      title={
                        showSearch ? (
                          <CustomLabelsSearchWrapper>
                            {/* <CustomLabelsSearchIcon
                              src="/static/sessions/search.svg"
                              alt="Search icon"
                            /> */}
                            <CustomLabelsSearchIcon>
                                <SearchOutlined />
                            </CustomLabelsSearchIcon>
                            <CustomLabelsSearchInput
                              placeholder="Search labels"
                              // eslint-disable-next-line react/jsx-props-no-spreading
                              {...searchInput}
                            />
                          </CustomLabelsSearchWrapper>
                        ) : undefined
                      }
                    >
                      <CommonMapping
                        // eslint-disable-next-line react/jsx-props-no-spreading
                        {...rest}
                        listOfAttribute={options}
                        isArray={false}
                        category={selectedKey}
                        isCustomLabel
                      />
                    </MenuItemGroup>
                  </StyledMenuWrapper>
                </Tabs.TabPane>
              );
            })}
          </TabWrapper>
        </TabContainer>
      )}
    </LabelOverlayWrapper>
  );
}

export default TabsMenuItem;