import { useQuery, useMutation, useQueryClient } from 'react-query';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';
import omit from 'lodash/omit';
import appFilterApi from 'services/appFilterApi';
import { useMemo } from 'react';
import { rollbar } from 'components/common/rollbar';
import { AxiosResponse } from 'axios';
import { fetchPlanHatApi } from 'redux/actions/common';
import { trackPageViews } from 'redux/actions/trackingReport';
import { cloneDeep } from 'lodash';
import useAppFilter from '../../useAppFilter';
import { ISegment, ISegmentPayload, ISelectedSegment } from '../types';
import { SessionSegmentPages } from '../variables';

const useSegmentAPI = () => {

  const dispatch = useDispatch();
  const queryClient = useQueryClient();

  const { pageType } = useAppFilter();
  const { urlReducer: { appId, parentType } } = useSelector((state: RootStateOrAny) => state);

  const newPageType = useMemo(() => pageType === 'event' ? 'session' : pageType, [pageType]);
  const queryKey = useMemo(() => [`${newPageType}-filter-segments-list`, appId], [appId, newPageType]);

  const getSegmentList = async (filter: string) => appFilterApi.getSegmentListV2(appId, filter.split('-')[0])

  const { data: sessionSegmentList } = useQuery(queryKey, () => getSegmentList('session-filter'),
    {
      enabled: !!appId && SessionSegmentPages.includes(parentType),
      retry: false
    }
  )

  const { data: userSegmentList } = useQuery(queryKey, () => getSegmentList('user-filter'),
    {
      enabled: !!appId && parentType === 'usersList',
      retry: false
    }
  )
  
  const segmentList = useMemo(() => newPageType === 'user' ? cloneDeep(userSegmentList?.data?.data) : cloneDeep(sessionSegmentList?.data?.data), [newPageType, sessionSegmentList?.data?.data, userSegmentList?.data?.data]);

  const addSegment = async (addedData: ISelectedSegment): Promise<ISegment> => {
    const response = await appFilterApi.saveSegments(appId, addedData, newPageType, true);
    return response.data.data[0];
  };

  const updateSegment = async (updatedData: ISegmentPayload): Promise<ISegment> => {
    const { id } = updatedData;
    const payload = omit(updatedData, 'id');
    const response = await appFilterApi.editSegments(appId, payload, newPageType, id);
    return response.data.data[0];
  };

  const deleteSegment = async (id: string) => {
    await appFilterApi.deleteSaveSegment(appId, id, newPageType, true);
    return id;
  };

  const trackEvents = (responseData: ISegment) => {
    dispatch(
      fetchPlanHatApi({
        action: `Created ${newPageType} segment`,
        info: {
          'segment name': responseData.name,
          description: 'when they create a new segment',
        },
      })
    );
    dispatch(
      trackPageViews(null, {
        eventName: 'create_segment',
        track_type: 'event',
        eventProperty: responseData,
      })
    );
  }

  const invalidateQueries = () => {
    queryClient.invalidateQueries( { queryKey } )
  }

  const addSegmentMutation = useMutation({
    mutationFn: (addedData: ISegmentPayload) => addSegment(addedData),
    onSuccess: (responseData: ISegment) => {
      trackEvents(responseData);
      const previousValue = queryClient.getQueryData(queryKey) as AxiosResponse;

      if (previousValue) {
        const newData = {
          ...previousValue,
          data: {
            ...previousValue.data,
            data: [...cloneDeep(previousValue.data.data), cloneDeep(responseData)]
          }
        }
        queryClient.setQueryData(queryKey, newData);
      }
    },
    onError: (error: Error) => {
      rollbar.error('error', error)
    },
  });

  const updateSegmentMutation = useMutation({
    mutationFn: (updatedData: ISegmentPayload) => updateSegment(updatedData),
    onSuccess: (responseData: ISegment) => {
      const { isDefault, id, previousId } = responseData;
      const segmentId = isDefault && id !== previousId ? previousId :  id;
      const previousValue = queryClient.getQueryData(queryKey) as AxiosResponse
      if (previousValue) {
        const updateSegments = cloneDeep(previousValue.data.data as ISegment[]).map(item =>
          item.id === segmentId ? cloneDeep(responseData) : item);
        const newData = {
          ...previousValue,
          data: {
            ...previousValue.data,
            data: updateSegments
          }
        }
        queryClient.setQueryData(queryKey, newData);
      }
    },
    onError: (error: Error) => {
      rollbar.error(error);
    },
  });

  const deleteSegmentMutation = useMutation({
    mutationFn: (id: string) => deleteSegment(id),
    onSuccess: (responseId: string) => {
      const previousValue = queryClient.getQueryData(queryKey) as AxiosResponse;
      if (previousValue) {
        const updateSegments = cloneDeep(previousValue.data.data as ISegment[]).filter(item => item.id !== responseId);
        const newData = {
          ...previousValue,
          data: {
            ...previousValue.data,
            data: updateSegments
          }
        }
        queryClient.setQueryData(queryKey, newData);
      }
    },
    onError: (error: Error) => {
      rollbar.error(error);
    },
  });

  return {
    segmentList,
    addSegment: addSegmentMutation.mutateAsync,
    updateSegment: updateSegmentMutation.mutateAsync,
    deleteSegment: deleteSegmentMutation.mutateAsync,
    invalidateQueries,
  };
};

export default useSegmentAPI;