import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import { useFloatingToolbarContext } from 'components/IntegratePages/layout/FloatingToolbar/context'
import { useAISessionUtils } from 'components/shared/GlobalFilter/components/aiSessionFilter/AISessionUtilsContext'
import useGetRole from 'hooks/useGetRole'
import React, { useEffect } from 'react'
import styled from 'styled-components'
import { UFCTooltip } from 'uxcam-frontend-components'
import { useDispatch } from 'react-redux'
import { trackSelectSessions } from 'components/features/aiSessions/components/utils'

const Container = styled.div`
	width: 100%;
	height: 100%;
	display: flex;
	justify-content: space-between;
	align-items: center;
`

const Title = styled.div`
	font-family: Roboto;
	font-weight: 400;
	font-size: 13px;
	line-height: 13px;
	color: rgba(255, 255, 255, 1);

	strong {
		font-weight: 600;
	}
`

const WatchButton = styled.button`
	position: relative;
	display: flex;
	align-items: center;
	justify-content: center;
	gap: 2px;
	padding: 7px 8px;
	background: rgba(255, 255, 255, 0.05);
	border: 1.5px solid transparent;
	border-radius: 6px;
	font-family: Roboto;
	font-weight: 500;
	font-size: 12px;
	line-height: normal;
	color: #ffffff;
	cursor: pointer;
	transition: all 0.2s ease-in-out;
	background-clip: padding-box;

	&::before {
		content: '';
		position: absolute;
		top: 0;
		left: 0;
		right: 0;
		bottom: 0;
		border-radius: 6px;
		padding: 1.5px;
		background: linear-gradient(189deg, rgba(238, 94, 221, 0.8) 0%, rgba(73, 197, 255, 0.5) 100%);
		-webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
		-webkit-mask-composite: xor;
		mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
		mask-composite: exclude;
		pointer-events: none;
	}

	&:hover {
		background: rgba(255, 255, 255, 0.1);
	}

	&:active {
		background: rgba(255, 255, 255, 0.15);
	}

	&:disabled {
		opacity: 0.5;
		cursor: not-allowed;
	}
`

const SelectedToolbarContent = () => {
	const { setBatchModalVisible, selected, setSelected, upgradeVariant, setUpgradeModalVisible } = useAISessionWatchlist()
	const { setRowSelection } = useAISessionUtils()
	const { setOnClose } = useFloatingToolbarContext()
	const { isRole } = useGetRole()
	const isViewer = isRole( 'viewer' )
	const dispatch = useDispatch()

	const handleButtonClick = () => {
		if ( upgradeVariant ) {
			setUpgradeModalVisible( true )
			return
		}
		
		dispatch(trackSelectSessions())
		setBatchModalVisible( true )
	}

	useEffect(() => {
		setOnClose(() => () => {
			setSelected( [] )
			setRowSelection( [] )
		})
		return () => {
			setOnClose(null)
		}
	}, [setOnClose, setSelected, setRowSelection])

	return (
		<Container>
			<Title>
				<strong>
					{`${ selected?.length } session${ selected?.length > 1 ? 's' : '' }`}
				</strong>
				{' '}
				selected
			</Title>
			<UFCTooltip title={ isViewer ? 'You don\'t have permission to analyze more sessions' : undefined } align={{offset:[0, -4]}}>
				<WatchButton type="button" onClick={ handleButtonClick } disabled={ isViewer }>
					{ upgradeVariant ? 'Upgrade to watch selected' : 'Watch selected' }
				</WatchButton>
			</UFCTooltip>
		</Container>
	)
}

export default SelectedToolbarContent