const SunBurstGraph = memo(({ chartRef }) => {
  const { parentType } = useSelector((state) => state.urlReducer);
  const { sunburstPlotGraph } = useSelector((state) => state.screenDetailReducer);
  const dispatch = useDispatch();
  const handler = useCallback(
    (e) => {
      dispatch(
        trackPageViews(null, {
          eventName: 'click_on_chart',
          track_type: 'event',
          eventProperty: {
            page: 'app navigation',
            screenname: e.target.textContent,
            description: 'User clicks on a screen of the screen burst char',
          },
        })
      );
      if (e.target.className === 'btn  view-session') {
        dispatch(
          trackPageViews(null, {
            eventName: 'click_on_view_sessions',
            track_type: 'event',
            eventProperty: {
              page: 'app navigation',
              screenname: e.target.id,
              description: 'User clicks on view sessions',
            },
          })
        );
      }
      if (e.target.className === 'btn funnel-tooltip-toggle ') {
        dispatch(
          trackPageViews(null, {
            eventName: 'sb_clicked_on_create_funnel',
            track_type: 'event',
            eventProperty: {
              page: 'app navigation',
              screenname: e.target.id,
              description: 'User clicks on create funnel',
            },
          })
        );
      }
    },
    [dispatch]
  );

  const containerProps = useMemo(
    () => ({
      className:
        parentType === 'usersList'
          ? 'sun-burst-chart-user'
          : 'sun-burst-chart',
    }),
    [parentType]
  );
  useEventListener('click', handler);
  const { graphOptions: options, chartDataRef } = useGraphOptions();
  useEffect(() => {
    if (options && chartDataRef.current) {
      chartDataRef.current?.update({
        series: [{
          ...options.series[0],
          data: [...sunburstPlotGraph],
        }],
      });
    }
  }, [chartDataRef, options, sunburstPlotGraph]);
  const showMoreDetails = (H, point) => {
    const drillId = point && point.drillId;
    if (drillId) {
      point.setState(''); // Remove hover
      point.series.setRootNode(drillId, true, { trigger: 'click' });
      dispatch(
        trackPageViews(null, {
          eventName: 'sb_clicked_on_drill_down',
          track_type: 'event',
          eventProperty: {
            page: 'app navigation',
            description: 'User clicks on drill down',
          },
        })
      );
    }
  }
   ((H) => {
    H.wrap(H.Tooltip.prototype, 'refresh', function (proceed, point) {
      proceed.apply(this, Array.prototype.slice.call(arguments, 1));
      // eslint-disable-next-line react/no-this-in-sfc
      const button =
        this.label && this.label?.div?.querySelector("button[class='btn']");
      if (button && !button.addedEvent) {
        button.addEventListener('click', () => showMoreDetails(H, point));
        button.addedEvent = true;
      }
    });
  })(Highcharts);
  return (
    options ? <HighchartsReact
      ref={chartRef}
      highcharts={Highcharts}
      options={options}
      containerProps={containerProps}
    /> : (
        <ReactLoader fullscreen={true} />
    )
  );
});
export default SunBurstGraph;
