import React from "react";
import { connect } from "react-redux";
import {
  QuestionCircleOutlined,
  ShareAltOutlined,
} from "@ant-design/icons";
import { Modal, Button, Input, Checkbox, Tooltip, message } from "antd";
import { isEmpty } from 'underscore'
import { ReactMultiEmail } from "react-multi-email";
import { CopyToClipboard } from "react-copy-to-clipboard";
import { timeFormatToSecond } from "Utils/helpers/commonUtils";

import { shareSession, getShareSessionLink, fetchPlanHatApi } from "redux/actions/common";
import { trackPageViews } from 'redux/actions/trackingReport';

const matchRegex = /^(?:(?:([01]?\d|2[0-3]):)?([0-5]?\d):)([0-5][0-9]?\d)$/;

const InputGroup = Input.Group;
const { TextArea } = Input;
class ShareSession extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      visible: false,
      checkedList: true,
      emails: [],
      privateMessage: "",
      loading: false,
      shareLoading: false,
      publicUrl: "",
      privateUrl: "",
      playerTime: -1,
      displayedPlayerTime: "",
      isValidTime: true,
      videoTime: "",
      videoDuration: 0
    };
  }

  showModal = async () => {
    let publicUrl = '';
    let privateUrl = '';
    this.setState({ shareLoading: true });
    let shareSessionLink = await this.props.getShareSessionLink(
      this.props.urlQuery.appId,
      this.props.shareMultiple
        ? this.props.selectedSession
        : [this.props.urlQuery.sessionid]
    );
    if (shareSessionLink.status === 200) {
      publicUrl = shareSessionLink.data.data?.publicUrl?.join("\n");
      privateUrl = shareSessionLink.data.data.privateUrl.join("\n");
    }
    this.setState({
      publicUrl: publicUrl,
      privateUrl: privateUrl,
      shareLoading: false,
      visible: true,
      emails: [],
      privateMessage: "",
      loading: false,
      playerTime: undefined,
      displayedPlayerTime: undefined,
    }, () => {
      this.props.urlQuery?.parentType === 'screensList' &&
      this.props.trackPageViews(null, {
        eventName: 'hm_open_session_sharing_dialog',
          track_type: 'event',
          eventProperty: {
          screenname: this.props.urlQuery?.screenname,
          sessionid: this.props.urlQuery?.sessionid,
          },
      });
    });
  };

  handleOk = async (e) => {
    this.setState({ loading: true });
    let data = {
      sessions: this.props.shareMultiple
        ? this.props.selectedSession
        : [this.props.urlQuery.sessionid],
      appId: this.props.urlQuery.appId,
      privateMessage: this.state.privateMessage,
      email: this.state.emails,
      isPublic: this.state.publicUrl && this.state.checkedList,
      ...this.state.playerTime > 0 && {viewTime: this.state.playerTime},
    };
    let callShareSession = await this.props.shareSession(data);

    if (callShareSession.data) {
      message.success("Session successfully shared.");
      this.setState({ visible: false, loading: false });
    } else {
      this.setState({ loading: false });
      message.error(callShareSession.response.data.error.message);
    }
    this.props.fetchPlanHatApi({ action: 'Shared session', info: { method: 'email' } })
    this.props.trackPageViews(null, {
      eventName: 'hm_share_session',
        track_type: 'event',
        eventProperty: {
        screenname: this.props.urlQuery?.screenname,
        sessionid: this.props.urlQuery?.sessionid,
        'added emails': this.state.emails,
        },
       });
  };

  handleCancel = () => {
    this.setState({
      displayedPlayerTime: "",
      isValidTime: true,
      checkedList: true,
    }, () => {
      this.setState({ visible: false });
    });
  };

  onChange = (e) => {
    this.setState({ checkedList: e.target.checked });
  };


  isValidTime = (enteredTime, videoTime) => {
    const { videoDuration } = this.state;
    const { starttime, sessionid } = this.props.urlQuery;
    const { body: detailTable } = this.props.issueDetailTable
    const findSelectedIssue = detailTable && detailTable?.length && detailTable.find((data)=> data?.sessionid === sessionid && data.timeOfIncidence  === +starttime )
    const urlTime = timeFormatToSecond(Math.floor(findSelectedIssue?.sessionDuration || 0));
    if (matchRegex.test(enteredTime) || !Number.isNaN(enteredTime)) {
      return videoTime <= videoDuration || videoTime <= urlTime
    }
    return false;
  }

  handleTimeChange = (e) => {
    const initialTime = isEmpty(e.target.value) ? "" : e.target.value;
    let validTime = false;
    this.setState({ displayedPlayerTime: initialTime }, () => {
      if (initialTime !== "") {
        const time = timeFormatToSecond(initialTime);
        validTime = this.isValidTime(initialTime, time);
        this.setState({ playerTime: time, isValidTime: validTime});
      } else {
        this.setState({ playerTime: -1, isValidTime: true });
      }
    });
  };

  copy = (e) => {
    e.stopPropagation();
    e.preventDefault();
    message.success("Sessions link has been copied.");
    this.props.fetchPlanHatApi({ action: 'Shared session', info: { method: 'link' } })
    this.props.trackPageViews(null, {
      eventName: 'hm_share_session', track_type: 'event', eventProperty: {
        screenname: this.props.urlQuery?.screenname,
        sessionid: this.props.urlQuery?.sessionid,},
    });
    this.handleCancel();
  };

  handlePrivateMessage = (e) => {
    let { value } = e.target;
    this.setState({ privateMessage: value });
  };

  getUrl = (url, time) => {
    return this.props.shareMultiple ? url : time > 0 ? `${url}/${time}` : url;
  };


  render() {
    const {
      playerTime,
      isValidTime,
      visible,
      emails,
      loading,
      shareLoading,
      publicUrl,
      privateUrl,
      checkedList,
      privateMessage,
      displayedPlayerTime,
    } = this.state;

    const { shareMultiple, selectedSession } = this.props;
    const TextBox = (
      <TextArea
        style={{
          padding: "15px",
          fontSize: "12px",
          color: "#868EA1",
        }}
        placeholder="Add personal message (optional)"
        autoSize={{ minRows: 3, maxRows: 4 }}
        value={privateMessage}
        onChange={this.handlePrivateMessage}
      />
    );

    let title = shareMultiple
      ? selectedSession.length > 1
        ? "Share selected sessions"
        : "Share selected session"
      : "Share selected session";

    return (
      <span>
        {shareMultiple ? (
          <Button
            icon={<ShareAltOutlined />}
            onClick={this.showModal}
            loading={shareLoading}
          >
            Share
          </Button>
        ) : (
          <Tooltip title="Share session" >
            <Button
              icon={<ShareAltOutlined />}
              shape="circle"
              onClick={this.showModal}
            />
          </Tooltip>
        )}

        <Modal
          wrapClassName='shared-session-modal'
          title={title}
          visible={visible}
          onOk={this.handleOk}
          onCancel={this.handleCancel}
          centered
          footer={[
            <Button
              key="submit"
              type="primary"
              disabled={!isValidTime || emails?.length === 0 || loading}
              loading={loading}
              onClick={this.handleOk}
            >
              Share
            </Button>,
            <Button key="back" type="secondary" onClick={this.handleCancel}>
            Cancel
          </Button>,
          ]}
        >
          <div className="email-invite-box">
            <div className={`checkbox-wrap ${!publicUrl ? 'public-disable' : ''}`} >
              {publicUrl && <span>
              <Tooltip
                placement="topLeft"
                title="Check the box to toggle between public and private link"
                overlayStyle={{ zIndex: "999999" }}
                arrowPointAtCenter
              >
                <Checkbox
                  onChange={this.onChange}
                  checked={checkedList}
                ></Checkbox>
              </Tooltip>{" "}
              <span>Generate public link{" "}</span>
              <Tooltip
                title="Check this box only if you also want to make the session replay accessible to people who don’t have access to your app’s UXCam account."
                overlayStyle={{ zIndex: "999999" }}
              >
                <QuestionCircleOutlined />
              </Tooltip>
              </span>}
              
              {!shareMultiple && (
                <span>
                  {/* we will use this later <Checkbox
                    onChange={this.playerTimeCheckedChange}
                    checked={playerTimeChecked}
                  ></Checkbox> */}
                  Starts at:
                  <Input
                    placeholder="00:00"
                    value={displayedPlayerTime}
                    onChange={this.handleTimeChange}
                  />
                  {!isValidTime &&<span className='invalid-time-message'>Please enter valid time</span>}
                </span>
              )}
              <CopyToClipboard
                text={
                  checkedList && publicUrl
                    ? this.getUrl(publicUrl, playerTime)
                    : this.getUrl(privateUrl, playerTime)
                }
                onCopy={() => {}}
              >
                <Button
                  disabled={!isValidTime}
                  onClick={(e) => this.copy(e)}
                  size="small"
                  className='copy-link-btn'
                >
                  Copy link
                </Button>
              </CopyToClipboard>
            </div>
            <p
              style={{
                marginBottom: "5px",
                fontSize: "12px",
              }}
            >
              Enter comma separated emails to share session
              {shareMultiple
                ? selectedSession.length > 1
                  ? "s"
                  : ""
                : ""}{" "}
              with multiple recipients
            </p>
            <InputGroup style={{ marginBottom: "20px" }}>
              <ReactMultiEmail
                style={{ fontSize: "12px" }}
                placeholder="Enter email address"
                emails={this.state.emails}
                onChange={(_emails) => {
                  this.setState({ emails: _emails });
                }}
                getLabel={(email, index, removeEmail) => {
                  return (
                    <div data-tag key={index}>
                      {email}
                      <span data-tag-handle onClick={() => removeEmail(index)}>
                        ×
                      </span>
                    </div>
                  );
                }}
              />
            </InputGroup>
            <p
              style={{
                marginBottom: "5px",
                fontSize: "12px",
              }}
            >
              Let your recipient know what's interesting about this shared
              session
              {shareMultiple ? (selectedSession.length > 1 ? "s" : "") : ""}
            </p>
          </div>
          {TextBox}
        </Modal>
        <style>{`
          .shareSession span a{
            color:rgba(0,0,0,.65)
          }
          .react-multi-email.focused{
            border-color: #5D97FF;
          }
          .email-invite-box p{
            font-weight: 400;
          }
          .checkbox-wrap{
            margin-bottom: 30px;
            color: #161E35;
            font-weight: 400;
          }
          .checkbox-wrap .ant-checkbox-wrapper{
            margin-right: 0;
            color: #161E35;
            font-weight: 500;
          }
          .react-multi-email > input{
            width: 100% !important;
          }
          .ant-modal .ant-modal-footer .ant-btn{
            height: 32px;
            line-height: 0;
          }
          .ant-modal .ant-modal-footer .ant-btn.ant-btn-primary{
            font-weight: 600;
          }
              `}</style>
      </span>
    );
  }
}

function mapStateToProps(state) {
  return {
    currentApp: state.currentAppReducer,
    selectedSession: state.selectedSessionReducer,
    urlQuery: state.urlReducer,
    issueDetailTable : state.issueDetailTableReducer
  };
}

export default connect(mapStateToProps, { shareSession, getShareSessionLink, fetchPlanHatApi, trackPageViews })(
  ShareSession
);
