import React, { useState, createContext, useContext, useMemo } from 'react';

const AppNavigationContext = createContext(null);

const AppNavigationContextProvider = ({ children }) => {
  const [flagCogDrop, setFlagCogDrop] = useState(false);
  const [inverted, setInverted] = useState(false);
  const value = useMemo(
    () => ({
      flagCogDrop,
      setFlagCogDrop,
      inverted,
      setInverted
    }),
    [flagCogDrop, inverted]
  );
  return (
    <AppNavigationContext.Provider value={value}>
      {children}
    </AppNavigationContext.Provider>
  );
};

const useAppNavigationContextContext = () => useContext(AppNavigationContext);

export { AppNavigationContextProvider, useAppNavigationContextContext };
