import React, { memo } from 'react';
import { Select, Tooltip } from 'antd';
import { operator } from 'components/shared/GlobalFilter/components/data-structures-v2';
import { useAppliedFilterContext } from 'components/shared/GlobalFilter/context/AppliedFilterContext';
import styled from 'styled-components';

const CustomSelect = styled(Select)`
  &.ant-select-disabled .ant-select-selector {
    background-color: #fff !important;
    color: #161E35 !important;
  }
`;

export const EventOperator = memo(({ handleEventOperatorChange, eventOperator, attribute }) => {
  const { viewOnly, disabledFilterMessage } = useAppliedFilterContext();
  return (
   <Tooltip title={disabledFilterMessage}>
    <CustomSelect
        onChange={handleEventOperatorChange}
        value={eventOperator}
        dropdownClassName="filter-event-dropdown"
        disabled={viewOnly}
    >
        {[
        { key: 'in', title: `With ${attribute === 'nce_name' ? 'smart' : ''} events` },
        { key: 'not_in', title: `Without ${attribute === 'nce_name' ? 'smart' : ''} events` },
        ].map((value) => (
        <Select.Option key={value.key}>{value.title}</Select.Option>
        ))}
    </CustomSelect>
    </Tooltip>
    )
});

export const ActivityFilterEventOperator = memo(({ handleActivityFilterEventOperatorChange, eventOperator, title }) => (
    <>
     <span>{title}</span>
     <span>
        <Select
            onChange={handleActivityFilterEventOperatorChange}
            value={eventOperator}
            width='100px'
            dropdownClassName="filter-event-dropdown"
            style={{marginLeft: '5px'}}
        >
            {operator.event_name_json.map((value) => (
            <Select.Option key={value.attribute}>{value.title}</Select.Option>
            ))}
        </Select>
    </span>
  </>
));
