import { useMemo } from "react"
import Cookies from "universal-cookie"

const useIsLoggedInAdmin = (): {
	isLoggedInFromAdmin: boolean
	isLoggedInAsAdminAdmin: boolean
	isLoggedInAsAdminGuest: boolean
} => {
	const browserCookies = useMemo( () => new Cookies(), [] )
	
	const isLoggedInFromAdmin = useMemo( () => {
		try {
			return !!parseInt(browserCookies.get('loggedInFromAdminDashboard'), 10) || false
		} catch (error) {
			return false
		}
	}, [browserCookies])

	const isLoggedInAsAdminGuest = useMemo(() => {
		return isLoggedInFromAdmin && browserCookies.get('loggedInType') === 'guest'
	}, [isLoggedInFromAdmin, browserCookies])

	const isLoggedInAsAdminAdmin = useMemo(() => {
		return isLoggedInFromAdmin && browserCookies.get('loggedInType') === 'admin'
	}, [isLoggedInFromAdmin, browserCookies])

	return {
		isLoggedInFromAdmin,
		isLoggedInAsAdminAdmin,
		isLoggedInAsAdminGuest,
	}
}

export default useIsLoggedInAdmin