import React, { useMemo, memo } from 'react';
import { Tooltip } from 'antd';
import { useSelector } from 'react-redux';

const ScreenTooltip = ({ onRenderScreen, originalScreenName }) => {
  const screenRenamedList = useSelector((state) => state.screenRenamedList);
  const renamedScreenName = screenRenamedList[originalScreenName];
  const screen = renamedScreenName || originalScreenName;
  const title = useMemo(() => {
    let screenTitle;
    if (renamedScreenName)
      screenTitle = (
        <span>
          <strong>Screen name:</strong>
          <br /> {renamedScreenName} <br />
          <strong>Original screen name:</strong>
          <br />
          {originalScreenName}
        </span>
      );
    else if (screen.length > 20) screenTitle = <span>{screen}</span>;
    return screenTitle;
  }, [renamedScreenName, originalScreenName, screen]);
  return <Tooltip title={title} placement='topLeft'>{onRenderScreen(screen)}</Tooltip>;
};
export default memo(ScreenTooltip);
