/* eslint-disable react-hooks/exhaustive-deps */
import React, { useMemo, memo, useCallback, useState, useEffect } from 'react';
import { InfoCircleOutlined } from '@ant-design/icons';
import { Tooltip, Select } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import styled from 'styled-components';
import debounce from 'lodash/debounce';
import ScreenTooltip from 'components/common/ScreenTooltip';
import { useIsAppType } from 'hooks/useIsAppType';
import { useAppText } from 'Utils/helpers/commonUtils';
import { getSearchAttrRemoteData } from 'redux/actions/filter';
import { getScreenPayload } from '../index';

const SelectWrapper = styled(Select)`
  width: 145px;
  .ant-select-selector {
    border: 0 !important;
  }
`;

const ScreenDropdown = memo((props) => {
  const { initOption, onChangeHandler, value, screenList, isFetching, isLoading } = props;
  const dispatch = useDispatch();
  const { dateSegment } = useSelector(state => state.appFilter);
  const [searchValue, setSearchValue] = useState('');
  const [searchLoading, setSearchLoading] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const isWebApp = useIsAppType('web');

  const { dropdownLaunchText: launchText, exitText } = useAppText();

  const appClosedMsg = isWebApp
    ? `Pick the final step to explore all paths leading to it, or select '${exitText}' for the entire journey.`
    : `Select the final screen of the screen flow sequence you want to analyze, or choose "${exitText}" to see the sequence all the way until the app is closed.`;
  const appLaunchMsg = isWebApp
    ? `Pick the first step to explore all paths starting from it, or select '${launchText}' for the entire journey. `
    : `Select the initial screen of the screen flow sequence you want to analyze, or choose "${launchText}" to see the sequence from the app start.`;

  const tooltipMessage = useMemo(
    () =>
      (initOption === 'App Closed' || initOption === exitText ? appClosedMsg : appLaunchMsg),
    [appClosedMsg, appLaunchMsg, exitText, initOption]
  );
  const labelPrefixText = useMemo(
    () => (initOption === 'App Closed' || initOption === exitText ? 'End' : 'Start'),
    [exitText, initOption]
  );
  const {
    screenRenamedList: renamedList,
    currentOrgReducer: { planFeature },
    urlReducer: { appId },
  } = useSelector(({ urlReducer, appFilter, screenRenamedList, currentOrgReducer }) => ({
    urlReducer,
    appFilter,
    screenRenamedList,
    currentOrgReducer
  }));
  const disabled = planFeature?.screenFlow === 0;
  
  // Local state to hold the displayed list of screens.
  const [displayedScreenList, setDisplayedScreenList] = useState(screenList || []);
  
  // Whenever the core screenList prop changes, update the displayed list.
  useEffect(() => {
    setDisplayedScreenList(screenList || []);
  }, [screenList]);
  
  // Combine initOption with the displayed list for rendering.
  const screensList = useMemo(() => {
    if (!searchValue) {
      // When there's no filter, place initOption at the top.
      return [initOption, ...(displayedScreenList || [])];
    }
    // When filtering, just use the filtered list.
    return displayedScreenList || [];
  }, [initOption, displayedScreenList, searchValue]);
  

  const loading = isFetching || isLoading;
  const optionsRender = useMemo(
    () =>
      screensList.map((v) => ({
        label: (
          <ScreenTooltip
            onRenderScreen={(screen) => renamedList[screen] || screen}
            originalScreenName={v}
          />
        ),
        value: v,
      })),
    [screensList]
  );

  // Decide if the original list is large (for local filtering purposes)
  const isLargeScreenList = useMemo(() => screenList && screenList.length > 500, [screenList, appId]);

  // Debounced search: on non-empty input, call the new remote API and update state.
  const debouncedSearch = useMemo(
    () =>
      debounce(async (input) => {
        if (input.length > 0 && isLargeScreenList) {
          setSearchLoading(true);
          try {
            const data = await dispatch(getSearchAttrRemoteData(getScreenPayload(dateSegment, input)));
            // Update the local displayed list with the remote results.
            setDisplayedScreenList(data);
          } catch (error) {
            console.error('Remote search error:', error);
          } finally {
            setSearchLoading(false);
          }
        } else {
          // If input is empty, reset to the original list.
          setDisplayedScreenList(screenList || []);
        }
      }, 500),
    [dateSegment, screenList, isLargeScreenList]
  );
  
  const resetSearchData = useCallback(() => {
    debouncedSearch.cancel();
    setSearchValue('');
    setDisplayedScreenList(screenList || []);
  }, [debouncedSearch, screenList]);
  
  const handleSearch = useCallback(
    (input) => {
      setSearchValue(input);
      debouncedSearch(input);
    },
    [debouncedSearch]
  );
  
  useEffect(() => {
    return () => {
      debouncedSearch.cancel();
    };
  }, [debouncedSearch]);

  const handleFilter = useCallback(
    (input, option) => {
      if (isLargeScreenList) {
        // For large lists, assume remote API handles filtering.
        return true;
      }
      // For smaller lists, filter locally.
      const screenOption = renamedList[option.value] || option.value;
      return screenOption.toLowerCase().includes(input.toLowerCase());
    },
    [renamedList, isLargeScreenList]
  );

  const handleDropdownVisibleChange = useCallback(
    (open) => {
      setDropdownOpen(open);
      if (!open) {
        // Reset search data when dropdown closes.
        resetSearchData();
      }
    },
    [resetSearchData]
  );

  return (
    <div className="filter-item" data-intercom-target={labelPrefixText}>
      <div className="combo-box">
        <strong>{labelPrefixText} With</strong>
        <SelectWrapper
          disabled={disabled}
          showSearch
          value={{ value, label: renamedList[value] || value }} // Pass both value and label
          defaultValue={{ value: initOption, label: renamedList[initOption] || initOption }}
          onSelect={(selected) => onChangeHandler(selected.value)} // Extract value on select
          loading={loading || searchLoading}
          dropdownClassName="screen-navigate-select-dropdown"
          className="filter-item-select-search"
          filterOption={handleFilter}
          options={optionsRender}
          dropdownStyle={{ minWidth: isWebApp ? '698px' : 'auto' }}
          onSearch={handleSearch}
          onDropdownVisibleChange={handleDropdownVisibleChange}
          open={dropdownOpen}
          labelInValue
        />
      </div>
      <Tooltip title={tooltipMessage}>
        <InfoCircleOutlined />
      </Tooltip>
    </div>
  );
});

export default ScreenDropdown;
