import React, { memo, useCallback } from 'react'
import { useSelector } from 'react-redux'
import findIndex from 'lodash/findIndex'
import { Menu } from 'antd'
import { operator } from 'components/shared/GlobalFilter/components/data-structures-v2'
import { singleValueType } from 'components/shared/GlobalFilter/components/utils'
import MenuHeader from './MenuHeader'
import MenuBody from './MenuBody'

const MenuItemGroup = Menu.ItemGroup;
const ThirdLevelMenu = memo((props) => {
  const {
    callApi,
    onVisibleChange,
    resetCategorySelect,
    pageType,
    handleOperatorSelect,
    selectedOperator,
  } = props
  const { selectedAttributeProps } = useSelector(
    (state) => state.megaFilterReducer
  )
  const { type: operatorType, propertyName, attribute } = selectedAttributeProps || {}
  const isOperatorRadio = singleValueType.includes(
    operatorType
  )
  const handleOperatorMenuClick = useCallback((itemProps, customOperatorType) => {
    const index = findIndex(operator[customOperatorType || operatorType], {
      attribute: itemProps.key,
    })
    handleOperatorSelect(index, customOperatorType)
  }, [handleOperatorSelect, operatorType])
  return (
    <MenuItemGroup
      key="menu-3rd-level"
      className="menu-item-column menu-filter menu-3rd-level"
    >
      <MenuHeader
        isOperatorRadio={isOperatorRadio}
        handleOperatorMenuClick={handleOperatorMenuClick}
        selectedOperator={selectedOperator}
        onVisibleChange={onVisibleChange}
      />
      {selectedOperator.attribute && (
        <MenuBody
          isOperatorRadio={isOperatorRadio}
          handleOperatorMenuClick={handleOperatorMenuClick}
          onVisibleChange={onVisibleChange}
          resetCategorySelect={resetCategorySelect}
          callApi={callApi}
          key={propertyName || attribute}
          pageType={pageType}
          selectedOperator={selectedOperator}
        />
      )}
    </MenuItemGroup>
  )
})
export default ThirdLevelMenu
