import React, { memo } from 'react';
import { Button } from 'antd';
import styled from 'styled-components';

const ButtonWrapper = styled.div`
  display: flex;
  justify-content: flex-end;
`

const NewButton = styled( Button )`
  border: none !important;
  &:hover {
    background-color: none;
  }
  &:disabled > span {
    color: #828282 !important;
  }
`
const NewButtonPrimary = styled( NewButton )`
  > span {
    color: #ffffff !important;
  }
  &:hover {
    background-color: #4A79CB;
  }
  &:disabled > span {
    color: #828282 !important;
  }
`

const MenuFooter = memo(({
  handleApplyGrouping,
  disabled,
  resetFields,
  onVisibleChange,
  resetCategorySelect,
}) => (
    <ButtonWrapper key="button-bar" className='button-bar'>
      <NewButton
        type='primary-outline'
        onClick={() => {
          resetFields()
          resetCategorySelect()
          onVisibleChange(false)
        }}
      >
        Cancel
      </NewButton>
      <NewButtonPrimary disabled={disabled} type='primary' onClick={handleApplyGrouping}>
        Apply
      </NewButtonPrimary>
    </ButtonWrapper>
  ))
export default MenuFooter
