
import React, { memo, useCallback, useMemo } from 'react'
import { Menu } from 'antd'
import styled, { createGlobalStyle } from 'styled-components'
import Lock from 'public/static/lock-features/lock.svg'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import { RightOutlined } from '@ant-design/icons';
import { useIsAppType } from 'hooks/useIsAppType'
import { useGetAvailableActivityFilters, useIsUserV2 } from 'hooks/useUserV2Filter'
import { isArray } from 'lodash'
import useHasSmartEvents from 'hooks/useHasSmartEvents'
import { categoriesExtra } from '../../data-structures-v2';
import { groupLabelsByCategory } from './utils'

const GlobalStyles = createGlobalStyle`
  .mega-filter {
    .ant-dropdown-menu-item.locked .ant-dropdown-menu-title-content, .ant-dropdown-menu-item.locked .ant-dropdown-menu-title-content > span {
      color: #A2A5AE;
      font-weight: 400;
      cursor: not-allowed;
      &:hover {
        color: #A2A5AE;
      }
    }
  }
`
  
const StyledMenuCategory = styled.div`
  color: #161E35;
  .menu-category-title {
        font-size: 13px;
        font-weight: 500;
        color: #161E35;
        padding: 5px 8px;
        margin-bottom: 0px !important;
    }
    .menu-category-block {
        padding: 0 8px;
    }
  `

export const MenuItem = Menu.Item;
export const MenuItemGroup = Menu.ItemGroup;
const excludedAdditionalList = {
  session: ['Event properties', 'User Labels', 'Date Range', 'Custom screen properties'],
  event: ['Events', 'User Labels', 'Date Range', 'Screen visit properties'],
  user: ['Event properties', 'Session Labels', 'Date Range', 'Custom screen properties'],
  screenFlow: ['Event properties', 'User Labels', 'Date Range', 'Custom screen properties'],
  issue: ['Event properties', 'User Labels', 'Date Range'],
  heatmap: ['Event properties', 'User Labels', 'Date Range', 'Events', 'Screen visit properties'],
}

const SpanItemWrap = styled.span`
  display: flex;
  justify-content: space-between;
  align-items: center;
`
const CategorizedMenu = ({
    categoriesFiltered,
    selectedKey,
    advancedFiltersAllowed,
    allowedCategoriesInFreePlan,
    titleOverride
}) => {

return  <MenuItemGroup>
        <>
            {categoriesFiltered.map((v) => {
                const locked = !advancedFiltersAllowed ? !allowedCategoriesInFreePlan.includes(v) : false
                return <MenuItem
                    dropdownId="isFirstLevel"
                    key={v}
                    className={` ${v === selectedKey ? 'selected' : ''} ${locked ? 'locked' : ''} `}
                    icon={locked ? <Lock /> : undefined}
                >
                    <SpanItemWrap>{titleOverride(v)} {v === selectedKey ? <RightOutlined /> : null}</SpanItemWrap>
                </MenuItem>
            })}
        </>
    </MenuItemGroup>

}
const InitialMenu = memo((props) => {
  const { advancedFiltersAllowed, allowedCategoriesInFreePlan, retentionFeatureAllowed, aiSessionFeatureAllowed } = useRestrictionContext();
  const isWebApp = useIsAppType( 'web' );
  const hasSmartEvents = useHasSmartEvents()
  const isUserV2 = useIsUserV2();
  const { categories: categoriesProps, selectedKey, segmentType, parentType } = props;
  const categoriesCopy =  useMemo( () => [...categoriesProps], [ categoriesProps ] )
  const someAreLocked = useMemo( () => !advancedFiltersAllowed ? categoriesProps.some( (v) => !allowedCategoriesInFreePlan.includes( v ) ) : false, [ allowedCategoriesInFreePlan, categoriesProps, advancedFiltersAllowed ] )
  const categoriesLockedSorted = useMemo( () => {
    const allElementPosition = categoriesCopy.findIndex( el => el === 'All' )
    if ( allElementPosition >= 0 ) categoriesCopy.splice( allElementPosition, 1 )
    return [ 'All', ...categoriesCopy.sort( (a, b) => allowedCategoriesInFreePlan.includes( a ) < allowedCategoriesInFreePlan.includes( b ) ? 1 : -1 ) ]
  }, [ allowedCategoriesInFreePlan, categoriesCopy ] )
  const categories = useMemo( () => someAreLocked ? categoriesLockedSorted : categoriesProps, [ categoriesProps, categoriesLockedSorted, someAreLocked ]);
  const getAvailableActivityFilterList = useGetAvailableActivityFilters();

  const categoriesFiltered = useMemo(() => parentType === 'nocodeEventsList' ? [...categories] : categories.filter(item => item !== "Smart event properties"), [categories, parentType]);
  let categoriesExtraFiltered = useMemo(() => parentType === 'nocodeEventsList' ?
    categoriesExtra.filter(extra => !['Event properties', 'SmartEvents'].includes(extra)) :
    categoriesExtra.filter(extra => !['SmartEvents'].includes(extra)), [parentType]);
  
  categoriesExtraFiltered = useMemo(() => {
      let filteredCategories = categoriesExtraFiltered;

      if (!retentionFeatureAllowed) {
        filteredCategories = filteredCategories.filter(category => category !== 'Cohorts');
      }

      if (!aiSessionFeatureAllowed || parentType === 'usersList') {
        filteredCategories = filteredCategories.filter(category => category !== "Tara's watchlist batches");
      }

      if (!isWebApp || parentType === 'usersList') {
        filteredCategories = filteredCategories.filter(category => category !== 'Landing UTM');
      }

      if (!isWebApp) {
        filteredCategories = filteredCategories.filter(category => category !== 'Screen visit properties' && category !== 'Custom screen properties');
      }

      if (!isWebApp) {
        filteredCategories = filteredCategories.filter(category => category !== 'Initial landing UTM');
      }
      const initialLandingUtmIndex = filteredCategories.indexOf('Initial landing UTM');
      if (initialLandingUtmIndex > -1) {
        filteredCategories.splice(initialLandingUtmIndex, 1);
        filteredCategories.unshift('Initial landing UTM');
      }

      const landingUtmIndex = filteredCategories.indexOf('Landing UTM');
      if (landingUtmIndex > -1) {
        filteredCategories.splice(landingUtmIndex, 1);
        filteredCategories.unshift('Landing UTM');
      }

      const screenVisitIndex = filteredCategories.indexOf('Screen visit properties');
      if (screenVisitIndex > -1) {
        filteredCategories.splice(screenVisitIndex, 1);
        filteredCategories.unshift('Screen visit properties');
      }

      const customScreenIndex = filteredCategories.indexOf('Custom screen properties');
      if (customScreenIndex > -1) {
        filteredCategories.splice(customScreenIndex, 1);
        filteredCategories.unshift('Custom screen properties');
      }

      return filteredCategories;
    }, [categoriesExtraFiltered, retentionFeatureAllowed, aiSessionFeatureAllowed, isWebApp, parentType]);
  
  const titleOverride = useCallback((title) => {
    if(isUserV2){
        if(title === 'Custom user properties') return 'User custom properties'
        if(title === 'Cohorts') return 'User cohorts'
        if(title === 'User Labels') return 'User labels'
        if(title === 'Had a coded event' && !hasSmartEvents ) return 'Had an event'
    }else if (title === 'Session Labels' || title === 'User Labels') return 'Labels';
    if (title === 'Coded events') return 'Events';
    return title;
  }, [isUserV2, hasSmartEvents]);
  // * if user v2 then group by properties
    const excludedAndCategorizedExtraFilter = categoriesExtraFiltered.filter((v) => !excludedAdditionalList[segmentType].includes(v))
    const groupedCategories = useMemo(() => 
        groupLabelsByCategory(categoriesFiltered, excludedAndCategorizedExtraFilter, getAvailableActivityFilterList, isUserV2,isWebApp)
    ,[categoriesFiltered, isUserV2,excludedAndCategorizedExtraFilter, getAvailableActivityFilterList,isWebApp])

  return (
  <>
    <GlobalStyles />
    <div className="menu-item-column menu-initial">
              {isArray(groupedCategories) ?
                  <CategorizedMenu
                      categoriesFiltered={groupedCategories}
                      selectedKey={selectedKey}
                      advancedFiltersAllowed={advancedFiltersAllowed}
                      allowedCategoriesInFreePlan={allowedCategoriesInFreePlan}
                      titleOverride={titleOverride}
                      />
                :
                Object?.keys(groupedCategories)?.map(key => {
                    if(['All', 'others'].includes(key)) {
                    return <CategorizedMenu
                        key={key}
                        categoriesFiltered={groupedCategories[key]}
                        selectedKey={selectedKey}
                        advancedFiltersAllowed={advancedFiltersAllowed}
                        allowedCategoriesInFreePlan={allowedCategoriesInFreePlan}
                        titleOverride={titleOverride}
                        />
                    }
                    return <StyledMenuCategory key={key}>
                        <p className='menu-category-title'>{key}</p>
                        <div className="menu-category-block">
                        <CategorizedMenu
                            categoriesFiltered={groupedCategories[key]}
                            selectedKey={selectedKey}
                            advancedFiltersAllowed={advancedFiltersAllowed}
                            allowedCategoriesInFreePlan={allowedCategoriesInFreePlan}
                            titleOverride={titleOverride}
                            />
                            </div>
                    </StyledMenuCategory>
                })
            }
              
      </div>
    </>
  )
})
export default InitialMenu
