/* eslint-disable react/jsx-props-no-spreading */
/* eslint-disable import/no-cycle */
import React, { memo, useCallback, useEffect, useRef } from 'react';
import { Menu } from 'antd'
import { Icon as LegacyIcon } from '@ant-design/compatible'
import { noMatchingFilterMenu } from 'components/shared/GlobalFilter/components'
import { LoaderMenuItem } from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import { DynamicToolTip } from 'Utils/helpers/commonUtils'
import styled from 'styled-components';
import { RightOutlined } from '@ant-design/icons';
import { useIsUserV2 } from 'hooks/useUserV2Filter';
import { withContextProps } from '../FilterContextProvider'
import { filterStrategyIncluded } from '.'
import { activityFilterSelector } from '../../FilterDisplayBar/ActivityFilter/constants';
import { keyLabelMap } from '../../utils';

const { Item: MenuItem } = Menu

const SpanItemWrap = styled.span`
  display: flex;
  justify-content: space-between;
  align-items: center;
`

const rightArrowHiddenCategories = ['Events', 'SmartEvents']
const rightArrowShownCategories = ['Custom user properties', 'Event properties', 'Landing UTM', 'Screen visit properties', 'Custom screen properties', 'Initial landing UTM']

const CommonMapping = (props) => {
  const {
    listOfAttribute,
    isArray,
    isUserCohort = false,
    isBatchId = false,
    isCustomLabel,
    category,
    // context props
    isEmptyMessage,
    loading,
    isAllSelected,
    selectedAttributeProps,
    eventType,
    ...rest
  } = props

  const listRef = useRef(null);
  const isUserV2 = useIsUserV2();
  const hasSessionActivityCrashedSession = isUserV2 ? 'session_crashed' : false
  const handleScrollTopSelectedItem = useCallback((element, scrollTop) => {
    element.style.scrollBehavior = 'smooth';
    element.scrollTop = scrollTop;
  }, [])

  useEffect(() => {
    // selectedAttributeProps.table as dependency to prevent scroll to top on tables that are already in view
    if(listRef.current) {
      const listParent = document.getElementById('menu-selected-key');
      const siblingElement = listParent.children[0];
      const scrollableParent = listParent.children[1];
      if(listRef.current.offsetTop > 0)
      {
        const scrollTop = listRef.current.offsetTop - siblingElement.offsetHeight - 35;
        handleScrollTopSelectedItem(scrollableParent, scrollTop);
      }
    }
  }, [selectedAttributeProps.table])
  
  let attributeSelected = selectedAttributeProps?.attribute
  let renderList = <></>
  if (!listOfAttribute) return renderList
  if (loading && filterStrategyIncluded.includes(category) && !isAllSelected) return <LoaderMenuItem className="menuitem-loader" />
  if (
    filterStrategyIncluded.includes(category)
      ? isEmptyMessage
      : !listOfAttribute.length
  )
    return noMatchingFilterMenu

  if (!isArray) {
    if ( isUserCohort ) {
      // eslint-disable-next-line arrow-body-style
      return listOfAttribute.map( ( { name, id, description } ) => {
        return (
          <MenuItem
            key={ id }
            dropdownAttribute={id}
            data-intercom-target={name}
            dropdownId="isSecondLevel"
            dropdownCategory={category}
            className={id === attributeSelected ? 'selected' : ''}
            {...rest}
          >
            <span className='checkbox-content'>
              <span className='custom-label-name'>
                <DynamicToolTip description={ description } title={ name } count={ description ? 0 : undefined } />
              </span>
            </span>
          </MenuItem>
        )
      } )
    }
    if (isBatchId) {
      return listOfAttribute.map( ( { batch_id, batch_name } ) => {
        return (
          <MenuItem
            key={ batch_id }
            dropdownAttribute={batch_id}
            data-intercom-target={batch_name}
            dropdownId="isSecondLevel"
            dropdownCategory={category}
            className={batch_id === attributeSelected ? 'selected' : ''}
            {...rest}
          >
            <span className='checkbox-content'>
              <span className='custom-label-name'>
                <DynamicToolTip title={ batch_name } />
              </span>
            </span>
          </MenuItem>
        )
      } )
    }
    if (isCustomLabel) {
      renderList = listOfAttribute.map((label) => {
        attributeSelected = selectedAttributeProps?.name
        return (
          <MenuItem
            key={label.name}
            dropdownAttribute={label.name}
            data-intercom-target={label.name}
            dropdownId="isSecondLevel"
            dropdownCategory={category}
            className={label.name === attributeSelected ? 'selected' : ''}
            {...rest}
          >
            <span className='checkbox-content'>
              <LegacyIcon type={label.icon} />
              <span className='custom-label-name'>
                <DynamicToolTip title={label.name} />
              </span>
            </span>
          </MenuItem>
        )
      })
    } else {
      renderList = listOfAttribute.map(
        ({ attribute, title, type }) => (
          <span ref={attribute === attributeSelected ? listRef : null}>
          <MenuItem
            key={attribute}
            title={title}
            dropdownAttribute={attribute}
            type={type}
            data-intercom-target={title}
            dropdownId="isSecondLevel"
            dropdownCategory={category}            
            className={attribute === attributeSelected ? 'selected' : ''}
            {...rest}
          >
            {['rageTap', 'UI Freeze', ...Object.keys(activityFilterSelector),hasSessionActivityCrashedSession].includes(attribute) ?
            <DynamicToolTip title={title} /> :
            <SpanItemWrap><DynamicToolTip title={title} /><RightOutlined /></SpanItemWrap>}
          </MenuItem>
          </span>
        )
      )
    }
  } else {
    const attributeSelectedValue =
      ['user_custom_property', 'event_custom_property'].includes(attributeSelected)
        ? selectedAttributeProps?.property_name
        : attributeSelected
    renderList = listOfAttribute.sort().map((value) => {
      if ( value?.isUserCohort ) {
        return (
          <MenuItem
            {...rest}
            key={value.id}
            dropdownAttribute={value.id}
            data-intercom-target={value.name}
            dropdownId="isSecondLevel"
            dropdownCategory="Cohorts"
            className={value.id === attributeSelectedValue ? 'selected' : ''}
          >
            <span className='checkbox-content'>
              <span className='custom-label-name'>
                <DynamicToolTip description={ value.description } count={ value.description ? 0 : undefined } title={value.name} />
              </span>
            </span>
          </MenuItem>
        )
      }
      if ( value?.isBatchId ) {
        return (
          <MenuItem
            {...rest}
            key={value.batch_id}
            dropdownAttribute={value.batch_id}
            data-intercom-target={value.batch_name}
            dropdownId="isSecondLevel"
            dropdownCategory="Tara's watchlist batches"
            className={value.batch_id === attributeSelectedValue ? 'selected' : ''}
          >
            <span className='checkbox-content'>
              <span className='custom-label-name'>
                <DynamicToolTip title={value.batch_name} />
              </span>
            </span>
          </MenuItem>
        )
      }
      if (value?.isCustomLabel)
        return <MenuItem
          {...rest}
          key={value.name}
          dropdownAttribute={value.name}
          data-intercom-target={value.name}
          dropdownId="isSecondLevel"
          dropdownCategory={value.category}
          className={value.name === attributeSelectedValue ? 'selected' : ''}
        >
          <span className='checkbox-content'>
            <LegacyIcon type={value.icon} />
            <span className='custom-label-name'>
              <DynamicToolTip title={value.name} />
            </span>
          </span>
        </MenuItem>
      if (value?.attribute)
        return <MenuItem
          key={value.attribute}
          title={value.title}
          data-intercom-target={value.title}
          dropdownAttribute={value.attribute}
          type={value.type}
          dropdownId="isSecondLevel"
          dropdownCategory={value.category}
          className={value.attribute === attributeSelectedValue ? 'selected' : ''}
          {...rest}
        >
          {!rightArrowHiddenCategories.includes(value?.category) ? <SpanItemWrap><DynamicToolTip title={value.title} />  <RightOutlined /></SpanItemWrap> 
          : <DynamicToolTip title={value.title} />}
        </MenuItem>
      return (
      <span ref={(value === attributeSelectedValue || value === selectedAttributeProps?.propertyName) ? listRef : null}>
      <MenuItem
        dropdownAttribute={value}
        key={value}
        dropdownId="isSecondLevel"
        dropdownCategory={category}
        data-intercom-target={value}
        className={(value === attributeSelectedValue || value === selectedAttributeProps?.propertyName) ? 'selected' : ''}
        eventType={eventType}
        {...rest}
      >
        {rightArrowShownCategories.includes(category) ? 
        <SpanItemWrap><DynamicToolTip title={keyLabelMap[value] || value} />  <RightOutlined /></SpanItemWrap> : 
        <DynamicToolTip title={value} />}
      </MenuItem>
      </span>
      )
    })
  }
  return renderList
}
export default withContextProps(memo(CommonMapping))
