import { useQuery } from 'react-query'
import { axiosInstance } from 'services/globalInstance'
import { IEventPropertyFilter, IStatBoxes } from 'types/reduxStateTypes'

const pythonBaseURL = process.env.PYTHON_API_URL


interface IStatBoxesData {
	boxes: IStatBoxes
}

interface IStatBoxesRes {
	data?: {
		data?: IStatBoxesData
	}
}

export interface IStatisticsBoxesPostBody {
	appid: string | undefined
	filters: IEventPropertyFilter[]
	date_range: {
		 table?: "event" | string
		 attribute: "date_range" | "upload_time" | "device_time" | string
		 operator: "between_dates" | string
		 value: {
			  lower: string
			  upper: string
		 }
		 label?: "1month" | string
		 labelId?: string
	}
}

const getStatsBoxData = async ( postBody: IStatisticsBoxesPostBody ): Promise<IStatBoxesRes> => axiosInstance.post( `${ pythonBaseURL }/ai/sessions/stat_box_data`, postBody, {
	withCredentials: true,
} )

interface IUseStatsBoxDataOptions {
	enabled?: boolean
}

export const useStatsBoxData = ( postBody: IStatisticsBoxesPostBody, options?: IUseStatsBoxDataOptions ) =>
	useQuery<IStatBoxesData | undefined, Error>(
		[
			`aiStatsBoxData`,
			postBody.appid,
			postBody.date_range.value.lower,
			postBody.date_range.value.upper,
			JSON.stringify( postBody.filters ),
			postBody.date_range.attribute,
		],
		() => getStatsBoxData( postBody )
			.then( res => res.data?.data ),
		{
			staleTime: 30000,
			enabled: options?.enabled ?? true,
			refetchOnWindowFocus: false,
		}
	)