import { Button, Form, Input, Select, message } from "antd";
import { FormContainer, FormItemLayoutContainer, ModalFooterWrapper, StyledModal } from "components/shared/CustomPropertyModal/styles";
import React, { useCallback, useEffect, useMemo, useState } from "react";
import { RootStateOrAny, useSelector } from "react-redux";
import isEmpty from 'lodash/isEmpty';
import DeleteSegmentSvg from 'public/static/segments/deleteSegment.svg'
import { useIsUserV2 } from "hooks/useUserV2Filter";
import { getSaveAsSegmentPayloadWithActivityFilterCheck } from "Utils/helpers/segmentHelper";
import { useSegmentModal } from "../hooks/useModal";
import DeleteSegmentModal from "../DeleteSegment";
import { IFilter, ISegment, ISegmentPayload, SaveModalState } from "../types";
import { CancelText, CreateText, DeleteText, EditText, SaveText, SegmentErrorText, SegmentName, SegmentNameErrorText, SegmentNameInputPlaceholder, SetAccess, segmentAccessOptions, SegmentNameLengthErrorText } from "../variables";
import useAppFilter from "../../useAppFilter";
import useSegmentAPI from "../hooks/useSegmentAPI";

const hasValidValue = (f: Partial<IFilter>) =>
  'value' in f && f.value !== undefined && f.value !== null && f.value !== '' && !(Array.isArray(f.value) && f.value.length === 0);

const filterEmptyValueFilters = (filters: IFilter[]): IFilter[] =>
  filters
    ?.filter(hasValidValue)
    .map((f) => f.filters ? { ...f, filters: f.filters.filter(hasValidValue) } : f);

const SaveSegmentModal: React.FC = () => {

  const [form] = Form.useForm();
  const { segmentType } = useAppFilter();

  const { addSegment, updateSegment } = useSegmentAPI();
  const { appFilter, currentAppReducer } = useSelector((state: RootStateOrAny ) => state);

  const { saveModalOpen, toggleModal } = useSegmentModal();
  const [showLoader, setShowLoader] = useState<boolean>(false);
  const isUserV2 = useIsUserV2();
  const {activityFilterList, segment} = appFilter[segmentType];
  // * CX-2103 : APPLYING ACTIVITY FILTERS TO SEGMENTS FOR USER LIST (ICEBERG)
  const appliedSegment = useMemo(()=>getSaveAsSegmentPayloadWithActivityFilterCheck(
    activityFilterList,
    segment,
    isUserV2
  ,), [activityFilterList, segment, isUserV2]);

  const { name: appName } = currentAppReducer || {};

  const  { isModalOpen, modalSegment, filterPayload } = saveModalOpen as SaveModalState;
  const isEditModal = useMemo(() => !isEmpty(modalSegment), [modalSegment]);
  const { name: segmentName, id: segmentId, isPublic } = modalSegment as ISegment || {};

  useEffect(() => {
    form.setFieldsValue({
      segmentName: segmentName || '',
      access: isPublic ?  '1' : '2',
      accessType: isPublic ? 'view' : 'view_edit',
    });
  }, [form, isModalOpen, isPublic, segmentName])

  const handleCancel = () => {
    toggleModal?.('save', [], []);
    form.resetFields();
  };

  const setSegmentNameError = useCallback((errorMsg: string) => {
    form.setFields([
      {
        name: 'segmentName',
        errors: [`${errorMsg}`],
      },
    ]);
  }, [form]);

  const handleFinish = async (values: any) => {
    const { segmentName: name, access } = values;
    setShowLoader(true);
    try {
      if (isEditModal) {
        await updateSegment({
          id: segmentId,
          name: name.trim(),
          filter: modalSegment.filter,
          isPublic: access === '1',
        } as ISegmentPayload)
      } else {
        // Use filterPayload if available (from mass user id filter), otherwise use appliedSegment
        const filterToUse = filterPayload || appliedSegment;
        await addSegment({
          name: name.trim(),
          filter: filterEmptyValueFilters(filterToUse as IFilter[]),
          isPublic: access === '1',
        } as ISegmentPayload)
      }
      setShowLoader(false);
      message.success(isEditModal ? 'Segment has been updated successfully. ' : `Segment has been created successfully as "${name}".`);
    } catch (error: any) {
      setShowLoader(false);
      const { response: { status, data: { error: errorMsg }}  } = error;
      if (status === 409) {
        setSegmentNameError( errorMsg.message || errorMsg)
        return;
      }
      setSegmentNameError(SegmentErrorText)
      return;
    }
    handleCancel();
  }

  const handleAccessChange = useCallback((value: string) => {
    form.setFieldsValue({ 'accessType': value === '2' ? 'view_edit' : 'view' });
  }, [form]);

  return (
    <>
      <StyledModal
        visible={isModalOpen}
        centered
        footer={null}
        closable={false}
        destroyOnClose>

        <h2>{isEditModal ? EditText : CreateText}</h2>
        <FormContainer
          form={form}
          layout="vertical"
          requiredMark={false}
          onFinish={handleFinish}>

          <Form.Item
            shouldUpdate
            name="segmentName"
            label={SegmentName}
            required
            initialValue={segmentName}
            rules={[
              {
                required: true,
                message: SegmentNameErrorText,
              },
              {
                max: 50,
                message: SegmentNameLengthErrorText,
              }
            ]}>
            <Input placeholder={SegmentNameInputPlaceholder} />
          </Form.Item>

          <FormItemLayoutContainer>
            <Form.Item
              name="access"
              label={SetAccess}
              required
              shouldUpdate
            >
              <Select
                getPopupContainer={node => node.parentNode}
                dropdownStyle={{
                  maxHeight: 400,
                  overflow: "auto",
                  zIndex: 9999
                }}
                onChange={handleAccessChange}
                options={[
                  {
                    value: '1',
                    label: `Everyone in "${appName}"`,
                  },
                  {
                    value: '2',
                    label: 'Only me',
                  }
                ]} />
            </Form.Item>

            {/* In future we will have to add edit option as well */}
            <Form.Item
              name="accessType"
              label=" "
            >
              <Select
                showArrow={false}
                dropdownStyle={{
                  maxHeight: 400,
                  overflow: "auto",
                  zIndex: 9999
                }}
                options={segmentAccessOptions} />
            </Form.Item>

          </FormItemLayoutContainer>

          <ModalFooterWrapper isEditModal={isEditModal}>
            { isEditModal ? <Button className='danger' icon={<DeleteSegmentSvg />} type='link' danger onClick={() => {
              toggleModal?.('delete', [])
            }}>
              {DeleteText}
            </Button> : null }

            <div className='modal-footer'>
              <Button onClick={handleCancel} type='link'>
                {CancelText}
              </Button>
              <Button
                type="primary"
                htmlType="submit"
                loading={showLoader}
              >
                {SaveText}
              </Button>
            </div>
          </ModalFooterWrapper>

        </FormContainer>
      </StyledModal>
      <DeleteSegmentModal />
    </>

  )
}

export default SaveSegmentModal;