import { useQuery } from 'react-query';
import { useSelector } from 'react-redux';
import { axiosInstance } from 'services/globalInstance';
import SessionTableApi from 'services/sessionTableApi';

const getAISessionItems = async ({ postBody }) => SessionTableApi.getV2AISessionsList(postBody)
const sortColumns = async (postBody) =>
  axiosInstance.post(
    `${process.env.PYTHON_API_URL}/preference/column-sort-order`,
    postBody,
    {
      withCredentials: true,
      credentials: 'include',
    }
  )

export const useAISessionItems = (postBody,options,parentType) => {
  const { _id: currentAppId } = useSelector((state) => state.currentAppReducer) || {};
  const isCurrentAppReady = postBody?.appid && postBody.appid === currentAppId;
  const { enabled: optionsEnabled, ...restOptions } = options || {};

  return useQuery(['aiSessionItems', postBody], () => getAISessionItems({ postBody }), {
    refetchOnMount: false,
    retry: 3,
    cacheTime: 5 * 60 * 1000, // 5 minutes
    enabled: (optionsEnabled ?? parentType !== 'usersList') && isCurrentAppReady,
    keepPreviousData: true,
    ...restOptions
  });
}


export const useSessionSort = (postBody) =>
  useQuery('sortSession', () => sortColumns(postBody), {
    enabled: false,
    retry: false,
  });