import React, { useCallback, useEffect, useMemo } from 'react'

import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';

import LottieIcon from 'components/common/LottieIcon';
import { AiLoaderLottie } from 'public/static/lottie-icons/animations';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useFilterContext } from '../FilterContextProvider';

import { SuggestionFilters, Title, FooterContent, AiSearchComponent, NoResultsComponent, PromptResultsComponent, AIDisabledOverlay } from './common';

import { LoaderContainer, MainContainer, TitleSection } from './styles';

// import resultTest from './dummyPromptResult.json';

import { StoredFilterPayload, TFilterPayload } from './types';
import { useAiPrompt } from './hooks/useAiPrompt';

import { suggestions } from './suggestionsConst';
import { getFilterData, validateFilterData } from './utils';
import useAppFilter from '../../useAppFilter';
import { useAiFilterSettings } from './hooks/useAiSettings';

const AiFilter:React.FC<{
  isTabSelected: boolean;
  onVisibleChange: (visible: boolean) => void;
}> = ({
  isTabSelected,
  onVisibleChange,
}) => {
  const { tabContentWidth } = useFilterContext();
  const { pageType } = useAppFilter();
  const dispatch = useDispatch();
  const [searchText, setSearchText] = React.useState<string>('');
  const inputRef = React.createRef<HTMLTextAreaElement>();
  const [isLoading, setIsLoading] = React.useState<boolean>(false);
  const [results, setResults] = React.useState<TFilterPayload[] | null>(null);
  const { getFiltersFromPrompt } = useAiPrompt();
  const { mutate } = getFiltersFromPrompt;
  const [savedSearchText, setSavedSearchText] = React.useState<string>('');
  let savedAiFilterPayload: string | null = ''
  try {
    savedAiFilterPayload = localStorage.getItem('aiFilerPayload');
  } catch (err) {
    // silent fail
  }
  const alreadyRated = useMemo(() => {
    if (!savedAiFilterPayload) return false;
    const parsedSavedAiFilterPayload = JSON.parse(savedAiFilterPayload as string) as StoredFilterPayload;
    return parsedSavedAiFilterPayload.rated;
  }, [savedAiFilterPayload])
  const {
    currentAppReducer, currentOrgReducer
  } = useSelector((state: RootStateOrAny) => state);
  const { aiFilterSettings } = useAiFilterSettings();

  const { _id: appId } = currentAppReducer || {};
  const { orgId:orgid } = currentOrgReducer || {};

  const isSuggested = suggestions.find((suggestion) => suggestion.title === savedSearchText);

  const onClear = useCallback(() => {
    setSearchText('');
    inputRef.current?.focus();
  }, [inputRef])

  const onSubmit = useCallback((promptText = '') => {
    if (!aiFilterSettings) return;
    // TODO: test loading state to be replaced with actual API call
    setIsLoading(true);
    setResults(null);
    setSavedSearchText(searchText || promptText);

    mutate({
      prompt: searchText || promptText,
      orgid,
    }, {
      onSuccess: (res) => {
        const validFilters = validateFilterData(res.data, pageType);

        const filterHasInvalid = validFilters.some((item) => !item.isValid);

        // show loader for 1 seconds
        setTimeout(() => {
          try {
            if (filterHasInvalid) {
              setResults([]);
              localStorage.setItem('aiFilerPayload', JSON.stringify({
                filters: res.data,
                prompt: searchText || promptText,
                appId,
                rated: false,
                pageType,
              }))
            } else {
              setResults(res.data);
              localStorage.setItem('aiFilerPayload', JSON.stringify({
                filters: res.data,
                prompt: searchText || promptText,
                appId,
                rated: false,
                pageType,
              }))
            }
          } catch (err) {
            // silent fail
          }
          setIsLoading(false);
        }, 1000)
      },
      onError: () => {
        setTimeout(() => {
          setIsLoading(false);
          setResults([]);
        }, 3000)
      },
      onSettled: (res, error, variable) => {
        let filters = [];
        if (res && res.data) {
          filters = res?.data?.map((item: TFilterPayload) => {
            const getType = getFilterData(item, pageType).type;
            return {
                ...item,
                type: getType,
            }
          });
        }
        if (error) {
          // eslint-disable-next-line @typescript-eslint/ban-ts-comment
          // @ts-expect-error
          const errorResponse = error?.response?.data;
          const errorFilters = errorResponse?.filters || [];
          filters = errorFilters;
        }
        // track event
        dispatch( trackPageViews(null, {
          eventName: 'wa_ai_filter_submit_prompt',
          track_type: 'event',
          eventProperty: {
            prompt_text: variable.prompt,
            suggested: !!isSuggested,
            filter_properties: filters,
          }
        }))
      }
    })
    
  }, [aiFilterSettings, searchText, mutate, orgid, pageType, appId, dispatch, isSuggested]);

  const onResetPrompt = useCallback(() => {
    dispatch(trackPageViews(null, {
      eventName: 'wa_ai_filter_try_another',
      track_type: 'event',
      eventProperty: {
        prompt_text: savedSearchText,
        suggested: !!isSuggested,
      }
    }))
    setResults(null);
    setSearchText('');
    localStorage.removeItem('aiFilerPayload');
    inputRef.current?.focus();
  }, [inputRef, savedSearchText, dispatch, isSuggested]);

  const onSuggestionClick = useCallback((text: string) => {
    setSearchText(text);
    onSubmit(text);
  }, [onSubmit]);

  const onApplyFilters = useCallback((filters: unknown[]) => {
    dispatch(trackPageViews(null, {
      eventName: 'wa_ai_filter_apply_filter',
      track_type: 'event',
      eventProperty: {
        prompt_text: savedSearchText,
        suggested: !!isSuggested,
        filter_properties: filters,
      }
    }))
  }, [savedSearchText, dispatch, isSuggested])

  const onFeedbackClick = useCallback((type: 'positive' | 'negative') => {
    const payloadTemp = results?.map((item) => {
        const getType = getFilterData(item, pageType).type;
        return {
            ...item,
            type: getType,
        }
    });
    dispatch(trackPageViews(null, {
      eventName: 'wa_ai_filter_submit_feedback',
      track_type: 'event',
      eventProperty: {
        prompt_text: savedSearchText,
        feedback: type,
        filter_properties: payloadTemp,
      }
    }))
  }, [dispatch, pageType, results, savedSearchText])

  useEffect(() => {
    if (inputRef.current && isTabSelected) {
      setTimeout(() => {
        inputRef.current?.focus();
      }, 200);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isTabSelected, savedAiFilterPayload])

  useEffect(() => {
    if (savedAiFilterPayload && appId === JSON.parse(savedAiFilterPayload).appId) {
      const { filters, prompt, pageType: parsedPageType } = JSON.parse(savedAiFilterPayload);
      if( pageType === parsedPageType ) {
        setResults(filters);
        setSearchText( prompt );
      }
    }
    return () => {
      setIsLoading(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return (
    <MainContainer style={{
        width: tabContentWidth
    }}>
        {
          !aiFilterSettings ? (
            <AIDisabledOverlay />
          ) : null
        }
        <TitleSection>
            <Title visible={!isLoading && !(Array.isArray(results))} />

            <AiSearchComponent 
                inputProps={{
                    value: searchText,
                    onChange: (e) => setSearchText(e.target.value),
                    disabled: isLoading
                }}
                onSubmit={onSubmit}
                onClear={onClear}
                ref={inputRef}
                disabled={isLoading || searchText.length === 0}
            /> 
        </TitleSection>

        {
          results?.length ? (
            <PromptResultsComponent results={results} onApplyFilters={onApplyFilters} onVisibleChange={onVisibleChange} onTryAnother={onResetPrompt} />
          ) : null
        }

        {
          isLoading ? (
            <LoaderContainer>
              <span className='loader'>
                <LottieIcon animationData={AiLoaderLottie} loop autoPlay active />
              </span>
              <p>
                <div className='inner-text'>
                  Connecting the dots <br/>
                  Combining millions of data points <br/>
                  Refining filters
                </div>
              </p>
            </LoaderContainer>
          ) : null
        }
        {
          !isLoading && results?.length === 0 ? <NoResultsComponent /> : null
        }
        {
          isLoading || (results?.length ?? 0) > 0 ? null : (
            <SuggestionFilters onSuggestionClick={onSuggestionClick} pageType={ pageType }/>
          )
        }
        {
          isLoading ? null : (
            <FooterContent
              variant={Array.isArray(results) ? 'no-results' : 'default'}
              onFeedbackClick={onFeedbackClick}
              hideFooterContent={(Array.isArray(results) && results.length === 0) || (Array.isArray(results) && alreadyRated)}
            />
          )
        }
    </MainContainer>
  )
}

export default AiFilter