import isEqual from 'lodash/isEqual';
import { useSelector } from 'react-redux';
import { useQueryClient } from 'react-query';

export const videoPrivacyDefaultCustomizer = (val1, val2, key) => {
    if (key === 'config' && val1.rule === 'blur') {
      // Compare only the radius key of the config object
      return isEqual(val1, val2);
    }
    if (key === "config" && val1.rule !== "blur") {
      // Ignore the config object
      return undefined;
    }
}

export const checkVideoPrivacyExceptionsChange = (exceptionValue, successResponse) => {
    if (!exceptionValue[0]) {
        return isEqual(exceptionValue, successResponse?.videoPrivacy?.exceptions);
    //   return false;
    }
  
    const { rule, screens } = exceptionValue[0];
    const exceptions = successResponse?.videoPrivacy?.exceptions || [];

    if(exceptionValue.length !== successResponse.length) return false;
  
    // only blur has equal config key with radius, skip config check for others
    if (rule === 'blur') {
      return isEqual(exceptions, exceptionValue);
    }
  
    const firstException = exceptions && exceptions[0];
  
    return isEqual(firstException?.rule, rule) && isEqual(firstException?.screens, screens);
  };

  export const useRenamedScreenOptions = () => {
    const queryClient = useQueryClient();
    const { app: appId } = useSelector((state) => state.urlReducer);
  
    const renameScreenQueryKey = `rename-screen-${appId}`;
    const renameScreen = queryClient.getQueryData(renameScreenQueryKey);

    function getRenamedScreenName(screenName) {
      const renamedScreenName = (renameScreen && renameScreen[screenName]) || screenName || '';;
      return renamedScreenName;
    }

    return {
      renameScreenQueryKey,
      renameScreen,
      getRenamedScreenName,
    }
  }

export function addPlatformInfo(versionString, platformType) {
  if ( !platformType || versionString.includes('ios') || versionString.includes('android') ) {
      return versionString; // If the platform type is not provided, return the original string
  }
  // Check if the version string already contains the platform type
  if (versionString.includes(platformType)) {
      return versionString; // If it does, return the original string
  } 
      // If not, add the platform type to the version string and return it
      return `${versionString} (${platformType})`;
  
}