/* eslint-disable react/jsx-props-no-spreading */
import React, { memo, useCallback, useMemo } from 'react';
import { MinusCircleOutlined } from '@ant-design/icons';
import { Form } from 'antd';
import styled from 'styled-components';
import clone from 'lodash/clone'
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter';
import { FilterCountSvg } from 'components/shared/GlobalFilter/components/FilterSvgs';
import PropertiesOptions from './PropertiesOptions';
import PropertiesOperator from './PropertiesOperator';
import PropertiesValueOptions from './PropertiesValueOptions';

const FormItem = Form.Item;

const StyledMain = styled.div`
  display: flex;
  gap: 10px;
  margin: 8px 0;
  line-height: noraml;
  font-size: 12px;
  .ant-form-item-control-input {
    min-height: auto;
  }
  .ant-form-item {
    line-height: normal;
  }
  .ant-form-item-with-help .ant-form-item-explain {
    min-height: 4px;
  }
  .anticon svg {
    font-size: 13px;
    color: #dc4f44;
    margin-bottom: 6px;
  }
  svg {
    margin-top: 2px;
  }
`;

const StyledFormItem = styled(FormItem)`
  margin-bottom: 0;
  align-item: baseline;
  a {
    color: #49576e !important;
    min-width: 80px;
  }
  .ant-form-item-explain-error {
    font-size: 12px;
    line-height: normal;
  }
  .ant-col{
    margin-bottom: 0 !important;
   }
   .ant-form-item-control-input{
    align-items: baseline !important;
   }
`;

const EventFilterProperties = ({
  attributeProps,
  filterData,
  filterSegment,
}) => {
  const { callListApi } = useAppFilter();
  const [form] = Form.useForm();
  const formData = Form.useWatch('eventProperties', form) || [];

  const segment = clone(filterSegment);
  const index = segment.indexOf(filterData);
  const filterValue = useMemo(() => segment[index].filters, [index, segment]);

  const eventNameFilter = useMemo(
    () =>
      filterValue.find((valueField) => valueField?.attribute === 'event_name' || valueField?.attribute === 'nce_name'),
    [filterValue]
  );

  const withoutEventNameFilter = useMemo(
    () =>
      filterValue.filter(
        (valueField) => valueField?.attribute !== 'event_name' && valueField?.attribute !== 'nce_name'
      ),
    [filterValue]
  );

  const newPropertyFilter = useMemo(()=> eventNameFilter
  ? filterValue?.filter(
      (valueField) => valueField?.attribute === 'event_name' || valueField?.attribute === 'nce_name'
    )
  : [], [eventNameFilter, filterValue]);

  const newFilters =  useMemo(() => {
    segment[index].filters = [...newPropertyFilter, ...formData];
    return segment;
  }, [segment, index, newPropertyFilter, formData] )

  const handleApply = useCallback(() => {
    callListApi(newFilters);
  }, [callListApi, newFilters]);

  const handleRemoveApply = useCallback(
    (eventPropIndex) => {
      
      const removeEventProp = withoutEventNameFilter.filter(
        (_, valueIndex) => valueIndex !== eventPropIndex
      );
      if (filterData?.attribute === 'event_count_per_screen_visit' || filterData?.attribute === 'smart_event_count_per_screen_visit') {
        segment[index].filters = [...newPropertyFilter, ...removeEventProp]; // need to handle later
      }
      callListApi(segment);
    },
    [withoutEventNameFilter, filterData?.attribute, callListApi, segment, index, newPropertyFilter]
  );

  return (
    <Form
      form={form}
      name="dynamic_form_nest_item"
      autoComplete="off"
      initialValues={{ eventProperties: withoutEventNameFilter || [] }}
    >
      <Form.List name="eventProperties">
        {(fields, { add, remove }) => (
          <>
            {fields.map(({ key, name, ...restField }) => (
              <StyledMain key={key}>
                <FilterCountSvg/>
                <StyledFormItem
                  {...restField}
                  name={[name, 'attribute']}
                  initialValue="event_custom_property"
                  noStyle
                />

                <StyledFormItem
                  {...restField}
                  name={[name, 'json_field']}
                  rules={[
                    {
                      required: true,
                      message: 'Missing Event Property',
                    },
                  ]}
                >
                  <PropertiesOptions
                    id="property"
                    name={['eventProperties', name, 'json_field']}
                    attributeProps={attributeProps}
                    filterData={filterData}
                  />
                </StyledFormItem>
                <StyledFormItem
                shouldUpdate
                  {...restField}
                  name={[name, 'operator']}
                  initialValue='in'
                >
                  <PropertiesOperator
                    name={['eventProperties', name, 'operator']}
                    handleApply={handleApply}
                  />
                </StyledFormItem>
                <StyledFormItem
                shouldUpdate
                  {...restField}
                  
                  name={[name, 'value']}
                  validateTrigger={['onChange', 'onBlur']}
                  rules={[
                    {
                      required: true,
                      message: 'Missing event property value',
                    },
                  ]}
                >
                  <PropertiesValueOptions
                    name={['eventProperties', name, 'value']}
                    attributeProps={attributeProps}
                    filterData={filterData}
                    // selectedPropertiesOperaors={selectedPropertiesOperaors}
                    handleApply={handleApply}
                  />
                </StyledFormItem>
                <MinusCircleOutlined 
                    onClick={() => {
                      remove(name);
                      handleRemoveApply(name);
                    }}
                    />
              </StyledMain>
            ))}
            <PropertiesOptions
                id="condition"
                name={['eventProperties', formData?.length ?? 0, 'json_field']}
                attributeProps={attributeProps}
                addProperty={add}
                filterData={filterData}
              />
          </>
        )}
      </Form.List>
    </Form>
  );
};
export default memo(EventFilterProperties);
