import React, { useState, useEffect, memo, useCallback } from 'react';
import styled from 'styled-components'
import {
  DebounceInputComponent,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2';

const DebounceInputComponentWrap = styled(DebounceInputComponent)`
  border: 0;
  border-bottom: 1px dashed #a1a8c2;
  border-radius: 0;
  padding: 0;
  line-height: normal;
  font-size: 14px;
`

const InputPropertiesValues = (props) => {
  const {
    option,
    placeholder,
    handlePropertyValueInput
  } = props

  const [inputText, setInputText] = useState('');

  const handleInputChange = useCallback((arg) => {  
    const value = arg?.target ? arg.target.value : arg
    handlePropertyValueInput(value);
  }, [handlePropertyValueInput]);
  
  useEffect(() => {
    (typeof option === 'string' || typeof option === 'number') &&
      setInputText(option)
    return () => {
      setInputText('')
    }
  }, [option])

  return (
    <DebounceInputComponentWrap
      value={inputText}
      onChange={(e) => setInputText(e.target.value)}
      className="filter-input-width"
      onPressEnter={handleInputChange}
      placeholder={placeholder}
    />
  )
}
export default memo(InputPropertiesValues)
