import React, { useEffect, useCallback, memo} from 'react'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import LockedPage from 'components/common/LockedPage'
import { useDispatch, useSelector } from 'react-redux'
import { trackPageViews } from 'redux/actions/trackingReport'
import Illustration from 'public/static/lock-features/app-flows-locked-illustration.svg'

const AppFlowsPageLocked = () => {
	const dispatch = useDispatch()
	const { setTriggerRequestQuote, setShowPricingModal } = useRestrictionContext()
	const { urlReducer: { url } } = useSelector( state => state )
	const { selfServeFlag } = useRestrictionContext()

	const handleClickSeePricing = useCallback( () => {
		setShowPricingModal( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_see_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'ScreenFlow'
			},
		} ) )
	}, [ dispatch, setShowPricingModal ] )

	const handleClickRequestPricing = useCallback( () => {
		setShowPricingModal( true )
		// @Note for Appflows, we always show quote form instead of starter plan modal because we don't have issues in starter plan regardless of self-serve flag
		setTriggerRequestQuote( true )
		dispatch( trackPageViews( null, {
			eventName: 'wa_request_pricing_clicked',
			track_type: 'event',
			eventProperty: {
				source: 'ScreenFlow'
			},
		} ) )
	}, [ dispatch, setShowPricingModal, setTriggerRequestQuote ] )

	useEffect( () => {
		dispatch( trackPageViews( null, {
			eventName: 'wa_blocked_feature_pop_up_displayed',
			track_type: 'event',
			eventProperty: {
				source: 'ScreenFlow',
				self_Checkout: selfServeFlag,
			},
		} ) )
	}, [ url, dispatch, selfServeFlag ] )

	return (
		<LockedPage
			image={ Illustration }
			title="Screen flow & Screen burst"
			subTitle="Understand your users&apos; journey"
			list={ (
				<>
					<li>See the most common paths and drop-offs at a glance.</li>
					<li>Do targeted analysis with custom start and end screens.</li>
					<li>Get relevant session recordings, heatmaps, and funnels.</li>
					<li>Leverage advanced filters for user/device/session properties.</li>
					<li>Investigate app quits with the reverse flow.</li>
				</>
			) }
			handleClickSeePricing={ handleClickSeePricing }
			handleClickRequestPricing={ handleClickRequestPricing }
		/>
	)
}

export default memo( AppFlowsPageLocked )