export const includeAiFilterInParentTypes = ['sessionsList', 'sessionStatistics', 'aiSessionsList', 'aiSessionStatistics', 'eventsList', 'statistics'];

const MegaFilterDropdown = ({ id }) => {
  const dropdownOffsetLastVal = React.useRef( undefined )
  const { callListApi } = useAppFilter()
  const AiFilterEnabled = useFeatureFlag('ai-filter')
  const DefaultAiFilterEnabled = useFeatureFlag('ai-filter-default')
  const dispatch = useDispatch()
  const inputRef = useRef(null)
  const [dropdownOpen, setDropdownOpen] = React.useState(false)
  const { megaDropdownVisible: megaTopDropdownVisible, megaBottomDropdownVisible  } = useSelector(
    (state) => state.megaFilterReducer
  )
  const { parentType } = useSelector((state) => state.urlReducer)
  const [aiFilterTabSelected, setAiFilterTabSelected] = React.useState(false)
  const {openModal, setOpenModal, CommonModal, formRef} = useCommonModal()
  const watchAchieve = Form.useWatch('achieve', formRef);
  const watchImprove = Form.useWatch('improve', formRef);
  const disableSubmit = useMemo(() => !watchAchieve && !watchImprove || watchAchieve === '' && watchImprove === '', [watchAchieve, watchImprove]);

  const { filtersLockedModal } = useRestrictionContext()
  let storedFilterTab = ''
  try {
    storedFilterTab = DefaultAiFilterEnabled ? 'ai-filter' : localStorage.getItem('filter-active-tab')
  } catch (err) {
    // silent fail
  }
  useAiFilterSettings()

  const showAiFilter = useMemo(() => AiFilterEnabled && (includeAiFilterInParentTypes.includes(parentType)), [AiFilterEnabled, parentType]);

  const onVisibleChange = useCallback((flag) => {
    setDropdownOpen(flag)
    setTimeout(() => {
      inputRef?.current?.focus()
    }, 0)
    id === 'topLevelFilterBtn' ? dispatch(setMegaDropdownVisible(flag)) : dispatch(setBottomMegaDropdownVisible(flag))
  }, [dispatch, id])

  const dropdownOffsetVal = React.useMemo( () => {
    if ( megaTopDropdownVisible ) {
      const val = { offset: [ -2, 16 ] }
      dropdownOffsetLastVal.current = val
      return val
    }
    if ( megaBottomDropdownVisible ) {
      const val = { offset: [ -15, 34 ] }
      dropdownOffsetLastVal.current = val
      return val
    }
    return dropdownOffsetLastVal.current
  } , [ megaTopDropdownVisible, megaBottomDropdownVisible ] )

  const LeadingIconForButton = useMemo(() => {
    if (dropdownOpen) return <AIInputIcon />
    return <LottieIcon animationData={AiCtaLottie} active loop autoplay />
  }, [dropdownOpen])

  const AIFilterLabel = useMemo(() => (
    <LabelContainer data-intercom-target='Smart filters'>
      Smart filters ✨
      <NewPill>Beta</NewPill>
    </LabelContainer>
  ), [])

  const handleOpenFeedbackModal = useCallback(() => {
    setOpenModal(true)
    onVisibleChange(false)
  }, [onVisibleChange, setOpenModal])

  const handleFeedbackFormSubmit = useCallback((e) => {
    // TODO: send event to mix panel
    console.log('Feedback form submitted with values:', e)
  }, [])

  const FilterOverlayLayout = useMemo(() => (
        <FilterContextProvider inputRef={inputRef}>
          <StyledTabs defaultActiveKey={storedFilterTab || 'filter'} onTabClick={(active) => {
            try {
              localStorage.setItem('filter-active-tab', active)
            } catch (err) {
              // silent fail
            }
            if (active === 'ai-filter') {
              dispatch(trackPageViews(null, {
                eventName: 'wa_ai_filter_click_tab',
                track_type: 'event',
              }))
              setAiFilterTabSelected(true)
            }
            else setAiFilterTabSelected(false)
          }}>
            {
              DefaultAiFilterEnabled ? (
                <><Tabs.TabPane tab={AIFilterLabel} key="ai-filter</Tabs.TabPane>">
                  <AiFilter isTabSelected={aiFilterTabSelected} onVisibleChange={onVisibleChange} onFeedbackClick={handleOpenFeedbackModal} />
                </Tabs.TabPane><Tabs.TabPane className='filter-container' tab="Filters" key="filter">
                    <MainMenu callListApi={callListApi} />
                  </Tabs.TabPane></>
              ) : (
                <><Tabs.TabPane className='filter-container' tab="Filters" key="filter">
                  <MainMenu callListApi={callListApi} />
                </Tabs.TabPane><Tabs.TabPane tab={AIFilterLabel} key="ai-filter">
                    <AiFilter isTabSelected={aiFilterTabSelected} onVisibleChange={onVisibleChange} onFeedbackClick={handleOpenFeedbackModal} />
                  </Tabs.TabPane></>
              )
            }
          </StyledTabs>
        </FilterContextProvider>
    ), [callListApi, AIFilterLabel, aiFilterTabSelected, DefaultAiFilterEnabled, onVisibleChange, handleOpenFeedbackModal, dispatch])

  const OverlayContent = useMemo(() => {
    if (showAiFilter) {
      return FilterOverlayLayout
    }
    return <FilterContextProvider inputRef={inputRef}>
      <MainMenu callListApi={callListApi} />
    </FilterContextProvider>
  }, [FilterOverlayLayout, callListApi, showAiFilter])

  const FilterButton = useMemo(() => {
    if (showAiFilter) {
      return <MainBtn type='primary' leadingIcon={LeadingIconForButton} data-intercom-target="Top add filter">
      Filters <ChevronDown />
    </MainBtn>
    }
    return <Button type='primary' icon={<FilterIcon />} data-intercom-target="Top add filter">
    Filters <ChevronDown />
  </Button>
  }, [LeadingIconForButton, showAiFilter])

  return (
    <>
      <CommonModal
        title="Filter AI Feedback"
        subtitle={`Our AI is still learning and improving. If the results weren't what you expected, please help us by providing your feedback`}
        isModalOpen={openModal}
        handleOk={handleFeedbackFormSubmit}
        handleCancel={() => setOpenModal(false)}
        actionButtonTitles={{
          ok: 'Submit',
        }}
        disabled={disableSubmit}
      >
        <FormContainer>
          <Form.Item label='What were you trying to achieve?' name="achieve">
            <StyledTextArea
              autoSize={{
                maxRows: 2,
                minRows: 2,
              }}
              placeholder="Placeholder"
              maxLength={500}
            />
          </Form.Item>

          <Form.Item label='How can we improve?' name="improve">
            <StyledTextArea
              autoSize={{
                maxRows: 2,
                minRows: 2,
              }}
              placeholder="Placeholder"
              maxLength={500}
            />
          </Form.Item>
        </FormContainer>
      </CommonModal>
      <Dropdown
        overlayClassName="multi-column-menu mega-filter"
        overlay={OverlayContent}
        trigger={['click']}
        visible={
          id === 'topLevelFilterBtn'
            ? megaTopDropdownVisible
            : megaBottomDropdownVisible
        }
        onVisibleChange={filtersLockedModal ? undefined : onVisibleChange}
        align={dropdownOffsetVal}
        destroyPopupOnHide
      >
        {id === 'topLevelFilterBtn' ? (
          FilterButton
        ) : (
          <ButtonWrapper
            className="filter-spacing add-btn"
            size="small"
            data-intercom-target="Bottom add filter"
            icon={<AddFilterIcon />}
          >
            Add filter
          </ButtonWrapper>
        )}
      </Dropdown>
    </>
  );
}
export default MegaFilterDropdown
