import React, { createContext, useContext, useMemo, useState } from 'react'

type TTopBannerContext = {
	taraBatchLimitOpen: boolean
	setTaraBacthLimitOpen: React.Dispatch<React.SetStateAction<boolean>>
}

const defaultValue: TTopBannerContext = {
	taraBatchLimitOpen: false,
	setTaraBacthLimitOpen: () => null,
}

const TopBannerContext = createContext<TTopBannerContext>( defaultValue )

export const TopBannerContextProvider = ( { children }: { children: React.ReactNode } ) => {
	const [ taraBatchLimitOpen, setTaraBacthLimitOpen ] = useState( false )

	const value: TTopBannerContext = useMemo( () => ( {
		taraBatchLimitOpen,
		setTaraBacthLimitOpen,
	} ), [
		taraBatchLimitOpen,
		setTaraBacthLimitOpen,
	] )
	
	return (
		<TopBannerContext.Provider value={ value }>
			{ children }
		</TopBannerContext.Provider>
	)
}

export const useTopBannerContext = () => {
	const context = useContext( TopBannerContext )

	if ( context === undefined ) {
		throw new Error( 'useTopBannerContext must be used within TopBannerContextProvider' )
	}
	
	return context
}