/* eslint-disable no-prototype-builtins */
/* eslint-disable no-nested-ternary */
import React, { useCallback, useEffect, useMemo, memo, useState } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { Dropdown, Menu, Button, Checkbox, Tooltip } from 'antd'
import { SearchOutlined } from '@ant-design/icons'
import isArray from 'lodash/isArray'
import findIndex from 'lodash/findIndex'
import isEqual from 'lodash/isEqual'
import sortBy from 'lodash/sortBy'
import { ViewportList } from 'react-viewport-list';

import {
  DebounceInputComponent,
  MenuItemGroupWrapper,
  LoaderMenuItem,
  SelectAllAndClear,
  OverThresholdText,
  bringSelectedItemsToTop,
  bringMissingItemsToTop,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import { handleDefault, notInOperators, isOptionsPredefined, screenNameAttributes, filterTextByOption, getEnvTooltip, viewTypeUtils } from 'components/shared/GlobalFilter/components/utils'
import { withContextProps } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/FilterContextProvider'
import { MenuItem } from 'components/shared/GlobalFilter/components'
import { resetFetchedPropertyByKey } from 'redux/actions/filter'
import { operator } from 'components/shared/GlobalFilter/components/data-structures-v2';
import { getRenamedDeviceName } from 'Utils/helpers/commonUtils'
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip';

import isObject from 'lodash/isObject';

import useCustomLabels from 'hooks/useCustomLabels';
import { capitalizeEnvString } from 'components/features/setting/AppSetting/NewRecordingSection/DebounceSearch'
import { updateActivityFilterSegment } from 'redux/actions/megaFilter'
import { capitalize } from 'lodash'
import { useAppliedFilterContext } from 'components/shared/GlobalFilter/context/AppliedFilterContext'
import classNames from 'classnames'
import { NoCustomUserIdMessage } from 'Utils/helpers/userIdUtils'
import { StyledPropertyPlaceholder } from '../NestedFiltering/Style'
import { webScreenAttribtues } from '../../../MegaFilterDropdownV2/MainMenu'

const getScreenOriginalName = (renameScreenObj, screenName)=> Object.keys(renameScreenObj).find(key => key === screenName);
const noMatchingFilterMenu = (label)=> <span className="no-filter-text"> No matching {label} </span>

// Normalize time format for comparison (e.g., "1AM", "1 AM", "1am" all become "1am")
const normalizeTimeValue = (value) => {
  if (typeof value !== 'string') return value;
  return value.replace(/\s+/g, '').toLowerCase();
};

// Convert hour values to valueMapping format (e.g., "10AM", "10am", "10 am" → "10 AM")
const toHourDisplayFormat = (value) => {
  if (typeof value !== 'string') return value;
  return value.replace(/(\d+)\s*(am|pm)/i, (_, hour, period) => `${hour} ${period.toUpperCase()}`);
};

const FilterDropdown = (props) => {
  const dispatch = useDispatch()
  let disabled; let valueForCompare
  const firstAndPreviousKey = screenNameAttributes?.filter(value => value !== 'session_screen_list' && value !== 'screen_name')
  const {
    onVisibleChange,
    handleApply,
    visible,
    setSelectedOptions,
    selectedOptions,
    editFieldVisibility,
    filterTitleNew,
    titleRenderIfArray,
    // rest of the props
    keyName,
    value = [],
    attribute,
    isUserPropertyValue,
    operatorData,
    isMultiSelect,
    propertyName,
    id,
    filterData = [],
    isEventProperty,
    isScreenProperty,
    eventValue,
    isUserPropertyName,
    setWhereClicked,
    setPropertyValue,
    setPropertyName,
    toggleEditFieldVisibility,
    operatorChangeData,
    propValue,
    placeholderText,
    setOperatorData,
    activityPropertyIndex,
    activityFilterIndex,
    propFieldVisibility,
    isScreenPropertyValue,
  } = props
  const {
    // context props
    resetFieldsAndCallApi,
    handleSearchInputProps,
    searchAttrInputText,
    isEmptyMessage,
    loading,
    fetchedList
  } = props

  let fetchedListCopy = fetchedList

  const {
    screenRenamedList,
    commonReducer: { eventPropertyList },
    appFilter
  } = useSelector((state) => state);
  const [selectedOptionsReceived, setSelectedOptionsReceived] = useState(false);
  const activityFilter = useMemo(() => (appFilter['user'].activityFilterList) || [], [appFilter]);
  const capitalizeTitleAttributeList = ['session_recorded_weekday'];
  const { viewOnly, disabledFilterMessage} = useAppliedFilterContext();
  
  const {
    megaFilteredSessionLabels,
    filteredUserLabels,
    selectedLabels,
    setSelectedLabels,
    compareLabels,
  } = useCustomLabels();

  // to make sure the fetchListCopy is updated with selectedOptions once
  useEffect(() => {
    if(value?.length > 0) {
      setSelectedOptionsReceived(true);
    }
    else {
      setSelectedOptionsReceived(false);
    }
    return () => {
      setSelectedOptionsReceived(false);
    }
  }, [selectedOptions])
  
  // for user name menu items with Object{id, uxcamuserid}
  const processArrayChildren = (arr) => {
    return arr.map((child) => {
      if (_.isObject(child)) {
        return child.batch_id || child.uxcamuserid || child.id;
      } else {
        return child;
      }
    });
  };

  const isEventActivityScreen = attribute === 'event_name' && propertyName === 'activity';
  const processSelectedOption = (selectedOptionsArgs) => {
    if (
      isOptionsPredefined(attribute) &&
      notInOperators.includes(operatorData.attribute)
    ) {
      return selectedOptionsArgs ? selectedOptionsArgs.map(
        (option) => option.charAt(0).toUpperCase() + option.slice(1)
      ) : []
    }
    return selectedOptionsArgs;
  };

  fetchedListCopy = useMemo(() => bringSelectedItemsToTop(fetchedListCopy, processSelectedOption(selectedOptions)), [fetchedListCopy, selectedOptionsReceived, visible]);
  switch (id) {
    case 'userpropertyname':
    case 'eventpropertyname':
    case 'utmpropertyname':
    case 'userfirstutmname':
    case 'sessionscreenpropertyname':
    case 'customscreenpropertyname':
      valueForCompare = filterData?.property?.name
      break
    case 'userpropertyvalue':
    case 'eventpropertyvalue':
    case 'utmpropertyvalue':
    case 'userfirstutmvalue':
    case 'sessionscreenpropertyvalue':
    case 'customscreenpropertyvalue':
      valueForCompare = filterData?.property?.value
      break
    default:
      valueForCompare = filterData?.value
      break
  }
  if (isMultiSelect) {
    disabled =
      !selectedOptions?.length ||
      (!editFieldVisibility &&
        valueForCompare &&
        selectedOptions &&
        isArray(selectedOptions) &&
        isArray(valueForCompare) &&
        isEqual(selectedOptions?.sort(), valueForCompare?.sort()))
  }

  // handle selection for multi select checkboxs
  const handleSelectedOptions = useCallback(
    (val, alternativeVal) => {
      let selectedOptionsNew
      const screenName = getScreenOriginalName(screenRenamedList, val) || val

      // For predefined options, use normalized comparison to handle case/space variations
      const usesNormalizedComparison = isOptionsPredefined(attribute) && attribute !== 'uxcamuserid_cohort' && attribute !== 'viewtype';

      // For uxcamuserid, check against both val and alternativeVal to handle cases where
      // selectedOptions contains either uxcamuserid or name
      let isAlreadySelected;
      if (usesNormalizedComparison) {
        isAlreadySelected = selectedOptions?.some(opt => normalizeTimeValue(opt) === normalizeTimeValue(screenName));
      } else if (alternativeVal) {
        // Check if either val (uxcamuserid) or alternativeVal (name) exists in selectedOptions
        isAlreadySelected = selectedOptions?.includes(screenName) || selectedOptions?.includes(alternativeVal);
      } else {
        isAlreadySelected = selectedOptions?.includes(screenName);
      }

      if (isAlreadySelected) {
        if (usesNormalizedComparison) {
          selectedOptionsNew = selectedOptions.filter((v) => normalizeTimeValue(v) !== normalizeTimeValue(screenName));
        } else if (alternativeVal) {
          // Remove both val (uxcamuserid) and alternativeVal (name) from selectedOptions
          selectedOptionsNew = selectedOptions.filter((v) => v !== screenName && v !== alternativeVal);
        } else {
          selectedOptionsNew = selectedOptions.filter((v) => v !== screenName);
        }
      } else if (selectedOptions) {
        const addedValue = attribute === 'session_recorded_hour_of_user' ? toHourDisplayFormat(screenName) : screenName;
        selectedOptionsNew = [...selectedOptions, addedValue]
      } else {
        selectedOptionsNew = [attribute === 'session_recorded_hour_of_user' ? toHourDisplayFormat(val) : val]
      }
      setSelectedOptions(selectedOptionsNew)
  },
    [selectedOptions, setSelectedOptions, screenRenamedList, attribute],
  )

  const handleSelectAllOptions = () => {
    setSelectedOptions(processArrayChildren(fetchedListCopy));
  }

  const checkSelectDisabled = useMemo(() => {
    if(selectedOptions?.length !== fetchedListCopy.length) return false;
    return isEqual(sortBy(selectedOptions), sortBy(processArrayChildren(fetchedListCopy)));
  }, [selectedOptions, fetchedListCopy]);

  const handleMenuClick = useCallback(async ({ key }) => {
    await setSelectedOptions(key)
    if (
      id === 'eventpropertyname' ||
      id === 'eventproperty' ||
      id === 'event_custom_property' ||
      id === 'utm' ||
      id === 'user_first_utm' ||
      id === 'session_screen_with_property' ||
      id === 'session_screen_with_property_list' ||
      isUserPropertyName
    ) {
      await setPropertyName(key)
      if (propValue && !notInOperators.includes(operatorData.attribute))
        handleApply(null, key)
      else {
        if(toggleEditFieldVisibility) toggleEditFieldVisibility(true)
        setPropertyValue()
        if (id === 'eventpropertyname') {
          const opIndx = findIndex(eventPropertyList, { propertyName: key });
          if (opIndx > -1) {
            const customOpType = eventPropertyList[opIndx].propertyType
            setOperatorData(operator[customOpType][0])
          }
          dispatch(resetFetchedPropertyByKey('eventpropertyvalue'))
          setWhereClicked(true)
        }
      }
    }
    onVisibleChange(false)
  }, [setSelectedOptions, id, isUserPropertyName, onVisibleChange, setPropertyName, propValue, operatorData.attribute, handleApply, toggleEditFieldVisibility, setPropertyValue, eventPropertyList, dispatch, setWhereClicked, setOperatorData])
  if (attribute === 'event_name' && !isEventProperty)
    // fetchedListCopy = fetchedListCopy.filter( (v) => !['rageTap', 'UI Freeze'].includes(v) )
  if (attribute === 'user_custom_property')
    fetchedListCopy = fetchedListCopy.filter( (v) => !['alias', 'kUXCam_UserIdentity'].includes(v) )
  useEffect(() => {
    if ((isEventProperty || isUserPropertyValue || isScreenProperty) && propertyName)
      setSelectedOptions([])
  }, [propertyName, operatorChangeData])

  const selectedOptionsCopy = useMemo(() => [...selectedOptions], [selectedOptions]);
  
  useEffect(() => {
    if (visible) {
      if (editFieldVisibility) {
        setSelectedOptions([]);
        onVisibleChange(true);
      } else if (!editFieldVisibility) {
        if (keyName === 'property') {
          if (value) setSelectedOptions(value)
          return
        }
        if(attribute === 'viewtype'){
            setSelectedOptions(viewTypeUtils.getTitles(value));
            return;
        }
        if(attribute === 'session_recorded_hour_of_user' && isArray(value)){
            setSelectedOptions(value.map(toHourDisplayFormat));
            return;
        }
        setSelectedOptions(value);
      }
    }
    if (attribute === 'custom_label' || attribute === 'user_custom_label' && selectedOptionsReceived) {
      megaFilteredSessionLabels?.sort((a, b) =>
        compareLabels(selectedOptionsCopy, a, b)
      );
      filteredUserLabels?.sort((a, b) =>
        compareLabels(selectedOptionsCopy, a, b)
      );
    }
  }, [visible, editFieldVisibility, eventValue, selectedOptionsReceived]);

// * CX-1876: handles the filter visibility on activity segment changes
    useEffect(() => {
        const timeout = setTimeout(() => {
            if (activityFilter?.length > 0 && activityFilter[activityFilterIndex]?.filters?.find((i, index) => index === activityPropertyIndex && i.attribute === attribute && i.open && operatorData?.isSearchable)) {
                resetFieldsAndCallApi({ isSearchable: true });
                onVisibleChange(true);
                //* reset the segment
                dispatch(updateActivityFilterSegment(
                    activityFilter[activityFilterIndex]?.filters?.map(i => ({ ...i, open: false })),
                    activityFilterIndex,
                    false
                ))
            }
        }, 500)

    return ()=> clearTimeout(timeout)
  },[activityFilter, attribute, operatorData?.isSearchable, resetFieldsAndCallApi, onVisibleChange, dispatch ,activityPropertyIndex, activityFilterIndex])
  const renderView = useMemo(() => {
      if (isEmptyMessage && !fetchedListCopy?.length ) return noMatchingFilterMenu(keyName)
      if (!fetchedListCopy?.length && isObject(fetchedListCopy[0])) return noMatchingFilterMenu(keyName)
      if (fetchedListCopy?.length) {
        fetchedListCopy = bringMissingItemsToTop(fetchedListCopy, selectedOptionsCopy, attribute);
        if (attribute === 'session_recorded_hour_of_user') {
          const seen = new Set();
          fetchedListCopy = fetchedListCopy.map(toHourDisplayFormat).filter(item => {
            if (seen.has(item)) return false;
            seen.add(item);
            return true;
          });
        }
      }
      const isRageActivityEvent = attribute === 'event_name' && propertyName === 'activity';
      if (isMultiSelect) {
        return <div>
          {!!fetchedListCopy?.length >= 1
            ? (
            <ViewportList
              items={fetchedListCopy}
            >
              {
                (data) => {
                  let key = data; let title = data; let description; let showItalicAsterisk = false
                  if ( attribute === 'uxcamuserid_cohort' ) {
                    key = data.id
                    title = data.name
                    description = data.description
                  }
                  if ( attribute === 'batch_id' ) {
                    key = data.batch_id
                    title = data.batch_name
                  }
                  if (data.uxcamuserid) {
                    key = data.uxcamuserid
                    // Determine the attribute type based on properties
                    const hasNameProperty = data.hasOwnProperty('name')
                    const hasCustomUserIdProperty = data.hasOwnProperty('hasCustomUserId')
                    
                    let attributeType = ''
                    
                    if (hasNameProperty && data.uxcamuserid) {
                        // If value has minimum of 2 properties name and uxcamuserid then its a uxcamuserid attribute
                        attributeType = 'uxcamuserid'
                    } else if (hasCustomUserIdProperty && data.uxcamuserid) {
                        // If value has minimum of 2 properties hasCustomUserId and uxcamuserid then its a uxcam_user_id attribute
                        attributeType = 'uxcam_user_id'
                    }

                    if(attributeType === 'uxcam_user_id'){
                        title = data.uxcamuserid
                        description = !data.hasCustomUserId ? NoCustomUserIdMessage : null
                        showItalicAsterisk = !data.hasCustomUserId 
                    }else{
                        title = attributeType === 'uxcam_user_id' ? data.uxcamuserid : data.name
                        description = data.name === data.uxcamuserid ? NoCustomUserIdMessage : null
                        showItalicAsterisk = data.name === data.uxcamuserid // * it means custom user id is not set
                    }
                  }
                  /* 
                  isRageActivityEvent -> edge case - this is for if event name is rageTap with property name activity 
                  */
                  if (screenNameAttributes.includes(attribute) || isRageActivityEvent || attribute === 'event_custom_property' || propertyName === 'screen') {
                    title = screenRenamedList[data] || data
                    description = data
                  }
                  
                  if(attribute === 'environment'){
                    title = capitalizeEnvString(data)
                    description = getEnvTooltip(data)
                  }
                  if(data === '__undefined__'){
                    if (attribute === 'userpropertyvalue' && propertyName === 'kUXCam_UserIdentity') {
                      description = 'Users without an ID set by the API at the time of session.';
                    } else {
                      description = 'Users without specified value for the custom property at the time of session.';
                    }
                    // title = <Tooltip overlayClassName="undefined_tooltip_content" title={tooltiptitle}><em>{data}</em></Tooltip>
                  }
                  if (['device_class', 'device_model'].includes(attribute)) title = getRenamedDeviceName(data)
                  if (isOptionsPredefined(attribute) && attribute !== 'uxcamuserid_cohort' && attribute !== 'viewtype' ) key = data.toLowerCase()

                  // Check if option is selected using normalized comparison for predefined options
                  const usesNormalizedComparison = isOptionsPredefined(attribute) && attribute !== 'uxcamuserid_cohort' && attribute !== 'viewtype';

                  // For uxcamuserid, check against both uxcamuserid and name
                  let isSelected = false;
                  if (isArray(selectedOptionsCopy) && selectedOptionsCopy?.length) {
                    if (usesNormalizedComparison) {
                      isSelected = selectedOptionsCopy.some(opt => normalizeTimeValue(opt) === normalizeTimeValue(key));
                    } else if (data?.uxcamuserid && data?.name) {
                      // For uxcamuserid filters: check if selectedOptions includes either uxcamuserid OR name
                      isSelected = selectedOptionsCopy.includes(data.uxcamuserid) || selectedOptionsCopy.includes(data.name);
                    } else {
                      isSelected = selectedOptionsCopy.includes(key);
                    }
                  }

                  return (
                    <li key={key}>
                      <Checkbox
                        checked={isSelected}
                        onChange={() => handleSelectedOptions(key, data?.name)}
                      >
                        <span className='checkbox-label'>
                          <CellOverflowTooltip
                            width={175}
                            text={title}
                            value={ capitalizeTitleAttributeList.includes(attribute) ?  capitalize(title) : title }
                            tooltipElement={ description || title }
                            className={ classNames( showItalicAsterisk && "text-italic-asterisk" )}
                            placement={ webScreenAttribtues.includes(attribute) ? 'topLeft' : 'right' }
                          /></span>
                      </Checkbox>
                    </li>
                  )
                }
              }
            </ViewportList>
            )
            : isEmptyMessage && noMatchingFilterMenu(keyName)}
        </div>
      }
      return fetchedListCopy?.length ? fetchedListCopy.map((data) => <MenuItem key={data}>{data}</MenuItem>) : ''
    }, [isEmptyMessage, fetchedListCopy, isMultiSelect, selectedOptionsCopy, attribute, handleSelectedOptions, propertyName, screenNameAttributes])
  const menu =
    <Menu
      selectedKeys={isArray(value) ? value : [value]}
      onClick={handleMenuClick}
    >
      <LoaderMenuItem spinning={loading}>
        <MenuItemGroupWrapper
          // placeholder={placeholderText || setPlaceholder('Search', filterTitleNew)}
          placeholder='Search'
          onChange={(e) => handleSearchInputProps(e.target.value)}
          value={searchAttrInputText}
          id="filtered-options"
          editFieldVisibility={editFieldVisibility}
          headerChildren={
          <>
            {
              fetchedListCopy.length > 500 && (
                <OverThresholdText 
                  text='Not all results are displayed - type to search for more.'
                />
              )
            }
            <SelectAllAndClear
              operatorAttribute={isMultiSelect ? operatorData.attribute : 'contains'}
              isOperatorRadio={false}
              newFetchedList={fetchedListCopy}
              operatorType={false}
              handleSelectAllOptions={handleSelectAllOptions}
              handleClearAllOptions={() => setSelectedOptions([])}
              disableSelect={checkSelectDisabled}
              disableClear={selectedOptionsCopy.length <= 0}
            />
          </>
          }
          >
          {renderView}
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
      {isMultiSelect && (
        <div key="button-bar" className='button-bar'>
          <Button type='primary-outline' onClick={() => onVisibleChange(false)}>
            Cancel
          </Button>
          <Button
            disabled={disabled}
            type='primary'
            onClick={() => {
              resetFieldsAndCallApi({})
              handleApply(selectedOptions)
            }}
          >
            Apply
          </Button>
        </div>
      )}
    </Menu>
  const fieldVisibility = useMemo(() => isScreenPropertyValue ? propFieldVisibility : editFieldVisibility, [isScreenPropertyValue, propFieldVisibility, editFieldVisibility])
  return (
     <Tooltip title={disabledFilterMessage} >
     {['alias', 'kUXCam_UserIdentity'].indexOf(value) > -1 ? titleRenderIfArray : 
     <Dropdown
      overlay={menu}
      overlayClassName={`multi-column-menu mega-segment-menu filter-applied-segment-menu ${editFieldVisibility ? 'dropdown-without-search' : ''}` }
      overlayStyle={{maxWidth: '300px', minWidth:'auto'}}
      onVisibleChange={(v) => {
        if (v) resetFieldsAndCallApi({ isSearchable: true })
        onVisibleChange(v)
      }}
      visible={visible}
      trigger={['click']}
      disabled={viewOnly}
    >
      {fieldVisibility ? (
        <DebounceInputComponent
          prefix={<SearchOutlined />}
          // placeholder={placeholderText || `Search ${filterTitleNew}`}
          placeholder='Enter value'
          className="filter-input-width"
          onClick={() => onVisibleChange(true)}
          onChange={(e) => handleSearchInputProps(e.target.value)}
          value={searchAttrInputText}
          editFieldVisibility={fieldVisibility}
        />
      ) : (
        <a href='#!' onClick={handleDefault}>{
            titleRenderIfArray === 'select_activity' ? 
            <StyledPropertyPlaceholder >
                select value
            </StyledPropertyPlaceholder> : titleRenderIfArray
            }</a>
      )}
    </Dropdown>}
    </Tooltip>
  )
}

export default withContextProps(memo(FilterDropdown))
