/* eslint-disable prefer-destructuring */
/* eslint-disable react/jsx-props-no-spreading */
import React, {
  useState,
  useCallback,
  useMemo,
  useEffect,
  useRef,
  memo,
} from 'react';

import { useDispatch, useSelector } from 'react-redux';

import {
  useSessionVideoControlls
} from 'components/shared/Sessions/Context';

import useAISessionColumns from 'components/features/aiSessions/hooks/useAISessionColumns';
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'

import { usePagination } from 'components/features/issues/components/ReactTable/usePagination';
import { addSessionId } from 'redux/actions/common';
import { DashboardTable, StylesProvider } from 'uxcam-frontend-components';
import { schematicFrameworks } from 'components/shared/Sessions/Video/utils';
import { PLAYLIST_STATUS, useAISessionUtils } from 'components/shared/GlobalFilter/components/aiSessionFilter/AISessionUtilsContext';
import { useFloatingToolbarContext } from 'components/IntegratePages/layout/FloatingToolbar/context';
import { useAISessionTableHelper } from './utils';
import CornerDropdown from './CornerDropdown'
import SelectedToolbarContent from './ToolbarContent';

import {
  SessionTableWrapper,
} from './styles';
import { trackAISessionSelect } from '../../components/utils';

const SessionTable = ({
  data,
  expanded,
  isLoading,
  setSortedBy,
  sortedBy,
  openIOSReplayModal,
  onResetSuccess,
}) => {
  const dispatch = useDispatch();
  const {
    urlReducer: urlQuery,
    selectedSessionReducer: selectedSession,
    appFilter: {session: { segment: sessionSegment}}
  } = useSelector((state) => state);
  const prevPaginationRef = useRef();
  const { setSelected } = useAISessionWatchlist()
  const { setSessionLockedModal, aiSessionFeatureAllowed } = useRestrictionContext();
  const batchesEnabled = aiSessionFeatureAllowed

  const newPagination = useMemo(() => data?.pagination ? data?.pagination : prevPaginationRef?.current, [data?.pagination])

  const headers = useMemo(() => data?.header?.filter((item) => item.attribute !== 'video' && item.title !== 'Rec'), [data?.header]);
  const {pagination, setPagination} = usePagination();
  const { sessionpage, sessionid: sessionIdURL, parentType } = urlQuery;
  const moveToRef = useRef();
  const { prevSessionCallbackRef, nextSessionCallbackRef } =
    useSessionVideoControlls();
  const { setOpen, setContent } = useFloatingToolbarContext()

  const sessionPage = React.useMemo(() => Number(sessionpage), [sessionpage]);
  const { setUtils, rowselection, setRowSelection } = useAISessionUtils();

  const {
    handleRowClick,
    handleUserClick,
    getUserPageUrl,
    navigatePage,
    onItemSetActive,
    pageChange,
    onItemPlay,
    onItemPause,
  } = useAISessionTableHelper({ expanded });

  const sessionIndex = useMemo(
    () => data?.body?.findIndex(({ sessionid }) => sessionid === sessionIdURL),
    [data, sessionIdURL]
  );

  const handleSchematicReplay = (e, platform, sdkPluginType) => {
    // Skip on modifier clicks so the session opens in a new tab instead of the modal.
    if (e.metaKey || e.ctrlKey || e.shiftKey) return;
    if (e.button === 0 && platform === 2 && schematicFrameworks.includes(sdkPluginType?.toLowerCase())) {
      openIOSReplayModal();
    }
  }

  const handleClickLockedSession = useCallback( () => setSessionLockedModal( true ), [ setSessionLockedModal ] )

  const handleNext = useCallback(() => {
    moveToRef.current = undefined;
    if (!data) {
      return;
    }
    if (sessionIndex === -1) {
      return;
    }
    const nextIndex = sessionIndex + 1;
    const isLast = data?.body?.length === nextIndex;
    if (isLast) {
      moveToRef.current = 'first';
      navigatePage(sessionPage + 1);
    } else {
      const nextId = data.body[nextIndex].sessionid;
      const isViewed = data.body[nextIndex].isViewed;
      onItemSetActive(nextId, true, !isViewed);
      // if (videoElemRef?.current) videoElemRef.current.play();
    }
  }, [onItemSetActive, sessionPage, sessionIndex, data]);

  useEffect(() => {
    if (moveToRef.current && data?.body?.length) {
      let displaySession;
      if (moveToRef.current === 'first') {
        displaySession = data.body[0];
      } else {
        displaySession = data.body[data.body.length - 1];
      }

      if (displaySession) {
        onItemSetActive(
          displaySession.sessionid,
          true,
          !displaySession?.isViewed
        );
      }
      moveToRef.current = undefined;
    }
  }, [data]);

  const handlePrev = useCallback(() => {
    moveToRef.current = undefined;
    if (!data) {
      return;
    }
    if (sessionIndex === -1) {
      return;
    }
    const prevIndex = sessionIndex - 1;
    const prevPage = prevIndex === -1;
    if (prevPage) {
      if (sessionPage === 0) {
        return;
      }
      moveToRef.current = 'last';
      // move to prev page
      navigatePage(sessionPage - 1);
    } else {
      const prevId = data.body[prevIndex].sessionid;
      const isViewed = data.body[prevIndex].isViewed;
      onItemSetActive(prevId, true, !isViewed);
    }
  }, [onItemSetActive, sessionPage, sessionIndex, data]);

  useEffect(() => {
    prevSessionCallbackRef.current = handlePrev;
  }, [handlePrev]);

  useEffect(() => {
    setPagination({...pagination, pageIndex: parseInt(sessionpage || 1, 10)})
    // to clear out selected values on pagination update
    dispatch(addSessionId([]));
  }, [sessionpage]);

  useEffect(() => {
    if (moveToRef.current && data?.body?.length) {
      let displaySession;
      if (moveToRef.current === 'first') {
        displaySession = data.body[0];
      } else {
        displaySession = data.body[data.body.length - 1];
      }

      if (displaySession) {
        onItemSetActive(
          displaySession.sessionid,
          true,
          !displaySession?.isViewed
        );
      }
      moveToRef.current = undefined;
    }
  }, [data]);

  useEffect(() => {
    if(newPagination){
      prevPaginationRef.current = newPagination;
    }
  }, [newPagination]);

  const [cachedHeadersData, setCachedHeadersData] = useState([]);

  useEffect(() => {
    if (headers) setCachedHeadersData(headers);
  }, [headers])

  const highlightActiveRow = useCallback((row) => row.sessionid === sessionIdURL, [sessionIdURL])
  const columns = useAISessionColumns((headers || cachedHeadersData || []), expanded);
  const rowsData = useMemo(
    () =>
      data?.body?.map((item) => ({
        ...item,
        onItemPlay: (args) => (
          onItemPlay(
            args?.sessionId,
            args?.isActive,
            args?.isViewed,
            args?.userTime
          )
        ),
        onItemPause: (args) => onItemPause(args?.sessionId),
        handleUserClick: (e, userId) => handleUserClick(e, userId),
        getUserPageUrl: (userId) => getUserPageUrl(userId),
        onRowClick: (row, e) => {
          const { sessionid, isViewed, sessionLocked, platform, sdkPluginType } = row;
          if (!sessionLocked) {
            setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.INACTIVE }));
          
            dispatch(trackAISessionSelect({
                sessionId: sessionid,
                aiAnalyzed: item.sessionanalyzedbyai,
                containsVideo: item.video,
                duration: item.sessionDuration, 
                gestureCount: item.totalGesture,
                parentType, 
                sessionSelectedFrom: 'list',
                filtersApplied: sessionSegment,
                isRageTap: item.isRageTap,
                isUiFreeze: item.isuifreeze,
                isCrashed: item.crashed,
            }))
            handleRowClick(e, sessionid, !isViewed);
            handleSchematicReplay(e, platform, sdkPluginType);
          } else {
            handleClickLockedSession();
          }
        },
        highlightActiveRow,
      })),
    [data, highlightActiveRow, handleClickLockedSession, handleUserClick, getUserPageUrl, handleRowClick, handleSchematicReplay, onItemPause, onItemPlay, setUtils ,parentType, sessionSegment, dispatch ]
  );

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number)
    const filteredBody = data?.body?.filter((el, index) => selectedRowId.includes(index))
    setSelected( filteredBody )
  }, [rowselection])

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number)
    const filteredBody = data?.body?.filter((el, index) => selectedRowId.includes(index))
    const selectedSessionIds = filteredBody?.map((el) => el.sessionid)
    if ( selectedSessionIds?.length ) {
      setOpen( true )
      setContent( <SelectedToolbarContent /> )

    } else {
      setOpen( false )
      setContent( null )
    }
  }, [rowselection, setContent, setOpen, setSelected, data])

  useEffect(() => {
    const selectedRowId = Object.keys(rowselection).map(Number);
    if(selectedRowId.length > selectedSession) setRowSelection([]);
  }, [selectedSession])

  const stickyHeaders = [ 'select', 'sessionhashofuser' ]

  return (
    <SessionTableWrapper isEmpty={ rowsData && rowsData.length === 0 } data-batch={ batchesEnabled }>
      <StylesProvider>
        { rowsData && !expanded && (
          <CornerDropdown
            headers={ headers }
            onResetSuccess={onResetSuccess}
          />
        ) }
        <DashboardTable
          data={rowsData}
          columns={columns}
          sorting={sortedBy}
          setSorting={setSortedBy}
          resizeMode="onChange"
          isLoading={isLoading}
          expandedView={expanded}
          tableHeight='100%'
          pagination={{
            ...pagination,
            totalPagination: data?.pagination?.pages || 1,
          }}
          setPagination={setPagination}
          handleRouteUpdate={pageChange}
          stickyHeaders={ stickyHeaders }
          rowSelection={rowselection}
          setRowSelection={setRowSelection}
          emptyText={{message: 'No sessions match the current filters.'}}
          lastRowPagination
          enableSelection
          headIntercomTag='ai-table-head'
        />
      </StylesProvider>
    </SessionTableWrapper>
  );
};

export default memo(SessionTable);
