import { useQuery } from 'react-query';
import { axiosInstance } from 'services/globalInstance';

const getReplayInfo = async (postBody) => axiosInstance.post(`${process.env.PYTHON_API_URL}/users/replay_info`, postBody, {
    withCredentials: true,
    credentials: 'include',
  })
  .then(({ data: { data: respData } }) => respData)
  .catch((error) => 
    error?.response?.data
  );
export const useReplayInfo = (postBody, options) => useQuery(
    ["replay_info", postBody], 
    () => getReplayInfo(postBody), 
    {
        retry: true,
        refetchOnWindowFocus: false,
        staleTime: 5 * 60 * 1000, // 5 minutes
        cacheTime: 5 * 60 * 1000, // 5 minutes
        keepPreviousData: false,
        ...options,
    }
);  