import React from 'react'
import styled from 'styled-components'
import { StylesProvider, UFCTooltip } from 'uxcam-frontend-components'

interface IProps {
	summary: string
}

const StyledCell = styled.div`
	display: flex;
	height: 100%;
	width: 100%;
	justify-content: center;
	align-items: flex-start;
	flex-direction: column;
	flex-wrap: nowrap;
	font-size: 13px;
	line-height: 20px;
	min-height: 40px;
	padding: 0;

	white-space: nowrap;
	text-overflow: ellipsis;
	overflow: hidden;

	@supports (-webkit-line-clamp: 2) {
		overflow: hidden;
		text-overflow: ellipsis;
		white-space: initial;
		display: -webkit-box;
		-webkit-line-clamp: 2;
		-webkit-box-orient: vertical;
	}
`

const AISummaryCell = ( { summary }: IProps ) => {
	const value = summary || '-'
	return (
		<StylesProvider>
			<StyledCell>
				<UFCTooltip 
					title={ value }
					align={ { offset: [ 0, -10 ] } }
					arrowPointAtCenter
				>
					{ value }
				</UFCTooltip>
			</StyledCell>
		</StylesProvider>
	)
}

export default AISummaryCell