const adjustActivitySegmentDateRangeValue = (activityFilter:ActivityFilterPayloadType):ActivityFilterPayloadType => {
    const { activity_attribute_date_range, filters, value ,operator, attribute } = activityFilter;
    // * perform check for applied daterange 
    // * if daterange has label, then ignore the value {to and from} ,recalculate the value
    if (activity_attribute_date_range.labelId) {
      // * ensure which label is used and then  recalculate the value
        const dateRangeVal = datePresetsAbsoluteCD(activity_attribute_date_range.labelId as DATE_RANGE_LABEL);
        activity_attribute_date_range.value = {
                lower: dateRangeVal.from,
                upper: dateRangeVal.to
            }
    }
    return {
        attribute,
        operator,
        value,
        activity_attribute_date_range,
        filters
    }
}



const activityFilterSegmentSegregator = (appliedSegments: Array<ActivityFilterPayloadType | IFilter>):
{
    normalSegment: IFilter[];
    sessionSegment: IFilter[];
    eventSegment: IFilter[];
    smartEventSegment: IFilter[];
    activitySegment: ActivityFilterPayloadType[];
} => {
    const normalSegment: IFilter[] = [];
    const sessionSegment: IFilter[] = [];
    const eventSegment: IFilter[] = [];
    const smartEventSegment: IFilter[] = [];
    const activitySegment: ActivityFilterPayloadType[] = [];

    const listOfOldAttributes = Object.keys(userV2AttributeNewOldMap);
    const sessionActivityApplicableAttributes = [...listOfOldAttributes, 'screen_name']
    appliedSegments?.forEach(filter => {
        if (sessionActivityApplicableAttributes.includes(filter.attribute)) {
            sessionSegment.push(filter as IFilter)
        }
        else if (filter.attribute === 'event_name') {
            eventSegment.push(filter as IFilter)
        }
        else if (filter.attribute === 'nce_name') {
            smartEventSegment.push(filter as IFilter)
        }
        else if (hasActivityFilter([filter])) {
            activitySegment.push(filter as ActivityFilterPayloadType)
        } else {
            normalSegment.push(filter as IFilter)
        }
    }
    )
    return {
        normalSegment,
        sessionSegment,
        eventSegment,
        smartEventSegment,
        activitySegment
    }
}
export const adjustRawSegment = (rawSegment: Array<ActivityFilterPayloadType | IFilter>) => {
    const { normalSegment, sessionSegment, eventSegment, smartEventSegment, activitySegment } = activityFilterSegmentSegregator(rawSegment);

    const dateRangeAdjustedActivitySegment = activitySegment?.map((filter) => adjustActivitySegmentDateRangeValue(filter));

    const modifiedActivityFilterSegment = dateRangeAdjustedActivitySegment || [];

    if (sessionSegment.length) {
        const implementedSessionActivityFilterSegment = {
            ...activityFilterSelector.user_with_session_activity.defaultValue,
            filters: sessionSegment
        }
        modifiedActivityFilterSegment.push(implementedSessionActivityFilterSegment) 
    }

    if (eventSegment.length) {
        const implementedEventActivityFilterSegment = {
            ...activityFilterSelector.user_with_event_activity.defaultValue,
            filters: eventSegment
        }
        modifiedActivityFilterSegment.push(implementedEventActivityFilterSegment)
    }
    if (smartEventSegment.length) {
        const implementedSmartEventActivityFilterSegment = {
            ...activityFilterSelector.user_with_smart_event_activity.defaultValue,
            filters: smartEventSegment
        }
        modifiedActivityFilterSegment.push(implementedSmartEventActivityFilterSegment)
    }
    return {
        normalSegment,
        activitySegment: modifiedActivityFilterSegment,
    }
}
const normalizeValue = (value: string[]| string) => 
    Array.isArray(value) ? value.sort() : String(value);

const normalizeProperty = (property: any) => {
    if (!property) return property;
    const { name, value, ...rest } = property;
    return {
        ...rest,
        name,
        value: normalizeValue(value),
    };
};

const normalizeFilters = (filters:  Array<ActivityPropertyType>) =>
    sortBy(filters.map(({ value, property, isLocal: _iL, table: _t , open, ...rest }) => ({
        ...rest,
        ...(property && { property: normalizeProperty(property) }),
        ...( value &&{ value: normalizeValue(value) }) 
    })), [f => f?.attribute]);

const getModified = (segment: ActivityFilterPayloadType | IFilter) => {

    // Handle activity filters
    if (ActivityFilterAttributesList.includes(segment.attribute)) {
        const {
            activity_attribute_date_range,
            filters = [],
            active: _a,
            ...rest
        } = segment as ActivityFilterPayloadType;

        const result: any = cloneDeep(rest);

        if (activity_attribute_date_range) {
            const isLabelKnown = datePresetsAbsolute.some(
                preset => preset.id === activity_attribute_date_range.labelId
            );
        // * conditions: (for activityFilterSegments only)
        // * if activity_attribute_date_range has known labelId, don't compare value
        // * else compare value but don't compare labelId 
            const propToRemove = isLabelKnown ? 'value' : 'labelId';
            const { [propToRemove]: _, ...restDateRange } = activity_attribute_date_range;
            result.activity_attribute_date_range = restDateRange;
        }

        result.filters = normalizeFilters(filters);
        return result;
    }

    // Handle non-activity filters
    const {
        unit: _u,
        type: _t,
        filters = [],
        value,
        ...rest
    } = segment as IFilter;

    const result: any = cloneDeep(rest);

    if (filters.length) {
        result.filters = normalizeFilters(filters);
    }

    if (value !== undefined) {
        result.value = normalizeValue(value);
    }

    return result;
};
export const isEqualActualSegmentVSAppliedSegment = (
    rawActualSegment: Array<ActivityFilterPayloadType | IFilter>,
    rawAppliedSegment: Array<ActivityFilterPayloadType | IFilter>,
  ): boolean => {
    const actualSegment = sortBy( cloneDeep(rawActualSegment), o => o.attribute);
    const appliedSegment = sortBy( cloneDeep(rawAppliedSegment), o => o?.attribute);
  
    const hasActualActivity = hasActivityFilter(actualSegment);
    const hasAppliedActivity = hasActivityFilter(appliedSegment);
  
    const mapAndSort = (segment: typeof actualSegment) =>
      sortBy(segment.map(getModified), s => s?.attribute);
  
    // Case 1: Both segments either have or don't have activity filters
    const sameActivityPresence = hasActualActivity === hasAppliedActivity;
  
    if (sameActivityPresence) {
        if (actualSegment.length !== appliedSegment.length) return false;
      return isEqual(
        actualSegment.map(getModified),
        appliedSegment.map(getModified)
      );
    }
  
    // Case 2: Only one segment has activity filters
    const { normalSegment, activitySegment } = adjustRawSegment(actualSegment);
    const adjustedActual = [...activitySegment, ...normalSegment];
  
    if (adjustedActual.length !== appliedSegment.length) return false;
  
    return isEqual(
      mapAndSort(adjustedActual),
      mapAndSort(appliedSegment)
    );
  };
  

export const getSaveAsSegmentPayloadWithActivityFilterCheck = (
    activityFilterList: ActivityFilterPayloadType[],
    normalFilters: ActivityPropertyType[],
    isUserV2: boolean
) => {
    // * refactor payload 
    if (!isUserV2) return normalFilters;

    const modifiedActivityFilters = activityFilterList?.map(
        ({ filters, operator, value, activity_attribute_date_range , attribute}) => {
            const copyActivityProperty = cloneDeep(filters);
            const copyActivityDateRange = cloneDeep(activity_attribute_date_range);

            const payload = {
                attribute,
                operator,
                value,
                filters: map(copyActivityProperty, (i) => omit(i, ['open'])),
                activity_attribute_date_range: {
                    attribute: copyActivityDateRange.attribute,
                    operator: copyActivityDateRange.operator, // * static * should be between_dates
                    value: copyActivityDateRange.value,
                    tz: copyActivityDateRange?.tz || currentTimeZone,
                    labelId: copyActivityDateRange?.labelId || ''                   
                }
            }

            if (find(datePresetsAbsolute, (i) => i.id === activity_attribute_date_range.labelId)) {
                // * Recalculation of daterange required: value should be current date range 
                const now = new Date();
                const from = new Date();
                from.setDate(now.getDate() - 30);
                payload.activity_attribute_date_range.value={
                    lower: from,
                    upper: now
                }
            } 

            return payload;
        }
    );
    return [...normalFilters, ...modifiedActivityFilters];
}

