import React, { useState } from 'react';
import { Button, message } from 'antd';
import { DeleteOutlined } from '@ant-design/icons';
import { useSelector, useDispatch } from 'react-redux';
import { useMutation, useQueryClient } from 'react-query';

import { addSessionId, addUserId } from 'redux/actions/common';
import MarkMultipleLabelV2 from 'components/IntegratePages/layout/dashboardTopMenu/MarkMultipleLabel';
import DeleteSessionBox from 'components/common/deleteSession';
import ShareSession from 'components/common/shareSession';
import { axiosInstance } from 'services/globalInstance';
import { getSessionIdWithDate, getUserIdWithDate } from 'Utils/helpers/SessionUtils';

const baseUrl = process.env.DB_API_URL;

const UserAndSessionSelection = () => {
  const dispatch = useDispatch();
  const queryClient = useQueryClient();
  
  const {
    urlReducer,
    selectedSessionReducer: selectedSession,
    selectedUserReducer: selectedUser,
    profileReducer: user,
  } = useSelector((state) => state);
  const [deleteModalVisible, setDeleteModalVisible] = useState(false);
  const { parentType, appId } = urlReducer;
  const { name } = user;
  
  const sessionKey = parentType === 'aiSessionsList' ? 'aiSessionItems' : 'sessionItems'
  const sessionBodyKey = parentType === 'aiSessionsList' ? 'aiSessionsListReqBody' : 'sessionsListReqBody'
  let sessionQueryKey = ''
  let userQueryKey = ''
  try {
    sessionQueryKey = [sessionKey, JSON.parse(localStorage.getItem(sessionBodyKey))]
    userQueryKey = ['userList', JSON.parse(localStorage.getItem('usersListReqBody'))]
  } catch (err) {
    // silent fail
  }
  const sessionList = queryClient.getQueryData(sessionQueryKey);
  const userList = queryClient.getQueryData(userQueryKey);

  const onCancel = () => {
    [ 'sessionsList', 'aiSessionsList' ].includes( parentType )
      ? dispatch(addSessionId([]))
      : dispatch(addUserId([]));
    setDeleteModalVisible(false);
  };

  const { mutate, isLoading } = useMutation(
    ({ data }) =>
      axiosInstance({
        method: 'POST',
        url: `${baseUrl}/deletion_requests`,
        data,
        withCredentials: true,
      }),
    {
      onSuccess: (_, payload) => {
        message.success(`Session Deleted Successfully.`);
        const ids = payload.data.identifiers.map((item) => item.id);
        queryClient.setQueryData(sessionQueryKey, (oldData) => {
          const newData = oldData?.data?.data?.body?.filter((item) => !ids.includes(item.sessionid));
          return {
            ...oldData,
            data: {
              ...oldData.data,
              data: {
                ...oldData.data.data,
                body: newData,
              },
            },
          };
        });
        onCancel();
        queryClient.invalidateQueries(sessionQueryKey);
      },
      onError: (_err) => {
       onCancel();
        message.error(_err?.response?.data?.error?.message);
      },
    }
  );

  const { mutate: userDelete, isLoading: userLoading } = useMutation(
    ({ data }) =>
      axiosInstance({
        method: 'POST',
        url: `${baseUrl}/deletion_requests`,
        data,
        withCredentials: true,
      }),
    {
      onSuccess: (_, payload) => {
        message.success(`User Deleted Successfully.`);
        const ids = payload.data.identifiers.map((item) => item.id);
        queryClient.setQueryData(userQueryKey, (oldData) => {
          const newData = oldData?.data?.data?.body?.filter((item) => !ids.includes(item.uxcamuserid));
          return {
            ...oldData,
            data: {
              ...oldData.data,
              data: {
                ...oldData.data.data,
                body: newData,
              },
            },
          };
        });
        queryClient.invalidateQueries(userQueryKey);
        onCancel();
      },
      onError: (_err) => {
        message.error(_err?.response?.data?.error?.message);
        onCancel();
      },
    }
  );

  const deleteUsers = () => {
    const identifiers = getUserIdWithDate(selectedUser, userList?.data?.data?.body);
    const data = {
      table_name: 'user',
      app_id: appId,
      requested_by_user_name: name,
      identifiers
    }
    userDelete({ data });
  };
  const deleteSession = async () => {
    const identifiers = getSessionIdWithDate(selectedSession, sessionList?.data?.data?.body);
    const data = {
      table_name: 'session',
      app_id: appId,
      requested_by_user_name: name,
      identifiers
    }
    mutate({ data });
  };

  return (
    <>
      <div className="table-action-item-box">
        <span className="session-count-p">
          {`${
            [ 'sessionsList', 'aiSessionsList' ].includes( parentType )
              ? selectedSession.length
              : selectedUser.length
          }${
            [ 'sessionsList', 'aiSessionsList' ].includes( parentType )
              ? ` session${selectedSession?.length > 1 ? 's' : ''}`
              : ` user${selectedUser?.length > 1 ? 's' : ''}`
          }  selected`}
        </span>
        <MarkMultipleLabelV2 />
        {['sessionsList', 'usersList'].includes(parentType) && (
          <div className="table-action-btn">
            <Button
              icon={<DeleteOutlined />}
              onClick={() => setDeleteModalVisible(true)}
            >
              Delete
            </Button>
          </div>
        )}
        {[ 'sessionsList', 'aiSessionsList' ].includes( parentType ) && selectedSession.length < 2 && (
          <div className="table-action-btn">
            <ShareSession shareMultiple />
          </div>
        )}
      </div>
      <DeleteSessionBox
        title={
          parentType === 'usersList'
            ? `Delete ${selectedUser.length > 1 ? 'users' : 'user'}?`
            : `Delete ${selectedSession.length > 1 ? 'sessions' : 'session'}?`
        }
        content={
          parentType === 'usersList'
            ? `Do you want to delete ${selectedUser.length} selected ${
                selectedUser.length > 1 ? 'users?' : 'user?'
              } This action is irreversible.`
            : `Do you want to delete ${selectedSession.length} selected ${
                selectedSession.length > 1 ? 'sessions?' : 'session?'
              } This action is irreversible.`
        }
        onOk={parentType === 'usersList' ? deleteUsers : deleteSession}
        onCancel={onCancel}
        deleteLoading={parentType === 'usersList' ? userLoading : isLoading}
        deleteModalVisible={deleteModalVisible}
      />
    </>
  );
};

export default UserAndSessionSelection;
