// This logic handles duplicate legend item removal and legend item click/hover events handling for sunburst chart
const HighChartSunburstTooltip = (Highcharts) => {
    const H = Highcharts
    const {each} = H;
            const {defined} = H;
            const {merge} = H;
            const {pick} = H;

        H.Legend.prototype.getAllItems = function () {
            let allItems = [];
            each(this.chart.series, (series) => {
                const seriesOptions = series && series.options;
                if (series && pick(
                    seriesOptions.showInLegend, !defined(seriesOptions.linkedTo) ? undefined : false, true
                )) {
                    allItems = allItems.concat(
                        series.legendItems ||
                        (
                            seriesOptions.legendType === 'point' && series?.type === 'sunburst' ?
                                [...new Map(series.data.map(item =>
                                    [item['name'], item])).values()] :
                                series?.type === 'pie' ? series?.data : series
                        )
                    );
                }
            });
            return allItems.filter(item => item.name !== " ");
        }

        H.Legend.prototype.setItemEvents = function (item, legendItem, useHTML) {
            const legend = this;
            const {boxWrapper} = legend.chart.renderer;
            const activeClass = `highcharts-legend-${  item.series ? 'point' : 'series'  }-active`;
            const target = useHTML ? legendItem : item.legendItem.group;
            if (target) {
                H.addEvent(target.element, 'mouseover', (event) => {
                    const selectLegend = legendItem.textStr
                    const strLegendItemMouseOver = 'legendItemMouseOver';
                        const fnLegendItemClick = function () {
                            this.series ?  this.series.points.forEach((el) => {
                                if (el.name === selectLegend) {
                                    boxWrapper.addClass(activeClass);
                                    legendItem.css(merge(legend.options.itemHoverStyle));
                                    el.setState('hover');
                                }
                            }, this) : item && function (){
                                legendItem.css(merge(legend.options.itemHoverStyle));
                                boxWrapper.addClass(activeClass)
                                item.setState('hover');
                            }()
                        };
                    event = {
                        browserEvent: event
                    };
                    if (item.firePointEvent) { // point
                        item.firePointEvent(strLegendItemMouseOver, event, fnLegendItemClick);
                    } else {
                        H.fireEvent && H.fireEvent(item, strLegendItemMouseOver, event, fnLegendItemClick);
                    }
                })
                H.addEvent(target.element, 'mouseout', (event) => {
                    const selectLegend = legendItem.textStr
                    const strLegendItemMouseOut = 'legendItemMouseOut';
                        const fnLegendItemClick = function () {
                            this.series ? this.series.points.forEach((el) => {
                                if (el.name === selectLegend) {
                                    legendItem.css(merge(el.visible ? legend.itemStyle : legend.itemHiddenStyle));
                                    boxWrapper.removeClass(activeClass);
                                    el.setState();
                                }
                            }, this) : item && function (){
                                legendItem.css(merge(item.visible ? legend.itemStyle : legend.itemHiddenStyle))
                                boxWrapper.removeClass(activeClass)
                                item.setState()
                            }()
                        };
                    event = {
                        browserEvent: event
                    };
                    if (item.firePointEvent) { // point
                        item.firePointEvent(strLegendItemMouseOut, event, fnLegendItemClick);
                    } else {
                        H.fireEvent && H.fireEvent(item, strLegendItemMouseOut, event, fnLegendItemClick);
                    }
                })
                H.addEvent(target.element, 'click', (event) => {
                    const selectLegend = legendItem.textStr
                    const strLegendItemClick = 'legendItemClick';
                        const fnLegendItemClick = function () {
                            this.series ? this.series.points.forEach((el) => {
                                if (el.name === selectLegend) {
                                    if (el.setVisible) {
                                        el.setVisible();
                                    }
                                }
                            }, this) : item.setVisible && item.setVisible();
                        };
                    event = {
                        browserEvent: event
                    };
    
                    if (item.firePointEvent) { // point
                        item.firePointEvent(strLegendItemClick, event, fnLegendItemClick);
                    }else {
                        H.fireEvent && H.fireEvent(item, strLegendItemClick, event, fnLegendItemClick);
                    }
                })
            }
        };
    }

export default  HighChartSunburstTooltip
