import React, { memo, useMemo, useState } from "react";
import { Dropdown, Form, Menu } from 'antd';
import { useSelector } from "react-redux";
import { PlusCircleOutlined } from "@ant-design/icons";
import { useQuery } from "react-query";
import { isEmpty, clone } from 'lodash';

import useDebounce from 'hooks/useDebounce';
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import { LoaderMenuItem, MenuItemGroupWrapper } from "components/shared/GlobalFilter/components/CommonComponentsV2";
import { CustomPropertyIcon, EventNameIcon } from "components/shared/GlobalFilter/components/FilterSvgs";
import FilterApi from "services/filterApi";
import { rollbar } from "components/common/rollbar";
import { useEventPropertySearchPayload } from "../hooks/useEventPropertySearchPayload";
import { AddConditionStyle, MenuItemWrap, NotFoundMessage, StyledSpace } from "../Style";

const PropertiesOptions = ({ id, name, filterData, addProperty }) => {
  // from form data
  const form = Form.useFormInstance();
  const formData = Form.useWatch('eventProperties', form);
  const formDataIndex = name[1];
  const formProperty = formData?.[formDataIndex]?.['json_field'] ?? '';

  // redux data
  const { callListApi, segmentType } = useAppFilter()
  const {
    appFilter,
  } = useSelector((state) => state);

  const { filters } =   filterData || {};
  const hasEventName = useMemo(()=> filters?.length && filters?.find(filter=> filter?.attribute === 'event_name'), [ filters]);
  const hasSmartEventName = useMemo(()=> filters?.length && filters?.find(filter=> filter?.attribute === 'nce_name'), [ filters]);
  
  // local state
  const [visible, setVisibleChange] = useState(false);
  const [searchInput, setSearchInput] = useState('');
  const debouncedSearchValue = useDebounce(searchInput, 500);
  const newFilters = clone(filterData)

  const refactorPayload = useMemo(()=> {
    if(hasEventName){
      const eventFilter = filters.find(filter=> filter?.attribute === 'event_name');
      if(eventFilter?.value?.length === 0){
        newFilters.filters = []
      } else {
        newFilters.filters =[eventFilter]
      }
    }
    if (hasSmartEventName) {
      const eventFilter = filters.find(filter=> filter?.attribute === 'nce_name');
      if(eventFilter?.value?.length === 0){
        newFilters.filters = []
      } else {
        newFilters.filters =[eventFilter]
      }
    }
    else {
      newFilters.filters = []
    }
    return newFilters;
  } , [filters, hasEventName, hasSmartEventName, newFilters])

  // API call
  const { payload } = useEventPropertySearchPayload({ filterData: refactorPayload, searchInput: debouncedSearchValue });
  
  const { data: rawData, isLoading: loadingAPI, isRefetching, refetch } = useQuery([`event-filter-eventProperty`, debouncedSearchValue, payload?.filter],
    () => FilterApi.getPropertiesWithCancelToken(payload),
    {retry: false});
  
  // sent [] for smart events as Add condition does not work for smart events filters yet
  const remoteData = useMemo(() => hasSmartEventName ? [] : rawData?.data?.data, [rawData?.data?.data])
  
  const renderView = useMemo(() => remoteData?.length ? remoteData.map((data) => <MenuItemWrap key={data} icon={<CustomPropertyIcon />}>{data}</MenuItemWrap>) : <NotFoundMessage>No matching event properties found.</NotFoundMessage>, [remoteData]);

  const onVisibleChange = () => {
    setVisibleChange(!visible)
  }

  const handleMenuPropertyClick = (data) => {
    onVisibleChange(false);
    
    const eventName = {attribute: 'event_name', operator: 'in', value: []}
    
    if(data.key !== 'event_name') {
      form.setFields([{ name, value: data.key }]);
      form.setFields([
        {
          name: ['eventProperties', `${formDataIndex}`, 'value'],
          value: undefined,
        },
      ]);
    } else {
     const filterSegment = [eventName].concat(filters)
     const segmentData = filterData
     segmentData.filters= filterSegment
     const heatmapSegement = appFilter[segmentType].segment || []
     const index = heatmapSegement.indexOf(segmentData);
     const dataSegment = heatmapSegement.map((filter, ind)=> {
      let segment = {...filter}
      if(ind === index){
        segment = segmentData
      }
      return segment
     })
     callListApi(dataSegment)
    }
  }

  const propertiesMenu =
    <Menu
      selectedKeys={[formProperty]}
      onClick={handleMenuPropertyClick}
    >
      <LoaderMenuItem spinning={loadingAPI || isRefetching} style={{ left: 'unset' }}>
        <MenuItemGroupWrapper
          placeholder='Search event attribute'
          onChange={(e) => setSearchInput(e.target.value)}
        > 
         {!loadingAPI ? 
         <>
          <MenuItemWrap key='event_name' disabled={hasEventName || hasSmartEventName} icon={<EventNameIcon/>}>Event name</MenuItemWrap>
          {renderView}
         </>
         : null
         }
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
    </Menu>

  // to hide add condition for smart events
  // if (hasSmartEventName) return null;

  return (
    <Dropdown
      overlay={propertiesMenu}
      overlayClassName='properties-segment-menu'
      onVisibleChange={async (v) => {
        if (id === 'property') { 
          onVisibleChange(v);
          return;
        }
        const values = await form.validateFields();
        if (values) {
          onVisibleChange(v)
          v && !remoteData && refetch()
        }
      }}
      visible={visible}
      trigger={['click']}
    >
      {id === 'property' ?
        <span className='filter-spacing'>
          <a href="#!" onClick={(e) => e.preventDefault()}><StyledSpace isBold={formProperty}> {formProperty} </StyledSpace></a>
        </span> 
        :
        <AddConditionStyle onClick={async () => {
          try {
            const values = await form.validateFields();
            if (values && !isEmpty(values.eventProperties[formDataIndex])) addProperty();
          } catch (errorInfo) {
            rollbar.log('Failed:', errorInfo);
          }

        }} icon={<PlusCircleOutlined />}>
          Add condition
        </AddConditionStyle>}
    </Dropdown>
  )
}

export default memo(PropertiesOptions);