import { SearchOutlined } from "@ant-design/icons";
import React, { useEffect, useRef } from "react";
import { InputRef } from "antd";
import { DebounceInputComponentWrap, InputContainer } from "./styles";
import { ISegmentFilterProps } from "./types";
import { SearchPlaceholderText } from "./variables";

const SegmentFilter: React.FC<ISegmentFilterProps>= ({ value, onChange }) => {

  const ref = useRef<InputRef>(null);

  useEffect(() => {
    if (ref.current) ref.current.focus();
  }, [])

  return (
  <InputContainer>
    <DebounceInputComponentWrap
      prefix={<SearchOutlined />}
      ref={ref}
      placeholder={SearchPlaceholderText}
      onChange={onChange}
      value={value}
      autoFocus
    />
  </InputContainer>
)}

export default SegmentFilter;