import { LoadingOutlined } from '@ant-design/icons';
import { Spin } from 'antd';
import React, { memo } from 'react'
import styled, { css } from 'styled-components';

interface IProps {
	children: React.ReactNode;
	variant?: 'primary' | 'ghost' | 'secondary' | 'outline';
	width?: 'default' | 'small' | 'medium' | 'wide';
	size?: 'big' | 'medium';
	onClick?: React.MouseEventHandler<HTMLButtonElement> | undefined;
	type?: 'button' | 'submit' | 'reset' | undefined;
	loading?: boolean;
	disabled?: boolean;
	style?: React.CSSProperties;
}

interface IButtonBaseProps {
	variant: IProps[ 'variant' ];
	width: IProps[ 'width' ];
	size: IProps[ 'size' ];
	loading: IProps[ 'loading' ];
	disabled: IProps[ 'disabled' ];
}

const ButtonBase = styled.button<IButtonBaseProps>`
	position: relative;
	font-style: normal;
	font-weight: 500;
	font-size: 12px;
	line-height: 24px;
	transition: all 0.2s ease-in-out;
	border-radius: 4px;
	border: none;
	outline: none;
	cursor: pointer;
	display: flex;
	align-items: center;
	svg {
		margin-right: 6px;
	}
	.anticon-loading {
		margin-top: 2px;
	}
	${ ( { variant } ) => {
		if ( variant === 'ghost' ) return css`
			background-color: transparent;
			color: #5D97FF;
			&:hover:not(:disabled) {
				background-color: #F7FAFF;
			}
			&:focus-visible {
				background-color: #DFEAFF;
			}
			&:disabled {
				color: #D0D2D7 !important;
				cursor: not-allowed;
			}
		`
		if ( variant === 'secondary' ) return css`
			background-color: #F3F4F5;
			color: #090F19;
			&:hover:not(:disabled) {
				background-color: #4A79CC;
				color: #ffffff;
			}
			&:focus-visible {
				background-color: #DFEAFF;
			}
			&:disabled {
				color: #D0D2D7 !important;
				cursor: not-allowed;
			}
		`
			if ( variant === 'outline' ) return css`
			background-color: transparent;
			color: #5D97FF;
			border: 1px solid #5D97FF;
			&:hover:not(:disabled) {
				background-color: #F7FAFF;
			}
			&:focus-visible {
				background-color: #395B99;
				color: #ffffff;
			}
			&:disabled {
				color: #D0D2D7 !important;
				cursor: not-allowed;
			}
		`
		return css`
			color: #ffffff;
			background-color: #5D97FF; 
			&:hover:not(:disabled) {
				background-color: #4A79CC;
			}
			&:focus-visible {
				background-color: #395B99;
			}
			&:disabled {
				color: #F3F5F6;
				background-color: #A2A5AE;
				cursor: not-allowed;
			}
		`
	} }
	${ ( { width } ) => {
		if ( width === 'wide' ) return css`
			padding-left: 49px;
			padding-right: 49px;
		`
		if ( width === 'medium' ) return css`
			padding-left: 29px;
			padding-right: 29px;
		` 
		if ( width === 'small' ) return css`
			padding-left: 12px;
			padding-right: 12px;
		` 
		return css`
			padding-left: 6px;
			padding-right: 6px;
		`
	} }
	${ ( { size } ) => {
		if ( size === 'medium' ) return css`
			padding-top: 0px;
			padding-bottom: 0px;
		`
		return css`
			padding-top: 4px;
			padding-bottom: 4px;
		`
	} }
	${ ( { loading, variant } ) => {
		if ( loading && variant !== 'ghost' ) return css`
			&, &:hover:not(:disabled), &:focus-visible, &:disabled {
				color: transparent !important;
				svg > path {
					fill: #ffffff;
				}
			}
		`
		if ( loading ) return css`
			&, &:hover:not(:disabled), &:focus-visible, &:disabled {
				color: transparent !important;
				svg > path {
					fill: #A2A5AE;
				}
			}
		`
		return css``
	} }
`

const LoaderWrapper = styled.div`
	position: absolute;
	top: 0;
	left: 0;
	height: 100%;
	width: 100%;
	display: flex;
	justify-content: center;
	align-items: center;
	svg {
		margin-right: 0px;
	}
	.ant-spin {
		margin-top: 2px;
	}
`

const ButtonNew: React.FC<IProps> = ( { 
	variant = 'primary', 
	children, 
	width = 'default', 
	size = 'big', 
	onClick, 
	type,
	loading = false,
	disabled = false,
	style,
	...rest
} ) => {
	const Loader = React.useMemo( () => {
		if ( !loading ) return null

		return (
			<LoaderWrapper>
				<Spin indicator={ <LoadingOutlined style={{ fontSize: 20 }} spin /> } />
			</LoaderWrapper>
		)
	}, [ loading ])
	
	return (
		<ButtonBase
			variant={ variant }
			width={ width }
			onClick={ onClick }
			size={ size }
			type={ type }
			loading={ loading }
			disabled={ disabled || loading }
			style={ style }
			// eslint-disable-next-line react/jsx-props-no-spreading
			{ ...rest }
		>
			{ children }
			{ Loader }
		</ButtonBase>
	)
}

export default memo( ButtonNew )