import React, { createContext, ReactNode, useContext, useMemo, useState } from 'react'
import { useTopBannerContext } from 'components/IntegratePages/layout/TopBanners/TopBanner/context'
import { Session } from 'components/features/aiSessions/components/types'
import { useFetchAIUsageOverview } from 'components/features/setting/useSettingPage'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import { useDispatch, useSelector } from 'react-redux'
import { useIntervalCheck } from 'hooks/useIntervalCheck'
import { IReduxState, TOrganization } from 'types/reduxStateTypes'
import useIsLoggedInAdmin from 'hooks/useIsLoggedInAdmin'
import { useQuery, useQueryClient } from 'react-query'
import { useRouter } from 'next/router'
import { useAISessionUtils } from 'components/shared/GlobalFilter/components/aiSessionFilter/AISessionUtilsContext'
import { trackSessionProcessingCompleted } from 'components/features/aiSessions/components/utils'
import { getRecentBatches, getTaraCreditConversion, TTaraCreditConversion, TRecentBatchResponse } from '../../AIAssistant/queries'

export type TWatchItem = {
	id: string
	name: string
	requestedCredits: number
	analyzedCredits: number
	analyzedCount?: number
	completedStatus: boolean
	createdAt: string
	scheduledByName: string
	source: 'session' | 'batch'
	url?: string
}

export const SessionWatchStatusStateEnum = {
	idle: 'idle',
	filtered: 'filtered',
	selected: 'selected',
	selectedFiltered: 'selectedFiltered',
} as const

export type SessionWatchStatusState = typeof SessionWatchStatusStateEnum[ keyof typeof SessionWatchStatusStateEnum]

type AISessionWatchlistContextProps = {
	items: TWatchItem[]
	setItems: React.Dispatch<React.SetStateAction<TWatchItem[]>>
	popupVisibility: undefined | boolean
	setPopupVisibility: React.Dispatch<React.SetStateAction<boolean | undefined>>
	selected: Session[]
	setSelected: React.Dispatch<React.SetStateAction<Session[]>>
	showSessionWatchStatus: boolean
	setShowSessionWatchStatus: React.Dispatch<React.SetStateAction<boolean>>
	state: SessionWatchStatusState
	triggerManualCheck: () => void
	batchModalVisible: boolean
	setBatchModalVisible: React.Dispatch<React.SetStateAction<boolean>>
	upgradeModalVisible: boolean
	setUpgradeModalVisible: React.Dispatch<React.SetStateAction<boolean>>
	successModalVisible: boolean
	setSuccessModalVisible: React.Dispatch<React.SetStateAction<boolean>>
	errorModalVisible: boolean
	setErrorModalVisible: React.Dispatch<React.SetStateAction<boolean>>
	upgradeErrorModalVisible: boolean
	setUpgradeErrorModalVisible: React.Dispatch<React.SetStateAction<boolean>>
	upgradeVariant: boolean
	creditsUsageISLoading: boolean
	isFreeCustomer: boolean
	remainingCredits: number
	totalCredits: number
	creditsConversion: TTaraCreditConversion
	popupVisibilityEnforced: boolean
	setPopupVisibilityEnforced: React.Dispatch<React.SetStateAction<boolean>>
	markCompletedItemsAsSeen: () => void
	sessionProcessingErrorModalVisible: boolean
	setSessionProcessingErrorModalVisible: React.Dispatch<React.SetStateAction<boolean>>
	orgId: string | undefined
}

const AISessionWatchlistContext = createContext<AISessionWatchlistContextProps>( {
	items: [],
	setItems: () => null,
	popupVisibility: undefined,
	setPopupVisibility: () => null,
	selected: [],
	setSelected: () => null,
	showSessionWatchStatus: false,
	setShowSessionWatchStatus: () => null,
	state: SessionWatchStatusStateEnum.idle,
	triggerManualCheck: () => null,
	batchModalVisible: false,
	setBatchModalVisible: () => null,
	upgradeModalVisible: false,
	setUpgradeModalVisible: () => null,
	successModalVisible: false,
	setSuccessModalVisible: () => null,
	errorModalVisible: false,
	setErrorModalVisible: () => null,
	upgradeErrorModalVisible: false,
	setUpgradeErrorModalVisible: () => null,
	upgradeVariant: false,
	creditsUsageISLoading: false,
	isFreeCustomer: true,
	remainingCredits: 0,
	totalCredits: 0,
	creditsConversion: {
		chat_questions: 1,
		tara_credits: 1,
		video_minutes: 1,
	},
	popupVisibilityEnforced: false,
	setPopupVisibilityEnforced: () => null,
	markCompletedItemsAsSeen: () => null,
	sessionProcessingErrorModalVisible: false,
	setSessionProcessingErrorModalVisible: () => null,
	orgId: undefined,
} )

export const AISessionWatchlistContextProvider = ( { children }: { children: ReactNode} ) => {
	const { aiSessionFeatureAllowed: isTaraEnabled } = useRestrictionContext() as unknown as { aiSessionFeatureAllowed: boolean }
	const { setTaraBacthLimitOpen } = useTopBannerContext()
	const { setRowSelection } = useAISessionUtils()
	const queryClient = useQueryClient()
	const router = useRouter()
	const dispatch = useDispatch()
	const { parentType } = router.query
	const {
		currentOrgReducer,
		organizationReducer: organizationList,
	} = useSelector( ( state: IReduxState ) => state )
	const { orgId, status: orgStatus, isTaraProPackage = false } = currentOrgReducer
	const restrictionContext: any = useRestrictionContext();
  	const planFeatureAiSessions = !!restrictionContext?.planFeatureAiSessions
	const { data: usageData, isFetching, isFetched } = useFetchAIUsageOverview( orgId, planFeatureAiSessions )
	const usageDataISLoading = useMemo( () => !isFetched || isFetching, [ isFetched, isFetching ] )
	const [ selected, setSelected ] = useState<Session[]>([])
	const [ items, setItems ] = useState<TWatchItem[]>( [] )
	const [ popupVisibility, setPopupVisibility ] = useState<AISessionWatchlistContextProps['popupVisibility']>( undefined )
	const [ popupVisibilityEnforced, setPopupVisibilityEnforced ] = React.useState( false )
	const [ showSessionWatchStatus, setShowSessionWatchStatus ] = React.useState( true )
	const { data: creditsConversion = {
		chat_questions: 1,
		tara_credits: 1,
		video_minutes: 1,
	} } = useQuery( {
		queryFn: getTaraCreditConversion,
		queryKey: 'tara-credit-conversion',
		enabled: !!planFeatureAiSessions,
	} )

	const isAISessionPage = React.useMemo(
		() => ['aiSessionsList', 'aiSessionStatistics', 'sessionsList', 'sessionStatistics'].includes(parentType as string),
		[parentType]
	)

	const [ batchModalVisible, setBatchModalVisible ] = useState( false )
	const [ upgradeModalVisible, setUpgradeModalVisible ] = useState( false )
	const [ successModalVisible, setSuccessModalVisible ] = useState( false )
	const [ errorModalVisible, setErrorModalVisible ] = useState( false )
	const [ upgradeErrorModalVisible, setUpgradeErrorModalVisible ] = useState( false )
	const [ sessionProcessingErrorModalVisible, setSessionProcessingErrorModalVisible ] = useState( false )
	const [ seenCompletedItems, setSeenCompletedItems ] = useState<Set<string>>( new Set() )
	const isInitialLoad = React.useRef( true )

	// eslint-disable-next-line no-underscore-dangle
	const filterOrg: TOrganization | object = useMemo(()=> organizationList?.length ? organizationList.find((org) => org._id === currentOrgReducer?.orgId) || {} : {}, [currentOrgReducer, organizationList] ) ;
	const isFreeCustomer = useMemo(()=> currentOrgReducer?.planType === "free", [ currentOrgReducer ] )

	const monthlyTaraCredits = usageData?.monthly_tara_credit || 0
	const customAnalaysisEnabled = monthlyTaraCredits > 0
	const consumedTaraCredits = Math.max(usageData?.consumed_tara_credit || 0, 0)
	const scheduledTaraCredits = Math.max(usageData?.scheduled_tara_credit || 0, 0)
	const remainingCredits = useMemo( () => ( monthlyTaraCredits ) - ( consumedTaraCredits + scheduledTaraCredits ), [ monthlyTaraCredits, consumedTaraCredits, scheduledTaraCredits ] )
	const { isLoggedInAsAdminAdmin } = useIsLoggedInAdmin()
	const shouldIgnoreLimits = isLoggedInAsAdminAdmin
	const upgradeVariant = useMemo( () => {
		if ( shouldIgnoreLimits ) return false
		
		return !usageDataISLoading && ( isFreeCustomer || ( !isFreeCustomer && !customAnalaysisEnabled ) || ( !isFreeCustomer && customAnalaysisEnabled && remainingCredits <= 0 ) ) || orgStatus === 'Canceled'
	}, [ customAnalaysisEnabled, isFreeCustomer, remainingCredits, shouldIgnoreLimits, usageDataISLoading, orgStatus ] )

	const {
		appFilter: {
			dateSegment,
			session: {
				segment: appFilterSegment,
			},
		},
		currentAppReducer: {
			_id: appID
		}
	} = useSelector((reduxState: IReduxState) => reduxState)

	// Function to mark all completed items as seen
	const markCompletedItemsAsSeen = React.useCallback(() => {
		const completedIds = items
			.filter((item) => item.completedStatus)
			.map((item) => item.id)

		setSeenCompletedItems((prev) => {
			const updated = new Set(prev)
			completedIds.forEach((id) => updated.add(id))
			return updated
		})
	}, [items])

	// eslint-disable-next-line no-underscore-dangle
	const isOrgDataReady = !!organizationList?.length && !!currentOrgReducer?.orgId && !!(filterOrg as TOrganization)?._id
	const isPlanDataReady = !!currentOrgReducer?.planType
	const hasCustomerStatusData = (
		(filterOrg as TOrganization)?.selfServeCheckout !== undefined ||
		currentOrgReducer?.onTrial !== undefined ||
		!!currentOrgReducer?.planType	)

	const shouldBeEnabled = isTaraEnabled && !upgradeVariant && !!appID && isOrgDataReady && isPlanDataReady && hasCustomerStatusData && !!planFeatureAiSessions

	const hasSetContent = React.useRef( false )
	React.useEffect( () => {
		const hasLowCredits = !isFreeCustomer && customAnalaysisEnabled && remainingCredits <= 0
		const isTaraLiteUser = !isTaraProPackage && !isFreeCustomer && customAnalaysisEnabled

		if ( ( hasLowCredits || isTaraLiteUser ) && isOrgDataReady && isPlanDataReady && hasCustomerStatusData && !hasSetContent.current && !usageDataISLoading ) {
			setTaraBacthLimitOpen( true )
			hasSetContent.current = true
		}
	}, [ upgradeVariant, isOrgDataReady, isPlanDataReady, hasCustomerStatusData, customAnalaysisEnabled, isFreeCustomer, remainingCredits, setTaraBacthLimitOpen, usageDataISLoading, isTaraProPackage ] )

	React.useEffect(() => {
		setTaraBacthLimitOpen(false)
		hasSetContent.current = false
	}, [orgId, appID, setTaraBacthLimitOpen])

	// Refresh credits when watchlist items change (new batch added or completed)
	const prevItemsRef = React.useRef<TWatchItem[]>([])
	React.useEffect(() => {
		const prevItems = prevItemsRef.current

		// Skip on initial load
		if (prevItems.length === 0 && items.length > 0) {
			prevItemsRef.current = items
			return
		}

		const hasNewItems = items.length > prevItems.length

		// Create maps for easier lookup by ID
		const prevItemsMap = new Map(prevItems.map(item => [item.id, item]))
		const hasCompletedItems = items.some(item => {
			const prevItem = prevItemsMap.get(item.id)
			return prevItem && !prevItem.completedStatus && item.completedStatus
		})

		// Check if any item's analyzed credits changed (sessions being analyzed)
		const hasAnalyzedCreditsChanged = items.some(item => {
			const prevItem = prevItemsMap.get(item.id)
			return prevItem && prevItem.analyzedCredits !== item.analyzedCredits
		})

		if (hasNewItems || hasCompletedItems || hasAnalyzedCreditsChanged) {
			queryClient.invalidateQueries(`ai_usage_overview_${orgId}`)
			queryClient.invalidateQueries(`ai_overview_${orgId}`)
		}

		prevItemsRef.current = items
	}, [items, orgId, queryClient])

	React.useEffect(() => {
		if (!isAISessionPage) {
			setPopupVisibility(false)
			setPopupVisibilityEnforced(false)
		}
	}, [isAISessionPage])

	// Clear selected sessions when date range or filters change
	const prevFiltersRef = React.useRef({ dateSegment, appFilterSegment })
	React.useEffect(() => {
		const filtersChanged =
			JSON.stringify(prevFiltersRef.current.dateSegment) !== JSON.stringify(dateSegment) ||
			JSON.stringify(prevFiltersRef.current.appFilterSegment) !== JSON.stringify(appFilterSegment)

		if (isAISessionPage && filtersChanged) {
			setSelected([])
			setRowSelection([])
		}

		prevFiltersRef.current = { dateSegment, appFilterSegment }
		// eslint-disable-next-line react-hooks/exhaustive-deps
	}, [dateSegment, appFilterSegment, isAISessionPage])

	const { triggerManualCheck } = useIntervalCheck({
		checkInterval: 1000, // Check every 1 second
		mainInterval: 60000, // Run every 60 seconds
		onCheck: async (isManualTrigger) => {
			const delay = (ms: number) => new Promise((resolve) => {
				setTimeout(resolve, ms)
			})

			const fetchWithRetry = async (attempt: number): Promise<TRecentBatchResponse> => {
				const data = await getRecentBatches({ appid: appID as string, page: 1 })

				// Only retry on manual triggers (after scheduling a batch)
				if (!isManualTrigger || data?.data?.length > 0 || attempt >= 3) {
					return data
				}

				// Wait 1 second and retry
				await delay(1000)
				return fetchWithRetry(attempt + 1)
			}

			return fetchWithRetry(0)
		},
		onSuccess: (data) => {
			if (data?.data) {
				// On initial load, mark all completed items as seen without triggering popup
				if (isInitialLoad.current) {
					const completedIds = data.data
					.filter((item: TWatchItem) => item.completedStatus)
					.map((item: TWatchItem) => item.id)
					
					setSeenCompletedItems(new Set(completedIds))
					isInitialLoad.current = false
				} else {
					// Find newly completed items that haven't been seen yet
					const newlyCompletedItems = data.data.filter(
						(item: TWatchItem) => item.completedStatus && !seenCompletedItems.has(item.id)
					)

					// If there are unseen completed items and we're on an AI session page, open the popup with enforcement after a delay
					if (newlyCompletedItems.length > 0 && isAISessionPage) {
						newlyCompletedItems.map( completedItem => {
							const totalCreditsUsed = completedItem.analyzedCredits
							const totalSessions = completedItem.analyzedCount || 0
							const batchNames = completedItem.name
							const type = completedItem.source

							dispatch(trackSessionProcessingCompleted({
								batchName: batchNames,
								approximateSessions: totalSessions,
								creditsUsed: totalCreditsUsed,
								creditsRemaining: remainingCredits,
								filtersApplied: appFilterSegment,
								parentType: (parentType as string) || 'unknown',
								type,
							}) )

							setTimeout(() => {
								setPopupVisibility(true)
								setPopupVisibilityEnforced(true)
							}, 1000) // 1 second delay

							// Refetch session meta
							queryClient.invalidateQueries(['ai-session-meta'])

							// Refetch AI session list to get new sessions
							queryClient.invalidateQueries(['aiSessionItems'])

							// Mark newly completed items as seen
							setSeenCompletedItems((prev) => {
								const updated = new Set(prev)
								newlyCompletedItems.forEach((item: TWatchItem) => updated.add(item.id))
								return updated
							})

							return null
						})
					}
				}

				setItems(data.data)
			}
		},
		shouldStopOnEmptyData: (data) => {
			// Stop checking if there's no data
			if (!data?.data || data.data.length === 0) {
				return true
			}
			return false
		},
		runOnMount: shouldBeEnabled,
		enabled: shouldBeEnabled,
	})

	const state: SessionWatchStatusState = useMemo( () => {
		const hasFilters = appFilterSegment?.length
		const isSelected = selected?.length 
		if ( isSelected ) {
			if ( hasFilters ) {
				return SessionWatchStatusStateEnum.selectedFiltered
			}
			return SessionWatchStatusStateEnum.selected
		}

		if ( appFilterSegment?.length ) {
			return SessionWatchStatusStateEnum.filtered
		}
 
		return SessionWatchStatusStateEnum.idle
	}, [ appFilterSegment, selected ] )

	const contextValue = useMemo( () => ( {
		items,
		setItems,
		popupVisibility,
		setPopupVisibility,
		selected,
		setSelected,
		showSessionWatchStatus,
		setShowSessionWatchStatus,
		state,
		triggerManualCheck,
		batchModalVisible,
		setBatchModalVisible,
		upgradeModalVisible,
		setUpgradeModalVisible,
		successModalVisible,
		setSuccessModalVisible,
		errorModalVisible,
		setErrorModalVisible,
		upgradeErrorModalVisible,
		setUpgradeErrorModalVisible,
		upgradeVariant,
		isFreeCustomer,
		creditsUsageISLoading: usageDataISLoading,
		remainingCredits,
		totalCredits: monthlyTaraCredits,
		creditsConversion,
		popupVisibilityEnforced,
		setPopupVisibilityEnforced,
		markCompletedItemsAsSeen,
		sessionProcessingErrorModalVisible,
		setSessionProcessingErrorModalVisible,
		orgId,
	} ), [
		items,
		setItems,
		popupVisibility,
		setPopupVisibility,
		selected,
		setSelected,
		showSessionWatchStatus,
		setShowSessionWatchStatus,
		state,
		triggerManualCheck,
		batchModalVisible,
		setBatchModalVisible,
		upgradeModalVisible,
		setUpgradeModalVisible,
		successModalVisible,
		usageDataISLoading,
		setSuccessModalVisible,
		errorModalVisible,
		setErrorModalVisible,
		upgradeErrorModalVisible,
		setUpgradeErrorModalVisible,
		upgradeVariant,
		isFreeCustomer,
		remainingCredits,
		monthlyTaraCredits,
		creditsConversion,
		popupVisibilityEnforced,
		setPopupVisibilityEnforced,
		markCompletedItemsAsSeen,
		sessionProcessingErrorModalVisible,
		setSessionProcessingErrorModalVisible,
		orgId,
	] )

	return (
		<AISessionWatchlistContext.Provider value={ contextValue }>
			{ children }
		</AISessionWatchlistContext.Provider>
	)
}

export const useAISessionWatchlist = () => {
	const context = useContext( AISessionWatchlistContext )

	if ( !context ) {
		throw new Error( 'useAISessionWatchlistContext must be used from within AISessionWatchlistContextProvider' )
	}

	return context
}