import React, { useCallback, useEffect, useMemo, memo } from 'react';
import { Dropdown, Menu, Button, Checkbox } from 'antd';
import isArray from 'lodash/isArray';
import isEqual from 'lodash/isEqual';
import sortBy from 'lodash/sortBy';

import {
  DebounceInputComponent,
  MenuItemGroupWrapper,
  LoaderMenuItem,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2';
import { isOptionsPredefined } from 'components/shared/GlobalFilter/components/utils';
import { withContextProps } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/FilterContextProvider';
import {
  MenuItem,
  noMatchingFilterMenu,
} from 'components/shared/GlobalFilter/components';
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip';

import { SelectAllAndClear, OverThresholdText, bringSelectedItemsToTop } from 'components/shared/GlobalFilter/components/CommonComponentsV2';

const FilterDropdown = (props) => {
  let disabled;
  let valueForCompare;
  const {
    onVisibleChange,
    handleApply,
    visible,
    setSelectedOptions,
    selectedOptions,
    editFieldVisibility,
    titleRenderIfArray,

    // rest of the props
    value = [],
    attribute,
    isMultiSelect,
    id,
    filterData = [],
    placeholderText,
  } = props;
  const {
    // context props
    resetFieldsAndCallApi,
    handleSearchInputProps,
    searchAttrInputText,
    isEmptyMessage,
    loading,
    fetchedList,
  } = props;

  // for user name menu items with Object{id, uxcamuserid}
  const processArrayChildren = (arr) => {
    return arr.map((child) => {
      if (_.isObject(child)) {
        return child.uxcamuserid;
      } else {
        return child;
      }
    });
  };

  const fetchedListCopy = useMemo(
    () => (fetchedList ? [...bringSelectedItemsToTop(processArrayChildren(fetchedList), selectedOptions)] : []),
    [fetchedList]
  );

  const selectedOptionsCopy = useMemo(
    () => (selectedOptions ? [...selectedOptions] : []),
    [selectedOptions]
  );

  switch (id) {
    case 'userpropertyname':
    case 'eventpropertyname':
    case 'utmpropertyname':
    case 'userfirstutmname':
    case 'sessionscreenpropertyname':
    case 'customscreenpropertyname':
      valueForCompare = filterData?.property?.name;
      break;
    case 'userpropertyvalue':
    case 'eventpropertyvalue':
    case 'utmpropertyvalue':
    case 'userfirstutmvalue':
    case 'sessionscreenpropertyvalue':
    case 'customscreenpropertyvalue':
      valueForCompare = filterData?.property?.value;
      break;
    default:
      valueForCompare = filterData?.value;
      break;
  }
  if (isMultiSelect) {
    disabled =
      !selectedOptions?.length ||
      (!editFieldVisibility &&
        valueForCompare &&
        selectedOptions &&
        isArray(selectedOptions) &&
        isArray(valueForCompare) &&
        isEqual(selectedOptions?.sort(), valueForCompare?.sort()));
  }
  const handleSelectedOptions = useCallback(
    (val) => {
      let selectedOptionsNew;
      if (selectedOptionsCopy?.includes(val))
        selectedOptionsNew = selectedOptionsCopy.filter((v) => v !== val);
      else selectedOptionsNew = [...selectedOptionsCopy, val];

      setSelectedOptions(selectedOptionsNew);
    },
    [selectedOptionsCopy, setSelectedOptions]
  );

  const handleDefaultOpen = async () => {
    const { filters } = filterData || {};
    const eventFilter = filters.find((obj) => obj.attribute === 'event_name' || obj.attribute === 'nce_name');
    if ((!eventFilter || eventFilter?.value?.length === 0) && selectedOptions?.length === 0) {
      await onVisibleChange(true);
      await resetFieldsAndCallApi({ isSearchable: true });
    }
  };

  const renderView = useMemo(() => {
    if (isEmptyMessage) return noMatchingFilterMenu;
    if (isMultiSelect) {
      return (
        <ul>
          {!!fetchedListCopy?.length >= 1
            ? fetchedListCopy.map((data) => {
                let key = data;
                const title = data;

                if (isOptionsPredefined(attribute)) key = data.toLowerCase();
                return (
                  <li key={key}>
                    <Checkbox
                      checked={
                        isArray(selectedOptionsCopy) &&
                        selectedOptionsCopy?.length &&
                        selectedOptionsCopy?.includes(key)
                      }
                      onChange={() => handleSelectedOptions(key)}
                    >
                     <CellOverflowTooltip
                      width={195}
                      text={title}
                      value={title}
                    />
                    </Checkbox>
                  </li>
                );
              })
            : isEmptyMessage && noMatchingFilterMenu}
        </ul>
      );
    }
    return fetchedListCopy?.length
      ? fetchedListCopy.map((data) => <MenuItem key={data}>{data}</MenuItem>)
      : '';
  }, [
    isEmptyMessage,
    fetchedListCopy,
    isMultiSelect,
    selectedOptionsCopy,
    attribute,
    handleSelectedOptions,
  ]);

  const handleSelectAllOptions = () => {
    setSelectedOptions(processArrayChildren(fetchedListCopy));
  }

  const checkSelectDisabled = useMemo(() => {
    if(selectedOptions.length !== fetchedListCopy.length) return false;
    return isEqual(sortBy(selectedOptions), sortBy(processArrayChildren(fetchedListCopy)));
  }, [selectedOptions, fetchedListCopy]);

  const menu = (
    <Menu
      selectedKeys={isArray(value) ? value : [value]}
     // onClick={handleMenuClick}
    >
      <LoaderMenuItem spinning={loading} style={{ left: 'unset' }}>
        <MenuItemGroupWrapper
          placeholder="Search eventname"
          onChange={(e) => handleSearchInputProps(e.target.value)}
          value={searchAttrInputText}
          id="filtered-options"
          headerChildren={
            <>
            {
              fetchedListCopy.length > 500 && (
                <OverThresholdText 
                  text='Not all results are displayed - type to search for more.'
                />
              )
            }
            <SelectAllAndClear
              operatorAttribute={attribute}
              isOperatorRadio={false}
              newFetchedList={fetchedListCopy}
              operatorType={false}
              handleSelectAllOptions={handleSelectAllOptions}
              handleClearAllOptions={() => setSelectedOptions([])}
              disableSelect={checkSelectDisabled}
              disableClear={selectedOptionsCopy.length <= 0}
            />
          </>
          }
        >
          {renderView}
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
      {isMultiSelect && (
        <div key="button-bar" className="button-bar">
          <Button type="primary-outline" onClick={() => setSelectedOptions([])}>
            Clear
          </Button>
          <Button
            disabled={disabled}
            type="primary"
            onClick={() => {
              resetFieldsAndCallApi({});
              handleApply(selectedOptions);
            }}
          >
            Apply
          </Button>
        </div>
      )}
    </Menu>
  );

  useEffect(() => {
    if (selectedOptions?.length === 0) {
      handleDefaultOpen()
    }
  }, []);

  return (
    <Dropdown
      overlay={menu}
      overlayClassName="multi-column-menu mega-segment-menu filter-applied-segment-menu"
      onVisibleChange={(v) => {
        if (v) resetFieldsAndCallApi({ isSearchable: true });
        onVisibleChange(v);
       !v && handleApply(selectedOptions);
      }}
      visible={visible}
      trigger={['click']}
    >
      {!editFieldVisibility || selectedOptions?.length === 0 ? (
        <DebounceInputComponent
          placeholder={placeholderText}
          className="filter-input-width event-name"
          onClick={() => onVisibleChange(true)}
          onChange={(e) => handleSearchInputProps(e.target.value)}
          value={selectedOptions}
          editFieldVisibility={editFieldVisibility}
        />
      ) : (
        <a href="#!" onClick={(e) => e.preventDefault()}>
          {titleRenderIfArray}
        </a>
      )}
    </Dropdown>
  );
};

export default withContextProps(memo(FilterDropdown));
