import React from 'react'
import Quickbar from 'components/common/Quickbar'
import styled from 'styled-components'
import { theme } from 'theme'

interface IProps {
	onVisibleChange: ( flag: boolean ) => void
}

const Container = styled.div`
	width: 100%;
	height: auto;
	padding: 16px 16px 14px 16px;
	display: flex;
	gap: 8px;
	flex-direction: column;
`

const Label = styled.span`
	font-size: 12px;
	line-height: 12px;
	font-weight: 400;
	color: ${ theme.colors.surface200.toString() };
	margin: 0;
	padding: 0;
`

const MegaQuickFilters = ( { onVisibleChange }:  IProps ) => {
	const containerRef = React.useRef<HTMLDivElement>( null )

	const callback = React.useCallback( () => {
		onVisibleChange( false )
	}, [ onVisibleChange ] )
	return (
		<Container ref={ containerRef }>
			<Label>
				Quick filters:
			</Label>
			<Quickbar
				megaFilterRestyle
				loadTable={ callback as unknown as null | undefined }
				renderRef={ containerRef as unknown as null }
			/>
		</Container>
	)
}

export default React.memo( MegaQuickFilters )
