import React from 'react'
import { useSelector } from 'react-redux'
import styled from 'styled-components'
import { IConversionStepFilter, mapConversionFilter, mapConversionFilterStep } from '../utils'
import FunnelStepItem from '../../FunnelSequence/FunnelStepItem'
import ConversionFilterItem from './ConversionFilterItem'

const StepsWrapper = styled.div`
  display: flex;
  flex-direction: column;
`
const FilterWrapper = styled.div`
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 8px;
`
const ConversionSteps:React.FC<{
    filterData: IConversionStepFilter,
}> = ({
    filterData,
}) => {
    const {
      screenRenamedList: renamedScreens = {},
      batchData = [],
    } = useSelector(({ screenRenamedList, appFilter }: never) => ({
      screenRenamedList: screenRenamedList as Record<string, string>,
      batchData: (appFilter as any)?.fetchProperty?.batch_id?.data || [],
    }));

    const initialStep = React.useMemo(() => {
      const { value: {
        initial_event: initialEvent
      } } = filterData

      return mapConversionFilterStep( initialEvent, renamedScreens )
    }, [ filterData, renamedScreens ])

    const conversionStep = React.useMemo(() => {
      const { value: {
        conversion_events: conversionEvents
      } } = filterData

      return mapConversionFilterStep( conversionEvents[0], renamedScreens )
    }, [filterData, renamedScreens])

    const conversionFilters = React.useMemo(() => {
      const { value: {
        conversion_analytics_filters: conversionAnalyticsFilters
      } } = filterData
      if( !conversionAnalyticsFilters ) return []

      return mapConversionFilter(conversionAnalyticsFilters, renamedScreens, batchData)
    }, [ filterData, renamedScreens, batchData ])
    
  return (
    <StepsWrapper>
        <FunnelStepItem index={1} type="conversion" step={initialStep} isConversion />
        {
          conversionFilters.length > 0 && (
            <FilterWrapper>
              {
                conversionFilters.map((filter, index) => (
                  <ConversionFilterItem filter={filter} index={index }/>
                ))
              }
            </FilterWrapper>
          )
        }
        <FunnelStepItem index={2} type='conversion' step={conversionStep} isConversion />
    </StepsWrapper>
  )
}

export default React.memo(ConversionSteps)