export const getChatThread = async (
	appID: string,
	version: TARA_API_VERSION = TARA_API_VERSION.PROD,
	persona = 'assistant',
	debugMode = false,
	chatId: string | undefined = undefined,
	page = 1,
): Promise<TLastChat> => {
	const baseUrl = taraApiFactory.getEndpoint(version, 'chat_thread', debugMode)
	const url = chatId ? `${baseUrl}/session` : baseUrl
	const params: Record<string, string | number> = { app_id: appID, page, page_size: 50, persona }
	if (chatId) params.session_id = chatId
	return axiosInstance.get(url, { params, withCredentials: true }).then((response) => response.data)
}


