const mappingValues = {
  'Launch': 'Session start',
  'Quit': 'Exit',
}

const SequenceFilterVersionTwo = memo(({ filterValue }) => (
  <span className="sequential-filter">
    <span className="filter-spacing">Follows screen sequence</span>
    <div className="sequential-list-wrapper">
      <div className="sequential-list">
        {filterValue.map((v, i) => (
          <>
            <span className="filter-spacing" key={v}>
              {/* <FilterContextProvider attributeProps={attributeProps}>
                  <ScreenSelectDropdown
                    selectedKeyIndex={i}
                    key={i}
                    selectedScreenList={v}
                    {...rest}
                  > */}
              <ScreenTooltip
                // eslint-disable-next-line react/no-unstable-nested-components
                onRenderScreen={(el) => <span>{el}</span>}
                originalScreenName={v}
              />
              {/* </ScreenSelectDropdown>
                </FilterContextProvider> */}
            </span>
            <span className="sequence-icon">
              {i !== filterValue.length - 1 && <SequenceFrontIcon />}
            </span>
          </>
        ))}
      </div>
    </div>
  </span>
));

const ScreenFilterWithSequence = memo((props) => {
  const {
    value: rawValue,
    attributeProps,
    // ...rest
  } = props;
  const isWebSDK = useIsAppType('web')
  const value = Array.isArray(rawValue) ? rawValue?.map((v) => {
    if (isWebSDK) {
      return mappingValues[v] || v
    }
    return v
  }) : rawValue;
  return <SequenceFilterVersionTwo filterValue={value} attributeProps={attributeProps} />
});
