import { useMemo } from 'react';
import { useMutation } from 'react-query';
import { useSelector, RootStateOrAny } from 'react-redux';
import { axiosInstance } from 'services/globalInstance';

type PromptPayload = {
    prompt: string,
    orgid: string,
}

export const useAiPrompt = () => {
    const { 
        currentAppReducer:{_id: appId}, 
        urlReducer: { parentType, issueType, sessionid, eventid, screenname, uxcamuserid, issueid } 
    } = useSelector((state: RootStateOrAny) => state);
    
    const page = useMemo(() => {
        switch( parentType ){
            case 'sessionStatistics':
                return 'session_analytics';
            case 'aiSessionStatistics':
                return 'ai_session_analytics';
            case 'sessionsList':
                if( sessionid ){
                    return 'session_detail'
                }
                return 'session_list'
            case 'aiSessionsList':
                if( sessionid ){
                    return 'ai_session_detail'
                }
                return 'ai_session_list'
            case 'eventsList':
                if( eventid ){
                    return 'event_detail'
                }
                return 'event_list'
            case 'statistics':
                return 'event_analytics'
            case 'heatmapsList':
                if( screenname ){
                    return 'screen_detail'
                }
                return 'screen_list'
            case 'usersList':
                if( uxcamuserid ){
                    return 'user_detail'
                }
                return 'user_list'
            case 'screenFlow':
                return 'screen_flow'
            case 'screenBurst':
                return 'screen_burst'
            case 'issuesList':
                if( issueType === 'crashes' ){
                    if( issueid ){
                        return 'crash_detail'
                    }
                    return 'crash_list'
                } 
                if( issueType === 'freezes' ){
                    if( issueid ){
                        return 'UI_freeze_detail'
                    }
                    return 'UI_freeze_list'
                } 
                if( issueType === 'exceptions' ){
                    if( issueid ){
                        return 'exceptions_detail'
                    }
                    return 'exceptions_list'
                }
                return null;
            default:
                return null;
        }
    }, [ eventid, issueType, issueid, parentType, screenname, sessionid, uxcamuserid ])

    const getFiltersFromPrompt = useMutation({
        mutationFn: (payload: PromptPayload) =>
            axiosInstance.post(
                `${process.env.PYTHON_API_URL}/nova/prompt`,
                {
                ...payload,
                appid: appId,
                page,
                },
                {
                withCredentials: true,
                }
            ),
    })

    return { getFiltersFromPrompt };
}