import axios from 'axios'
import React from 'react'
import { useQuery } from 'react-query'
import { useSelector } from 'react-redux'
import { IReduxState } from 'types/reduxStateTypes'

export interface IUserCohort {
	name: string
	id: string
	isUserCohort: boolean
	description: string
}

interface IUserCohortResponse {
	data: {
		name: string
		cohort_id: string
		description: string
	}[]
}

const getFetchUserCohorts = ( appId?: string ) => {

	const fetchFn = async () => {

		if ( !appId ) {
			return []
		}

		const { data: { data } } = await axios.get<IUserCohortResponse>(
			`${process.env.PYTHON_API_URL}/retention/cohort/list/${ appId }`, {
				withCredentials: true,
			}
		).catch( () => ( {
			data: {
				data: [],
			},
		} ) )

		return data
			// eslint-disable-next-line camelcase
			.map( ( { name, cohort_id: id, description } ) => ( {
				name,
				id,
				isUserCohort: true,
				description: description || '',
			} ) )
	}

	return fetchFn
}

interface IUserCohortsContextProps {
	userCohorts: IUserCohort[],
    refetchCohorts: () => void,
    isCohortsRefetching: boolean,
}

const UserCohortsContext = React.createContext<IUserCohortsContextProps>({
	  userCohorts: [],
      refetchCohorts: () => undefined,
      isCohortsRefetching: false,
} )

export const UserCohortsProvider: React.FC<{
	children: React.ReactNode
}> = ({ children }) => {


	const {
		currentAppReducer
	} = useSelector( ( state: IReduxState ) => state )

	// eslint-disable-next-line no-underscore-dangle
	const appId = currentAppReducer?._id
	
	const fetchUserCohorts = getFetchUserCohorts( appId )

	const { data ,refetch, isRefetching } = useQuery( {
		queryFn: fetchUserCohorts,
		queryKey: [ 'userCohorts', appId ],
		enabled: !!appId,
	} )

	const contextValues = React.useMemo( () => ({
		userCohorts: data || [],
        refetchCohorts: refetch,
        isCohortsRefetching: isRefetching,
	}), [data, refetch, isRefetching] )

	return (
		<UserCohortsContext.Provider value={ contextValues }>
			{children}
		</UserCohortsContext.Provider>
	)

}

export const useUserCohorts = () => React.useContext( UserCohortsContext )