/* eslint-disable no-restricted-syntax */
import React, { createContext, useState, useMemo, useCallback, useRef } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import clone from 'lodash/clone'
import isArray from 'lodash/isArray'
import uniq from 'lodash/uniq'
import uniqBy from 'lodash/uniqBy'

import { getFilterPropertyRemoteData } from 'redux/actions/filter'
import { filterTextByOption, isOptionsPredefined, screenNameAttributes } from 'components/shared/GlobalFilter/components/utils'
import { useUserCohorts } from 'components/common/Contexts/UserCohortsContext'
import { useIsAppType } from 'hooks/useIsAppType'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'

const SearchContext = createContext()
const FilterContextProvider = (props) => {
  const {
    children,
    attributeProps,
    isEventProperty,
    isScreenProperty,
    eventOperator,
    eventValue,
    propertyNameProp: propertyNameArg,
    attributeNew: attributeArg,
    inputRef,
    operatorData,
    ...rest
  } = props
  const dispatch = useDispatch()
  const {
    appFilter: rawAppFilter,
    megaFilterReducer,
    urlReducer: { screenname, appId, parentType },
  } = useSelector((state) => state);

  const [isEmptyMessage, showEmptyMessage] = useState(false)
  const [searchAttrInputText, setSearchAttributeText] = useState('')
  const [loading, setLoading] = useState(false)
  const [availableOptions, setAvailableOptions] = useState([])
  const [searchedStrings, setSearchedStrings] = useState({})
  const [fetchedData, setFetchedData] = useState([])
  const [activeEventTab, setActiveEventTab] = useState('codedEvents');
  const [tabContentWidth, setTabContentWidth] = useState(470)
  const propertyName = useRef()
  const isWebApp = useIsAppType( 'web' );
  const {selectedAttributeProps} = megaFilterReducer
  const searchAttributeProps =
    selectedAttributeProps && selectedAttributeProps.attribute
      ? selectedAttributeProps
      : attributeProps
  const valueMapping = searchAttributeProps?.valueMapping
  let attribute = attributeArg || searchAttributeProps?.attribute
  propertyName.current = propertyNameArg || searchAttributeProps?.propertyName

  if (isEventProperty) {
    attribute = 'eventpropertyname';
    if (propertyName.current) attribute = 'eventpropertyvalue';
  }

  // const isRageTap = Array.isArray(eventValue) && eventValue.length === 1 && eventValue[0] === 'rageTap';
  // const isEventActivityScreen = isEventProperty && propertyName.current === 'activity' && isRageTap
  const isScreen = screenNameAttributes.includes(attribute)
  const isScreenAttribute = isScreen
  const isUserCohorts = attribute === 'uxcamuserid_cohort'
  const isBatchId = attribute === 'batch_id'

  const { userCohorts } = useUserCohorts()
  const { aiSessionFeatureAllowed } = useRestrictionContext() || {}

  // eslint-disable-next-line arrow-body-style
  const appFilter = React.useMemo( () => {
    return {
      ...rawAppFilter,
      fetchProperty: {
        ...rawAppFilter.fetchProperty,
        uxcamuserid_cohort: {
          data: userCohorts,
        },
      }
    }
  }, [ rawAppFilter, userCohorts ] )
  const { event: { segment: eventSegment }, fetchProperty } = appFilter;

  const searchApiCall = useCallback(async (
    searchInput = '',
    dropdownLimit = 501,
  ) => {
    if(!attribute) return [];
    if(attribute === 'batch_id' && !aiSessionFeatureAllowed) return [];
    let payloadAttribute = attribute
    // if(payloadAttribute === 'screen_name') payloadAttribute = 'screenname' // removing this as we are now useing screen_name filter
    if (payloadAttribute === 'event_name') { 
      payloadAttribute = (activeEventTab === 'smartEvents') ? 'nce_name' : 'event_name' 
    }
    if (isEventProperty) payloadAttribute = 'event_custom_property'
    if (isScreenProperty) payloadAttribute = 'session_screen_with_property'
    if (payloadAttribute === 'session_screen_list') payloadAttribute = 'screen_name'
    if(propertyName.current && payloadAttribute === 'userpropertyvalue') payloadAttribute = 'user_custom_property'
    if(['alias', 'kUXCam_UserIdentity'].indexOf(payloadAttribute) > -1) {
      payloadAttribute = 'user_custom_property'
      propertyName.current = attribute
    }
    const eventFilters = eventSegment.filter(item => item.attribute === 'event_name'); // Added to send the event filters to get the associated event proeprties.
    
    setLoading(true)
    const filter = []
    if (screenname && ['previous_screen_name', 'next_screen_name'].indexOf(payloadAttribute) > -1) {
      filter.push({
        attribute: 'screen_name',
        operator: 'in',
        value: [screenname],
        table: 'screenvisit',
      });
    }
    if (isEventProperty && eventValue) {
      filter.push({
        attribute: 'event_name',
        operator: 'in',
        value: eventValue || [],
        table: 'event'
      });
    }
    if (isScreenProperty && eventValue){ // @TODO: Rename eventValue eventually to value
      filter.push({
        attribute: 'screen_name',
        operator: operatorData?.attribute || 'in',
        value: eventValue || [],
        table: 'screenvisit'
      });
    }
    if (parentType === 'eventsList' && payloadAttribute === 'event_custom_property' && eventFilters.length > 0) {
      filter.push(eventFilters[0])
    }
    const remoteData = await dispatch(getFilterPropertyRemoteData({
      appid: appId,
      search: searchInput,
      filter,
      attribute: payloadAttribute,
      property_name: propertyName.current || undefined,
      dropdownLimit,
      isWebApp,
      has_mass_value: searchAttributeProps?.has_mass_value,
      mass_value_segment_id: searchAttributeProps?.mass_value_segment_id,
      mass_values_id: searchAttributeProps?.mass_values_id,
    }))
    remoteData && setLoading(false)
    if (isArray(remoteData)) return remoteData
    if (remoteData && !remoteData.toString().includes('Cancel')) return []
    return []
  }, [attribute, isEventProperty, isScreenProperty, eventSegment, screenname, eventValue, parentType, dispatch, appId, isWebApp, activeEventTab, operatorData?.attribute, searchAttributeProps?.has_mass_value, searchAttributeProps?.mass_value_segment_id, searchAttributeProps?.mass_values_id, aiSessionFeatureAllowed])

  const initialCall = (remoteData) => {
    if (isArray(remoteData)) {
      // remove sorting from FE
      // const remoteDataSorted = remoteData.sort();
      setFetchedData(remoteData)
      setSearchedStrings({ '': remoteData?.length > 0 })
      setAvailableOptions(remoteData)
    }
  }
  const searchAttributeApi = useCallback(async (isCallApi = false) => {
    if (!isCallApi) {
      let newAttribute = attribute;
      if (attribute === 'event_name') { 
        newAttribute = (activeEventTab === 'smartEvents') ? 'nce_name' : 'event_name' 
      }
      const fetchProperty = appFilter.fetchProperty[newAttribute]
      isEmptyMessage && showEmptyMessage(false)
      const fetchedList = fetchProperty ? fetchProperty.data : []
      if (valueMapping) {
        setFetchedData(valueMapping)
        isCallApi = false
      } else if (!fetchedList.length) isCallApi = true
      else initialCall(fetchedList)
    } else {
      const remoteData = await searchApiCall()
      if (remoteData) {
        showEmptyMessage(!remoteData.length)
        initialCall(remoteData)
      }
    }
  }, [activeEventTab, appFilter.fetchProperty, attribute, isEmptyMessage, searchApiCall, valueMapping])

  const resetFieldsAndCallApi = useCallback(({ isSearchable }) => {
    setSearchAttributeText('')
    showEmptyMessage(false)
    const shouldCallApi = !isOptionsPredefined(attribute)
    setLoading(false)
    setSearchedStrings({})
    setFetchedData([])
    setAvailableOptions([])
    if(isSearchable) searchAttributeApi(shouldCallApi)
  }, [attribute, searchAttributeApi])

  const resetEventsAndCallApi = useCallback(() => {
    setSearchAttributeText('');
    showEmptyMessage(false);
    setFetchedData([]);
    setAvailableOptions([]);
    searchAttributeApi(true);
  }, [searchAttributeApi])

  const handleAvailableContent = (...[,,filteredOptions]) => setFetchedData([...filteredOptions])
  const handleSearchInputProps = useCallback(async (value) => {
    const searchText = value.trim() || ''
    setSearchAttributeText(searchText)
    setLoading(false)
    showEmptyMessage(false)
    if ( isUserCohorts ) {
      const filterOptions = userCohorts || []
      const filteredOptions = filterOptions
        .filter((v) => filterTextByOption(v.name, searchText))
      setFetchedData(
        filteredOptions,
      )
      showEmptyMessage(!filteredOptions.length)
      setFetchedData(filteredOptions)
      return
    }
    if ( isBatchId ) {
      const batchOptions = availableOptions || []
      const filteredOptions = batchOptions
        .filter((v) => filterTextByOption(v.batch_name, searchText))
      showEmptyMessage(!filteredOptions.length)
      setFetchedData(filteredOptions)
      return
    }
    if (valueMapping) {
      // const filterList = isScreenAttribute ? [...renamedScreenList] : [...valueMapping]
      const fetchedList = valueMapping.filter((v) => filterTextByOption(v, searchText));
      showEmptyMessage(!fetchedList.length)
      setFetchedData(fetchedList)
      return
    }
    let filteredOptions = []
    let filteredOptionsNew = []
    const searchedStringsCloned = clone(searchedStrings)
    let availableOptionsNew = [...availableOptions]
    if (searchText === '') {
      setFetchedData(availableOptionsNew)
      return
    }

    filteredOptions = availableOptionsNew.length
      ? availableOptionsNew.filter((item) =>{
        let referenceText = item
        if (attribute === 'uxcamuserid') {
            referenceText = item.name
        } 
        if (attribute === 'uxcam_user_id') {
            referenceText = item.uxcamuserid
        } 
        return filterTextByOption(
              referenceText,
              searchText
            )
        }
        )
      : []
    // if (
    //   !isEmpty(searchedStringsCloned) &&
    //   Object.keys(searchedStringsCloned).includes(searchText) &&
    //   searchedStringsCloned[searchText]
    // ) {
    //   handleAvailableContent(
    //     searchText,
    //     searchedStringsCloned,
    //     filteredOptions
    //   )
    //   return
    // }
    for (const key in searchedStringsCloned) {
      if (searchText.includes(key) && !searchedStringsCloned[key]) {
        showEmptyMessage(true);
        setFetchedData([]);
        return;
      }
    }
    setFetchedData([])
    if( screenNameAttributes.includes(attribute) ) {
      const remoteDataBy100 = await searchApiCall(searchText, 100, 100000)
      filteredOptionsNew = remoteDataBy100.concat(filteredOptions)
      availableOptionsNew = availableOptionsNew.concat(remoteDataBy100)
    } else if (filteredOptions.length < 10) {
      const remoteDataBy100 = await searchApiCall(searchText, 100, 100000)
      // remoteDataBy100?.length >= 1
      //   ? (searchedStringsCloned[searchText] = true)
      //   : (searchedStringsCloned[searchText] = false)
      const remoteDataBy100New = isScreenAttribute ? remoteDataBy100.filter((val) => availableOptionsNew.includes(val)) || []
        : remoteDataBy100.filter((val) => !availableOptionsNew.includes(val)) || [];
      filteredOptionsNew = filteredOptions.concat(remoteDataBy100New)
      availableOptionsNew = availableOptionsNew.concat(remoteDataBy100New)
    } else {
      filteredOptionsNew = filteredOptions 
    }
    showEmptyMessage(!filteredOptionsNew.length)
    setFetchedData(filteredOptionsNew)
    setSearchedStrings(searchedStringsCloned)
    setAvailableOptions(availableOptionsNew)
  }, [attribute, availableOptions, isScreenAttribute, isUserCohorts, isBatchId, searchApiCall, searchedStrings, userCohorts, valueMapping])

  const fetchedList = useMemo(() => {
    if(attribute === 'batch_id') {
      return uniqBy(fetchedData, 'batch_id')
    }
    if(attribute === 'uxcamuserid') {
      const existingUserId = fetchProperty?.uxcamuserid?.data || [];
      if (searchAttrInputText.length > 0) {
        if(fetchedData.length === 0) return uniqBy(existingUserId, 'uxcamuserid').filter((val) => filterTextByOption(val.name, searchAttrInputText));
        return uniqBy(fetchedData, 'uxcamuserid');
      }
      
        return uniqBy([
          ...fetchedData,
          ...existingUserId
        ], 'uxcamuserid');
      
    }
    return uniq(fetchedData)
}, [attribute, fetchedData, searchAttrInputText, fetchProperty]);
const valuesPassed = useMemo(
  () => ({
    activeEventTab,
    isEmptyMessage,
    searchAttrInputText,
    loading,
    fetchedList,
    showEmptyMessage,
    setLoading,
    handleSearchInputProps,
    resetFieldsAndCallApi,
    setActiveEventTab,
    resetEventsAndCallApi,
    menuProps: { ...rest },
    inputRef,
    tabContentWidth,
    setTabContentWidth,
  }),
  [activeEventTab, fetchedList, handleSearchInputProps, inputRef, isEmptyMessage, loading, resetFieldsAndCallApi, resetEventsAndCallApi, rest, searchAttrInputText, setActiveEventTab, tabContentWidth, setTabContentWidth]
);
  return (
    <SearchContext.Provider
      value={valuesPassed}
    >
      {children}
    </SearchContext.Provider>
  )
}

export const useFilterContext = () => {
  const context = React.useContext(SearchContext)
  if (context === undefined) {
    throw new Error('useFilterContext must be used within a FilterContextProvider')
  }
  return context
}

const withContextProps = (Child) => (props) =>
  (
    <SearchContext.Consumer>
      {(context) => <Child {...props} {...context} />}
    </SearchContext.Consumer>
  )
export { FilterContextProvider, withContextProps }
