import { AI_SESSIONS_PER_PAGE } from "components/features/aiSessions"
import { currentTimeZone } from "Utils/DateConversion/dateConversionUtils"

// eslint-disable-next-line no-shadow
export enum TARA_API_VERSION {
  PROD = 'PROD',
  UAT = 'UAT',
  STAGING = 'STAGING',
  EXPERIENCE = 'EXPERIENCE',
  CX = 'CX',
  BIZOPS = 'BIZOPS',
  RESEARCH = 'RESEARCH',
}

  export type EndpointKey = 'chat_thread' | 'chat_list' | 'chat_rename' | 'chat_pin' | 'chat_peek' | 'chat_share'
  export interface DashboardContext {
    session_list: {
      filters: unknown
      date_range: unknown
      page: number
      sessions_per_page: number
    }
    stats: Record<string, number>
    session_detail?: { session_id: string }
  }

  export interface BuildPayloadParams {
    input: string
    appID: string
    userID?: string
    sessionid?: string
    sessionpage: number
    aiMeta: {
      descriptions?: string[]
      total_sessions?: number
    }
    statBoxesData: any
    appFilterSegment: any
    appFilterDateSegment: any
    chatThreadId?: string | null | undefined   //* Initially should be null, and should also reset when version changes
    persona: string
    requestSource?: string
    title?: string
  }

  interface EndpointConfig {
    url: string
    queryKey: (...args: any[]) => string[]
  }

  interface VersionConfig {
    baseURL: string
    endpoints: Record<EndpointKey, EndpointConfig>
    buildChatStreamPayload: (params: BuildPayloadParams) => object
  }

  interface DebugVersionConfig extends VersionConfig {
    debugEndpoints?: Partial<Record<EndpointKey, EndpointConfig>>
  }

  class TaraApiFactory {
    private readonly config: Record<TARA_API_VERSION, DebugVersionConfig>

    constructor() {
      const useProxy = process.env.USE_PROXY === 'true'
      const sessionsPerPage = AI_SESSIONS_PER_PAGE

    const baseURLProd = useProxy ? '/_tara_prod' : process.env.TARA_PROD_API || ''
    const baseURLUat = useProxy ? '/_tara_uat' : process.env.TARA_UAT_API || '';
    const baseURLStaging = useProxy ? '/_tara_staging' : process.env.TARA_STAGING_API || ''
    const baseURLExperience = useProxy ? '/_tara_experience' : process.env.TARA_EXPERIENCE_API || ''
    const baseURLCx = useProxy ? '/_tara_cx' : process.env.TARA_CX_API || ''
    const baseURLBizops = useProxy ? '/_tara_bizops' : process.env.TARA_BIZOPS_API || ''
    const baseURLResearch = useProxy ? '/_tara_research' : process.env.TARA_RESEARCH_API || ''

      this.config = {
        [TARA_API_VERSION.PROD]: TaraApiFactory.buildVersionConfig(baseURLProd, 'prod', sessionsPerPage),
        [TARA_API_VERSION.UAT]: TaraApiFactory.buildVersionConfig(baseURLUat, 'uat', sessionsPerPage),
        [TARA_API_VERSION.STAGING]: TaraApiFactory.buildVersionConfig(baseURLStaging, 'staging', sessionsPerPage),
        [TARA_API_VERSION.EXPERIENCE]: TaraApiFactory.buildVersionConfig(baseURLExperience, 'experience', sessionsPerPage),
        [TARA_API_VERSION.CX]: TaraApiFactory.buildVersionConfig(baseURLCx, 'cx', sessionsPerPage),
        [TARA_API_VERSION.BIZOPS]: TaraApiFactory.buildVersionConfig(baseURLBizops, 'bizops', sessionsPerPage),
        [TARA_API_VERSION.RESEARCH]: TaraApiFactory.buildVersionConfig(baseURLResearch, 'research', sessionsPerPage),
      }
  }

  private static buildVersionConfig(baseURL: string, key: string, sessionsPerPage: number): DebugVersionConfig {
    return {
      baseURL,
      endpoints: {
        chat_thread: {
          url: `${baseURL}/chat_thread`,
          queryKey: (appID: string, persona: string) => [`ai-chat-messages-${key}`, appID, persona],
        },
        chat_list: {
          url: `${baseURL}/chat/list`,
          queryKey: (appID: string) => [`chat-list-${key}`, appID],
        },
        chat_rename: {
          url: `${baseURL}/chat/session-detail/rename`,
          queryKey: () => [],
        },
        chat_pin: {
          url: `${baseURL}/chat/session-detail/pin`,
          queryKey: () => [],
        },
        chat_share: {
          url: `${baseURL}/chat/share`,
          queryKey: () => [],
        },
        chat_peek: {
          url: `${baseURL}/chat_thread/peek`,
          queryKey: (appID: string) => [`chat-peek-${key}`, appID],
        },
      },
      debugEndpoints: {
        chat_thread: {
          url: `${baseURL}/debug/chat_thread`,
          queryKey: (appID: string, persona: string) => [`ai-chat-messages-${key}-debug`, appID, persona],
        },
      },
      buildChatStreamPayload: (params) => TaraApiFactory.buildStreamPayload(params, sessionsPerPage),
    }
  }

  private static buildStreamPayload(params: BuildPayloadParams, sessionsPerPage: number) {
    const {
      input,
      appID,
      userID,
      sessionid,
      sessionpage,
      aiMeta,
      statBoxesData,
      appFilterSegment,
      appFilterDateSegment,
      chatThreadId,
      persona,
      requestSource,
      title,
    } = params
    return {
      appName: 'tara',
      userId: userID,
      sessionId: chatThreadId,
      persona,
      timezone: currentTimeZone,
      newMessage: {
        parts: [
          {
            text: input,
          },
        ],
        role: 'user',
      },
      streaming: true,
      app_id: appID,
      app_description: aiMeta?.descriptions?.join(' ') || '',
      ...(requestSource && { request_source: requestSource }),
      ...(title && { title }),
      dashboard_context: {
        session_list: {
          filters: appFilterSegment,
          date_range: appFilterDateSegment,
          page: sessionpage || 1,
          sessions_per_page: sessionsPerPage,
        },
        stats: TaraApiFactory.buildStats(statBoxesData, aiMeta),
        ...(sessionid && {
          session_detail: { session_id: sessionid },
        }),
      },
    }
  }

  public getEndpoint(version: TARA_API_VERSION, endpoint: EndpointKey, debugMode = false): string {
    if (debugMode && this.config[version]?.debugEndpoints?.[endpoint]) {
      return this.config[version]?.debugEndpoints?.[endpoint]?.url ?? ''
    }
    return this.config[version]?.endpoints?.[endpoint]?.url ?? ''
  }

    public getQueryKey(version: TARA_API_VERSION, endpoint: EndpointKey, debugMode = false, ...args: any[]): string[] {
      if (debugMode && this.config[version]?.debugEndpoints?.[endpoint]) {
        return this.config[version]?.debugEndpoints?.[endpoint]?.queryKey?.(...args) ?? []
      }
      return this.config[version]?.endpoints?.[endpoint]?.queryKey?.(...args) ?? []
    }

    public getBaseURL(version: TARA_API_VERSION): string {
      return this.config[version]?.baseURL ?? ''
    }

    public buildChatStreamPayload(version: TARA_API_VERSION, params: BuildPayloadParams): object {
      const builder = this.config[version]?.buildChatStreamPayload
      if (!builder) throw new Error(`No payload builder for version: ${version}`)
      const payload = builder(params)

      return payload
    }

    public createStream(version: TARA_API_VERSION, params: BuildPayloadParams, debugMode = false): EventSource {
      const body = this.buildChatStreamPayload(version, params)
      const query = `body=${encodeURIComponent(JSON.stringify(body))}&version=${version}&debugMode=${debugMode}`
      return new EventSource(`/api/aichat/stream?${query}`)
    }

    private static buildStats(statBoxesData: any, aiMeta: any): Record<string, number> {
      const getVal = (section: string, key: string) =>
        statBoxesData?.boxes?.[section]?.[key]?.value_this_period_number ?? 0

      return {
        sessions_analyzed_by_ai: aiMeta?.total_sessions ?? 0,
        total_sessions: getVal('Sessions', 'count'),
        avg_duration: getVal('Screen Visits', 'Average'),
        users: getVal('Users', 'Total'),
        new_users: getVal('Users', 'New'),
        rage_taps: getVal('Rage Taps', 'Total'),
        crashes: getVal('Crashes', 'Total'),
        ui_freeze: getVal('UI Freeze', 'Frequency'),
      }
    }
  }

  const taraApiFactory = new TaraApiFactory()
  export default taraApiFactory

  const opikProjectId = '019b218a-2973-70db-baa9-68ecd76421b5'

  /**
   * Builds a Comet link for tracing AI invocations
   * @param invocationId - The ADK invocation ID to filter by
   * @returns Comet trace link
   */
  export const buildCometLink = (invocationId: string) =>
  `https://www.comet.com/opik/uxcam/projects/${opikProjectId}/traces?traces_filters=[{"field":"metadata","type":"dictionary","operator":"=","key":"adk_invocation_id","value":"${invocationId}"}]`;


  /**
   * Strips markdown formatting from text while preserving readability
   * Removes formatting characters (bold, italic, code) but keeps structure (lists, headings, line breaks)
   * @param text - The markdown text to convert
   * @param appId - Optional app ID for session link replacement
   * @returns Plain text without markdown formatting characters
   */
  export const stripMarkdown = (text: string, appId?: string, sessionAliasMap?: Record<string, string> | null): string => {
    let plainText = text;

    // Replace session/screenvisit links with formatted URLs (if appId provided)
    if (appId) {
      plainText = plainText.replace(
        /\{\{session:([a-f0-9]{24}|S\d+)\}\}/gi,
        (_match, rawId) => {
          const sessionId = /^S\d+$/i.test(rawId) ? (sessionAliasMap?.[rawId] || rawId) : rawId;
          return `${sessionId} ( https://app.uxcam.com/app/${appId}/aisessions/list/1/${sessionId}?secondarysessionid=${sessionId} )`;
        }
      );

      plainText = plainText.replace(
        /\{\{screenvisit:([a-f0-9]{24}|S\d+),([0-9.:]+),([^}]+)\}\}/gi,
        (_match, rawId, _timestamp, screenName) => {
          const sessionId = /^S\d+$/i.test(rawId) ? (sessionAliasMap?.[rawId] || rawId) : rawId;
          return `${screenName} - ${sessionId} ( https://app.uxcam.com/app/${appId}/aisessions/list/1/${sessionId}?secondarysessionid=${sessionId} )`;
        }
      );
    }

    // Remove bold (**text** or __text__)
    plainText = plainText.replace(/(\*\*|__)(.*?)\1/g, '$2');

    // Remove italic (*text* or _text_)
    plainText = plainText.replace(/(\*|_)(.*?)\1/g, '$2');

    // Remove strikethrough (~~text~~)
    plainText = plainText.replace(/~~(.*?)~~/g, '$1');

    // Remove inline code (`code`)
    plainText = plainText.replace(/`([^`]+)`/g, '$1');

    // Remove code blocks (```code```) - keep the code content
    plainText = plainText.replace(/```[\s\S]*?```/g, (match) => {
      // Extract code content without the backticks and language identifier
      return match.replace(/```\w*\n?/g, '').replace(/```$/g, '');
    });

    // Remove links but keep the text [text](url) -> text
    plainText = plainText.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');

    // Remove images ![alt](url) -> alt
    plainText = plainText.replace(/!\[([^\]]*)\]\([^)]+\)/g, '$1');

    // Remove headers (# Heading, ## Heading, etc.) but keep the text
    plainText = plainText.replace(/^#{1,6}\s+(.*)$/gm, '$1');

    // Remove block quotes (> text or >> text) but keep the text
    plainText = plainText.replace(/^>+\s?/gm, '');

    // Clean up extra whitespace (but preserve structure)
    plainText = plainText.replace(/\n\s*\n\s*\n/g, '\n\n');

    return plainText.trim();
  }
