import React, { useEffect, memo, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux'
import { Button } from 'antd';
import Cookies from 'universal-cookie'
import { WarningOutlined } from '@ant-design/icons';
import styled from 'styled-components'

import { initializeIntercom } from 'Utils/helpers/initializePlugins'
import { errorMessageGlobal, sunBurstMaxMsg } from 'Utils/constants/index'
import { fetchPlanHatApi } from 'redux/actions/common';

const browserCookies = new Cookies()
const cookieFromAdmin = browserCookies.get('loggedInFromAdminDashboard')

export const ErrorBox = memo(({
  errorText,
  displayIcon,
  isNoData,
  isFunnels,
  imgSrc = '/static/icon-no-data.svg',
  errorException,
  onClickHandler
}) => {
  const { sessionid: sessionId } = useSelector(state => state.urlReducer)
  const dispatch = useDispatch()
  const errorTextComponent = useMemo(() => {
    if (errorText && typeof errorText === 'string') {
      if (errorText.includes('Please update your payment method')) {
        return (
          <PlanErrorElement planName={errorText.split(' ')[1]} />
        );
      }
      if (errorText.includes(sunBurstMaxMsg)) {
        return (
          <EmptyMsgContentWrapper>
            <HeadLineStyled>The graph has too many steps</HeadLineStyled><br />
            <ErrorMessageStyled>
              The graph might be too large for your browser. Please try reducing the number of steps.<br />
            </ErrorMessageStyled>
            <Button onClick={onClickHandler} type='primary'>Reduce Steps</Button>{' '}
          </EmptyMsgContentWrapper>
        );
      }
      return errorText;
    }
    return <></>
  }, [errorText, onClickHandler])
  useEffect(() => {
    if(cookieFromAdmin === null || cookieFromAdmin === undefined) initializeIntercom()
  }, [])
  useEffect(() => {
    if(errorException && sessionId) dispatch(
      fetchPlanHatApi({
        action: `${errorText}`,
        info: {
          sessionId,
        },
      })
    );
  }, [errorException])
  return isNoData ? (
    <DataEmptyBoxStyled isFunnels={isFunnels} className="data-empty-box">
      <div className="icon-box">
        <img alt="" src={imgSrc} />
      </div>{' '}
      {errorText === 'error' ? (
        errorMessageGlobal
      ) : (
        <CustomErrorStyled>{errorTextComponent}</CustomErrorStyled>
      )}
    </DataEmptyBoxStyled>
  ) : (
    <span className="dashboard-nqi-error-box">
      {displayIcon && <WarningOutlined />}
      {errorTextComponent}
    </span>
  );
})
const PlanErrorElement = ({ planName }) => (
  <EmptyMsgContentWrapper>
    <Strong text={`Your ${planName} plan payment is expired`} />
    <br />
    Please update your payment method or get in touch with{' '}
    <a
      href="#!"
      onClick={() =>
        typeof window !== 'undefined' &&
        window.Intercom &&
        window.Intercom('show')
      }
    >
      our customer success team
    </a>{' '}
    to regain access to the dashboard.
  </EmptyMsgContentWrapper>
);
const EmptyMsgContentWrapper = ({ children }) => (
  <div className="empty-msg-content">{children}</div>
);
const Strong = ({text}) => <strong>{text}</strong>
const DataEmptyBoxStyled = styled.div`
    background-color: ${({ isFunnels }) => (isFunnels ? 'unset' : '#fff')};
    top: 40px;
`;
const CustomErrorStyled = styled.div`
  text-align: center;
  max-width: 300px;
`
const HeadLineStyled = styled.strong`
  font-size: 22px;
  padding: 10px 0px;
`
const ErrorMessageStyled = styled.p`
  font-size: 12px;
  font-weight: 400;
  line-height: 24px;
  letter-spacing: 0em;
  text-align: center;
  padding
`
export default ErrorBox
