const SubMenuTitle = styled.div`
	svg {
		margin-right: 6px;
	}
`

const ColumnUpdateWrapper = styled.div`
	height: 340px;
	position: relative;
`

const LoaderWrapper = styled.div`
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	height: 100%;
	display: flex;
	justify-content: center;
	align-items: center;
	background-color: rgba(255, 255, 255, 0.5);
	z-index: 10;
`

type IExportTypes = 'visibleOnly' | 'allColumns'

interface IProps {
	headers: any
	onResetSuccess?: () => void
}

const CornerDropdown = ( {
	headers,
	onResetSuccess,
}: IProps ) => {
	const [ visibleDownloadModal, setVisibleDownloadModal ] = React.useState( false )
	const [ downLoadColumn, setDownloadColumn ] = React.useState<IExportTypes>()
	const [ mainDropdownOpened, setMainDropdownOpened ] = React.useState<boolean>( false  )
	const [ subMenuActiveKeys, setSubmenuActiveKeys ] = React.useState<string[]>( [] )
	const [loading, setLoading] = React.useState(false)

	const { currentAppReducer: { _id: appID } } = useSelector( ( state: IReduxState ) => state )
	const {canExportData, isApiError, apiError, setUpgradePlan, upgradePlan, CommonUpgradeModal}: {
		canExportData: boolean,
		isApiError: boolean,
		apiError: any,
		setUpgradePlan: ( val: boolean ) => void,
		upgradePlan: boolean,
		CommonUpgradeModal: () => React.JSX.Element
	} = useCheckExportPlan()

	const handleVisibleModal = React.useCallback( ( visibleFlag: boolean ) => {
      setVisibleDownloadModal( visibleFlag )
	}, [] )

	const handleExportClick = React.useCallback( ( key: IExportTypes ) => {
		if (apiError?.response?.data?.error || isApiError) {
			message.error(
				apiError?.response?.data?.error?.message || 'Something went wrong'
			)
			return
		}
	
		if (canExportData) {
			setDownloadColumn(key);
			setUpgradePlan(false);
			handleVisibleModal(true);
		} else {
			setUpgradePlan(true)
		}
	}, [ apiError, canExportData, isApiError, setUpgradePlan, handleVisibleModal ] )

	const handleClick = React.useCallback( ( { key }: MenuInfo ) => {
		if ( [ 'visibleOnly', 'allColumns' ].includes( key ) ) {
			handleExportClick( key as IExportTypes )
		}
	}, [ handleExportClick ] )

	const closeMenus = React.useCallback( () => {
		setMainDropdownOpened( false )
		setSubmenuActiveKeys( [] )
	}, [] )

	const modalProps = {
		visibleDownloadModal,
		handleVisibleModal,
		downLoadColumn,
		setDownloadColumn,
		globalFilter: undefined,
	}

	const menu = React.useMemo( () => (
		<Menu 
			rootClassName='ai-session-corner-overlay'
			onClick={ ( e ) => handleClick( e ) }
			triggerSubMenuAction='click'
			openKeys={ subMenuActiveKeys }
			onOpenChange={ e => setSubmenuActiveKeys( e ) }
		>
			<SubMenu 
				title={
					<SubMenuTitle>	
						<DownloadOutlined />
						Download data as CSV
					</SubMenuTitle>
				}
				popupOffset={ [ 16, -11 ] }
				key='exportMenu'
			>
				<Menu.Item
					key="visibleOnly"
					id="visibleOnly"
					className='visibleOnly'
					onClick={ closeMenus }
				>
					Visible columns only
				</Menu.Item>
				<Menu.Item
					key="allColumns" 
					id="allColumns"
					onClick={ closeMenus }
				>
					All columns
				</Menu.Item>
			</SubMenu>
			<SubMenu
				title={
					<SubMenuTitle>
						<MenuOutlined />
						Arrange table columns
					</SubMenuTitle>
				}
				popupOffset={ [ 15, -49 ] }
				popupClassName="column-overlay"
				key="orderColumn"
			>
				<Menu.Item data-element="reorder" key="reorder" id="reorder">
					<ColumnUpdateWrapper onClick={props => props.stopPropagation()}>
						{loading && (
							<LoaderWrapper>
								<Spinner />
							</LoaderWrapper>
						)}
						<ColumnUpdate
							type="aiSession"
							appid={ appID }
							dropdownVisible
							setLoading={setLoading}
							setDropdownVisibility={ closeMenus }
							headers={ headers }
							showAddCustomUserButton
							showAddCustomEventButton={ false }
							minWidth={ 200 }
							onResetSuccess={onResetSuccess}
						/>
					</ColumnUpdateWrapper>
				</Menu.Item>
			</SubMenu>
		</Menu>
	), [ appID, handleClick, headers, subMenuActiveKeys, closeMenus, loading ])

	return (
		<>
			<GlobalStyles />
			<Container>
				<Dropdown
					overlay={ menu }
					trigger={ [ 'click' ] }
					align={ { offset: [ 0, 6 ] } }
					arrow={ false }
					placement='bottomRight'
					visible={ mainDropdownOpened || !!subMenuActiveKeys?.length }
					onVisibleChange={ val => setMainDropdownOpened( val ) }
				>
					<KebabIcon />
				</Dropdown>
			</Container>
			{ upgradePlan ? <CommonUpgradeModal /> : 
			visibleDownloadModal && <DownloadDataModal { ...modalProps } /> }
		</>
	)
}

export default memo(CornerDropdown)
