import { useCallback, useMemo } from 'react';

import { message } from 'antd';
import { useSelector, useDispatch } from 'react-redux';
import { useMutation, useQuery, useQueryClient } from 'react-query';

import { trackPageViews } from 'redux/actions/trackingReport';

import { axiosInstance } from 'services/globalInstance';
import { IReduxState } from 'types/reduxStateTypes';
import { useFeatureFlag } from 'uxcam-frontend-components';
import { includeAiFilterInParentTypes } from '../..';

type AiFilterSettingPayload = {
    aiFilter: boolean,
}

export const useAiFilterSettings = () => {
    const { orgId } = useSelector((state: IReduxState) => state.currentOrgReducer);
    const queryClient = useQueryClient();
    const dispatch = useDispatch();
    const AiFilterEnabled = useFeatureFlag('ai-filter')
    const { parentType } = useSelector((state: IReduxState) => state.urlReducer )

    const getAiFilterSettings = useQuery(['aiFilterSettings', orgId], () =>
        axiosInstance.get(
            `${process.env.SUBSCRIPTION_URL}/organization/${orgId}/ai-filter`,
            {
            withCredentials: true,
            }
        ),
        {
            enabled: !!orgId && AiFilterEnabled && includeAiFilterInParentTypes.includes( parentType || '' ),
        }
    )

    const { data: aiFilterSettingsData } = getAiFilterSettings;

    const cachedAiFilterSettings = queryClient.getQueryData(['aiFilterSettings', orgId]) as typeof aiFilterSettingsData;

    const aiFilterSettings = useMemo(() => {
        if (cachedAiFilterSettings && cachedAiFilterSettings?.data) {
            return cachedAiFilterSettings.data.data.aiFilter;
        }
        return aiFilterSettingsData?.data?.data.aiFilter;
    }, [aiFilterSettingsData, cachedAiFilterSettings]);

    const getSuccessMessage = useCallback((aiFilter: boolean) => `Smart filter has been ${aiFilter ? 'enabled' : 'disabled'} on all the apps of your organization
        `, [])

    const updateAiFilterSettings = useMutation({
        mutationFn: (payload: AiFilterSettingPayload) =>
            axiosInstance.put(
                `${process.env.SUBSCRIPTION_URL}/organization/${orgId}/ai-filter`,
                payload,
                {
                withCredentials: true,
                }
            ),
        onSuccess: (response, variables) => {
            if (response?.data?.success) {
                queryClient.setQueryData(['aiFilterSettings', orgId], (prev: any) => ({
                        ...prev,
                        data: {
                            ...prev.data,
                            data: {
                                ...prev.data.data,
                                aiFilter: variables.aiFilter,
                            },
                        },
                    }));
                
                // track event
                dispatch(trackPageViews(null, {
                    eventName: 'wa_ai_filter_setting',
                    track_type: 'event',
                    eventProperty: {
                        ai_filter_status: variables.aiFilter,
                    }
                }))
            }
            message.success(getSuccessMessage(variables.aiFilter));
        },
    })

    return { getAiFilterSettings, updateAiFilterSettings, aiFilterSettings };
}