import React, { useCallback } from 'react'
import Link from 'next/link';

import { Button, Tooltip } from 'antd';
import styled, { createGlobalStyle } from 'styled-components';
import { RootStateOrAny, useDispatch, useSelector } from 'react-redux';

import CircleAlert from 'public/static/circle-alert.svg';
import { trackPageViews } from 'redux/actions/trackingReport';
import { useRestrictionContext,  } from 'components/IntegratePages/layout/context/restrictionContext';
import { IUseRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContextTypes';

const StyledButton = styled(Button)`
    border-radius: 6px;
    border: none !important;
    outline: none;
    background-color: #EFF5FF;
    display: flex;
    justify-content: center;
    align-items: center;
    min-width: 120px;
    height: 32px;
    color: #5D97FF;
    gap: 6px;
    font-weight: 400 !important;
    font-size: 14px !important;
    margin-right: 16px;
    padding: 0 12px;

    &:hover {
        background-color: #E5EEFF;
    }
`

const GlobalStyles = createGlobalStyle`
  #alerts-btn-container {
    & > a {
      padding-top: 0px !important;
    }
    svg {
      height: 16px;
      width: 16px;
    }
    .create-alert-tooltip {
      display: flex !important;
    }
    button:disabled {
      svg {
        path {
          fill: #A1A5AE;
        }
      }
    }
  }
`

const LinkWrapper:React.FC<{ showLink?: boolean; children?: React.ReactNode }> = ( { showLink, children } ) => {
  const { orgId: org, _id: app } = useSelector(
    (state: RootStateOrAny) => state.currentAppReducer
  )

  let el = children

  if ( showLink ) {
    el = (
      <Link
        href={{
          pathname: '/integration',
          query: {
            parentType: 'settings',
            setting: 'app_setting',
            org,
            app,
            app_tab: 'alerts',
          },
        }}
        as={`/settings/app/${org}/${app}/alerts#create-alert`}
        passHref
        data-element="create-alert"
      >
        { children }
      </Link>      
    )
  }

  return (
    <div id="alerts-btn-container">
      { el }    
    </div>
  )
}

const AlertsButton:React.FC = () => {
    const dispatch = useDispatch()
    const { alertsFeatureAllowed } = useRestrictionContext() as unknown as IUseRestrictionContext

    const handleCreateAlertClick = useCallback(  () => {
      dispatch(
        trackPageViews( null, {
          eventName: 'wa_alerts_click_alert_creator',
          track_type: 'event',
          eventProperty: {},
        } )
      )
    }, [ dispatch ] )

    return (
      <>
        <GlobalStyles />
        <LinkWrapper showLink={ alertsFeatureAllowed }>
          <Tooltip title={ alertsFeatureAllowed ? null : 'Alerts are not available on your current plan. Upgrade to use this feature.' } className="create-alert-tooltip">
            <StyledButton type='default' icon={<CircleAlert />} data-intercom-target="Create alert top bar" onClick={ alertsFeatureAllowed ? handleCreateAlertClick : () => null } disabled={ !alertsFeatureAllowed }>
              Create alert
            </StyledButton>
          </Tooltip>
        </LinkWrapper>
      </>
    )
  }

export default AlertsButton;