import React, { useCallback } from 'react';
import styled from 'styled-components';
import { Modal, Button } from 'antd';
import ExclamationCircleRedIcon from 'public/static/exclamation-circle-red-icon.svg';
import { useMassUserIdFilterContext } from './MassUserIdFilterContext';

const StyledModal = styled(Modal)`
  .ant-modal-content {
    border-radius: 8px;
    padding: 32px;
    text-align: left;
  }
  .ant-modal-header {
    border-bottom: none;
    padding: 0;
  }
  .ant-modal-title {
    font-size: 18px;
    font-style: normal;
    color: #161e35;
    font-weight: 500;
    line-height: 24px; /* 133.333% */
    margin-bottom: 16px;
  }
  .ant-modal-body {
    padding: 0;
  }
  .ant-modal-footer {
    border-top: none;
    padding: 0;
  }
`;
const Title = styled.div`
  display: flex;
  align-items: center;
`;
const Description = styled.div`
  padding: 0;
  color: #454b5d;
  font-size: 12px;
  font-style: normal;
  font-weight: 400;
  line-height: 24px; /* 200% */
`;
const NewButton = styled(Button)`
  border: none !important;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  box-shadow: none !important;
  color: #5d97ff !important;
  padding: 4px 29px;
`;

const NewButtonPrimary = styled(NewButton)`
  height: 32px;
  padding: 4px 29px;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  > span {
    color: #ffffff !important;
  }
  &:hover {
    background-color: #4a79cb;
  }
  &:disabled > span {
    color: #828282 !important;
  }
`;
const NoCohortSavedModal: React.FC = () => {
  const {
    showNoCohortSaved,
    setShowNoCohortSaved,
    setShowMassUserIdFilterCtx,
  } = useMassUserIdFilterContext();

  const onBackToFilters = useCallback(() => {
    setShowNoCohortSaved(false);
    setShowMassUserIdFilterCtx(true);
  }, [setShowNoCohortSaved, setShowMassUserIdFilterCtx]);

  return (
    <StyledModal
      visible={showNoCohortSaved}
      onCancel={() => setShowNoCohortSaved(false)}
      footer={null}
      centered
      width={570}
      closable={false}
      title={
        <Title>
          <ExclamationCircleRedIcon style={{ marginRight: 4 }} />
          Cohort couldn’t be saved!
        </Title>
      }
    >
      <Description>
        This cohort couldn’t be saved. None of the provided user IDs were found
        in the UXCam database. Please go back and update the user ID list, then
        try again.
      </Description>
      <div
        style={{
          display: 'flex',
          justifyContent: 'flex-end',
          gap: 24,
          marginTop: 32,
        }}
      >
        <NewButton onClick={() => setShowNoCohortSaved(false)}>
          Cancel
        </NewButton>
        <NewButtonPrimary type="primary" onClick={onBackToFilters}>
          Back to filters
        </NewButtonPrimary>
      </div>
    </StyledModal>
  );
};

export default NoCohortSavedModal;
