/* eslint-disable react/no-array-index-key */
import React, { useEffect, useRef, memo, useMemo,useCallback } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import Cookies from 'universal-cookie';
import { Card, Row, Button, Col } from 'antd'
import styled from 'styled-components';
import clone from 'lodash/clone'
import findIndex from 'lodash/findIndex'
import $ from 'jquery'
import { UpOutlined } from '@ant-design/icons'
import classNames from 'classnames'

import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import { getFilterPropertyRemoteData } from 'redux/actions/filter'
import {
    setActivityFilterSegment,
  setFilterBarVisible,
} from 'redux/actions/megaFilter'
import { updateSelectedEvent } from 'redux/actions/event'
import { mappedPageType } from 'Utils/helpers/commonUtils'
import { trackPageViews } from 'redux/actions/trackingReport'
import {useIsUserV2} from 'hooks/useUserV2Filter'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import AppliedFilter from './AppliedFilter'
import { showSegmentList, hasDisabledSegmentInEvent } from '../utils'
import { ResetFilterIcon, SaveSegmentIcon } from '../FilterSvgs';
import MegaFilterDropdown from '../MegaFilterDropdownV2';
import { useSegmentModal } from '../SegmentMenu/hooks/useModal';
import SaveSegmentModal from '../SegmentMenu/SaveSegment';
import useSegmentAPI from '../SegmentMenu/hooks/useSegmentAPI';
import ActivityFilter from './ActivityFilter';
import AppliedSequenceFilter from './AppliedFilter/AppliedSequenceFilter';
import { useAppliedFilterContext } from '../../context/AppliedFilterContext';


const browserCookies = new Cookies();

const sequenceAttributeList = [ 'action_sequence_ordered', 'action_sequence', 'action_sequence_conversion' ]

const ButtonWrapper = styled(Button)`
  color: #5D97FF !important;
  display: inline-flex;
  svg {
    display: block;
    width: 16px;
    margin-right: 8px;
  }
`

const FilterDisplayBar = () => {
  const { callListApi, segmentType } = useAppFilter()
  const filterBarRef = useRef()
  const dispatch = useDispatch()
  const {
    megaFilterReducer: {
      filterBarVisible,
    },
    urlReducer,
    appFilter
  } = useSelector((state) => state);

  const { appliedSegment, setAppliedSegment, toggleModal } = useSegmentModal();
  const { invalidateQueries } = useSegmentAPI();
  const isUserV2 = useIsUserV2();
  const { aiSessionFeatureAllowed } = useRestrictionContext() || {};
  const isMounted = useRef(false);
  const { parentType } = urlReducer
  const pageType = mappedPageType[parentType]
  const filterSegmentList = clone(appFilter[segmentType].segment)
  // const segmentType = mappedSegmentType[parentType]
  const element = $('#mega-display-bar').is(':visible')
  const filterSegment = clone(appFilter[segmentType].segment)
  const handleFilterDelete = async (filterData) => {
    const index = appFilter[segmentType].segment.indexOf(filterData)
    const segment = appFilter[segmentType].segment.filter((_,i) => i !== index)
    callListApi(segment)
    if (!segment.length) {
      dispatch(setFilterBarVisible(true))
    }
  }
  const handleClearFilter = () => {
    // * CX-1876: If userlist and iceberg clear activityCallList 
    if(isUserV2) {
        dispatch(setActivityFilterSegment([]))
    }
    callListApi([])
    dispatch(updateSelectedEvent([]))
    setAppliedSegment({ name: `All ${pageType}s`, segment: [] });
    invalidateQueries();
    dispatch(setFilterBarVisible(false))
    dispatch(trackPageViews(null, {
    eventName: 'clear_filter',
    track_type: 'event',
    pageName: parentType,
    eventProperty: {}
  }))
  }
  const activityFilterList = appFilter[segmentType]?.activityFilterList;
  const scrollToTop = () => filterBarRef.current?.scrollIntoView(true)
  const hasDisabledAtrribute = useCallback((filterSegments)=> hasDisabledSegmentInEvent(filterSegments, parentType), [parentType])

  const hasEventSegment = useMemo(()=> hasDisabledAtrribute(filterSegmentList, parentType), [filterSegmentList, parentType, hasDisabledAtrribute]);

  useEffect(() => {
    const indexOfUserName = findIndex(appFilter[segmentType].segment, {
      attribute: 'uxcamuserid',
    })
    if (indexOfUserName > -1) {
      const payload = {
        search: '',
        attribute: 'uxcamuserid',
        dropdownLimit: 501,
      }
      dispatch(getFilterPropertyRemoteData( payload ))
    }
  }, [])

  useEffect(() => {
    if (aiSessionFeatureAllowed) {
      dispatch(getFilterPropertyRemoteData({
        search: '',
        attribute: 'batch_id',
        dropdownLimit: 501,
      }))
    }
  }, [aiSessionFeatureAllowed, dispatch])
  
const shouldDisplayFilterSegment = useMemo(()=>{
    if(isUserV2){
        return Boolean(filterSegment.length) || Boolean(activityFilterList.length) 
    } 
    return Boolean(filterSegment.length)
}, [activityFilterList, filterSegment, isUserV2])

const showClearAll = useMemo(()=>{
    if(isUserV2){
        return  Boolean(filterSegment.length) || Boolean(activityFilterList.length) 
    } 
    return Boolean(filterSegment.length)
},[ filterSegment, activityFilterList ,isUserV2]);

const isFilterBarVisible = useMemo(()=>{
    return filterBarVisible
},[filterBarVisible])

  useEffect(() => {
    if (element) scrollToTop()
  }, [element, isFilterBarVisible])
  // if (pageType === 'event') filterSegment = filterSegment.filter( ({ attribute }) => attribute !== 'event_name')

  const [sequenceStepFilters, normalFilters ] = React.useMemo( () => {
    const sequenceList = filterSegment.filter(({ attribute }) => sequenceAttributeList.includes( attribute ) );
    const normalList = filterSegment.filter(({ attribute }) => !sequenceAttributeList.includes( attribute ) );
    return [ sequenceList, normalList ]
  }, [filterSegment])

  const segmentName = useMemo(() => appliedSegment?.name, [appliedSegment?.name])

  const loginInFromGuest = browserCookies.get('loggedInType');

  useEffect(() => {
    if(isUserV2 && !isMounted.current) {
        dispatch(setFilterBarVisible(true))
        isMounted.current = true
    }
  },[activityFilterList, dispatch, isUserV2])

  const { viewOnly } = useAppliedFilterContext();

  return (
    <>
    <div ref={filterBarRef} id='mega-display-bar'>
      {shouldDisplayFilterSegment ? (
        <Card
          className={classNames(viewOnly ? 'filter-display-bar-view-only' : 'filter-display-bar')}        
          bodyStyle={{ padding: 15 }}
          style={{ 
            display: isFilterBarVisible ? 'block' : 'none'
         }}
          id="filter-display-bar"
        >
          <Row>
            {sequenceStepFilters?.map((data, index) => (
                <AppliedSequenceFilter key={`filter_${index}_${data.attribute}`} filterData={data} hasMoreFilters={isUserV2 ? true: !!normalFilters.length}
              />
            ))}
            {isUserV2 && activityFilterList?.map((_, filterIndex) => (
                <ActivityFilter filterIndex={filterIndex} key={`activity_filter_${filterIndex}`} />
            ))}
            {normalFilters.map((data, index, list) => (
              <AppliedFilter
                callListApi={callListApi}
                key={`filter_${index}_${data.attribute}`}
                filterData={data}
                filterIndex={index}
                handleFilterDelete={handleFilterDelete}
                filterSegment={list}
                pageType={pageType}
                segmentType={segmentType}
              />
            ))}
          </Row>
          <Button
            icon={<UpOutlined />}
            onClick={() => dispatch(setFilterBarVisible(false))}
            type='text'
            ghost
            className='display-bar-btn'
          />
          <Row>
            <Col span={24} className='filter-display-btn-wrapper'>
                <MegaFilterDropdown />
                {showClearAll && <ButtonWrapper
                  onClick={handleClearFilter}
                  className="filter-spacing clear-all-btn"
                  size='small'
                  icon={<ResetFilterIcon />}
                  data-intercom-target="Clear all"
                >
                  Clear all
                </ButtonWrapper>}
                {showSegmentList.includes(pageType) && !hasEventSegment && !sequenceStepFilters.length &&
                  (segmentName || loginInFromGuest === 'guest'
                    ? null : (
                      <ButtonWrapper
                        onClick={() => {
                          toggleModal?.('save', []);
                        }}
                        className="filter-spacing add-btn"
                        size="small"
                        icon={<SaveSegmentIcon />}
                        data-intercom-target="Save segment"
                      >
                        Save as segment
                      </ButtonWrapper>
                    ))}
            </Col>
          </Row>
        </Card>
      ) : (
        null
      )}  
    </div>
    <SaveSegmentModal />
    </>
  );
}
export default memo(FilterDisplayBar)
