import { useMemo } from "react";
import { RootStateOrAny, useSelector } from "react-redux";
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import Cookies from 'universal-cookie';
import { ISegment } from "../types";

const browserCookies = new Cookies();

const useCheckAccess = (segment: ISegment) => {

  const { createdBy } = segment;

  const { applicationReducer: appList , currentOrgReducer: { orgId }, profileReducer: { _id: userId } }
    = useSelector((state: RootStateOrAny) => state);

  const loginInFromGuest = browserCookies.get('loggedInType');
  const guestLogin = loginInFromGuest === 'guest';

  const userSegment = useMemo(() => userId === createdBy, [createdBy, userId]);

  const { isOwner } = appList.find((item: { orgId: string; }) => item.orgId === orgId);

  const isEditAccess = useMemo(() => !guestLogin && ( isOwner || userSegment ), [guestLogin, isOwner, userSegment]);

  return { isOwner, isEditAccess }
}

export default useCheckAccess;