import React, { useState, useEffect, memo, useMemo } from 'react'
import { InputNumber, message, Tooltip } from 'antd'
import debounce from 'lodash/debounce'
import isArray from 'lodash/isArray'
import {
  DateType,
  DebounceInputComponent,
  SelectWithTags,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2'
import { onlyNumber, setPlaceholder, handleDefault } from 'components/shared/GlobalFilter/components/utils'
import { addSecondsSuffix } from 'Utils/helpers/addSecondsSuffix'
import { useAppliedFilterContext } from 'components/shared/GlobalFilter/context/AppliedFilterContext'
import classNames from 'classnames'
import { StyledPropertyPlaceholder } from '../NestedFiltering/Style'

const InlineInputEdit = (props) => {
  const {
    option,
    handleApply,
    operatorData,
    title,
    toggleEditFieldVisibility,
    togglePropFieldVisibility,
    propFieldVisibility,
    setOperatorChangeData,
    editFieldVisibility,
    id: attribute,
    isScreenPropertyValue,
  } = props
  let { filterTitleNew } = props
  if (['eventpropertyname', 'eventpropertyvalue'].indexOf(attribute) > -1) {
    const mappedObj = {
      eventpropertyname: isScreenPropertyValue ? 'screen property' :'event property',
      eventpropertyvalue: isScreenPropertyValue? 'screen property' : 'event property',
    }
    filterTitleNew = mappedObj[attribute]
  }

  let content;
  const placeholder = setPlaceholder('Input value of', filterTitleNew)
  const [inputText, setInputText] = useState('')
  const [listOfOptions, setOptions] = useState([])
  const secondsSuffix = addSecondsSuffix(attribute, option)
  const handleInputChange = (arg) => {
    const value = arg?.target ? arg.target.value : arg
    setOperatorChangeData()
    value && handleApply(value, null, true)
  }
  useEffect(() => {
    isArray(option)
      ? setOptions(option)
      : (typeof option === 'string' || typeof option === 'number') &&
        setInputText(option)
    return () => {
      setInputText('')
      setInputText([])
    }
  }, [option])
  const { viewOnly, disabledFilterMessage} = useAppliedFilterContext();

  const fieldVisibility = useMemo(() => isScreenPropertyValue ? propFieldVisibility : editFieldVisibility, [editFieldVisibility, isScreenPropertyValue, propFieldVisibility])
  if (fieldVisibility) {
    switch (operatorData?.format) {
      case 'float':
     // case 'integer': revert for now
        content = (
          <Tooltip title={disabledFilterMessage}>
            <InputNumber
              autoFocus
              value={inputText}
              onChange={debounce((value) => setInputText(value), 0)}
              onPressEnter={(e) => {
                onlyNumber.test(e.target.value) ? handleInputChange(e) : message.error('Only numbers are allowed!')
              }}
              onBlur={(e) => {
                if (e.target.value && onlyNumber.test(e.target.value) && e.target.value !== String(option)) {
                  handleInputChange(e)
                }
              }}
              onStep={setInputText}
              placeholder={placeholder}
              className='filter-input-integer'
              disabled={viewOnly}
            />
          </Tooltip>
        )
        break
      case 'list_of_integer':
        content = (
          <Tooltip title={disabledFilterMessage}>
            <SelectWithTags
              handleChange={(values) => {
                const newValues = values.filter((x) => onlyNumber.test(x))
                setOptions(newValues)
                newValues.length && handleApply(newValues)
              }}
              value={listOfOptions}
              placeholder={placeholder}
              disabled={viewOnly}
            />
          </Tooltip>
        )
        break
      case 'date_range':
      case 'date':
        content = (
          <Tooltip title={disabledFilterMessage}>
            <DateType
              selectedOperator={operatorData}
              onDateChange={(date) => handleApply(date)}
              defaultValue={option || null}
              editFieldVisibility={editFieldVisibility}
              disabled={viewOnly}
            />
          </Tooltip>
        )
        break
      default:
        if ( [ 'contains_any', 'not_contains_any' ].includes( operatorData?.attribute ) ) {
          content = (
            <Tooltip title={disabledFilterMessage}>
              <SelectWithTags
                handleChange={(values) => {
                  const newValues = values.filter((x) => x.length)
                  setOptions(newValues)
                  newValues.length && handleApply(newValues)
                }}
                value={listOfOptions}
                placeholder={placeholder}
                numeric={false}
                tokenSeparators={[',']}
                disabled={viewOnly}
              />
            </Tooltip>
          )
        } else {
        content = (
            <Tooltip title={disabledFilterMessage}>
              <DebounceInputComponent
                value={inputText}
                debounceTimeout={0}
                onChange={(e) => setInputText(e.target.value)}
                className="filter-input-width"
                onPressEnter={handleInputChange}
                onBlur={(e) => {
                  if (e.target.value !== String(option)) {
                    handleInputChange(e)
                  }
                }}
                placeholder={placeholder}
                disabled={viewOnly}
              />
            </Tooltip>
          )
        }
        break
    }
  } else
    content = (
    <Tooltip title={disabledFilterMessage}>
      <a
        href='#!'
        onClick={(e) => {
          handleDefault(e)
          if(viewOnly) return;
          !isScreenPropertyValue ? ( toggleEditFieldVisibility && toggleEditFieldVisibility(true) ) : (togglePropFieldVisibility && togglePropFieldVisibility(true))
          isArray(option)
            ? setOptions(option)
            : (typeof option === 'string' || typeof option === 'number') &&
            setInputText(option)
        }}
        className={classNames(
            viewOnly && 'filter-input-disabled'
        )}
      >
            {title === 'select_activity' ?
                <StyledPropertyPlaceholder >{placeholder}</StyledPropertyPlaceholder>
                : title} {secondsSuffix}
      </a>
    </Tooltip>
    )
  return content
}
export default memo(InlineInputEdit)
