import React, { memo } from 'react';
import { Select } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import { DownloadOutlined } from '@ant-design/icons';
import { fetchPlanHatApi } from 'redux/actions/common';
import { trackPageViews } from 'redux/actions/trackingReport';
import {
  DownIconSVG,
} from 'components/svg_files';
import styled from 'styled-components';
import exportToCsv from './exportCSV';
import exportToXls from './exportXLS';
import { removeValuesFromFilters } from './commonUtils';

const SelectWrapper = styled(Select)`
  .ant-select-selector {
    padding-left: 3px !important;
  }
`
const { Option, OptGroup } = Select;
const CustomExportGraphDropdown = ({ chartRef, disabled, graphData }) => {
  const dispatch = useDispatch();
  const { urlReducer: urlQuery, sessionStatisticsReducer, appFilter } = useSelector(state => state);
  const { parentType } = urlQuery;
  const { group_list: grpList, series_plot_options: plotOptions } = sessionStatisticsReducer;
  const sessionFilters = appFilter?.session?.segment;
  const sessionDateRange = appFilter?.sessionsList;
  const rawData = graphData?.raw_data

  const trackChartDownloadEvents = (value) => {
    let eventProps = {};
    if (parentType === 'screenFlow' || parentType === 'sunburst') {
      eventProps = {
        track_type: 'event',
        eventName: `s${parentType === 'sunburst' ? 'b' : 'f'}_download`,
        eventProperty: {
          page: 'app navigation',
          description:
            parentType === 'sunburst'
              ? 'User downloads sunburst data'
              : 'User downloads screenflow data',
          additional: `chart.${value.toLowerCase()}`,
        },
      };
    }
    if (parentType === 'sessionStatistics') {
      eventProps = {
        track_type: 'event',
        eventName: 'download_data',
        eventProperty: {
          chartType: plotOptions?.type || 'bar',
          grouping: grpList,
          filters: removeValuesFromFilters(sessionFilters),
          dateRange: sessionDateRange,
          format: value
        },
      };
    }
    dispatch(trackPageViews(null, eventProps));
  };
  const rawDataToCSV = () => {
    if (rawData?.length) {
      const records = rawData.map(v => Object.values(v))
      const columns = rawData.map((v) => Object.keys(v))[0]
      exportToCsv('chart.csv', [columns, ...records])
    } else chartRef?.current?.chart?.downloadCSV();
  }

  const rawDataToXLS = () => {
    if (rawData?.length) {
      const records = rawData.map(v => Object.values(v))
      const columns = rawData.map((v) => Object.keys(v))[0]
      exportToXls('chart.xls', [columns, ...records])
    } else chartRef?.current?.chart?.downloadXLS();
  }

  const handleChange = (value) => {
    switch (value) {
      case 'CSV': rawDataToCSV(); break;
      case 'XLS': rawDataToXLS(); break;
      case 'JPEG': chartRef?.current?.chart?.exportChart({ type: 'image/jpeg' }); break;
      case 'PDF': chartRef?.current?.chart?.exportChart({ type: 'application/pdf' }); break;
      case 'SVG': chartRef?.current?.chart?.exportChart({ type: 'image/svg+xml' }); break;
      default: chartRef?.current?.chart?.exportChart(); break;
    }
    dispatch(
      fetchPlanHatApi({
        action: 'Graph export',
        info: {
          'Export format': value,
          page: parentType
        },
      })
    );
    trackChartDownloadEvents(value);
  }

  return (
      <SelectWrapper data-intercom-target="download" disabled={disabled} value={null} suffixIcon={<DownIconSVG />} dropdownClassName='exportchart-dropdown' optionLabelProp="label" onChange={handleChange}>
        <OptGroup label="Download data as">
        <Option
          value="CSV"
        >
          <DownloadOutlined /> CSV{' '}
        </Option>
        <Option
          value="XLS"
          className="exportchart-xls"
        >
          <DownloadOutlined /> XLS{' '}
        </Option>
        <Option
          value="PNG"
        >
          <DownloadOutlined /> PNG{' '}
        </Option>
        <Option
          value="JPEG"
        >
          <DownloadOutlined /> JPEG{' '}
        </Option>
        <Option
          value="PDF"
        >
          <DownloadOutlined /> PDF{' '}
        </Option>
        <Option
          value="SVG"
        >
          <DownloadOutlined /> SVG{' '}
        </Option>
        </OptGroup>
      </SelectWrapper>
  );
}
export default memo(CustomExportGraphDropdown)
