import React, { useCallback, memo } from "react";
import { useDispatch, useSelector } from 'react-redux'
import { findLastIndex, clone } from 'lodash'
import {
  updateSelectedEvent,
  eventNameFilter,
} from 'redux/actions/event'
import {
  addSegmentV2,
  getFilterPropertyRemoteData,
  resetFetchedPropertyByKey,
} from 'redux/actions/filter'
import { handleValuesByName } from 'redux/actions/statistic'
import SelectDropdownWithCount from 'components/common/SelectDropdownWithCount'
import { fetchPlanHatApi } from 'redux/actions/common'
import composedEventsHoc from '../hoc'

const EventNameDropdown = ({ callApi }) => {
  const dispatch = useDispatch()
  const {
    statisticsReducer: { dropdownVisible },
    urlReducer: urlQuery,
    eventTable: {
      table: eventTable,
      selectedEvent: eventDefaultSelected,
      eventTableLoader,
    },
    appFilter: {
      event: { segment: eventSegment },
    },
  } = useSelector((state) => state);
  const onDropdownVisibleChange = useCallback((flag) =>
    dispatch(handleValuesByName({
      dropName: 'dropdownVisible',
      data: flag
    })), [])
  const callSearchAttribute = useCallback(async (eventPropertyFilter) => {
    let eventPropertyFilterNew
    await dispatch(handleValuesByName({
      dropName: 'eventPropertyFilter',
      data: eventPropertyFilter,
    }))
    if (eventPropertyFilter.length && eventPropertyFilter[0]['value'].length)
      eventPropertyFilterNew = [...eventPropertyFilter]
    else eventPropertyFilterNew = []
    await dispatch(resetFetchedPropertyByKey('event_custom_property'))
    await dispatch(getFilterPropertyRemoteData(
      {
        attribute: 'event_custom_property',
        filter: eventPropertyFilterNew,
        search: '',
        dropdownLimit: 501,
      }
    ))
  }, [])
  const handleSelectionChange = useCallback(async (selectedRowKeys = []) => {
    await dispatch(handleValuesByName({
      dropName: 'loaderDisableSidebar',
      data: true,
    }))
    const eventNames = [...selectedRowKeys];
    // eventTable.filter((v) =>
    //   selectedRowKeys.includes(v.eventname)
    // ).map(v => v.eventname) // removed because of a report on EXP-1006
    dispatch(updateSelectedEvent(eventNames))
    const filter = eventNameFilter(eventNames, eventTable)
    let eventPropertyFilter =
      eventNames.length !== eventTable.length
        ? [
          {
            attribute: 'event_name',
            operator: 'in' || filter.operator,
            value: eventNames || [],
            table: 'event'
          },
        ]
        : []
    callSearchAttribute(eventPropertyFilter)
    if (!eventNames.length) eventPropertyFilter = []
    const index = findLastIndex(eventSegment, { attribute: 'event_name' })
    if (index > -1) {
      let eventSegmentCloned = clone(eventSegment)
      if (eventPropertyFilter.length) eventSegmentCloned[index] = eventPropertyFilter[0]
      else eventSegmentCloned = eventSegment.filter(v => v.attribute !== 'event_name')
      await dispatch(addSegmentV2([...eventSegmentCloned], 'event-filter'))
    } else { await dispatch(addSegmentV2([...eventSegment, ...eventPropertyFilter], 'event-filter')) }
    await callApi(urlQuery.appId)
    if(eventNames.length) dispatch(fetchPlanHatApi({ action: 'Filtered events list page', info: { 'filtered events': JSON.stringify(eventNames) } }))
    dispatch(handleValuesByName({
      dropName: 'loaderDisableSidebar',
      data: false,
    }))
  }, [ eventTable, callSearchAttribute, eventSegment ])
  return (
    <SelectDropdownWithCount
      id='allEvents'
      placeholder='All events'
      onChange={handleSelectionChange}
      selectedList={[...eventDefaultSelected]}
      originalList={eventTable?.map(v => v.eventname)}
      loader={eventTableLoader}
      eventTable={eventTable}
      dropdownVisible={dropdownVisible}
      onDropdownVisibleChange={onDropdownVisibleChange}
      parentType={urlQuery?.parentType}
    />
  )
}
export default composedEventsHoc(memo(EventNameDropdown))
