/* eslint-disable react/jsx-props-no-spreading */
import React, { memo, useCallback, useMemo } from 'react';
import { MinusCircleOutlined } from '@ant-design/icons';
import { Form, Input, Select } from 'antd';
import { useDispatch, useSelector } from 'react-redux';
import styled from 'styled-components';
import { trackPageViews } from 'redux/actions/trackingReport';
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter';
import { useIsAppType } from 'hooks/useIsAppType';
import { FilterCountSvg } from 'components/shared/GlobalFilter/components/FilterSvgs';
import { gesturesValueToStringType, gesturesViewTypeIntToString } from 'components/features/heatmaps/constants';
import GestureAttributes from './GestureAttributes';
import GestureOperator from './GestureOperator';
import GestureValue from './GestureValue';
import GestureAttibute from './GestureAttribute.json';

const FormItem = Form.Item;

const StyledMain = styled.div`
  display: flex;
  gap: 10px;
  margin: 8px 0;
  line-height: normal;
  font-size: 12px;
  .ant-form-item-control-input {
    min-height: auto;
  }
  .ant-form-item {
    line-height: normal;
  }

  .ant-form-item-with-help .ant-form-item-explain {
    width: 100px;
    min-height: 4px;
  }
  .anticon svg {
    font-size: 13px;
    color: #dc4f44;
    margin-bottom: 6px;
  }
`;

const StyledFormItem = styled(FormItem)`
  margin-bottom: 0;
  align-items: baseline;
  a {
    color: #49576e !important;
    min-width: 80px;
  }
  .ant-form-item-explain-error {
    font-size: 12px;
    line-height: normal;
  }
  .ant-col {
    margin-bottom: 0 !important;
  }
  .ant-form-item-control-input {
    align-items: baseline !important;
  }
`;

const StyledDoubleDiv = styled.div`
  display: inline-flex;
  .ant-input {
    border-bottom: 1px dashed #a1a8c2 !important;
  }
  .ant-input-status-error:focus {
    box-shadow: none !important;
  }
`;

const SelectWrap = styled(Select)`
  .ant-select-selector {
    min-width: 40px;
    height: 18px !important;
    border: 0 !important;
    border-bottom: 1px dashed #a1a8c2 !important;
    border-radius: 0 !important;
    padding: 0 !important;
    .ant-select-selection-item {
      font-size: 14px !important;
      line-height: normal !important;
    }
  }
`;

const StyledInput = styled(Input)`
  border: 0;
  border-radius: 0;
  padding: 0;
  margin: 0 8px;
  line-height: normal;
  max-width: 80px;
  .ant-input {
    border-bottom: 1px dashed #a1a8c2 !important;
  }
  :focus {
    box-shadow: none;
    border: none;
  }
`;

const GestureFilterProperties = ({
  attributeProps,
  filterData,
  filterSegment,
}) => {
  const { callListApi } = useAppFilter();
  const [form] = Form.useForm();
  const formData = Form.useWatch('gestureProperties', form);
  const dispatch = useDispatch()
  const { urlReducer } = useSelector((state) => state)

  // app type detection
  const isWebSdk = useIsAppType('web');

  // Filter attributes based on app type
  const filteredGestureAttributes = useMemo(() => {
    return GestureAttibute.filter(attr => {
      if (isWebSdk) {
        return attr.features.includes('websdk');
      }
      return attr.features.includes('default');
    });
  }, [isWebSdk]);

  const segment = useMemo(() => [...filterSegment], [filterSegment]);
  const index = segment.indexOf(filterData);
  const filterValue = useMemo(() => segment[index].filters, [index, segment]);

  const newFilters = useMemo(() => {
    const filteredData = formData?.filter((data) => {
      if (!data?.attribute) {
        return false;
      }
      if (data?.operator === 'between') {
        return data?.value?.lower && data?.value?.upper;
      }
      if (Array.isArray(data?.value)) {
        return data?.value?.length > 0;
      }
      return typeof data?.value !== 'undefined';
    });
    segment[index].filters = filteredData || [];
    return segment;
  }, [segment, index, formData]);

  const handleApply = useCallback(() => {
    const eventProp = newFilters.reduce((acc, item) => {
      item?.filters?.forEach(filter => {
        const { attribute, operator, value } = filter;

        acc.attribute.push(attribute);
        acc.operator.push(operator);

        if (attribute === "gesture_type") {
          acc.value.push(value?.map(val => gesturesValueToStringType[val]));
        } else if (attribute === "viewtype") {
          acc.value.push(value?.map(val => gesturesViewTypeIntToString[val] || 'Unknown view type'));
        } else {
          acc.value.push(value);
        }
      });
      return acc;
    }, {
      attribute: [],
      operator: [],
      value: []
    });


    dispatch(trackPageViews(null, {
      eventName: 'create_filter',
      track_type: 'event',
      eventProperty: [eventProp],
      pageName: urlReducer?.parentType
    }))
    callListApi(newFilters);
  }, [callListApi, dispatch, newFilters, urlReducer?.parentType]);

  const handleRemoveApply = useCallback(
    (eventPropIndex) => {
      const removeEventProp = filterValue.filter(
        (_, valueIndex) => valueIndex !== eventPropIndex
      );
      const newFilterAttribute = removeEventProp?.filter(
        (obj) => obj?.attribute
      );
      segment[index].filters = [...newFilterAttribute];
      callListApi(segment);
    },
    [filterValue, callListApi, segment, index]
  );

  const getSelectedGestureAttribute = useCallback(
    (indexValue) =>
      formData?.length && formData.find((_, ind) => indexValue === ind),
    [formData]
  );

  const handleInitialOperator = useCallback(
    (name) =>
      filteredGestureAttributes.find(
        (dataType) =>
          getSelectedGestureAttribute(name)?.attribute === dataType?.attribute
      )?.initailValue,
    [getSelectedGestureAttribute, filteredGestureAttributes]
  );

  const handleInitialOperatorType = useCallback(
    (name) =>
      filteredGestureAttributes.find(
        (dataType) =>
          getSelectedGestureAttribute(name)?.attribute === dataType?.attribute
      )?.type,
    [getSelectedGestureAttribute, filteredGestureAttributes]
  );

  const getSelectedOperator = useCallback(
    (valueIndex) => getSelectedGestureAttribute(valueIndex)?.operator,
    [getSelectedGestureAttribute]
  );

  const handleFetchList = () => {
    form.validateFields().then(() => {
      handleApply();
    });
  };

  const handleOnBlur = (e) => {
    const { value } = e.target;
    form.validateFields().then(() => {
      value && handleApply();
    });
  };

  const transformBooleanValues = useCallback((values) => {
    // @NOTE: this is a quick fix, all bool values should be sent as boolean, not string
    return values?.map(item => ({
      ...item,
      // eslint-disable-next-line no-nested-ternary
      value: item?.value === "True" ? true : item?.value === "False" ? false : item?.value
    }));
  }, []);

  return (
    <Form
      form={form}
      name="dynamic_form_nest_item"
      autoComplete="off"
      initialValues={{ gestureProperties: transformBooleanValues(filterValue) || [] }}
    >
      <Form.List name="gestureProperties">
        {(fields, { add, remove }) => (
          <>
            {fields.map(({ key, name, ...restField }) => (
              <StyledMain key={key}>
                <FilterCountSvg />

                <StyledFormItem
                  {...restField}
                  name={[name, 'attribute']}
                  rules={[
                    {
                      required: true,
                      message: 'is required',
                    },
                  ]}
                >
                  <GestureAttributes
                    id="property"
                    form={form}
                    name={['gestureProperties', name, 'attribute']}
                    attributeProps={attributeProps}
                    filterData={filterData}
                  />
                </StyledFormItem>
                <StyledFormItem
                  {...restField}
                  name={[name, 'operator']}
                  initialValue={handleInitialOperator(name)}
                >
                  {filteredGestureAttributes.find(
                    (dataType) =>
                      getSelectedGestureAttribute(name)?.attribute ===
                      dataType?.attribute
                  )?.type !== 'bool' ? (
                    <GestureOperator
                      form={form}
                      name={['gestureProperties', name, 'operator']}
                      operatorType={
                        handleInitialOperatorType(name) || 'gesture_position'
                      }
                      defaultValue={handleInitialOperator(name)}
                    />
                  ) : (
                    'is'
                  )}
                </StyledFormItem>

                {getSelectedOperator(name) === 'between' && (
                  <StyledFormItem>
                    <StyledDoubleDiv>
                      <StyledFormItem
                        name={[name, 'value', 'lower']}
                        rules={[
                          {
                            required: true,
                            message: 'Please enter value',
                          },
                          {
                            pattern: /^([+]?[1-9][0-9]*|0)$/,
                            message: 'Negative values are not allowed.',
                          },
                        ]}
                      >
                        <StyledInput
                          type="number"
                          placeholder="Enter value"
                          onPressEnter={handleOnBlur}
                          onBlur={handleOnBlur}
                        />
                      </StyledFormItem>

                      <div>and</div>

                      <StyledFormItem
                        name={[name, 'value', 'upper']}
                        rules={[
                          {
                            required: true,
                            message: 'Please enter value',
                          },
                          {
                            pattern: /^([+]?[1-9][0-9]*|0)$/,
                            message: 'Negative values are not allowed.',
                          },
                        ]}
                      >
                        <StyledInput
                          type="number"
                          placeholder="Enter value"
                          onPressEnter={handleOnBlur}
                          onBlur={handleOnBlur}
                        />
                      </StyledFormItem>
                      {getSelectedGestureAttribute(name)?.attribute ===
                        'gesture_time_on_screenvisit' && <div>seconds</div>}
                    </StyledDoubleDiv>
                  </StyledFormItem>
                )}

                {handleInitialOperatorType(name) === 'bool' && (
                  <StyledFormItem
                    {...restField}
                    name={[name, 'value']}
                    validateTrigger={['onChange', 'onBlur']}
                    rules={[
                      {
                        required: true,
                        message: 'Missing gesture property value',
                      },
                    ]}
                  >
                    <SelectWrap
                      showArrow={false}
                      defaultOpen={
                        getSelectedGestureAttribute(name)?.value === undefined
                      }
                      dropdownStyle={{ minWidth: '80px' }}
                      onChange={handleFetchList}
                      options={[
                        { value: true, label: 'True' },
                        { value: false, label: 'False' },
                      ]}
                    />
                  </StyledFormItem>
                )}

                {getSelectedOperator(name) !== 'between' &&
                  handleInitialOperatorType(name) !== 'bool' && (
                    <StyledFormItem
                      {...restField}
                      name={[name, 'value']}
                      rules={[
                        {
                          required: true,
                          message: 'Value is required',
                        },
                      ]}
                    >
                      <GestureValue
                        form={form}
                        name={['gestureProperties', name, 'value']}
                        attributeProps={attributeProps}
                        filterData={filterData}
                        handleApply={handleApply}
                        defaultOperatorValue={handleInitialOperator(name)}
                      />
                    </StyledFormItem>
                  )}

                <MinusCircleOutlined
                  onClick={() => {
                    remove(name);
                    handleRemoveApply(name);
                  }}
                />
              </StyledMain>
            ))}
            <StyledFormItem>
              <GestureAttributes
                id="condition"
                form={form}
                name={['gestureProperties', formData?.length ?? 0, 'attribute']}
                attributeProps={attributeProps}
                addProperty={add}
                filterData={filterData}
              />
            </StyledFormItem>
          </>
        )}
      </Form.List>
    </Form>
  );
};
export default memo(GestureFilterProperties);
