const aiSessionListRedirectionHelper = {
    modifyUrl: (originalUrl: string) => {
        if (originalUrl.includes('sessions/list')) {
            return originalUrl.replace('sessions/list', 'aisessions/list');
        }
        return originalUrl;
    },

    shouldRedirectToAISessionList: () => {
        return true;
    }
};

export default aiSessionListRedirectionHelper;
