/* eslint-disable no-nested-ternary */
import React, { memo, useState, useCallback, useMemo, useEffect, useRef } from 'react'
import { useDispatch, useSelector } from 'react-redux'
import { Dropdown, Menu, Button, Checkbox } from 'antd'
import { SearchOutlined } from '@ant-design/icons'
import { ViewportList } from 'react-viewport-list'
import isEqual from 'lodash/isEqual'
import sortBy from 'lodash/sortBy'
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip'
import isArray from 'lodash/isArray'
import debounce from 'lodash/debounce'
import { useRouter } from 'next/router'
import { trackPageViews } from 'redux/actions/trackingReport'

import styled from 'styled-components'
import { themeCommon } from 'theme/theme'
import { getFilterPropertyRemoteData, addSegmentV2 } from 'redux/actions/filter'
import { getScreenPayload } from 'components/features/navigation'
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder'
import { changeUrl } from 'redux/actions/common'
import {
  DebounceInputComponent,
  MenuItemGroupWrapper,
  LoaderMenuItem,
  SelectAllAndClear,
  OverThresholdText,
  bringSelectedItemsToTop,
  bringMissingItemsToTop,
} from './CommonComponentsV2'

const Wrapper = styled.div`
  display: flex;
  align-items: center;
  border: 1px solid ${themeCommon.color.Surface10};
  border-radius: 6px;
  overflow: hidden;
  gap: 10px;
  padding: 0 10px;

  > input {
    border: none;
    height: 32px;
    padding: 0px;
    min-width: 250px;
}
`

const WebScreenSearch = () => {
  const [visible, setVisible] = useState(false)
  const [searchText, setSearchText] = useState('')
  const [selectedOptions, setSelectedOptions] = useState([])
  const [initialSelectedOptions, setInitialSelectedOptions] = useState([])
  const [loading, setIsLoading] = useState(false)

  const dispatch = useDispatch()
  const router = useRouter()
  const { appFilter: {
    dateSegment,
    fetchProperty: {
      screen_name: {
        data: screenList
      } = {}
    },
    heatmap: { segment: heatmapSegment },
  },
    urlReducer: {
      appId,
      screenpage = 1
    },
  } = useSelector((state) => state)

  const debouncedFetchScreens = useRef(
    debounce((searchQuery) => {
      setIsLoading(true);
      dispatch(getFilterPropertyRemoteData(getScreenPayload(dateSegment, searchQuery), false, true))
        .finally(() => setIsLoading(false));
    }, 500)
  ).current;

  const fetchScreenList = useCallback(async () => {
    setIsLoading(true);
    try {
      await dispatch(getFilterPropertyRemoteData(getScreenPayload(dateSegment), false, true));
    } finally {
      setIsLoading(false);
    }
  }, [dispatch, dateSegment]);

  useEffect(() => {
    if (!appId) return;
    setSearchText('')
    if (visible) {
      fetchScreenList();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appId, visible]);

  useEffect(() => {
    const screenNameFilter = heatmapSegment?.find(filter => filter.attribute === 'screen_name');
    const urlSelectedOptions = screenNameFilter?.value || [];
    setSelectedOptions(urlSelectedOptions);
    setInitialSelectedOptions(urlSelectedOptions);
  }, [heatmapSegment]);

  const handleVisibleChange = useCallback((visibleState) => {
    setVisible(visibleState);
    // Reset selections to initial state when closing dropdown without applying
    if (!visibleState) {
      setSelectedOptions(initialSelectedOptions);
      setSearchText('');
    }
  }, [initialSelectedOptions]);

  const handleInputClick = useCallback((e) => {
    e.stopPropagation();
    if (!visible) {
      setVisible(true);
    }
  }, [visible]);

  const handleSearch = useCallback((value) => {
    setSearchText(value);
    debouncedFetchScreens(value);
  }, [debouncedFetchScreens]);

  useEffect(() => {
    return () => {
      debouncedFetchScreens.cancel();
    };
  }, [debouncedFetchScreens]);

  const filteredScreenList = useMemo(() => {
    if (loading || !screenList) return []
    return screenList
  }, [screenList, loading])

  const organizedScreenList = useMemo(() => {
    if (!filteredScreenList || !filteredScreenList.length) return [];

    let list = [...filteredScreenList];

    list = bringSelectedItemsToTop(list, selectedOptions);

    if (list.length > 500) {
      list = bringMissingItemsToTop(list, selectedOptions);
    }

    return list;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filteredScreenList, visible]);


  const handleSelectedOptions = useCallback((val) => {
    let updatedOptions;
    if (selectedOptions.includes(val)) {
      updatedOptions = selectedOptions.filter(v => v !== val);
    } else {
      updatedOptions = [...selectedOptions, val];
    }
    setSelectedOptions(updatedOptions);
  }, [selectedOptions])

  const handleSelectAllOptions = useCallback(() => {
    const newSelectedOptions = [...organizedScreenList]
    setSelectedOptions(newSelectedOptions)
  }, [organizedScreenList])

  const handleClearAllOptions = useCallback(() => {
    setSelectedOptions([])
  }, [])

  const checkSelectDisabled = useMemo(() => {
    if (selectedOptions.length !== organizedScreenList.length) return false
    return isEqual(sortBy(selectedOptions), sortBy(organizedScreenList))
  }, [selectedOptions, organizedScreenList])

  const isApplyDisabled = useMemo(() => {
    return loading ||
      !organizedScreenList.length ||
      !selectedOptions.length ||
      isEqual(sortBy([...selectedOptions]), sortBy([...initialSelectedOptions]));
  }, [loading, organizedScreenList, selectedOptions, initialSelectedOptions]);

  const handleApply = useCallback(async () => {
    let screenFilters = selectedOptions
    if (!screenFilters.length && organizedScreenList.length) {
      screenFilters = [organizedScreenList[0]]
      setSelectedOptions(screenFilters)
    }

    const screenFilter = screenFilters.length ? [
      {
        attribute: 'screen_name',
        operator: 'in',
        value: screenFilters,
      }
    ] : []

    const clonedHeatmapSegmentWithoutScreens = heatmapSegment.filter(v =>
      v.attribute !== 'screen_name'
    )

    const newSegment = [...screenFilter, ...clonedHeatmapSegmentWithoutScreens]

    await dispatch(addSegmentV2(newSegment, 'heatmap-filter'))

    const baseUrl = `/app/${appId}/screens/list/${screenpage}`

    dispatch(
      changeUrl({
        appId,
        parentType: 'heatmapsList',
        url: baseUrl,
      })
    )

    router.push(
      `/integration?parentType=heatmapsList&appId=${appId}&screenpage=${screenpage}`,
      urlSegmentEncoder(baseUrl, newSegment)
    )
    setVisible(false)
    setInitialSelectedOptions(screenFilters);
  }, [selectedOptions, organizedScreenList, heatmapSegment, dispatch, appId, screenpage, router])

  const prevSearchText = useRef('');
  const prevScreenList = useRef();
  useEffect(() => {
    if (
      searchText &&
      searchText !== prevSearchText.current &&
      Array.isArray(screenList) &&
      screenList.length > 0 &&
      searchText.trim().length > 0
    ) {
      dispatch(trackPageViews(null, {
        eventName: 'wa_screens_search_screen',
        track_type: 'event',
        eventProperty: {
          searchTerm: searchText,
        },
      }));
      prevSearchText.current = searchText;
      prevScreenList.current = screenList;
    }
  }, [screenList, searchText, dispatch]);

  const menu = (
    <Menu selectedKeys={selectedOptions}>
      <LoaderMenuItem spinning={loading} className={`loader-menu-item ${loading ? 'loading' : ''}`}>
        <MenuItemGroupWrapper
          placeholder="Search screen names"
          onChange={(e) => handleSearch(e.target.value)}
          value={searchText}
          id="filtered-screens"
          editFieldVisibility
          headerChildren={
            <>
              {!loading && organizedScreenList.length > 500 && (
                <OverThresholdText
                  text='Not all results are displayed - type to search for more.'
                />
              )}
              {!loading && (
                <SelectAllAndClear
                  newFetchedList={organizedScreenList}
                  handleSelectAllOptions={handleSelectAllOptions}
                  handleClearAllOptions={handleClearAllOptions}
                  disableSelect={checkSelectDisabled}
                  disableClear={selectedOptions.length <= 0}
                />
              )}
            </>
          }
        >
          <div>
            {loading ? (
              <div className="loading-message" />
            ) : organizedScreenList.length ? (
              <ViewportList
                items={organizedScreenList}
              >
                {(screen) => {
                  const displayName = screen

                  return (
                    <li key={screen}>
                      <Checkbox
                        checked={isArray(selectedOptions) && selectedOptions.includes(screen)}
                        onChange={() => handleSelectedOptions(screen)}
                      >
                        <span className='checkbox-label'>
                          <CellOverflowTooltip
                            width={230}
                            text={displayName}
                            value={displayName}
                            tooltipElement={screen}
                            placement='topLeft'
                          />
                        </span>
                      </Checkbox>
                    </li>
                  )
                }}
              </ViewportList>
            ) : (
              <div className="no-results">No matching screens found</div>
            )}
          </div>
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
      <div key="button-bar" className='button-bar'>
        <Button type='primary-outline' onClick={() => handleVisibleChange(false)}>
          Cancel
        </Button>
        <Button
          type='primary'
          onClick={handleApply}
          disabled={isApplyDisabled}
        >
          Apply
        </Button>
      </div>
    </Menu>
  )

  return (
    <Dropdown
      overlay={menu}
      overlayClassName="multi-column-menu mega-segment-menu filter-applied-segment-menu web-search"
      onVisibleChange={handleVisibleChange}
      visible={visible}
      trigger={['click']}
    >
      <Wrapper onClick={(e) => e.stopPropagation()}>
        <DebounceInputComponent
          prefix={<SearchOutlined />}
          placeholder="Search screens"
          className="filter-input-width"
          onClick={handleInputClick}
          onChange={(e) => handleSearch(e.target.value)}
          value={searchText}
          editFieldVisibility
        />
      </Wrapper>
    </Dropdown>
  )
}

export default memo(WebScreenSearch)