/* eslint-disable no-nested-ternary */
/* eslint-disable jsx-a11y/click-events-have-key-events */
import React, { memo, useCallback, useMemo, useState } from "react";
import { RootStateOrAny, useDispatch, useSelector } from "react-redux";
import { Button, Popover, Tooltip } from "antd";
import { resetActivityFilterSegment, setActivityFilterSegment, setFilterBarVisible } from "redux/actions/megaFilter";
import EditImage from 'public/static/segments/editSegment.svg';
import { getFilterListWithActivityFilterCheck, hasActivityFilterChangedFromDefaultState } from "Utils/helpers/activityFilterUtils";
import { addSegmentV2 } from "redux/actions/filter";
import { useIsUserV2 } from "hooks/useUserV2Filter";
import { ActivityFilterPayloadType } from "types/activityFilterConfigurationTypes";
import { adjustRawSegment } from "Utils/helpers/segmentHelper";
import { SegmentListWrapper, StyledSegmentSpan } from "./styles";
import { hasDisabledSegmentInEvent, highlightMatchingItems } from "../utils";
import useAppFilter from "../useAppFilter";
import { DefaultDisabledSegment, DisabledSegemntText, EventPages, PublicImageAlt, SegmentAddReplacetext, SegmentReplacetext, segmentTooltipInfo } from "./variables";
import { useSegmentModal } from "./hooks/useModal";
import { IFilter, ISegment, ISegmentDropdownProps, ISegmentListItemProps, ISegmentMenuTooltip } from "./types";
import useCheckAccess from "./hooks/useCheckAccess";
import TooltipContainer from "./TooltipContainer";

const SegmentListItem: React.FC<ISegmentListItemProps> = memo(({ segment }) => {
  const isUserV2 = useIsUserV2()

  const dispatch = useDispatch();
  const { filter: segmentFilter, name: segmentName, isDefault, createdByName, createdBy, isPublic } = segment;

  const { isEditAccess } = useCheckAccess(segment);
  const { callListApi, pageType, segmentType, activityCallListApi } = useAppFilter();
  const { appliedSegment, searchText, toggleModal } = useSegmentModal();
  const [popOverVisible, onVisibleChange] = useState(false);

  const newPageType = useMemo(() => pageType === 'event' ? 'session' : pageType, [pageType]);
  const { urlReducer: { parentType }, appFilter, applicationReducer: appList, currentOrgReducer: { orgId }, profileReducer: userProfile } = useSelector((state: RootStateOrAny) => state);
  const activityFilterList = appFilter[segmentType].activityFilterList as ActivityFilterPayloadType[]
  const hasAppliedFilterSegment = appFilter[segmentType].segment.length > 0 || hasActivityFilterChangedFromDefaultState(activityFilterList); 
  const isDefaultResetSegment = useMemo(() => segment.name === `All ${pageType}s`, [pageType, segment.name])

  const isFilterSegmentDisabledOnSession = useMemo(
    () => newPageType === 'session' && !EventPages.includes(parentType) ? segmentFilter?.some(filter => filter?.attribute === 'event_custom_property') : false,
    [newPageType, parentType, segmentFilter]);

  const isDisabledSegment = useMemo(() => hasDisabledSegmentInEvent(segmentFilter, parentType) || isFilterSegmentDisabledOnSession, [isFilterSegmentDisabledOnSession, parentType, segmentFilter]);
  const hasEventFilter = useMemo(() => segmentFilter.some(seg => seg?.attribute === 'event_name'), [segmentFilter]);
  const isLongSegmentName = useMemo(() => segment.name.length > 28, [segment.name]);
  const segmentNameDisabled = useMemo(() => segment?.name === appliedSegment?.name, [appliedSegment?.name, segment?.name])
  const hasSequenceFilter = useMemo(() => segmentFilter.some(({ attribute }) => [ 'action_sequence_ordered', 'action_sequence', 'action_sequence_conversion' ].includes( attribute ) ), [segmentFilter]);
  const isSegmentBlockDisabled = useMemo(() => ( isDisabledSegment || hasSequenceFilter), [isDisabledSegment, hasSequenceFilter]);
  
  const isTeamSegments = useMemo(() => {
    const isOwner = appList.find((item: { orgId: string }) => item.orgId === orgId)?.isOwner;
    if (isOwner) return createdBy !== userProfile['_id'] && !isDefault;
    return createdBy !== userProfile['_id'] && isPublic && !isDefault;
  }, [appList, createdBy, isDefault, isPublic, orgId, userProfile]);

  const disabledSegmentText = useMemo(() => {
    if (isFilterSegmentDisabledOnSession || (isDisabledSegment && hasEventFilter)) {
      return <span>{`This segment can't be applied to the ${segmentTooltipInfo[parentType as keyof ISegmentMenuTooltip]}s page because it has an ${hasEventFilter ?
        'event name among its properties' : 'event property among its conditions'}. Consider creating a new segment.`}</span>
    }
    if (isDisabledSegment) {
      return <span>{DisabledSegemntText}</span>
    }
    if (hasSequenceFilter) {
      return <span>{DefaultDisabledSegment}</span>
    }
    return null;
  }, [hasEventFilter, hasSequenceFilter, isDisabledSegment, isFilterSegmentDisabledOnSession, parentType])

  const tooltipText = useMemo(() =>
    isLongSegmentName ?
      <TooltipContainer>
        {isTeamSegments ?
          <p>{segmentName} was created by <span className='user-name'>{createdByName}</span></p>
          : <p>{segmentName}</p>}
        {disabledSegmentText ? <i>{disabledSegmentText}</i> : null }
      </TooltipContainer>
      :
      isTeamSegments ?
        <TooltipContainer>
          <p>Created by <span className='user-name'>{createdByName}</span></p>
          {disabledSegmentText ? <i>{disabledSegmentText}</i> : null}
        </ TooltipContainer> : disabledSegmentText
    , [isLongSegmentName, isTeamSegments, segmentName, createdByName, disabledSegmentText]);

  const setPopoverVisibility = () => {
    onVisibleChange(!popOverVisible);
  }

  const applySegmentFilter = useCallback(async (appliedSegmentFilter: Array<IFilter | ActivityFilterPayloadType>) => {
    toggleModal?.('reset', {});
    onVisibleChange(false);

    if(!isUserV2){
        callListApi(appliedSegmentFilter);
        dispatch(setFilterBarVisible(true));
        return;
    }
    if(appliedSegmentFilter.length === 0){
        dispatch(setFilterBarVisible(true))
        await dispatch(addSegmentV2([]));
        dispatch(resetActivityFilterSegment())
        activityCallListApi();
        return;
    }
    
    // * three segregation is required
    // * 1: normal segment
    // * 2: new segment // * need to be added to default activity filter
    // * 3: activity filter segment
   const {normalSegment, activitySegment} = adjustRawSegment(appliedSegmentFilter)  

   await dispatch(addSegmentV2(normalSegment));
   
   dispatch(setActivityFilterSegment(activitySegment));

   activityCallListApi();
   dispatch(setFilterBarVisible(true));
  }, [activityCallListApi, callListApi, dispatch, isUserV2, toggleModal])

  const handleSegmentReplace = useCallback((e: React.MouseEvent<HTMLElement> | null, replacedSegmentFilter: IFilter[]) => {
    e && e?.stopPropagation();
    applySegmentFilter(replacedSegmentFilter);
  }, [applySegmentFilter])


  const handleAddSegment = useCallback((e: React.MouseEvent<HTMLElement>, sessionSegment: IFilter[]) => {
    e.stopPropagation();
    if(isUserV2){
        const updatedActivityFilterSegment = appFilter[segmentType].activityFilterList?.length ?
         getFilterListWithActivityFilterCheck( appFilter[segmentType].activityFilterList, appFilter[segmentType].segment, true) : 
         []
        const addedSegment = [...sessionSegment, ...updatedActivityFilterSegment]; 
        applySegmentFilter(addedSegment);
    }else{
        applySegmentFilter(sessionSegment);
    }
  }, [appFilter, applySegmentFilter, isUserV2, segmentType])

  const toggleModalAndPopover = useCallback((seg: ISegment) => {
    toggleModal?.('save', seg);
  }, [toggleModal]);

  return (
    <li>
      <Popover
        className={isSegmentBlockDisabled ? 'disabled' : segmentNameDisabled ? 'selected' : ''}
        overlayClassName='popupSegementOverlay'
        trigger={segment?.name === appliedSegment?.name ? '' : 'click'}
        style={{
          height: '30px',
        }}
        placement='topLeft'
        onVisibleChange={() => {
          if (isSegmentBlockDisabled) {
            return;
          }
          if (hasAppliedFilterSegment) {
            setPopoverVisibility();
            return;
          }
          handleSegmentReplace(null, segment?.filter);
        }}
        visible={popOverVisible}
        title={segment?.name === `All ${pageType}s`
          ? SegmentReplacetext
          : SegmentAddReplacetext}

        content={
          <div>
            <Button size="small" onClick={(e) => handleSegmentReplace(e, segment?.filter)}>
              Replace
            </Button>
            {segment?.name !== `All ${newPageType}s` && (
              <Button size="small" onClick={(e) => handleAddSegment(e, segment?.filter)} >
                Add
              </Button>
            )}
          </div>
        }
      >        
        <Tooltip title={tooltipText} placement="right" overlayClassName="segmentTooltipOverlay">
          <StyledSegmentSpan className='content-wrapper'>
            <img src={segment?.isPublic ? '/static/segments/publicSegment.svg' : '/static/segments/privateSegment.svg'}
              alt={PublicImageAlt} />
            <span>
              {highlightMatchingItems(segment.name, searchText)}
            </span>
            
            {isEditAccess && !isDefaultResetSegment ?
              <Button
                className={isDisabledSegment ? 'disabled' : ''}
                onClick={(e) => {
                  e.stopPropagation();
                  if (isDisabledSegment) return;
                  toggleModalAndPopover(segment);
                }}
                icon={<EditImage />}
                type="text" /> : null}
          </StyledSegmentSpan>
        </Tooltip>
      </Popover>
    </li>
  )
})

const SegmentList: React.FC<ISegmentDropdownProps> = ({ title, segments }) => (
  <SegmentListWrapper>
    <h4>{title}</h4>
    <div
      className="scrollWrapper">
      {segments.length > 0 ? segments.map((segment) => (
        <SegmentListItem key={segment.name} segment={segment} />
      )) : <p className="noMatchingSegment">No matching filter</p>}
    </div>
  </SegmentListWrapper>)


export default memo(SegmentList);