import React, { memo, useMemo } from 'react';
import { Button } from 'antd'
import { useSelector, useDispatch } from 'react-redux'
import { DownOutlined } from '@ant-design/icons'
import $ from 'jquery'
import { setFilterBarVisible } from 'redux/actions/megaFilter'
import { FilterIconSVG } from 'components/svg_files'
import styled from 'styled-components';
import { useIsUserV2 } from 'hooks/useUserV2Filter';
import ChevronDown from 'public/static/chevron-down.svg';
import useAppFilter from './useAppFilter';

const StyledFilterButton = styled(Button)`
  display: flex;
  align-items: center;
  background-color: ${({ isAlternativeStyle }) => (isAlternativeStyle ? '#FFF': '#EFF5FF' )};
  border-color: ${({ isAlternativeStyle }) => (isAlternativeStyle ? '#F3F4F5' : '#BED5FF')} !important;
  color: ${({ isAlternativeStyle }) => (isAlternativeStyle ? '#A2A5AE' : '#5D97FF')} !important;
  border-radius: 6px;
  &.filter-applied-btn{
      padding: ${({ isAlternativeStyle }) => (isAlternativeStyle ? '8px 12px' : '4px 10px')} !important;
  }

  &:focus, &:active {
    background-color: ${({ isAlternativeStyle }) => (!isAlternativeStyle && '#EFF5FF')};
  }

  &:hover {
    background-color: ${({ isAlternativeStyle }) => (!isAlternativeStyle && '#EFF5FF')};
    opacity: 0.8;
  }

  svg {
    width: 16px;
    height: 16px;
    margin-right: ${({ isAlternativeStyle }) => (isAlternativeStyle ? '0px' : '5px')} !important;
    path {
      fill: ${({ isAlternativeStyle }) => (isAlternativeStyle ? '#A2A5AE' : '#5D97FF')} !important;
    }
  }

  .anticon {
    svg {
      width: 12px;
      height: 12px;
    }
  }
`;

const FilterCountButton = memo((
    { isAlternativeStyle = false }
) => {
  const { segmentType } = useAppFilter()
  const dispatch = useDispatch()
  const { megaFilterReducer, appFilter } = useSelector((state) => state);
  const isUserV2 = useIsUserV2();
  // * CX-1876 : Count ActivityFilter for UserV2
  const appliedSegmentCount = useMemo(() => {
    if (isUserV2) {
        return appFilter[segmentType].segment.length +  appFilter[segmentType].activityFilterList.length 
    }
    return appFilter[segmentType].segment.length
   }, [appFilter, segmentType, isUserV2])
  // if (segmentType === 'event') segment = segment.filter(({ attribute }) => attribute !== 'event_name')
  return (
    !!appliedSegmentCount > 0  && (
      <div className='filter-drop-item' data-intercom-target="Filter count">
        <StyledFilterButton
          onClick={() =>{
                dispatch(setFilterBarVisible(!megaFilterReducer.filterBarVisible))
            }}
          icon={!isAlternativeStyle && <FilterIconSVG />}
          className='filter-applied-btn'
          isAlternativeStyle={isAlternativeStyle}
        >
          {`${appliedSegmentCount} Filter${
            appliedSegmentCount > 1 ? 's' : ''
          } applied`}
          {
            isAlternativeStyle ?
              <ChevronDown /> :
             <DownOutlined />
          }

        </StyledFilterButton>
      </div>
    )
  )
})
export default FilterCountButton
