/* eslint-disable arrow-body-style */
import { Menu } from 'antd';
import { IUserCohort } from 'components/common/Contexts/UserCohortsContext'
import React from 'react'
import { SearchOutlined } from '@ant-design/icons';
import styled from 'styled-components';
import { DebounceInput } from 'react-debounce-input';
import CommonMapping from '../CommonMapping';

const InputContainer = styled.div`
  margin: 4px 0px;
  margin-right: 8px;
  position: relative;
  display: flex;
  align-items: center;
  .anticon {
    position: absolute;
    left: 8px;
    color: #828282;
  }
`

const DebounceInputComponentWrap = styled(DebounceInput)`
  border-radius: 4px;
  outline: none;
  height: 30px;
  padding: 8px 10px;
  padding-left: 28px;
  width: 100%;
  border: 1px solid #E0E0E0;
  font-size: 13px;
  &:focus-visible {
    border: 0.5px solid #5D97FF;
  }
`

const DivWrapper = styled.div`
  position: relative;
  margin: 0 4px 0 0;
  height: 290px;
  overflow-y: scroll;
  .anticon {
    position: absolute;
    top: 8px;
    z-index: 99;
    left: 8px;
    color: #A1A8C2;
  }
`

const { ItemGroup: MenuItemGroup } = Menu;

// eslint-disable-next-line @typescript-eslint/no-empty-interface
interface Props {
	inputRef: React.RefObject<HTMLInputElement>,
	searchText: string,
	onChange: ( e: React.ChangeEvent<HTMLInputElement>) => void,
	options: IUserCohort[] | any[],
	isBatchId?: boolean,
}

const CohortsMenu: React.FC<Props> = ( {
	inputRef,
	searchText,
	onChange,
	options,
	isBatchId = false,
	...rest
} ) => {

	return (
		<MenuItemGroup
			className='menu-list cohort-menu'
			key={ isBatchId ? 'batch-id' : 'cohorts' }
			style={{
				maxWidth: '250px',
			}}
		>
			<InputContainer>
			<SearchOutlined />
			<DebounceInputComponentWrap
				placeholder='Search'
				onChange={onChange}
				value={searchText}
				inputRef={inputRef}
				debounceTimeout={500}
			/>
			</InputContainer>
			<DivWrapper>
			<CommonMapping
				listOfAttribute={ options }
				isArray={ false }
				isUserCohort={ !isBatchId }
				isBatchId={ isBatchId }
				category={ isBatchId ? "Tara's watchlist batches" : 'Cohorts' }
				isCustomLabel={false}
				selectedAttributeProps={ {
					table: isBatchId ? 'session' : 'appuser',
				} }
				// eslint-disable-next-line react/jsx-props-no-spreading
				{ ...rest }
			/>
			</DivWrapper>

		</MenuItemGroup>
	)

}


export default React.memo( CohortsMenu )
