import React, { memo, useCallback, useMemo, useState } from 'react'
import DateRangePicker, { DateRangeValue } from 'dashboard-builder/dist/cjs/DateRangePicker';
import {  datePresetsAbsolute, getDisplayRangeDate } from 'Utils/DateConversion/dateConversionUtils';
import { Button, Dropdown } from 'antd';
import styled from 'styled-components';

const DatePickerButton = styled(Button)`
 width: auto !important;
    height: 20px !important;
    border-bottom: 1px dashed #a1a8c2 !important;
    border-radius: 0 !important;
    padding: 0 !important;
    display: inline-flex !important;
    align-items: center;

 p{
  margin: 0px 0px 0px 4px !important;
  line-height: normal !important;
 }
`;

function ActivityDatePicker({
    value,
    defaultDateRange,
    onChange,
    onDateRangeClose,
}: {
    value?: DateRangeValue
    defaultDateRange?: any
    onChange?: (val: any) => void,
    onDateRangeClose?: () => void
}) {
    const [open, setOpen] = useState(false)
    const handleClose = useCallback(() => setOpen(false), [])

    const { from, to, timezone, preset: selectedLabelId } = defaultDateRange || {};

    const handleDateRange = useCallback((newRange: any, preset: any) => {
        const { from: newRangeFrom, to: newRangeTo, timezone: newRangeTz } = newRange;
        const { id: labelId } = preset || {};
        setOpen(false);

        const utcRangeFrom = newRangeFrom.toISOString();
        const utcRangeTo = newRangeTo.toISOString();
        const newDateRange = {
            // attribute: (newRange.source).toLowerCase(), // * added from activity filter
            // operator: "between_dates", // * added from activity filter
            value: {
                lower: utcRangeFrom,
                upper: utcRangeTo
            },
            tz: newRangeTz,
            labelId,
        }
        onChange && onChange(newDateRange)
    }, [onChange]);

    const fromDate = useMemo(() => getDisplayRangeDate(from, timezone), [from, timezone]);

    const toDate = useMemo(() => getDisplayRangeDate(to, timezone), [to, timezone]);

    const dateLabel = useMemo(() => datePresetsAbsolute.find(item => item.id === selectedLabelId), [selectedLabelId]);

    const btnLabel = useMemo(() => {
        if (open) {
            return `${fromDate} - ${toDate}`;
        }
        return dateLabel?.label || `${fromDate} - ${toDate}`
    },
        [open, dateLabel, fromDate, toDate])

    return (
        <Dropdown
            trigger={['click']}
            onVisibleChange={setOpen}
            visible={open}
            destroyPopupOnHide
            overlay={(
                <DateRangePicker
                    onChange={handleDateRange}
                    value={defaultDateRange}
                    onClose={handleClose}
                />
            )}
        >
            <DatePickerButton>
                <svg width="17" height="15" viewBox="0 0 17 16" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M15.138 2.0837H12.1077V0.929304C12.1077 0.849939 12.0427 0.785004 11.9634 0.785004H10.9533C10.8739 0.785004 10.809 0.849939 10.809 0.929304V2.0837H6.19136V0.929304C6.19136 0.849939 6.12642 0.785004 6.04706 0.785004H5.03696C4.95759 0.785004 4.89266 0.849939 4.89266 0.929304V2.0837H1.86236C1.54309 2.0837 1.28516 2.34164 1.28516 2.6609V14.6378C1.28516 14.9571 1.54309 15.215 1.86236 15.215H15.138C15.4572 15.215 15.7152 14.9571 15.7152 14.6378V2.6609C15.7152 2.34164 15.4572 2.0837 15.138 2.0837ZM14.4165 13.9163H2.58386V7.06205H14.4165V13.9163ZM2.58386 5.8355V3.3824H4.89266V4.2482C4.89266 4.32757 4.95759 4.3925 5.03696 4.3925H6.04706C6.12642 4.3925 6.19136 4.32757 6.19136 4.2482V3.3824H10.809V4.2482C10.809 4.32757 10.8739 4.3925 10.9533 4.3925H11.9634C12.0427 4.3925 12.1077 4.32757 12.1077 4.2482V3.3824H14.4165V5.8355H2.58386Z" fill="#A2A5AE" />
                </svg>
                <p>
                    {btnLabel}
                </p>
            </DatePickerButton>
        </Dropdown>
    )
}

export default memo(ActivityDatePicker)