export const SuggestionFilters: React.FC<{
    onSuggestionClick: (text: string) => void,
    pageType: string,
}> = ({
    onSuggestionClick,
    pageType
}) => {

    const filteredSuggestions = suggestions.filter((suggestion) => suggestion.pageTypes.includes(pageType));
    return(
        <SuggestionSection>
            <span className='suggestion-title'>Not sure yet? Try these prompts</span>
            <ul>
                {
                    filteredSuggestions.map((suggestion) => (
                        // eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-noninteractive-element-interactions
                        <li key={suggestion.key} onClick={() => onSuggestionClick(suggestion.title)}>
                            <span className='icon-container'>
                                <suggestion.icon />
                            </span>
                            {suggestion.title}
                            <ArrowIcon />
                        </li>
                    ))
                }
            </ul>
        </SuggestionSection> 
    )}

export const FooterContent: React.FC<{
    variant: 'default' | 'no-results',
    onFeedbackClick: (feedbackType: 'positive' | 'negative') => void,
    hideFooterContent?: boolean,
}> = ({
    variant = 'default',
    onFeedbackClick,
    hideFooterContent,
}) => {
    const [likeOrDislike, setLikeOrDislike] = useState<1 | 0 | null>(null);
    const [hideFooter, setHideFooter] = useState(false);
    const [feedbackText, setFeedbackText] = useState('');
    let savedAiFilterPayload: string | null = ''
    try {
        savedAiFilterPayload = localStorage.getItem('aiFilerPayload');
    } catch (err) {
        // silent fail
    }
  
    const textString = useMemo(() => {
        if (variant === 'no-results') {
            return {
                // main: 'Not what you’re looking for?',
                // subText: 'Give feedback'
                main: 'Rate your results',
            }
        }
        return {
            main: 'This feature is still in Beta, check filters on your responses.',
            subText: 'Learn more'
        }
    }, [variant]);

    const showFeedbackText = useCallback(() => {
        setTimeout(() => {
            setHideFooter(true);
            setTimeout(() => {
                setFeedbackText('Thank you! Your feedback helps us improve.');
                setHideFooter(false);
                setTimeout(() => {
                    setHideFooter(true);
                    const parsedSavedAiFilterPayload = JSON.parse(savedAiFilterPayload as string) as StoredFilterPayload;
                    // set local storage to rated to true
                    try {
                        localStorage.setItem('aiFilerPayload', JSON.stringify({
                            ...parsedSavedAiFilterPayload,
                            rated: true,
                        }))
                    } catch (err) {
                        // silent fail
                    }
                }, 800)
            }, 800)
        }, 800)
    }, [])

    if (variant === 'no-results' && hideFooterContent) return <Footer />;

    return (
        <Footer
            fadeOut={hideFooter}
            autoMarginTop={variant === 'default'}
        >
            {
                likeOrDislike !== null && feedbackText ? feedbackText : textString.main
            }
            {variant === 'no-results' && feedbackText === '' ? (
                // <button type='button' onClick={onFeedbackClick}>
                //     {textString.subText}
                // </button>
                <div className="action-btn-container">
                    <button type="button" disabled={likeOrDislike !== null} onClick={() => {
                        setLikeOrDislike(1);
                        showFeedbackText();
                        onFeedbackClick('positive');
                        }}>
                    {' '}
                    <ThumbIcon className="like-icon" data-active={likeOrDislike === 1} />
                    </button>
                    <button type="button" disabled={likeOrDislike !== null} onClick={() => {
                        setLikeOrDislike(0);
                        showFeedbackText();
                        onFeedbackClick('negative');
                        }}>
                    {' '}
                    <ThumbIcon className="dislike-icon" data-active={likeOrDislike === 0} />
                    </button>
                </div>
            ) : 
            <a href='https://help.uxcam.com/en/articles/10222531-smart-filters-new-feature-in-beta' target='_blank' rel='noreferrer'>
                {textString.subText}
            </a>
            }
        </Footer>
    );
}

export const AiSearchComponent = React.forwardRef<HTMLTextAreaElement, AiSearchComponentProps>((props, ref) => {
    const { inputProps, onSubmit, onClear, disabled } = props;

    const [rows, setRows] = useState(1);

    const handleClear = useCallback(() => {
        onClear();
        setRows(1);
    }, [onClear]);

    const handleChange = (event: React.ChangeEvent<HTMLTextAreaElement>) => {
        const textareaLineHeight = 18; // Adjust based on your textarea line-height
        const minRows = 1;
        const maxRows = 3;

        const previousRows = event.target.rows;
        const {target} = event;
        target.rows = minRows; // reset number of rows in textarea 

        const currentRows = Math.floor(target.scrollHeight / textareaLineHeight);

        if (currentRows === previousRows) {
            target.rows = currentRows;
        }

        if (currentRows >= maxRows) {
            target.rows = maxRows;
            target.scrollTop = target.scrollHeight;
        }

        setRows(currentRows < maxRows ? currentRows : maxRows);
        if (inputProps?.onChange) {
            inputProps.onChange(event);
        }
    };
  
    return (
        <SearchContainer>
            <LabelContainer>
                <span className='icon-container leading-icon'>
                    <AIInputIcon />
                </span>
                
                <SearchInput
                    ref={ref}
                    rows={rows}
                    autoComplete='on'
                    maxLength={500}
                    // eslint-disable-next-line react/jsx-props-no-spreading
                    {...inputProps}
                    onChange={handleChange}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault(); // Prevent the default Enter action when not using Shift
                            onSubmit();
                        }
                    }}
                />

                {/* eslint-disable */}
                <button disabled={disabled} className='icon-container trailing-icon' type='button' onClick={handleClear}>
                    <CloseIcon />
                    {' '}
                </button>
            </LabelContainer>

            <SearchSubmitButton type="button" onClick={onSubmit} disabled={disabled}>
                <CTASubmitIcon />
            </SearchSubmitButton>
        </SearchContainer>
    )
})

