const FilterDisplay: React.FC<{
    filter: TFilterPayload,
    isInvalid?: boolean,
}> = ({filter, isInvalid}) => {
    const [isEllipse, setIsEllipse] = useState(false);
    const textRef = React.useRef<HTMLParagraphElement>(null);
    const { pageType } = useAppFilter();
    const { attribute, value } = filter;
    const filterData = getFilterData(filter, pageType);
    const isEvent = attribute === 'event_name' || attribute === 'nce_name';

    const hasProperty = filter.property;

    
    React.useEffect(() => {
        const checkEllipsis = () => {
        const element = textRef.current;
        if (element) {
            // Check if the text content overflows
            setIsEllipse(element.scrollHeight > element.clientHeight);
        }
        };

        checkEllipsis();
        window.addEventListener('resize', checkEllipsis);

        return () => {
        window.removeEventListener('resize', checkEllipsis);
        };
    }, []);

    const propertyDisplayText = useMemo(() => {
        if (!hasProperty) return '';
        const { name, value: propertyValue, operator } = hasProperty;
        const propertyValueText = Array.isArray(propertyValue) ? propertyValue.join(', ') : propertyValue;
        const operatorText = getFilterOperator(operator);

        return (<>
            where <span className='bold'>{name}</span> {operatorText} {' '}
            {
                isEllipse ? (
                    <Tooltip title={propertyValueText} placement="bottomRight" align={{
                        offset: [0, -28],
                    }}>
                        <span className='bold'>{propertyValueText}</span>
                    </Tooltip>
                ) : (
                    <span className='bold'>{propertyValueText}</span>
                )
            }
        </>)
    }, [hasProperty, isEllipse])

    let valueDisplay = Array.isArray(value) ? value.join(', ') : value;

    if (filterData.value) {
        valueDisplay = filterData.value;
    }

    const valueDisplayText = useMemo(() => {
        if (isEllipse) {
            if (hasProperty) {
                const tempValue = Array.isArray(value) ? value[0] : value;
                const restValueCount = Array.isArray(value) ? value.slice(1).length : 0;
                const restValue = Array.isArray(value) ? value.slice(1).join(', ') : '';
                return (
                    <span className='bold'>
                        {tempValue}{' '}
                        {
                            restValueCount > 0 ? (
                                <>
                                    and {' '}
                                    <Tooltip title={restValue} placement="bottomRight" align={{
                                        offset: [0, -8],
                                    }}>
                                        {restValueCount} more
                                    </Tooltip>
                                </>
                            ) : null
                        }
                    </span>
                )
            }
            return (
                <Tooltip title={valueDisplay}>
                    <span className='bold'>{valueDisplay}</span>
                </Tooltip>
            )
        }
        return valueDisplay;
    }, [isEllipse, valueDisplay, hasProperty, value])

    return (
        <li key={`${attribute}`} data-invalid={isInvalid}>
            <FilterStackIcon />
            {
                isEllipse ? (
                    // add tooltip for ellipsis
                    <p ref={textRef} className='text'>
                        { isEvent ? '' : filterData.title} {filterData.operator} {' '}
                        <span className='bold'>{valueDisplayText}</span> {' '}
                        {propertyDisplayText}
                    </p>
                ) : (
                    <p ref={textRef} className='text'>
                        { isEvent ? '' : filterData.title} {filterData.operator} {' '}
                        <span className='bold'>{valueDisplay}</span> {' '}
                        {propertyDisplayText}
                    </p>
                )
            }
        </li>
    )
}

export const PromptResultsComponent: React.FC<PromptResultsType> = (props) => {
    const { results, onVisibleChange, onTryAnother, onApplyFilters } = props;
    const { pageType, callListApi } = useAppFilter();
    // const { appFilter } = useSelector((state: RootStateOrAny) => state);
    // const { dateSegment } = appFilter;
    const validFilters = validateFilterData(results, pageType);

    const filterHasInvalid = validFilters.some((item) => !item.isValid);

    const getPayloadFilters = useCallback(() => {
        const payloadTemp = results.map((item) => {
            const getType = getFilterData(item, pageType).type;
            return {
                ...item,
                type: getType,
            }
        });
        callListApi(payloadTemp);
        onApplyFilters && onApplyFilters(payloadTemp);
        onVisibleChange(false);
        // close dropdown
    }, [pageType, results, callListApi, onVisibleChange])

    return (
        <PromptResultsContainer>
            Generated result:

            <ResultsContainer>
                <ul>
                    {results.map( (item) => (
                        <FilterDisplay filter={item} isInvalid={!validFilters.find(temp => temp.attribute === item.attribute)?.isValid} />
                    ))}
                </ul>

                <div className='action-button-wrapper'>
                    <Tooltip
                        placement="bottom"
                        title={filterHasInvalid ? 'Generated filter is not valid' : ''}
                        align={{
                            offset: [0, -5]     
                        }}
                    >
                        <Button disabled={filterHasInvalid} type='primary' onClick={getPayloadFilters}>Apply as filter</Button>
                    </Tooltip>
                    <Button type='link' onClick={onTryAnother}>Try another prompt</Button>
                </div>
            </ResultsContainer>
        </PromptResultsContainer>
    )
}

