const DebounceInputComponentWrap = styled(DebounceInput)`
  border-radius: 4px;
  outline: none;
  height: 30px;
  padding: 8px 10px;
  padding-left: 28px;
  width: 100%;
  border: 1px solid #E0E0E0;
  font-size: 13px;
  &:focus-visible {
    border: 0.5px solid #5D97FF;
  }
`

const InputContainer = styled.div`
  margin: 4px 0px;
  margin-right: 8px;
  position: relative;
  display: flex;
  align-items: center;
  .anticon {
    position: absolute;
    left: 8px;
    color: #828282;
  }
`

const TabPaneTabWrapper = styled.div`
  display: flex;
  align-items: center;  
`

export const CommonTabEvents = (props) => {
  const { activeEventTab, eventList, selectedKey, onChange, value, inputRef, disabled, id, hideSearch, ...rest } = props;
  return <MenuItemGroup
    className='menu-list'
    key={selectedKey}
  >
    {
      hideSearch ? null : (
        <InputContainer>
          <SearchOutlined />
          <DebounceInputComponentWrap
            placeholder='Search'
            onChange={onChange}
            value={value}
            maintainFocus={id === 'menu-selected-key'}
            inputRef={inputRef}
            disabled={disabled}
            debounceTimeout={500}
            autoFocus
          />
        </InputContainer>
      )
    }
    <DivWrapper>
      <CommonMapping
        listOfAttribute={eventList}
        isArray
        category={selectedKey}
        isCustomLabel={false}
        eventType={activeEventTab}
        {...rest}
      />
    </DivWrapper>

  </MenuItemGroup>
}
const EventMenuTab = (props) => {
  const { handleEventTab, activeEventTab, setActiveEventTab } = props;

  const onEventTabChange = useCallback((key) => {
    setActiveEventTab(key);
  }, [setActiveEventTab]);

  useEffect(() => {
    handleEventTab(activeEventTab)
  }, [activeEventTab]);

  return (
    <TabWrapper
      centered
      defaultActiveKey="codedEvents"
      onChange={onEventTabChange}>
      <TabPane tab="Coded events" key="codedEvents">
        <CommonTabEvents activeEventTab={activeEventTab} {...props} />
      </TabPane>
      <TabPane tab={ (
        <TabPaneTabWrapper>
          Smart events <BetaBadge variant="superSmall">BETA</BetaBadge>
        </TabPaneTabWrapper>
      ) } key="smartEvents">
        <CommonTabEvents activeEventTab={activeEventTab} {...props} />
      </TabPane>
    </TabWrapper>
  )

}

export default memo(EventMenuTab);
