import React, { memo, useMemo } from "react";
import { Form } from 'antd';
import findIndex from 'lodash/findIndex';

import { operator } from 'components/shared/GlobalFilter/components/data-structures-v2';
import {
  OperatorMenu,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2'

const GestureOperator = ({ form, name, operatorType }) => {

  const formData = Form.useWatch('gestureProperties', form);
  const formDataIndex = name[1];
  const formOperatorValue = useMemo(()=> formData?.[formDataIndex]?.['operator'] ?? '', [formData, formDataIndex]) ;

  const indexOfOperator = findIndex(operator[operatorType], {
    attribute: formOperatorValue,
  })
  const operatorDataByTypeIndex = useMemo(() => operator[operatorType][indexOfOperator], [indexOfOperator, operatorType]);

  return (
    <span className="filter-spacing">
     <OperatorMenu
      selectedOperator={operatorDataByTypeIndex}
      isFilterDisplayBar
      operatorType={operatorType}
      handleOperatorMenuClick={(data) => {
        form.setFields([{ name, value: data.key }]);
        form.setFields([
          {
            name: ['gestureProperties', `${formDataIndex}`, 'value'],
            value: undefined,
          },
        ]);
      }}
      isEventProperty
      propertyName=''
    />
    </span>
  )
}

export default memo(GestureOperator)