/* eslint-disable react-hooks/exhaustive-deps */
import React, { useState, useEffect,memo, useMemo } from "react";
import { Input } from "antd";
import styled from 'styled-components';

import useDebounce from 'hooks/useDebounce';

const isInteger = /^[0-9]+$/;
const InputWrapper = styled(Input)`
  width: 30px;
  height: 18px !important;
  border: 0 !important;
  border-bottom: 1px dashed #a1a8c2 !important;
  line-height: normal !important;
  border-radius: 0 !important;
  padding: 0;
`;
const NumberFieldWrapper = ({callApi, defaultValue}) => {
    
    const [values, setValues]= useState();
    const currentValue = useMemo(()=>  !values && typeof values === 'undefined' ? defaultValue : values, [defaultValue, values])

    const debouncedSearchValue = useDebounce(currentValue, 2000);

    const handleInputChange = (e) => {
        const { value } = e.target;
        if(value === '' || isInteger.test(value)){
            setValues(value)
        }
    }

    const handleOnBlur = (e) => {
        const { value } = e.target;
        value &&  callApi(value)
    }

    useEffect(()=> {
        debouncedSearchValue && callApi(debouncedSearchValue)
    }, [debouncedSearchValue])

    return(
        <InputWrapper maxLength={4} value={currentValue} onChange={handleInputChange} onBlur={handleOnBlur} onPressEnter={handleInputChange}/>
    )
}

export default memo(NumberFieldWrapper);