/* eslint-disable react/jsx-props-no-spreading */
import React, { useCallback } from 'react'
import styled from 'styled-components'
import IconStack from 'public/static/ai/icon-stack.svg'
import IconCaret from 'public/static/icon-caret.svg'
import { themeCommon } from 'theme/theme'
import { useAISessionWatchlist } from 'components/common/Contexts/AISessionWatchlist'
import WatchlistItem from './AIChatTogglePopoverContentItem'

const Container = styled.div`
	display: flex;
	gap: 12px;
	flex-direction: column;
`

const Header = styled.div`
	display: flex;
	gap: 8px;
	font-family: Roboto;
	font-weight: 500;
	font-style: Medium;
	font-size: 13px;
	line-height: 20px;
	letter-spacing: 0%;
	display: flex;
	align-items: center;
	color: ${themeCommon.color.Surface400.toString()};
	justify-content: space-between;
`

const Left = styled.div`
	display: flex;
	align-items: center;
	gap: 8px;
`

const CollapseButton = styled.button`
	padding: 0;
	margin: 0;
	border: none;
	height: 24px;
	width: 24px;
	cursor: pointer;
	background-color: transparent;
	svg {
		transform: rotate(180deg) scale(1.84);
		margin-top: 2px;
		path {
			stroke: ${themeCommon.color.Surface400.toString()};
		}
	}
`

const List = styled.div`
	display: flex;
	overflow: auto;
	max-height: 85dvh;
`

const ListWrapper = styled.div`
	display: flex;
	flex-direction: column;
	gap: 14px;
	flex-shrink: 0;
	width: 100%;
`

const PopoverContent = () => {
	const { items, setPopupVisibility, setPopupVisibilityEnforced, markCompletedItemsAsSeen } = useAISessionWatchlist()

	const handleCollapseButton = useCallback( () => {
		// Mark all completed items as seen before closing
		markCompletedItemsAsSeen()
		setPopupVisibility( false )
		setPopupVisibilityEnforced( false )
	}, [ setPopupVisibility, setPopupVisibilityEnforced, markCompletedItemsAsSeen ] )
	
	return (
		<Container>
			<Header>
				<Left>
					<IconStack />
					Tara Session Watchlist
				</Left>
				<CollapseButton onClick={ handleCollapseButton }>
					<IconCaret />
				</CollapseButton>
			</Header>
			<List>
				<ListWrapper>
					{ items?.map( item => (
						<WatchlistItem { ...item } />
					) ) }
				</ListWrapper>
			</List>
		</Container>
	)
}

export default PopoverContent