import { useCallback } from "react"
import { useQueryClient } from "react-query"
import { useSelector } from "react-redux"
import { IReduxState } from "types/reduxStateTypes"
import { TNewProfile, TNewProfileOrganization } from "./useValidatePermission"

const useGetRole = () => {
	const queryClient = useQueryClient()
	const { 
		currentOrgReducer: {
			orgId,
		},
		currentAppReducer: {
			_id: appId
		}
	 } = useSelector( ( state: IReduxState ) => state )
	const newProfile: TNewProfile | undefined = queryClient.getQueryData('profileInfo')

	const getRole = useCallback( () => {
		// eslint-disable-next-line no-shadow
		const org = newProfile?.organization.find( org => org.$oid === orgId )

		if ( org?.apps ) {
			return ( org as unknown as TNewProfileOrganization ).apps.find( app => app.id === appId )?.role
		}
		return null
	}, [ newProfile, orgId, appId ] )

	const isRole = useCallback( ( roleProps: string ) => {
		const role = getRole()
		return role === roleProps
	}, [ getRole ] )

	return {
		getRole,
		isRole,
	}
}

export default useGetRole