export interface FilterContext {
  attribute: string
  operator: string
  table: string
  property_name: string
}

export const URL_CHARACTER_LIMIT = 250000
const VIRTUAL_SCROLL_THRESHOLD = 100
const CHUNK_SIZE = 500
export const COHORT_THRESHOLD_LIMIT = 2500

interface MassUserIdFilterProps {
  visible: boolean
  onClose: () => void
  onApply: (values: string[]) => void
  initialValues?: string[]
  placeholder?: string
  title?: string
  subtitle?: string
  filterContext: FilterContext;
  onSaveAsCohort?: (cohortFilter: any) => void;
}

