const CloseGrayIconTrigger = ({ onClick }:{onClick: (e: React.MouseEvent<HTMLButtonElement>) => void})=>{
    return (
        <button type="button" onClick={onClick} className="remove-icon" style={{ border: 'none', background: 'transparent', cursor: 'pointer', padding: 0 }} aria-label="Remove value">
            <CloseIcon />
        </button>
    )
}
const MassUserIdFilterComponent = memo<MassUserIdFilterProps>(({
  visible,
  onClose,
  onApply,
  initialValues = [],
  placeholder = 'Enter values separated by comma, tab, or newline',
  title = 'Add Multiple Values',
  subtitle = '',
  filterContext,
  onSaveAsCohort
}) => {
  const dispatch = useDispatch()
  const [inputText, setInputText] = useState('')
  const [values, setValues] = useState<string[]>(initialValues)
  const [isCharacterLimitExceeded, setIsCharacterLimitExceeded] = useState(false)
  const [characterCount, setCharacterCount] = useState(0)
  const [isProcessing, setIsProcessing] = useState(false)
  const [isSaveCohortModalVisible, setIsSaveCohortModalVisible] = useState(false)
  const [selectedValues, setSelectedValues] = useState<Set<string>>(new Set())
  const containerRef = useRef<HTMLDivElement>(null)
  const prevVisibleRef = useRef(false)

  const {
    showMassUserIdFilterCtx, setShowMassUserIdFilterCtx, reset
  } = useMassUserIdFilterContext();
  
  const valueItems = useMemo(() =>
    values.map((value) => ({ id: value, value })),
    [values]
  )
  const massUserIdFilterVisibility = useMemo(() => showMassUserIdFilterCtx || visible, [showMassUserIdFilterCtx, visible]);

  const isVirtual = values.length > VIRTUAL_SCROLL_THRESHOLD
  const columnCount = 4

  const rowVirtualizer = useVirtualizer({
    count: isVirtual ? Math.ceil(valueItems.length / columnCount) : 0,
    getScrollElement: () => containerRef.current,
    estimateSize: () => 26,
    overscan: 10,
    enabled: isVirtual,
  })

  const parseValues = useCallback((text: string): string[] => {
    if (!text) return []
    const valueSet = new Set<string>()
    const parts = text.split(/[,\t\n\r]+/)
    for (let i = 0; i < parts.length; i++) {
      let trimmed = parts[i].trim()
      if (trimmed) {
        // Remove surrounding quotes (both single and double)
        if ((trimmed.startsWith('"') && trimmed.endsWith('"')) ||
            (trimmed.startsWith("'") && trimmed.endsWith("'"))) {
          trimmed = trimmed.slice(1, -1)
        }
        if (trimmed) valueSet.add(trimmed)
      }
    }
    return Array.from(valueSet)
  }, [])

  const checkCharacterLimit = useCallback((vals: string[], currentInput = '') => {
    let totalChars = 0
    for (let i = 0; i < vals.length; i++) totalChars += vals[i].length + 1
    if (currentInput) {
      totalChars += currentInput.length
    }
    setCharacterCount(totalChars)
    setIsCharacterLimitExceeded(totalChars > COHORT_THRESHOLD_LIMIT)
  }, [])

  const handleInputChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const text = e.target.value
    setInputText(text)
    setSelectedValues(new Set())
    if (/[,\t\n\r]/.test(text)) {
      const parsed = parseValues(text)
      if (parsed.length > 0) {
        const newValues = Array.from(new Set([...values, ...parsed]))
        setValues(newValues)
        checkCharacterLimit(newValues)
        setInputText('')
      }
    } else {
      checkCharacterLimit(values, text)
    }
  }, [parseValues, values, checkCharacterLimit])

  const processValuesInChunks = useCallback(async (newParsed: string[]): Promise<string[]> => {
    return new Promise((resolve) => {
      setIsProcessing(true)
      const resultSet = new Set(values)
      let currentIndex = 0
      const processChunk = () => {
        const endIndex = Math.min(currentIndex + CHUNK_SIZE, newParsed.length)
        for (let i = currentIndex; i < endIndex; i++) resultSet.add(newParsed[i])
        currentIndex = endIndex
        if (currentIndex < newParsed.length) {
          if (typeof requestIdleCallback !== 'undefined') {
            requestIdleCallback(() => processChunk(), { timeout: 50 })
          } else {
            setTimeout(processChunk, 0)
          }
        } else {
          const finalValues = Array.from(resultSet)
          setIsProcessing(false)
          resolve(finalValues)
        }
      }
      processChunk()
    })
  }, [values])

  const handlePaste = useCallback(async (e: React.ClipboardEvent<HTMLInputElement>) => {
    e.preventDefault()
    const pastedText = e.clipboardData.getData('text')
    setIsProcessing(true)
    const parsed = parseValues(pastedText)
    if (parsed.length > 0) {
      if (parsed.length > CHUNK_SIZE) {
        const newValues = await processValuesInChunks(parsed)
        setValues(newValues)
        checkCharacterLimit(newValues)
      } else {
        const newValues = Array.from(new Set([...values, ...parsed]))
        setValues(newValues)
        checkCharacterLimit(newValues)
        setIsProcessing(false)
      }
      setInputText('')
    } else {
      setIsProcessing(false)
    }
  }, [parseValues, values, checkCharacterLimit, processValuesInChunks])

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight' || e.key === 'ArrowUp' || e.key === 'ArrowDown') {
      e.stopPropagation()
      return
    }

    const text = inputText.trim()

    if ((e.ctrlKey || e.metaKey) && e.key === 'a' && values.length > 0) {
      e.preventDefault()
      setSelectedValues(new Set(values))
      return
    }

    if ((e.key === 'Delete' || e.key === 'Backspace') && selectedValues.size > 0) {
      e.preventDefault()
      const newValues = values.filter(v => !selectedValues.has(v))
      setValues(newValues)
      checkCharacterLimit(newValues)
      setSelectedValues(new Set())
      return
    }

    if (e.key === 'Tab') {
      e.preventDefault()
      e.stopPropagation()
      if (text) {
        const parsed = parseValues(text)
        const newValues = Array.from(new Set([...values, ...parsed]))
        setValues(newValues)
        checkCharacterLimit(newValues)
        setInputText('')
      }
      setSelectedValues(new Set())
      return
    }
    if (e.key === 'Backspace' && !inputText && values.length > 0) {
      e.preventDefault()
      const newValues = values.slice(0, -1)
      setValues(newValues)
      checkCharacterLimit(newValues)
      return
    }
    if ((e.key === 'Enter' || e.key === ',') && text) {
      e.preventDefault()
      e.stopPropagation()
      const parsed = parseValues(text)
      const newValues = Array.from(new Set([...values, ...parsed]))
      setValues(newValues)
      checkCharacterLimit(newValues)
      setInputText('')
      setSelectedValues(new Set())
    }
  }, [inputText, parseValues, values, checkCharacterLimit, selectedValues])

  const handleBlur = useCallback(() => {
    const text = inputText.trim()
    if (text) {
      const parsed = parseValues(text)
      if (parsed.length > 0) {
        const newValues = Array.from(new Set([...values, ...parsed]))
        setValues(newValues)
        checkCharacterLimit(newValues)
        setInputText('')
      }
    }
    setSelectedValues(new Set())
  }, [inputText, parseValues, values, checkCharacterLimit])

  const handleRemoveValue = useCallback((valueToRemove: string) => {
    const newValues = values.filter((v) => v !== valueToRemove)
    setValues(newValues)
    checkCharacterLimit(newValues)
    setSelectedValues(new Set())
  }, [values, checkCharacterLimit])

  const handleApply = useCallback(() => {
    if (values.length > 0) {
      dispatch(trackPageViews(null, { 
        eventName: 'wa_create_mass_id_filter',
         eventProperty: {
            mass_id_count: values.length 
         }
      }))
      onApply(values)
      reset() // * Reset state on apply since it closes the modal
      onClose()
    }
  }, [values, dispatch, onApply, reset, onClose])

  const handleOpenSaveCohortModal = useCallback(() => {
    onClose()
    setShowMassUserIdFilterCtx(false)
    setIsSaveCohortModalVisible(true)
  }, [onClose, setShowMassUserIdFilterCtx])

  const handleCloseSaveCohortModal = useCallback(() => {
    setIsSaveCohortModalVisible(false)
  }, [])

  const handleCancel = useCallback(() => {
    dispatch(trackPageViews(null, { eventName: 'wa_filter_cancel_multi_id' }))
    reset() // * Reset state on cancel
    onClose()
  }, [dispatch, onClose, reset])

  useEffect(() => {
    // * Reset state when modal is opened
    const wasVisible = prevVisibleRef.current
    prevVisibleRef.current = massUserIdFilterVisibility

    if (massUserIdFilterVisibility && !wasVisible) {
      dispatch(trackPageViews(null, { eventName: 'wa_filter_click_multi_id' }))
      setValues(initialValues)
      setInputText('')
      setIsProcessing(false)
      setSelectedValues(new Set())
      checkCharacterLimit(initialValues)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [massUserIdFilterVisibility, dispatch])

  return (
    <>
    <MassUserIdModal
      title={title}
      visible={massUserIdFilterVisibility}
      onCancel={handleCancel}
      width={600}
      footer={null}
      destroyOnClose
      zIndex={99999}
      centered
      closable={false}
    >
      <Subtitle>{subtitle}</Subtitle>

      <InputContainerWrapper>
        {isProcessing && (
          <ProcessingOverlay>
            <Spin indicator={<LoadingOutlined spin />} />
            <p> Processing... </p>
          </ProcessingOverlay>
        )}
        <SingleInputContainer
        ref={containerRef}
        $virtual={isVirtual}
        onClick={() => {
          if (!isProcessing) {
            const input = document.querySelector('.multi-value-input') as HTMLInputElement
            input?.focus()
            setSelectedValues(new Set())
          }
        }}
        style={{ opacity: isProcessing ? 0.6 : 1, pointerEvents: isProcessing ? 'none' : 'auto' }}
      >
        {isVirtual ? (
          <div
            style={{
              height: '100%',
              width: '100%',
              position: 'relative',
            }}
          >
            <div
              style={{
                height: `${rowVirtualizer.getTotalSize()}px`,
                width: '100%',
                position: 'relative',
              }}
            >
              {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                const startIndex = virtualRow.index * columnCount
                const endIndex = Math.min(startIndex + columnCount, valueItems.length)

                return (
                  <div
                    key={String(virtualRow.key)}
                    style={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      width: '100%',
                      height: `${virtualRow.size}px`,
                      transform: `translateY(${virtualRow.start}px)`,
                      display: 'grid',
                      gridTemplateColumns: `repeat(${columnCount}, 1fr)`,
                      gap: 8,
                    }}
                  >
                    {valueItems.slice(startIndex, endIndex).map((item) => (
                      <ValueChip key={item.id} $selected={selectedValues.has(item.value)}>
                        <span className="value-text" title={item.value}>
                          {item.value}
                        </span>
                        <CloseGrayIconTrigger
                          onClick={(e) => {
                            e.stopPropagation()
                            handleRemoveValue(item.value)
                          }}
                        />
                      </ValueChip>
                    ))}
                  </div>
                )
              })}
            </div>
          </div>
        ) : (
          valueItems.map((item) => (
            <ValueChip key={item.id} $selected={selectedValues.has(item.value)}>
              <span className="value-text" title={item.value}>
                {item.value}
              </span>
              <CloseGrayIconTrigger
                onClick={(e) => {
                  e.stopPropagation()
                  handleRemoveValue(item.value)
                }}
              />
            </ValueChip>
          ))
        )}
        {!isProcessing && (
          <HiddenInput
            className="multi-value-input"
            value={inputText}
            onChange={handleInputChange}
            onPaste={handlePaste}
            onKeyDown={handleKeyDown}
            onBlur={handleBlur}
            placeholder={values.length === 0 ? placeholder : ''}
            autoComplete="off"
            data-form-type="other"
            data-lpignore="true"
          />
        )}
      </SingleInputContainer>
      </InputContainerWrapper>

        <CharacterLimitAlert>
            {characterCount.toLocaleString()} / {URL_CHARACTER_LIMIT.toLocaleString()} characters
            <Tooltip title={<TooltipText>Max limit up to 250k characters. Exceeding this may cause the page to crash or fail to save. If you have a larger list, please <button onClick={showIntercom} type='button'>Talk to us.</button></TooltipText>} placement='topRight' overlayStyle={{minWidth: '280px'}}>
               <InfoCircleOutlined style={{color:"#737886", marginLeft:"4px"}} />
            </Tooltip>
        </CharacterLimitAlert>

      <ButtonWrapper>
        <NewButton onClick={handleCancel}>Cancel</NewButton>

        {isCharacterLimitExceeded ? (
            <NewButtonPrimary
            type="primary"
            onClick={handleOpenSaveCohortModal}
            disabled={values.length === 0}
            >
            Save as cohort
          </NewButtonPrimary>
        ) : (
            <NewButtonPrimary type="primary" onClick={handleApply} disabled={values.length === 0}>
              Apply as filter
            </NewButtonPrimary>
        )}
      </ButtonWrapper>

    </MassUserIdModal>
    <SaveCohortModal
        visible={isSaveCohortModalVisible}
        onClose={handleCloseSaveCohortModal}
        values={values}
        filterContext={filterContext}
        onSave={onSaveAsCohort}
    />

    <PartialCohortSavedModal onSave={onSaveAsCohort} />
    <NoCohortSavedModal />
    <CohortLimitReachedModal />
    </>
  )
})


const MassUserIdFilter = (props: MassUserIdFilterProps) => (
  <MassUserIdFilterProvider>
    <MassUserIdFilterComponent {...props} />
  </MassUserIdFilterProvider>
)

export default MassUserIdFilter
