/* eslint-disable no-plusplus */

const DANGEROUS_CSV_CHARS = ['=', '+', '-', '@'];

const sanitizeCsvCell = (value) => {
  if (value === null || value === undefined) return '""';

  const strValue = value instanceof Date ? value.toLocaleString() : value.toString();

  const escaped = strValue.replace(/"/g, '""');

  if (DANGEROUS_CSV_CHARS.some(char => strValue.trimStart().startsWith(char))) {
    return `"'${escaped}"`;
  }

  return `"${escaped}"`;
};

const exportToCsv = (filename, rows) => {
  const processRow = (row) => {
    return `${row.map(cell => sanitizeCsvCell(cell)).join(',')}\n`;
  };
  let csvFile = '';
  for (let i = 0; i < rows.length; i++) {
    csvFile += processRow(rows[i]);
  }
  const blob = new Blob([csvFile], { type: 'text/csv;charset=utf-8;' });
  if (navigator.msSaveBlob) navigator.msSaveBlob(blob, filename); // IE 10+
  else {
    const link = document.createElement("a");
    if (link.download !== undefined) { // feature detection
      // For browsers that support HTML5 download attribute
      const url = URL.createObjectURL(blob);
      link.setAttribute("href", url);
      link.setAttribute("download", filename);
      link.style.visibility = 'hidden';
      document.body.appendChild(link);
      link.click();
      if (link.parentNode && link.parentNode.contains(link)) {
        document.body.removeChild(link);
      }
    }
  }
}
export default exportToCsv

