/* eslint-disable react/jsx-props-no-spreading */
import React, { useState, useEffect, useMemo, memo, useRef, useCallback } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { Tooltip } from 'antd'
import findIndex from 'lodash/findIndex'
import isEqual from 'lodash/isEqual'
import isArray from 'lodash/isArray'
import lowerCase from 'lodash/lowerCase'
import capitalize from 'lodash/capitalize'
import invert from 'lodash/invert'

import { titleWithSeparator, notInOperators, isOptionsPredefined, screenNameAttributes, viewTypeUtils } from 'components/shared/GlobalFilter/components/utils'
import { FilterContextProvider } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/FilterContextProvider'
import { resetFetchedPropertyByKey } from 'redux/actions/filter'
import { capitalizeEnvString } from 'components/features/setting/AppSetting/NewRecordingSection/DebounceSearch'
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import { getRenamedDeviceName } from 'Utils/helpers/commonUtils'
import { useUserCohorts } from 'components/common/Contexts/UserCohortsContext'
import styled from 'styled-components'
import { useUserV2Properties } from 'hooks/useUserV2Filter'
import { updateActivityFilterSegment } from 'redux/actions/megaFilter'
import {getActivityFilterPropertyId, useActivityFilterValidator} from 'Utils/helpers/useActivityFilterValidator'
import InlineInputEdit from './InlineInputEdit'
import FilterDropdown from './FilterDropdown'



const FilterSpacing = styled.span`
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  a {
    height: 20px; 
    overflow: hidden;
    width: 100%;
    text-overflow: ellipsis;
  }
  &.required { // * CX-1876-USED BY ACTIVITY FILTER : SET BY ACTIVITY FILTER DIRECTLY TO THE DOM ELEMENT
     .ant-dropdown-trigger, .ant-input-number , .ant-select-selector, a {
        border-color: #F4584C;
      }
      &:after {
        content: "Required";
        color: #F4584C;
        font-size: 12px;
        display: block;
      }
      &:focus-within a {
        outline: 1px solid #5D97FF;
      }
  }
  &[data-error-message] {
    .ant-dropdown-trigger {
      border-color: #F4584C;
    }
    &:after {
      content: attr(data-error-message);
      color: #F4584C;
      font-size: 12px;
    }
  }
`

const FilterValue = memo((props) => {
  const {
    value,
    attribute,
    operatorData,
    callListApi,
    propertyName,
    propValue,
    isEventProperty,
    isScreenProperty,
    propertyOperator,
    isUserPropertyValue,
    isUserPropertyName,
    isMultiSelect,
    id,
    eventValue,
    editFieldVisibility,
    toggleEditFieldVisibility,
    operatorChangeData,
    setOperatorChangeData,
    setOperatorData,
    setPropertyOperator,
    isUserName,
    filterTitle,
    setWhereClicked,
    toggleEventPropertyVisibility,
    attributeProps,
    filterData,
    isActivitySegment = false,
    activityPropertyIndex = null, // * CX-1876 (Only required for activityFilter) : index of properties of each activity filter segment
    activityFilterIndex = null,  // * CX-1876 (Only required for activityFilter) : index of activity filter, one activityFilterIndex div contains multiple activityPropertyIndex div
    togglePropFieldVisibility,
    propFieldVisibility,
  } = props
  const dispatch = useDispatch()
  const isStringElement = useRef(false);
  const operatorDataNew = useRef()
  const placeholderText = useRef()
  const filterTitleNew = useRef();
  const filterSelectedValues = useRef();
  const [visible, onVisibleChange] = useState(false)
  const [selectedOptions, setSelectedOptions] = useState([])
  const { appFilter, screenRenamedList, commonReducer: { eventPropertyList } } = useSelector((state) => state)
  const isScreenPropertyValue = id === 'eventpropertyvalue' && isScreenProperty

  const { userCohorts } = useUserCohorts()
  const cohortsNameMap = useMemo(() => userCohorts.reduce((acc, curr) => ({ ...acc, [curr.id]: curr.name }), {}), [userCohorts])
  const {getQueryPrefix} = useUserV2Properties();
  
  const processedValue = useMemo(() => {
    if(attribute === 'viewtype' && value) {
        return viewTypeUtils.getTitles(value)
    }
    if(attribute === 'environment' && value) {
      return !isArray(value) ? capitalizeEnvString(value) : value?.map(v => capitalizeEnvString(v))
    }

    return value
  }, [attribute, value])

  const { segmentType } = useAppFilter()

  const fetchedProperty = appFilter.fetchProperty[attribute]
  // * CX-1876: finding correct filter segments
  const filterSegment = useMemo(()=>
    isActivitySegment ? appFilter[segmentType].activityFilterList[activityFilterIndex].filters : appFilter[segmentType].segment,
  [isActivitySegment, appFilter, segmentType, activityFilterIndex])   
  
  //* CX-1876: Validating activity filter values and handles error message
  const _ = useActivityFilterValidator({
    attribute,
    activityFilterIndex,
    activityPropertyIndex,
    filterSelectedValues: filterSelectedValues.current,
  })
  
  const attributeNew = useMemo(() => {
    let attributeNewCopy = attribute;
    if (isEventProperty) attributeNewCopy = 'event_custom_property';
    if (isUserPropertyValue) attributeNewCopy = 'user_custom_property';
    return attributeNewCopy;
  }, [attribute, isEventProperty, isUserPropertyValue]);

  operatorDataNew.current = operatorData
  filterSelectedValues.current = processedValue
  if (operatorChangeData?.attribute) operatorDataNew.current = operatorChangeData
  if ( isScreenPropertyValue ) operatorDataNew.current = propertyOperator

  if (isEventProperty || isScreenProperty) {
    if (value === 0 || value) {
      isStringElement.current = false
      placeholderText.current = `Search ${isScreenProperty ? 'screen' : 'event'} property`
      if (id === 'eventpropertyname') placeholderText.current = 'Search property'
    } else if (id === 'eventpropertyname') {
      filterSelectedValues.current = <span className="property-text">Select property</span>
      isStringElement.current = true
      placeholderText.current = 'Search property'
    } else {
      filterSelectedValues.current = <span className="property-text">Select property values</span>
      isStringElement.current = true
      placeholderText.current = 'Search property values'
    }
  }

  if (isUserPropertyValue) {
    placeholderText.current = 'Search custom user property'
    filterSelectedValues.current = value
    isStringElement.current = false
    if (!(isArray(value) ? value.length : value)) {
      filterSelectedValues.current = <span className="property-text">Select property values</span>
      isStringElement.current = true
    }
  }

  if (filterTitle !== 'OS version') filterTitleNew.current = lowerCase(filterTitle)
  else filterTitleNew.current = filterTitle
  const filterSelectedValuesCopy = filterSelectedValues.current

  if (
    isUserName &&
    fetchedProperty?.data &&
    notInOperators.includes(operatorData.attribute)
  ) {
    filterSelectedValues.current = fetchedProperty?.data
      .filter((el) => filterSelectedValues.current.includes(el?.uxcamuserid))
      .map((el) => el?.name)
  }

  if(attribute === 'uxcamuserid' && !filterSelectedValues.current.length) filterSelectedValues.current = filterSelectedValuesCopy
  const handleApply = useCallback( (payload, propName, fromInput) => {
    let args = payload
    const index = filterSegment.indexOf(filterData)
    if ( attribute === 'event_custom_property' || ((isUserPropertyValue || isUserPropertyName) || attribute === 'utm' || attribute === 'session_screen_with_property' || attribute === 'session_screen_with_property_list' || attribute === 'user_first_utm'  && !isEventProperty) ) {
      if (propName) filterSegment[index].property_name = propName
      else filterSegment[index].property_name = propertyName
      if (args) filterSegment[index].value = args
      filterSegment[index].operator = operatorDataNew.current.attribute
    } else if (!isEqual(filterSegment[index].value, args) || (fromInput && id === 'eventpropertyvalue')) {
      if (isEventProperty || isScreenProperty) {
        const eventPropertyName = id === 'eventpropertyname' ? propName : propertyName
        let eventPropertyValue = args || propValue
        const isEventActivityScreen = eventPropertyName === 'activity'
        if(isEventActivityScreen && ['in', 'not_in'].includes(operatorDataNew.current.attribute)) eventPropertyValue = eventPropertyValue.map(v => invert(screenRenamedList)[v] || v)
        filterSegment[index].property = {
          name: eventPropertyName,
          operator: operatorDataNew.current.attribute,
          value: eventPropertyValue,
        };
      } 
      else {
        if (attribute === 'event_name') {
          filterSegment[index].property = undefined
          setWhereClicked(false)
          toggleEventPropertyVisibility(false)
          dispatch(resetFetchedPropertyByKey('eventpropertyvalue'))
          dispatch(resetFetchedPropertyByKey('eventpropertyname'))
        }
        if (isOptionsPredefined(attribute) && isArray(args)) args = args.map((v) => v.toLowerCase())
        if (attribute === 'session_recorded_hour_of_user' && isArray(args)) args = args.map((v) => v.replace(/(\d+)\s*(am|pm)/i, (_, hour, period) => `${hour}${period.toUpperCase()}`))
        // if(['session_uploadedon'].indexOf(attribute) > -1 && isArray(args)) args = { lower: args[0], upper: args[1] }
        filterSegment[index].value = args
        filterSegment[index].operator = operatorDataNew.current?.attribute || filterSegment[index].operator
      }
    }
    if(attribute === 'viewtype'){
        filterSegment[index].value = viewTypeUtils.getValues(args)
    }
    // * CX-1876 
    if(isActivitySegment){
        dispatch(updateActivityFilterSegment(filterSegment, activityFilterIndex)) // * update segment 
        callListApi(); // * this is activityFilterCallList 
    }else{
        callListApi(filterSegment);
    } 

    setOperatorData && setOperatorData(operatorDataNew.current)
    setPropertyOperator && setPropertyOperator(operatorDataNew.current)
    setOperatorChangeData && setOperatorChangeData()
    toggleEditFieldVisibility && toggleEditFieldVisibility(false)
    togglePropFieldVisibility && togglePropFieldVisibility(false)
    onVisibleChange(false)
  }, [activityFilterIndex, attribute, callListApi, dispatch, filterData, filterSegment, id, isActivitySegment, isEventProperty, isScreenProperty, isUserPropertyName, isUserPropertyValue, propValue, propertyName, screenRenamedList, setOperatorChangeData, setOperatorData, setPropertyOperator, setWhereClicked, toggleEditFieldVisibility, toggleEventPropertyVisibility, togglePropFieldVisibility])
  
  const displayOption = useMemo(() => {
    let mutatedDisplayValue = filterSelectedValues.current;
    if ( attribute === 'uxcamuserid_cohort' ) {
      return ( Array.isArray( mutatedDisplayValue ) ? mutatedDisplayValue : [ mutatedDisplayValue ] )
        .map( ( v ) => cohortsNameMap[ v ] || v )
    }
    if ( attribute === 'batch_id' ) {
      const batchData = appFilter.fetchProperty?.batch_id?.data || []
      return ( Array.isArray( mutatedDisplayValue ) ? mutatedDisplayValue : [ mutatedDisplayValue ] )
        .map( ( v ) => {
          const batch = batchData.find( ( b ) => b.batch_id === v )
          return batch ? batch.batch_name : v
        })
    }
    if (
      filterSelectedValues.current &&
      typeof filterSelectedValues.current !== 'object'
    )
      return mutatedDisplayValue;
    let mutableAttributes = [ ...screenNameAttributes, 'event_name', 'device_class', 'device_model', 'event_custom_property' ];
    mutableAttributes = propertyName === 'activity'  ? mutableAttributes : mutableAttributes.filter((v) => v !== 'event_name')
    if ((mutableAttributes.includes(attribute) || propertyName === 'screen') && !isStringElement.current && ![ 'contains_any', 'not_contains_any' ].includes( operatorDataNew.current.attribute )) {
        mutatedDisplayValue =filterSelectedValues?.current &&  filterSelectedValues?.current?.map(
        (v) => screenRenamedList[v] || v
      );
      
      if (['device_class', 'device_model'].includes(attribute))
        mutatedDisplayValue = filterSelectedValues?.current && filterSelectedValues.current?.map((v) =>
          getRenamedDeviceName(v)
        );
    } else if (attribute === 'session_recorded_hour_of_user')
      mutatedDisplayValue = filterSelectedValues?.current && filterSelectedValues.current.map((v) =>
        v.replace(/(\d+)\s*(AM|PM)/i, (_, hour, period) => `${hour} ${period.toUpperCase()}`)
      );
    else if (isOptionsPredefined(attribute))
      mutatedDisplayValue = filterSelectedValues?.current && filterSelectedValues.current.map((v) =>
        capitalize(v)
      );
    return mutatedDisplayValue;
  }, [
    attribute,
    screenRenamedList,
    propertyName,
    filterSelectedValues.current,
    cohortsNameMap,
    appFilter.fetchProperty,
    operatorData,
  ]);

  if (attribute === 'event_name' && propertyName) {
    const opIndx = findIndex(eventPropertyList, { propertyName });
    if (opIndx > -1) {
      const propOperator = eventPropertyList[opIndx]['propertyType'];
      if (
        propOperator === 'integer' &&
        notInOperators.includes(operatorDataNew.current.attribute)
      ) {
        operatorDataNew.current.isSearchable = true;
      }
    }
  }

  useEffect(() => {
    setSelectedOptions([])
  }, [operatorChangeData])

  const titleRenderIfArray = useMemo(() => {
    let title = filterSelectedValues.current;
    let isTooltip = false
    if (
      filterSelectedValues.current &&
      typeof filterSelectedValues.current === 'object' &&
      !isStringElement.current
    ) {
      title = titleWithSeparator( isTooltip, displayOption);
      if (filterSelectedValues.current?.length > 3) {
        isTooltip = true
        title = (
          <Tooltip
            title={titleWithSeparator( isTooltip, displayOption )}
            overlayClassName="filter-display-tooltip"
            overlayInnerStyle={
              displayOption.length > 20 ? {
              // styles for scrollable tooltip 
              display: 'flex',
              flexDirection: 'row',
              flexWrap: 'wrap',
              width: '300px',
              maxHeight: '60vh',
              overflowY: 'auto',
            }: null}
          >
            {title}
          </Tooltip>
        );
      }
    }
    // * check for userV2 prefix `User Where ...` in title
    // * Rename kUXCam_UserIdentity to Custom user ID for usersList and featureflag
    return isActivitySegment ? title || 'select_activity' : getQueryPrefix(title, title )
    
  }, [displayOption, getQueryPrefix, isActivitySegment]);
  const errorMessage = useMemo(() => {
    switch ( attribute ) {
      case 'uxcamuserid_cohort': {
        return Array.isArray( value ) &&
          value.some( ( v ) => !cohortsNameMap[ v ] )
          ? 'Cohort not found'
          : undefined;
      }
      case 'batch_id': {
        const batchData = appFilter.fetchProperty?.batch_id?.data || []
        return Array.isArray( value ) &&
          value.some( ( v ) => !batchData.find( ( b ) => b.batch_id === v ) )
          ? 'Batch not found'
          : undefined;
      }
      default: {
        return undefined
      }
    }
  }, [attribute, cohortsNameMap, appFilter.fetchProperty, value])

  const filterValueElement = useMemo(() => {
      if (operatorDataNew.current?.isSearchable) {
        return (
        <FilterContextProvider
          attributeProps={{
            ...attributeProps,
            has_mass_value: filterData?.has_mass_value,
            mass_value_segment_id: filterData?.mass_value_segment_id,
            mass_values_id: filterData?.mass_values_id,
          }}
          isEventProperty={isEventProperty}
          isScreenProperty={isScreenProperty}
          isUserPropertyValue={isUserPropertyValue}
          propertyOperator={propertyOperator}
          eventValue={eventValue}
          propertyNameProp={propertyName}
          attributeNew={attribute}
          isMultiSelect={isMultiSelect}
          key={attributeNew}
          isFilterDisplayBar
          operatorData={operatorData}
        >
          <FilterDropdown
            onVisibleChange={onVisibleChange}
            handleApply={handleApply}
            visible={visible}
            setSelectedOptions={setSelectedOptions}
            selectedOptions={selectedOptions}
            editFieldVisibility={editFieldVisibility}
            propFieldVisibility={propFieldVisibility}
            isScreenPropertyValue={isScreenPropertyValue}
            filterTitleNew={filterTitleNew.current}
            titleRenderIfArray={titleRenderIfArray}
            placeholderText={placeholderText.current}
            key={attributeNew}
            activityPropertyIndex={activityPropertyIndex}
            activityFilterIndex={activityFilterIndex}
            {...props}
          />
        </FilterContextProvider>
      )
    }
    return (
      <InlineInputEdit
        title={titleRenderIfArray}
        option={filterSelectedValues.current}
        handleApply={handleApply}
        operatorData={operatorDataNew.current}
        toggleEditFieldVisibility={toggleEditFieldVisibility}
        propFieldVisibility={propFieldVisibility}
        togglePropFieldVisibility={togglePropFieldVisibility}
        setOperatorChangeData={setOperatorChangeData}
        editFieldVisibility={editFieldVisibility}
        filterTitleNew={filterTitleNew.current}
        key={operatorDataNew.current?.attribute}
        id={id}
        isScreenPropertyValue={isScreenPropertyValue}
      />
    )
  }, [titleRenderIfArray, handleApply, toggleEditFieldVisibility, propFieldVisibility, togglePropFieldVisibility, setOperatorChangeData, editFieldVisibility, id, isScreenPropertyValue, attributeProps, isEventProperty, isScreenProperty, isUserPropertyValue, propertyOperator, eventValue, propertyName, attribute, isMultiSelect, attributeNew, operatorData, visible, selectedOptions, props, activityFilterIndex, activityPropertyIndex, filterData?.has_mass_value, filterData?.mass_value_segment_id, filterData?.mass_values_id])
  

  return (
    <FilterSpacing
      className="filter-spacing"
      data-error-message={ errorMessage }
      {...(activityFilterIndex !== null && activityFilterIndex !== undefined && {
        id: getActivityFilterPropertyId( attribute, activityFilterIndex, activityPropertyIndex ),
      })}
    >
      {filterValueElement}
      {/* {editFieldVisibility && (
        <CloseCircleOutlined
          onClick={handleClose}
          className="close-input"
        />
      )} */}
    </FilterSpacing>
  )

})
export default FilterValue
