import React, { useCallback, useEffect, useMemo, useRef } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { PLAYLIST_STATUS, useAISessionUtils } from 'components/shared/GlobalFilter/components/aiSessionFilter/AISessionUtilsContext';
import { urlSegmentEncoder } from 'Utils/helpers/urlSegmentEncoder';
import Router from 'next/router';
import { formatTime } from 'components/shared/Sessions/Video/utils';
import { useIsAppType } from 'hooks/useIsAppType';
import { useSessionVideoContext } from 'components/shared/Sessions/Context';
import { useSessionTableHelper } from 'components/features/sessions/SessionDetailsAndVideo/SessionTable/utils';
import { ActiveSession, DropdownSession, PlaylistType, ReplayInfo, UserSessionData} from './types';
import { getUserName, getTimeDuration, getUserNameConfig, trackPlaylistDropdownClick, trackAISessionSelect, trackPlaylistSessionSelect, trackNextPrevNavigation } from './utils';
import BaseSessionDropdown from './BaseSessionDropdown';
import { useAIUserSessions } from './service';


interface Props {
    activeSession?: ActiveSession;
    userSessionListData?: UserSessionData | null;
    isLoading?: boolean;
    replayInfo: ReplayInfo | undefined
    paginationInfo: {
        hasPrev: boolean;
        hasNext: boolean;
    }
}


const UserListDropdown: React.FC<Props> = ({
    activeSession,
    userSessionListData,
    isLoading = false,
    replayInfo,
    paginationInfo,
}) => {
    const {
        urlReducer: { sessionid, sessionpage = 1, appId, secondarysessionid ,parentType},
        appFilter: { session: { segment: sessionSegment }, dateSegment },
    } = useSelector((state: any) => state);
    const { utils, setUtils } = useAISessionUtils();

    const lastPaginationDirection = useRef<'next' | 'prev' | null>(null);
    const lastSessionId = useRef<string | null>(null);
    const dispatch = useDispatch();
    const { data: userDataBody , isLoading:isAIUserSessionLoading, mutate:mutateAIUserSession } = useAIUserSessions()
    const isWebApp = useIsAppType( 'web' );
    const { isPlaying, timeRef } = useSessionVideoContext()
    const { trackUserTimeEvent } = useSessionTableHelper({expanded: true})
    const handleSessionReplayStoppedTrackEvent = useCallback((userSessionId: string) => {
        if(isPlaying) {
            trackUserTimeEvent(userSessionId, timeRef?.current);
        }
    }, [trackUserTimeEvent, isPlaying, timeRef]);
    const sessions: DropdownSession[] = useMemo(() => {
        const body = userSessionListData?.data?.data?.body || []
        return body?.map((item, index: number) => ({
            dataIndex: index,
            index: (index + 1),
            id: item.sessionid,
            name: getUserName(item.userProperty),
            location: item.country || 'Unknown',
            duration: formatTime(item.sessionDuration).toString(),
            date: getTimeDuration(item.deviceLocalDateTime, item.userTimezone)[0],
            status: 'playing',
            isAIAnalyzed: item.sessionanalyzedbyai || false,
            hasVideo: item.video || false,
        }));
    }, [userSessionListData?.data?.data?.body]);

    const totalSessionsCount = useMemo(() => {
        return replayInfo?.totalsession?.toString() ?? '';
    }, [replayInfo?.totalsession]);
        
    const handleRowClick = useCallback((userSessionId: string, currentIndex?: number, previousIndex?: number, skipTracking = false) => {
        setUtils(prev => ({ ...prev, activePlaylist: PLAYLIST_STATUS.USER_PLAYLIST }));
        const autoplay = false;
        
        if (!skipTracking) {
            if (currentIndex && previousIndex) {
                dispatch(trackPlaylistSessionSelect({
                    parentType,
                    playlistType: PlaylistType.USER,
                    sessionsPosition: previousIndex,
                    selectedSessionPosition: currentIndex
                }))
            }
            const sessionData = userSessionListData?.data?.data?.body?.find((item)=>item.sessionid === userSessionId);
            if (sessionData) {
                dispatch(trackAISessionSelect({
                    sessionId: sessionData.sessionid,
                    aiAnalyzed: sessionData.sessionanalyzedbyai,
                    containsVideo: sessionData.video,
                    duration: sessionData.sessionDuration,
                    gestureCount: sessionData?.totalGesture,
                    parentType,
                    sessionSelectedFrom: 'user_playlist',
                    filtersApplied: sessionSegment,
                    isRageTap: sessionData?.isRageTap || false,
                    isUiFreeze: sessionData?.isuifreeze || false,
                    isCrashed: sessionData?.crashed || false
                }))
            }
        }
        handleSessionReplayStoppedTrackEvent(secondarysessionid)
        
        const autoPlayPart = autoplay ? '#autoplay' : '';
        let url = `/app/${appId}/aisessions/list/${sessionpage || 1}/${sessionid}?secondarysessionid=${userSessionId}&`;
        url = `${urlSegmentEncoder(url, [...sessionSegment, ...[{ ...dateSegment }], ])}${autoPlayPart}`;
        const query = `appId=${appId}&parentType=aiSessionsList&sessionid=${sessionid}&sessionpage=${
            sessionpage || 1
        }&starttime=0${autoPlayPart}&secondarysessionid=${userSessionId}`;
        Router.push(`/integration?${query}`, url);
    },[setUtils, appId, sessionpage, sessionid, sessionSegment, dateSegment, userSessionListData?.data?.data?.body, handleSessionReplayStoppedTrackEvent, secondarysessionid, dispatch, parentType]);

    const handleNextPrevClick = (direction: 'next' | 'prev') => {
        const currentSession = sessions.find(s => s.id === secondarysessionid);
        if (!currentSession) return;

        const potentialNewIndex = direction === 'next'
            ? currentSession.dataIndex + 1
            : currentSession.dataIndex - 1;

        const isNavigatingToNextPage = potentialNewIndex >= sessions.length && direction === 'next';
        const isNavigatingToPrevPage = potentialNewIndex < 0 && direction === 'prev';
        const sessionBody = userSessionListData?.data?.data?.body || [];

        dispatch(trackNextPrevNavigation({
            currentOrder: sessionBody?.find((item) => item.sessionid === secondarysessionid)?.userSessionRun || 0,
            total: replayInfo?.totalsession || 0,
            playlistType: PlaylistType.USER,
            direction: direction === 'next' ? 'next session' : 'previous session',
            parentType
        }))


        if (isNavigatingToNextPage) {
            if (paginationInfo.hasNext) {
                const lastItem = sessionBody[sessionBody.length - 1];
                if (lastItem?.recordedon) {
                    lastPaginationDirection.current = 'next';
                    lastSessionId.current = lastItem.sessionid;
                    mutateAIUserSession({
                        appid: appId,
                        recordedon: lastItem?.recordedon || '',
                        session_per_page: 101,
                        usersessionrun: lastItem?.userSessionRun || null,
                        uxcamuserid:lastItem?.userProperty?.uxcamuserid || '',
                        webApp: isWebApp
                    });
                }
            }
            return;
        }

        if (isNavigatingToPrevPage) {
            if (paginationInfo.hasPrev) {
                const firstItem = sessionBody[0];
                if (firstItem?.recordedon) {
                    lastPaginationDirection.current = 'prev';
                    lastSessionId.current = firstItem.sessionid;
                      mutateAIUserSession({
                        appid: appId,
                        recordedon: firstItem?.recordedon || '',
                        session_per_page: 101,
                        usersessionrun: firstItem?.userSessionRun || null,
                        uxcamuserid:firstItem?.userProperty?.uxcamuserid || '',
                        webApp: isWebApp
                    })
                }
            }
            return;
        }

        // If we're staying on the same page, clamp the index and navigate to that session
        const newIndex = direction === 'next' 
            ? Math.min(potentialNewIndex, sessions.length - 1)
            : Math.max(potentialNewIndex, 0);

        const newSessionId = sessions[newIndex]?.id;
        if (newSessionId) {
            handleRowClick(newSessionId, undefined, undefined, true); // Pass skipTracking=true
        }
    };
    useEffect(() => {
        if (!sessions || !sessions.length ) return;
        const lastSessionIndexInLatest = sessions.findIndex(session => session.id === lastSessionId.current)
        // * Handle session selection based on context
        if (lastPaginationDirection.current !== null) {
            if (sessions.length > 0) {
                let sessionIdToSelect: string | undefined;
                if (lastPaginationDirection.current === 'next') {
                    sessionIdToSelect = sessions[Math.min(lastSessionIndexInLatest + 1, sessions.length - 1)].id;  // * if lastSessionIndexInLatest === -1 , its 0
                } else if (lastPaginationDirection.current === 'prev') {
                    sessionIdToSelect = sessions[Math.max(lastSessionIndexInLatest - 1, 0)].id;  // * if lastSessionIndexInLatest === -1 , its 0
                }
                if (sessionIdToSelect) {
                    handleRowClick(sessionIdToSelect, undefined, undefined, true); // Pass skipTracking=true
                }
                lastPaginationDirection.current = null;
            }
        }
    }, [sessions, secondarysessionid, handleRowClick, userSessionListData?.data?.data?.body, mutateAIUserSession, appId, isWebApp]);


    const dropdownTitle = useMemo(() => {
        const useName = activeSession?.userProperty && getUserNameConfig(activeSession?.userProperty);
        return `Sessions from ${useName?.content}`;
    }, [activeSession?.userProperty]);

    const currentSessionInfo = useMemo(() => {
        const sessionBody = userSessionListData?.data?.data?.body;
        
        if (!secondarysessionid || !sessionBody?.length) {
            return {
                userSessionRun: activeSession?.userSessionRun || 0,
                currentIndex: 0
            };
        }
    
        const currentIndex = sessionBody.findIndex(session => session.sessionid === secondarysessionid);
        
        if (currentIndex === -1) {
            return { 
                userSessionRun: activeSession?.userSessionRun || 0,
                currentIndex: 0
            };
        }
    
        return {
            userSessionRun: sessionBody[currentIndex].userSessionRun || 0,
            currentIndex
        };
    }, [secondarysessionid, userSessionListData?.data?.data?.body, activeSession?.userSessionRun]);

    const triggerLabel = useMemo(() => {
        if ( !isLoading && !!totalSessionsCount ) {
            return `User session: ${currentSessionInfo.userSessionRun} out of ${totalSessionsCount }`;
        }
        return 'User session';
    }, [currentSessionInfo.userSessionRun, isLoading, totalSessionsCount]);

     const hasPrevNext = useMemo(() => {
        const data = userSessionListData?.data?.data;
        if (!data) return { hasPrev: false, hasNext: false };
        
        const { next, prev } = data;
        const { currentIndex } = currentSessionInfo;
        
        return {
            hasPrev: currentIndex === 0 ? Boolean(prev) : true,
            hasNext: currentIndex === sessions.length - 1 ? Boolean(next) : true
        };
    }, [userSessionListData?.data?.data, currentSessionInfo, sessions.length]);

    const onVisibleChange = useCallback((visible: boolean) => {
        visible && dispatch(trackPlaylistDropdownClick({
            parentType,
            playlistType: PlaylistType.USER
        }))
    }, [dispatch, parentType])
       
    return (
        <BaseSessionDropdown
            sessions={sessions}
            currentSessionId={secondarysessionid}
            isLoading={isLoading}
            isActive={utils.activePlaylist === PLAYLIST_STATUS.USER_PLAYLIST}
            onSessionClick={handleRowClick}
            onNextPrevClick={handleNextPrevClick}
            dropdownTitle={dropdownTitle}
            triggerLabel={triggerLabel}
            hasNext={hasPrevNext.hasNext}
            hasPrev={hasPrevNext.hasPrev}
            onVisibleChange={onVisibleChange}
        />
    );
};

export default React.memo(UserListDropdown);