/* eslint-disable jsx-a11y/label-has-associated-control */
import React, { memo, useMemo, useCallback } from 'react';
import { InfoCircleOutlined } from '@ant-design/icons';
import styled from 'styled-components';
import { Tooltip } from 'antd';
import { DebounceInput } from 'react-debounce-input';

import { changeCommonValue } from 'redux/actions/common';

const symbolsArr = ['e', 'E', '+', '-', '.'];
const DebounceInputStyled = styled(DebounceInput)`
  border: 0;
  padding: 0 5px;
  width: 42px;
  outline: 0;
`;
const DebounceInputField = memo(
  ({
    label,
    onChange,
    id,
    autoFocus = true,
    value,
    tooltipTitle,
    errorFlag,
    setMessage,
    errorMessage,
    setErrorMessage,
    stepMaxValue
  }) => {
    const handleInputChange = useCallback(
       async (e) => {
      e.preventDefault();
      const useTargetValue = +e?.target?.value;
      if ( id === 'valMaxScreenNumber' && (useTargetValue < 1 || useTargetValue > 50 || !useTargetValue) ) {
        setMessage(true);
        setErrorMessage('Please enter a number from 1 to 50.');
        return;
      }
      if ( id === 'valMaxLength' && (useTargetValue < 1 || useTargetValue > stepMaxValue || !useTargetValue) ) {
        setMessage(true);
        setErrorMessage(`Please enter a number from 1 to ${stepMaxValue}.`);
        return;
      }
      setMessage(false);
      await changeCommonValue(id, useTargetValue);

      document.getElementById('valMaxLength').value = id === 'valMaxLength' ? useTargetValue : 5;
      document.getElementById('valMaxScreenNumber').value = id === 'valMaxScreenNumber' ? useTargetValue : 12;

      if(useTargetValue !== +value) await onChange(useTargetValue);
    }, [id, onChange, setErrorMessage, setMessage, stepMaxValue, value]);
    const className = useMemo(() => `combo-box ${
      (id === 'valMaxScreenNumber' || id === 'valMaxLength') && errorFlag
        ? 'error-message'
        : ''
    }`, [errorFlag, id]);
    return (
      <div className="filter-item">
        <div className={className}>
          <label>{label}</label>
          <DebounceInputStyled
            key={id}
            id={id}
            autoFocus={autoFocus}
            value={value}
            type="number"
            debounceTimeout={1000}
            onKeyDown={(e) => symbolsArr.includes(e.key) && e.preventDefault()}
            onChange={handleInputChange}
            max={stepMaxValue}
          />
        </div>
        <Tooltip title={tooltipTitle}>
          <InfoCircleOutlined />
        </Tooltip>
        <br />
        {errorFlag && ( <div className="display-error-message">{errorMessage}</div> )}
      </div>
    );
  }
);
export default DebounceInputField;
