import { capitalizeEnvString } from "components/features/setting/AppSetting/NewRecordingSection/DebounceSearch";

import { allFilters, operator } from "../../data-structures-v2";

import { mappedOperator, singleValueType } from "../../utils";

import { FilterData, FilterOperator, MappedOperator, TFilterPayload, TValidFilterPayload } from "./types";

const getFilterOperator = (operatorValue: string) => {
    const filterOperator = (mappedOperator as MappedOperator)[operatorValue];

    return filterOperator;
}

const getEventOperator = (attribute: string, operatorValue: string) => {
    const tempOperators = [
        { key: 'in', title: `With ${attribute === 'nce_name' ? 'smart' : ''} events` },
        { key: 'not_in', title: `Without ${attribute === 'nce_name' ? 'smart' : ''} events` },
    ];

    return tempOperators.find((item) => item.key === operatorValue)?.title || operatorValue;
}

const attributeToPropName = ['user_custom_property', 'event_custom_property', 'utm', 'session_screen_with_property', 'session_screen_with_property_list', 'user_first_utm'];

const getFilterData = (data: TFilterPayload, pageType: string) => {
    const { attribute, operator: operatorValue, value: receivedValue, property_name: propertyName } = data;
    const allFiltersCloned = JSON.parse(JSON.stringify(allFilters));
    const mappedFilters = allFiltersCloned[pageType]

    const filterData = mappedFilters.find((filter: FilterData) => filter.attribute === attribute) as FilterData;
    if (!filterData) return {
        ...data,
        operator: '',
        value: '',
        type: '',
        title: '',
    };

    const allOperators = JSON.parse(JSON.stringify(operator));
    const mappedOperators = allOperators[filterData?.attribute || ''];

    const isEvent = attribute === 'event_name' || attribute === 'nce_name';

    let operatorTemp = getFilterOperator(operatorValue);
    let value = null;
    const titleTemp = attributeToPropName.includes(attribute) ? propertyName : filterData.title;

    if (data.attribute.includes('custom_label')){
        operatorTemp = allOperators[filterData.type].find((item: FilterOperator) => item.attribute === operatorValue).title;
    }

    if (isEvent) {
        operatorTemp = getEventOperator(data.attribute, operatorValue);
    }

    if(filterData.type === 'date') {
        const temp = allOperators[filterData.type];
        operatorTemp = temp.find((item: FilterOperator) => item.attribute === operatorValue)?.title || '';
    };

    // value manipulations
    if (singleValueType.includes(filterData.type)) {
        operatorTemp = 'is';
        if (mappedOperators && mappedOperators.length > 0) {
            value = mappedOperators.find((item: FilterOperator) => item.attribute === receivedValue)?.title || '';
        }
    }
    if (attribute === 'environment' && Array.isArray(receivedValue) && receivedValue.length > 0) {
        const newAlteredValue = receivedValue.map(item => capitalizeEnvString(item));
        value = newAlteredValue.join(', ');
    }

    const result = {
        ...filterData,
        operator: operatorTemp,
        value,
        title: titleTemp,
    }

    return result;
}

const validateFilterData = (data: TFilterPayload[], pageType: string) => {
    const allFiltersCloned = JSON.parse(JSON.stringify(allFilters));
    const mappedFilters = allFiltersCloned[pageType]

    const validateEachFilter = data.map((item) => {
        const { attribute } = item;
        const filterData = mappedFilters.find((filter: FilterData) => filter.attribute === attribute) as FilterData;
        const validOperator = getFilterData(item, pageType).operator;

        if (filterData && validOperator) {
            return {
                ...item,
                isValid: true,
            }
        }
        return {
            ...item,
            isValid: false,
        }
    });

    return validateEachFilter as TValidFilterPayload[];
}


export {
    getFilterData,
    getFilterOperator,
    validateFilterData,
}