/* eslint-disable react/jsx-props-no-spreading */
import React, { useState, useEffect, useMemo, memo, useRef, useCallback } from 'react'
import { useSelector } from 'react-redux'
import styled from 'styled-components'

import { showOverflowItems
} from 'components/shared/GlobalFilter/components/utils'
import { FilterContextProvider } from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/FilterContextProvider'
import useAppFilter from 'components/shared/GlobalFilter/components/useAppFilter'
import InlineInputEdit from './InlineInputEdit'
import FilterDropdown from './FilterDropdown'

const StyledSpan = styled.span`
.ant-dropdown-trigger{
  font-weight: 400 !important;
}
.ant-input:placeholder{
  font-weight: 500;
}
`
const FilterValue = memo((props) => {
  const {
    value,
    attribute,
    operatorData,
    callListApi,
    propertyName,
    isEventProperty,
    eventOperator,
    isUserPropertyValue,
    isMultiSelect,
    id,
    eventValue,
    editFieldVisibility,
    toggleEditFieldVisibility,
    filterTitle,
    attributeProps,
    filterData,
  } = props

  const operatorDataNew = useRef()
  const filterTitleNew = useRef();
  const filterSelectedValues = useRef();
  const [visible, onVisibleChange] = useState(false)
  const [selectedOptions, setSelectedOptions] = useState()
  const { appFilter } = useSelector((state) => state)
  // const [ operatorChangeData, setOperatorChangeData]= useState()
  const { segmentType } = useAppFilter()

  const filterSegment = appFilter[segmentType].segment

  const attributeNew = useMemo(() => attribute, [attribute]);
  const eventNameOperator = useMemo(()=> operatorData, [operatorData])

  operatorDataNew.current = operatorData
  filterSelectedValues.current = useMemo(()=> selectedOptions || value, [selectedOptions, value]) 
  // if (operatorChangeData?.attribute) operatorDataNew.current = operatorChangeData

  filterTitleNew.current = filterTitle;
  const index = filterSegment.indexOf(filterData)   

  const handleApply = useCallback( (payload) => {
   if (attribute === 'event_count_per_screen_visit' || attribute === 'smart_event_count_per_screen_visit'){
    filterSegment[index].filters[0].value = payload; 
    filterSelectedValues.current = payload;
    // setSelectedOptions()
    filterSegment[index].filters[0].operator = eventNameOperator?.attribute; 
    }
    callListApi(filterSegment)
    onVisibleChange(false)
  }, [index, filterSegment, attribute, callListApi, eventNameOperator?.attribute])

  const displayOption = useMemo(() => {
    const mutatedDisplayValue = selectedOptions || filterSelectedValues.current;
    if (
      filterSelectedValues.current &&
      typeof filterSelectedValues.current !== 'object'
    )
      return mutatedDisplayValue;
  
    return mutatedDisplayValue;
  }, [selectedOptions, filterSelectedValues]);

  // useEffect(() => {
  //   if(['in', 'not_in'].includes(eventNameOperator?.attribute)){
  //     setSelectedOptions()
  //   }
  // }, [eventNameOperator])

  useEffect(() => {
    setSelectedOptions(filterData ? filterData?.filters[0]?.value : null)
  }, [filterData])

  const titleRenderIfArray = useMemo(() => {
    let title = selectedOptions || filterSelectedValues.current;
    if (
      filterSelectedValues.current &&
      typeof filterSelectedValues.current === 'object'
    ) {
      title = showOverflowItems(displayOption);
      if (filterSelectedValues.current?.length >= 2) {
        return title;
      }
    }
    return title;
  }, [displayOption, filterSelectedValues?.current, selectedOptions]);

  const isSelectedValue =  useMemo(()=> selectedOptions || filterSelectedValues?.current, [selectedOptions]);
  
  const attributeSelection = useMemo(() => {
    if (attribute === 'event_count_per_screen_visit') {
      return 'event_name';
    }
    if (attribute === 'smart_event_count_per_screen_visit') {
      return 'nce_name';
    }
    return attribute;
  }, [attribute]);

  const filterValueElement = useMemo(() => {
      if (operatorDataNew.current?.isSearchable) {
        return (
        <FilterContextProvider
          attributeProps={attributeProps}
          isEventProperty={isEventProperty}
          isUserPropertyValue={isUserPropertyValue}
          eventOperator={eventOperator}
          eventValue={eventValue}
          propertyNameProp={propertyName}
          attributeNew={attributeSelection}
          isMultiSelect={isMultiSelect}
          key={attributeNew}
          isFilterDisplayBar
        >
          <FilterDropdown
            onVisibleChange={onVisibleChange}
            handleApply={handleApply}
            visible={visible}
            setSelectedOptions={setSelectedOptions}
            selectedOptions={isSelectedValue instanceof Array ? isSelectedValue : [] }
            editFieldVisibility={editFieldVisibility}
            filterTitleNew={filterTitleNew.current}
            titleRenderIfArray={titleRenderIfArray}
            placeholderText='Select eventname'
            key={attributeNew}
            {...props}
          />
        </FilterContextProvider>
      )
    }
    return (
      <InlineInputEdit
        title={titleRenderIfArray}
        option={filterSelectedValues.current}
        handleApply={handleApply}
        operatorData={eventNameOperator}
        toggleEditFieldVisibility={toggleEditFieldVisibility}
       // setOperatorChangeData={setOperatorChangeData}
        editFieldVisibility={editFieldVisibility}
        filterTitleNew={filterTitleNew.current}
        key={eventNameOperator?.attribute}
        id={id}
      />
    )
  }, [attribute, attributeNew,isSelectedValue, operatorDataNew, attributeProps, editFieldVisibility, eventOperator, eventValue, handleApply, id, isEventProperty, isMultiSelect, isUserPropertyValue, propertyName, props, titleRenderIfArray, toggleEditFieldVisibility, visible, eventNameOperator])

  return (
    <StyledSpan className="filter-spacing">
      {filterValueElement}
    </StyledSpan>
  )

})
export default FilterValue
