import React from 'react';
import { useSelector } from 'react-redux';

import ReactLoading from 'components/common/reactLoading';
import LoaderAdvanced from 'components/common/LoaderAdvanced';
import { ErrorBox } from 'components/common/Customary/ErrorBox';
import PendingLoaderInfo from 'components/common/PendingLoaderInfo';
import { useAppNavigationContextContext } from 'components/features/navigation/Context';

import SunBurstGraph from './SunBurstGraph';

const ReactLoader = () => (
  <>
    <PendingLoaderInfo preText="Computing flow data" />
    <ReactLoading />
  </>
);
const Sunburst = ({ chartRef }) => {
  const { sunBurstLoader, sunburstPlotGraph } = useSelector( (state) => state.screenDetailReducer );
  const errorMessage = sunburstPlotGraph?.error?.message
  const errorText = typeof errorMessage === 'string' ? errorMessage : errorMessage?.[0];
  const { setFlagCogDrop  } = useAppNavigationContextContext()
  return (
    <div className="stat-graph-box" data-intercom-target="Sunburst Stats">
      <LoaderAdvanced
        show={sunBurstLoader || false}
        message={<ReactLoader />}
        backgroundStyle={{
          backgroundColor: 'rgba(255,255,255,0.6)',
        }}
        style={{ position: 'initial' }}
      >
        {!sunBurstLoader ? (
          <>
            {sunburstPlotGraph &&
            sunburstPlotGraph instanceof Array &&
            sunburstPlotGraph.length ? (
              <SunBurstGraph chartRef={chartRef} />
            ) : (
              <ErrorBox
                displayIcon
                errorText={errorText ?? 'There is either no data to display or it is possible that the step limits have been exceeded.'}
                imgSrc="/static/sunburst/new-error-icon.svg"
                isNoData
                onClickHandler={() => setFlagCogDrop(true)}
              />
            )}
          </>
        ) : (
          <></>
        )}
      </LoaderAdvanced>
    </div>
  );
};

export default Sunburst;
