import React, { useCallback, useMemo } from "react";
import useDebounce from "hooks/useDebounce";
import { RootStateOrAny, useSelector } from "react-redux";
import { cloneDeep } from "lodash";
import { SegmentTitle } from "./variables";
import SegmentList from "./SegmentList";
import SegmentFilter from "./SegmentFilter";
import { SegmentContainer, SegmentMenuWrapper } from "./styles";
import { ISegmentListProps, ISegmentsMapperProps } from "./types";
import { useSegmentModal } from "./hooks/useModal";

const SegmentOverlay: React.FC<ISegmentListProps> = ({ segmentList =[] }) => {

  const { searchText, setSearchText } = useSegmentModal();
  const debouncedSearchValue = useDebounce(searchText, 500);

  const { profileReducer: userProfile, 
    applicationReducer: appList,
    currentOrgReducer: { orgId } } = useSelector((state: RootStateOrAny) => state);
  const { _id: userId } = userProfile || {};

  const searchedSegments = useMemo(() => cloneDeep(segmentList)?.filter(item => item.name.toLowerCase().includes(debouncedSearchValue.toLowerCase())), [debouncedSearchValue, segmentList]);

  const defaultSegments = useMemo(() => searchedSegments?.filter(item => item.isDefault), [searchedSegments]);
  const mySegments = useMemo(() => searchedSegments?.filter(item => item.createdBy === userId && !item.isDefault), [searchedSegments, userId]);
  const teamSegments = useMemo(() => {
    const isOwner =  appList.find((item: { orgId: string; }) => item.orgId === orgId)?.isOwner;
    if (isOwner) return searchedSegments?.filter(item => item.createdBy !== userId && !item.isDefault);
    return searchedSegments?.filter(item => item.createdBy !== userId && item.isPublic && !item.isDefault);
  },[appList, orgId, searchedSegments, userId]);

  const segmentsMapper = {
    'Default segments': defaultSegments,
    'My segments': mySegments,
    'Team segments': teamSegments
  }

  const onSearchTextChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    setSearchText(e.target.value);
  }, [setSearchText]);

  return (
    <SegmentMenuWrapper>
      <SegmentFilter value={searchText} onChange={onSearchTextChange} />
      <SegmentContainer>
        {SegmentTitle.map(item => <SegmentList title={item} segments={segmentsMapper[item as keyof ISegmentsMapperProps]} />)}
      </SegmentContainer>
    </SegmentMenuWrapper>
  )
}

export default SegmentOverlay;