import hasPermission from './PermissionUtils';

export const hasManagerRoleOnApps = (currentAppList) =>
  currentAppList?.length > 0
    ? currentAppList.some((app) => app?.role === 'admin')
    : false;

export const findOrgIndex = (organizationList, orgId) =>
  organizationList
    ? organizationList.findIndex((org) => org.$oid === orgId)
    : -1;

export const appManagerAppList = (currentAppList) =>
  currentAppList?.length > 0
    ? currentAppList.filter((app) => app?.role === 'admin')
    : [];

export const hasManagerOrOwnerRole = (organizationRole) =>
  organizationRole === 'owner' || organizationRole === 'manager';

export const hasManagerCommonRole = (organizationRole, role) =>
  organizationRole === 'owner' ||
  organizationRole === 'manager' ||
  role === 'App Manager';

export const handleLowerCase = (value) => value?.toLowerCase();

export const userRoleOnOrgnization = (organizationList, orgId) => {
  const orgIndex = findOrgIndex(organizationList, orgId);
  return organizationList?.length > 0 ? organizationList[orgIndex]?.role : '';
};

export const getUId = () => Date.now().toString(36) + Math.random().toString(36);

// team update delete on access level  and app role basis
export const authorizedOrgAppTeamPermission = (
  permissionCode,
  definedRoles,
  organization,
  orgId,
  accessLevel
) => {
  if (organization instanceof Array) {
    const orgIndex = findOrgIndex(organization, orgId);
    const appList = organization[orgIndex]?.apps;
    const orgRole = organization[orgIndex]?.role;
    if (
      ['manager', 'owner'].includes(orgRole) &&
      handleLowerCase(accessLevel) === 'organization'
    ) {
      return true;
    }
    return (
      accessLevel !== 'Organization' &&
      appList.some((data) =>
        hasPermission(permissionCode, data.role, definedRoles)
      )
    );
  }
  return false;
};

// for organization manager or owner  access on organization
export const authorizeOrgManagerPermission = (
  permissionCode,
  definedRoles,
  organization,
  orgId
) => {
  if (organization instanceof Array) {
    const orgIndex = findOrgIndex(organization, orgId);
    const orgRole = organization[orgIndex]?.role;
    return hasPermission(permissionCode, orgRole, definedRoles);
  }
  return false;
};

//  has app manager access for specific app
export const authorizeSpecificAppManagerPermission = (
  permissionCode,
  definedRoles,
  organization,
  orgId,
  appId
) => {
  if (organization instanceof Array) {
    const orgIndex = findOrgIndex(organization, orgId);
    const appList = organization[orgIndex]?.apps;
    const appIndex = appList.findIndex((app) => app.id === appId);
    const roleOnApp = appList[appIndex]?.role;
    // permission on specific app
    return hasPermission(permissionCode, roleOnApp, definedRoles);
  }
  return false;
};

// has any app manager access on an apps of organization
export const authorizeAppManagerPermission = (
  permissionCode,
  definedRoles,
  organization,
  orgId
) => {
  if (organization instanceof Array) {
    const orgIndex = findOrgIndex(organization, orgId);
    const appList = organization[orgIndex]?.apps;
    return appList.some((data) =>
      hasPermission(permissionCode, data.role, definedRoles)
    );
  }
  return false;
};

export const subtractMonths = (numOfMonths, date) => {
  const clonedDate = new Date(date);
  clonedDate.setMonth(date.getMonth() - numOfMonths);

  return clonedDate;
}

export const handleCommonPercentCalculate = (
  totalLimit,
  totalCount,
  billingPercent
) => (100 - totalLimit / (totalCount  / billingPercent))?.toFixed(0) ;

