import React, { useMemo, useState } from 'react';
import { Spinner } from "uxcam-frontend-components";
import PlayForward from "public/static/sessions/play-forward.svg";
import PlayBackward from "public/static/sessions/play-backward.svg";
import UserIcon from 'public/static/session-replay/user3.svg';
import PlayIcon from 'public/static/play-icon.svg';
import { DropdownSession, StyleConfig } from './types';
import {
    Container,
    ButtonContent,
    ButtonText,
    StyledDropdown,
    DropdownTitle,
    StyledMenu,
    DropdownContent,
    StyledMenuItem,
    SessionItemContent,
    PlayBackInfo,
    Duration,
    SessionAvatar,
    SessionInfo,
    InDropdownSpinnerWrapper,
    SpinnerWrapper
} from './styles';
import {
    getVisibleSessions,
    getSessionStatus,
    formatDuration
} from './utils';

interface BaseSessionDropdownProps {
    sessions: DropdownSession[];
    currentSessionId: string;
    isLoading: boolean;
    isActive: boolean;
    onSessionClick: (sessionId: string, currentIndex: number, previousIndex?: number) => void;
    onNextPrevClick: (direction: 'next' | 'prev') => void;
    showContinueWatching?: (sessionId: string) => boolean;
    styleConfig?:StyleConfig;
    dropdownTitle: string;
    triggerLabel: string;
    hasPrev: boolean;
    hasNext: boolean;
    onVisibleChange?: (visible: boolean) => void;
}

const getPreviousVisibleIndex = (sessions: DropdownSession[], currentSessionId: string) => {
    const visibleSessions = getVisibleSessions(sessions, currentSessionId);
    return visibleSessions.findIndex(s => s.id === currentSessionId) + 1;
};

const BaseSessionDropdown: React.FC<BaseSessionDropdownProps> = ({
    sessions,
    currentSessionId,
    isLoading,
    isActive,
    onSessionClick,
    onNextPrevClick,
    showContinueWatching,
    styleConfig = { size: 'sm' },
    dropdownTitle,
    triggerLabel,
    hasPrev,
    hasNext,
    onVisibleChange
}) => {
    const [visible, setVisible] = useState(false);
    const selectedKeys = useMemo(() => (currentSessionId ? [currentSessionId] : []), [currentSessionId]);

    const handleMenuClick = (session: DropdownSession, idx: number) => {
        setVisible(false);
        const previousIndex = getPreviousVisibleIndex(sessions, currentSessionId);
        const currentIndex = idx + 1 
        onSessionClick(session.id, currentIndex, previousIndex);
    };

    const handleVisibleChange = (flag: boolean) => {
        onVisibleChange && onVisibleChange(flag);
        setVisible(flag)
    };

    const handleNextPrevClick = (
        e: React.MouseEvent<HTMLButtonElement>,
        direction: 'next' | 'prev'
    ) => {
        e.stopPropagation();
        e.preventDefault();
        onNextPrevClick(direction);
        setVisible(false);
    };

    const menu = (
        <DropdownContent isLoading={isLoading}>
            <DropdownTitle>{dropdownTitle}</DropdownTitle>
            <StyledMenu
                onClick={({ key }) => {
                    const visibleSessions = getVisibleSessions(sessions, currentSessionId);
                    const selectedSessionIdx = visibleSessions.findIndex(session => session.id === key);
                    const selectedSession = visibleSessions[selectedSessionIdx];
                    if (selectedSession) handleMenuClick(selectedSession, selectedSessionIdx);
                }}
                selectedKeys={selectedKeys}
            >
                {getVisibleSessions(sessions, currentSessionId).map((session, idx) => (
                    <StyledMenuItem 
                        key={session.id} 
                        className={showContinueWatching?.(session.id) ? 'inactive-selected' : ''}
                    >
                        <SessionItemContent>
                            <PlayBackInfo>
                                <SessionAvatar>
                                    {getSessionStatus(
                                        false,
                                        idx,
                                        session?.isAIAnalyzed,
                                        currentSessionId,
                                        session.id,
                                        session.hasVideo
                                    )[1]}
                                </SessionAvatar>
                                <Duration>{formatDuration(session.duration)}</Duration>
                            </PlayBackInfo>
                            <SessionInfo>
                                <span className='name'>
                                    <UserIcon/>
                                    {session?.name}
                                </span>
                                <span className='date'>{session.date}</span>
                                {showContinueWatching?.(session.id) && 
                                    <span className='continue-watching'>
                                        <PlayIcon/>
                                        Continue watching
                                    </span>
                                }
                            </SessionInfo>
                        </SessionItemContent>
                    </StyledMenuItem>
                ))}
            </StyledMenu>
             {
                isLoading &&
                  <InDropdownSpinnerWrapper><Spinner data-size="m" /></InDropdownSpinnerWrapper>
             }
        </DropdownContent>
    );


    return (
        <Container>
            <StyledDropdown
                overlay={menu}
                visible={visible}
                onVisibleChange={handleVisibleChange}
                trigger={['click']}
                placement="bottomLeft"
                size={styleConfig.size}
            >
                <ButtonContent isActive={isActive}>
                        <button
                            className='playlist-action-icon'
                            type='button'
                            aria-label="Previous session"
                            onClick={e => handleNextPrevClick(e, "prev")}
                            disabled={!hasPrev || isLoading}
                        >
                            <PlayBackward />
                        </button>
                        <ButtonText>
                            {triggerLabel}
                            {
                                (isLoading) &&
                                <SpinnerWrapper><Spinner data-size="xs" /></SpinnerWrapper>
                            }
                        </ButtonText>
                        <button
                            className='playlist-action-icon'
                            type='button'
                            aria-label="Next session"
                            onClick={e => handleNextPrevClick(e, "next")}
                            disabled={!hasNext || isLoading}
                        >
                            <PlayForward />
                        </button>
                </ButtonContent>
            </StyledDropdown>
        </Container>
    );
};

export default BaseSessionDropdown; 