/* eslint-disable arrow-body-style */
/* eslint-disable no-nested-ternary */
/* eslint-disable react/jsx-props-no-spreading */
/* eslint-disable import/no-cycle */
import React, { useState, useEffect, memo, useCallback, useMemo } from 'react'
import { Menu } from 'antd'
import { useSelector, useDispatch } from 'react-redux'
import {
  setMegaDropdownVisible,
  setAttributeProps,
  setFilterBarVisible,
  setBottomMegaDropdownVisible,
  appendActivityFilterSegment
} from 'redux/actions/megaFilter'
import styled from 'styled-components'
import { findLastIndex, findIndex, clone } from 'lodash'
import { fetchPlanHatApi } from 'redux/actions/common'
import { trackPageViews } from 'redux/actions/trackingReport'
import { mapPageNames } from 'Utils/constants/index'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext'
import useCustomLabels from 'hooks/useCustomLabels'
import { removeValuesFromFilters } from 'Utils/helpers/commonUtils'
import { useIsAppType } from 'hooks/useIsAppType'
import {useFilterOptionType, useGetAvailableActivityFilters, useIsUserV2} from 'hooks/useUserV2Filter';
import { hasActivityFilter } from 'Utils/helpers/activityFilterUtils'
import MegaQuickFilters from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/MegaQuickFilters'
import { theme } from 'theme'
import { ACTIVITY_FILTER_CATEGORY } from 'types/activityFilterConfigurationTypes'
import useHasSmartEvents from 'hooks/useHasSmartEvents'
import {
  dropdownOptions as dropdownOptionsProps,
  dropdownOptionsWithNocode,
  additionalFilters,
  allFilters,
  operator,
  categoriesExtra,
  eventFiltering,
  gestures,
} from '../../data-structures-v2'
import InitialMenu from './InitialMenu'
import { withContextProps } from '../FilterContextProvider'
import SecondLevelMenu from './SecondLevelMenu'
import useAppFilter from '../../useAppFilter';
import ThirdLevelMenu from './ThirdLevelMenu';
import { activityFilterSelector, getActivityFilterAttributeByType } from '../../FilterDisplayBar/ActivityFilter/constants'
import { shouldImplementActivityFilter } from './utils'

const ColumnWrapper = styled.div`
  display: flex;
  flex-direction: column;
  width: 470px;
  &[ data-three-columns="true" ] {
    width: 720px;
  }
`

const RowWrapper = styled.div`
  display: flex;
  height: 100%;
`
const Divider = styled.div`
  height: 1px;
  width: calc(100% - 32px);
  background-color: ${ theme.colors.surface05.toString() };
  margin: 0 auto;
`

export const filterStrategyIncluded = ['Events']

export const webScreenAttribtues = [ "user_first_referer", "user_first_screen_name", "user_first_referer_domain", "referer_domain", "referer" ]

const MenuStyled = styled(Menu)`
  .checkbox-label {
    width: ${(props) => (props.hasWideWidth ? '240px !important' : '170px')};
  }
  .menu-filter{
    width: ${(props) => (props.hasWideWidth ? '300px !important' : '250px')};
    max-width: ${(props) => (props.hasWideWidth ? '300px !important' : '250px')};
  }
    
  div[data-name="column-wrapper"][data-three-columns="true"] {
      width: ${(props) => (props.hasWideWidth ? '770px !important' : '720px')};
  }
`
const EventOrGestureFilter = [
  'Screen visits with events',
  `Screen visits without events`,
  'Screen visits with smart events',
  'Screen visits without smart events',
  'Screen visits with gestures',
  'Screen visits without gestures',
];
const MainMenu = memo((props) => {
  const { setFiltersLockedModal, advancedFiltersAllowed, allowedCategoriesInFreePlan, aiSessionFeatureAllowed: isAISession } = useRestrictionContext() || {}
  const hasSmartEvents = useHasSmartEvents();
  const isWebSDK = useIsAppType( 'web' );
  const useFeatures = React.useMemo( () => {
    let features = [ 'default' ]

    if ( isWebSDK ) {
      features = [ 'websdk' ]
    }

    if ( isAISession ) {
      features = [ ...features, 'aisession' ]
    }

    return features
  }, [ isWebSDK, isAISession ] )
  const { resetFieldsAndCallApi, inputRef, menuProps, setActiveEventTab, setTabContentWidth } = props
  const { pageType, segmentType, callListApi, activityCallListApi } = useAppFilter()
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const dispatch = useDispatch()
  const onVisibleChange = useCallback( (flag) => {
    dispatch(setBottomMegaDropdownVisible(flag));
    dispatch(setMegaDropdownVisible(flag));
  }, [dispatch]);
  const { appFilter, megaFilterReducer: { selectedAttributeProps }, urlReducer } = useSelector( (state) => state )

  const allFiltersCloned = JSON.parse(JSON.stringify(allFilters))
  const { parentType, issueType } = urlReducer
  const showMegaQuickFilter = React.useMemo( () => [ 'aiSessionsList', 'aiSessionStatistics' ].includes( parentType ), [ parentType ] )
  
  const filterSegment = appFilter[segmentType].segment
  const [selectedKey, setSelectedKey] = useState('All')
  const [clickedDropdownLevel, setClickedDropdownLevel] = useState('firstLevel')
  const [selectedOperator, setSelectedOperator] = useState({})
  const dropdownOptions = useMemo( () => noCodeEventsFeatureFlag ? dropdownOptionsWithNocode : dropdownOptionsProps, [ noCodeEventsFeatureFlag ])

  const filterOptionType = useFilterOptionType(parentType);
  const mappedAllFilters = allFiltersCloned[filterOptionType]
  const isUserV2 = useIsUserV2();
  const getAvailableActivityFilterList = useGetAvailableActivityFilters();
  const dropdownOptionsByType = useMemo( () => {
    const optionsType = dropdownOptions[filterOptionType];
    if (issueType === 'crashes') {
      return {
        ...optionsType,
        'UX issues': optionsType['UX issues'].filter( option => option.attribute !== 'session_crashed')
      }
    }
    if (issueType === 'freezes') {
      return {
        ...optionsType,
        'UX issues': optionsType['UX issues'].filter( option => option.attribute !== 'UI Freeze')
      }
    }
    if (parentType === 'nocodeEventsList') {
      return {
        ...optionsType,
        'UX issues': optionsType['UX issues'].filter( option => option.attribute === 'session_crashed')
      }
    }
    if (parentType === 'heatmapsList') {// filtering out smart events here, not checking flag because custom events is only listed for heatmaps where when flag is enabled, a completely different component is rendered
      const tempData = optionsType['Custom events']?.filter(item => item.table === 'event')
      return {
        ...optionsType,
        ...(tempData?.length > 0 && { 'Custom events': tempData })
      }
    }

      return Object.entries( dropdownOptions[filterOptionType] )
    .reduce( (acc, [key, value]) => {
    const options = value.map(option => {
        // * CX-2200 - RENAME USER SESSION COUNT > SESSION NUMBER (ONLY:ICEBERG)
         if (option.attribute === "session_number_of_user") {
                return { ...option, title: "Session number" };
          }
        // * PF-1098 - RENAME CODED EVENT COUNT > EVENT COUNT (BASED ON SMART EVENTS)
        if(option.attribute === "session_with_event" && !hasSmartEvents ) {
            return { ...option, title: "Event count" };
          }
        if(option.attribute === "user_event_count" && !hasSmartEvents ) {
            return { ...option, title: "Total event count of user" };
          }
         return option;
    }).filter(option => {
        const hasValidFeatures = !option.features || option.features.some(feature => useFeatures.includes(feature));
        return hasValidFeatures
    });

      if ( !options.length ) return acc
      acc[ key ] = options
      return acc
    }, {} )
  }, [dropdownOptions, filterOptionType, issueType, parentType, hasSmartEvents, useFeatures])
  const categories = Object.keys(dropdownOptionsByType)
  
  const { getLabelTypeFromValue } = useCustomLabels();

  const resetCategorySelect = useCallback(() => {
    dispatch(setAttributeProps({}))
    setSelectedKey('All')
  }, [dispatch])

  const callApi = useCallback((rawNewFilter, activityFilterConfig) => {
    // * CX-2094 - Adds Activity Filter Segment
    if (activityFilterConfig) {
          const activityFilterAttribute = getActivityFilterAttributeByType(activityFilterConfig.attributeCategory)
          if (activityFilterAttribute) {
              const filterPayload = clone(activityFilterSelector[activityFilterAttribute].defaultValueWithFilters) ;
              if (['rageTap','UI Freeze'].includes(activityFilterConfig.attribute)) {
                  filterPayload.filters = rawNewFilter;
              } 
              if(['session_crashed'].includes(activityFilterConfig.attribute)) {
                filterPayload.filters = [
                        {
                            attribute : "session_crashed",
                            operator: "equal",
                            value: "True",
                            table: "session"
                        }
                ]
              }
              const shouldOpenAddPropertyDropdown = !['rageTap','UI Freeze','session_crashed'].includes(activityFilterConfig.attribute) &&
              activityFilterConfig.attributeCategory === ACTIVITY_FILTER_CATEGORY.SESSION 
              dispatch(appendActivityFilterSegment(filterPayload ,shouldOpenAddPropertyDropdown));
          }
          dispatch(setFilterBarVisible(true))
          resetCategorySelect()
          activityCallListApi()
          onVisibleChange(false)
          return;
    }
    dispatch(trackPageViews(null, {
      eventName: 'create_filter',
      track_type: 'event',
      eventProperty: removeValuesFromFilters(rawNewFilter),
      pageName: parentType
    }));

    // Filter out multi_id properties before sending to API (if present)
    const newFilter = rawNewFilter.map(filter => {
      if (!filter.multi_id_filter && !filter.multi_id_count) {
        return filter;
      }
      // eslint-disable-next-line camelcase, @typescript-eslint/no-unused-vars
      const { multi_id_filter, multi_id_count, ...cleanFilter } = filter;
      return cleanFilter;
    });

    dispatch(setFilterBarVisible(true))
    resetCategorySelect()
    onVisibleChange(false)
    dispatch(fetchPlanHatApi({ action: `Filtered ${mapPageNames[parentType]} page`, info: { 'Filtered names': JSON.stringify(newFilter) }}))
    callListApi([...filterSegment, ...newFilter])
  }, [callListApi, dispatch, filterSegment, onVisibleChange, parentType, resetCategorySelect, activityCallListApi])
  
  const handleAPICallfromFirstLevel = useCallback(
    (filterAttribute) => {
      const type = filterAttribute.includes('event') ? 'event' : 'gesture';
      const isSmartEvent = filterAttribute.includes('smart');
      const attributeType = filterAttribute.includes('doesnot');
      const filterPayload = [{
          attribute: isSmartEvent ? `smart_${type}_count_per_screen_visit`: `${type}_count_per_screen_visit`,
          operator: attributeType ? 'equal' : 'greater_or_equal' ,
          value: attributeType ? 0 : 1,
          filters: type === 'event' ?
          [{
            attribute: isSmartEvent ? 'nce_name' : 'event_name',
            operator: "in",
            value: []
          }] : [],
      }]
      dispatch(setAttributeProps(filterAttribute));
      dispatch(setFilterBarVisible(true))
      callApi(filterPayload);
    }
  , [callApi, dispatch])

  const handleMenuActivity = useCallback(({
    key: attributeKey,
    dropdownId,
    dropdownAttribute,
    dropdownCategory,
    title,
    eventType,
  }) => {
    let attributeProps; let selectedKeyNew = selectedKey;
    const isActivityFilterAttribute = hasActivityFilter([{attribute:dropdownAttribute}])
    if (dropdownId === 'isFirstLevel') {
      setTabContentWidth(470)
      setClickedDropdownLevel('firstLevel');
      setSelectedKey(attributeKey);
      const implementActivityFilter = shouldImplementActivityFilter(
        attributeKey,
        dropdownCategory,
        dropdownAttribute,
        getAvailableActivityFilterList,
        dropdownId,
        isUserV2
        )
      setActiveEventTab('codedEvents')
      implementActivityFilter &&  callApi([],implementActivityFilter);
      if (filterStrategyIncluded.includes(attributeKey)) {
        attributeProps = additionalFilters[attributeKey];
        dispatch(setAttributeProps(attributeProps));
      }
    }
    if (dropdownId === 'isSecondLevel') {
      setTabContentWidth(470)
      if(EventOrGestureFilter.includes(title)) { 
        const filterJson = title.includes('event') ? eventFiltering : gestures;
        const filterAttribute = filterJson.find(type => type?.title === title )?.attribute
        handleAPICallfromFirstLevel(filterAttribute);
        return 
      }

      setClickedDropdownLevel('secondLevel');
      const isCrashedSession = isUserV2 ? ['session_crashed'].includes(dropdownAttribute) : false;
      const isRageUIEvents = ['UI Freeze', 'rageTap'].includes(dropdownAttribute);
      if (dropdownCategory) selectedKeyNew = dropdownCategory;
    
      let indexAttribute = findIndex(mappedAllFilters, { attribute: dropdownAttribute });

      const { default: defaultPayload } = mappedAllFilters[indexAttribute] || {};
      const shouldCallApiProperties = categoriesExtra.indexOf(selectedKeyNew) > -1 || isRageUIEvents || isActivityFilterAttribute || isCrashedSession
      if (shouldCallApiProperties) {
        const isCategoryLabelsEvents = ['User Labels', 'Session Labels', 'Events', 'SmartEvents', 'Cohorts', "Tara's watchlist batches"].includes(dropdownCategory)

        const shouldCallApi = isCategoryLabelsEvents || isRageUIEvents || isActivityFilterAttribute || isCrashedSession
        if (shouldCallApi) {
          let filterPayload;
          if (isRageUIEvents || isCrashedSession) filterPayload = defaultPayload;
          else if(!isActivityFilterAttribute) {
            if (selectedKey === 'Events' || selectedKey === 'All') {
              if (['smartEvents'].includes(eventType)) { 
                selectedKeyNew = 'SmartEvents'
              }
            }
            const { table } = clone(additionalFilters[selectedKeyNew]);
            const labelType = getLabelTypeFromValue(dropdownAttribute);
            const getLabelAttribute = () => {
              if (labelType === 'user') return 'user_custom_label';
              return 'custom_label';
            }
            const labelAttribute = getLabelAttribute();
            const attribute = ( () => {
              switch( selectedKeyNew ) {
                case 'Events':
                  return 'event_name';
                case 'SmartEvents':
                  return 'nce_name';
                case 'Cohorts':
                  return 'uxcamuserid_cohort'
                case "Tara's watchlist batches":
                  return 'batch_id'
                default:
                  return labelAttribute;
              }
            } )()
            filterPayload = [
              {
                attribute,
                operator: ['Events', 'SmartEvents', 'Cohorts', "Tara's watchlist batches"].includes(selectedKeyNew) ? 'in' : 'has_any',
                value: [dropdownAttribute],
                table,
              },
            ];
          }
          const implementActivityFilter = shouldImplementActivityFilter(
            selectedKeyNew,
            dropdownCategory,
            dropdownAttribute,
            getAvailableActivityFilterList,
            dropdownId,
            isUserV2
            )
        callApi(filterPayload,implementActivityFilter);
        return;
        }
        attributeProps = clone(additionalFilters[selectedKeyNew]);
        if ( selectedKeyNew === 'Custom user properties' || selectedKeyNew === 'Event properties' || selectedKeyNew === 'Landing UTM' || selectedKeyNew === 'Screen visit properties' || selectedKeyNew === 'Custom screen properties' || selectedKeyNew === 'Initial landing UTM' ) attributeProps.propertyName = dropdownAttribute;
      } else if (dropdownOptionsByType[selectedKey]) {
        // opens the third level dropdown
        setTabContentWidth(720)
        indexAttribute = findLastIndex(dropdownOptionsByType[selectedKey], { attribute: dropdownAttribute });
        attributeProps = dropdownOptionsByType[selectedKey][indexAttribute];
      }
      dispatch(setAttributeProps(attributeProps));
    }
  }, [selectedKey, setTabContentWidth, setActiveEventTab, dispatch, mappedAllFilters, dropdownOptionsByType, handleAPICallfromFirstLevel, isUserV2, callApi, getLabelTypeFromValue, getAvailableActivityFilterList]);

  const handleMenuClick = useCallback(
    (itemProps) => {
    const { domEvent, key, item } = itemProps
    domEvent.stopPropagation()
    const locked = !advancedFiltersAllowed && key !== 'tmp_key-1' && !allowedCategoriesInFreePlan.includes(key)

    if (typeof key === 'undefined') return
    if ( locked ) {
      setFiltersLockedModal( true )
      return
    }
    handleMenuActivity({ key, ...itemProps.item.props, eventType: item?.props?.eventType })
  }, [handleMenuActivity, allowedCategoriesInFreePlan, setFiltersLockedModal, advancedFiltersAllowed])


  const handleOperatorSelect = useCallback((index = 0, customOperatorType) => {
    const { type: operatorType } = selectedAttributeProps || {}
    const operatorTypeEither = customOperatorType || operatorType
    if (operatorTypeEither && operator[operatorTypeEither]) {
      const operatorTake =
        operator[operatorTypeEither] &&
        operator[operatorTypeEither][index];
      setSelectedOperator(operatorTake);
      return operatorTake
    }
    return customOperatorType
  }, [selectedAttributeProps])

  const handleAttributeChange = useCallback(
    async () => {
    if (selectedAttributeProps?.attribute) {
      resetFieldsAndCallApi({
        isSearchable: handleOperatorSelect()?.isSearchable,
      })
    } else if (filterStrategyIncluded.includes(selectedKey)) {
      resetFieldsAndCallApi({
        isSearchable: true,
      })
    }
  }, [handleOperatorSelect, resetFieldsAndCallApi, selectedAttributeProps?.attribute, selectedKey])

  useEffect(() => {
   const timer = setTimeout(() => {
      inputRef?.current?.focus()
    }, 0)
    return () => { clearTimeout(timer)}
  }, [selectedKey])
  useEffect(() => {
    handleAttributeChange()
  }, [
    // selectedKey,
    selectedAttributeProps?.attribute, 
    selectedAttributeProps?.propertyName,
  ])
    const hasWideWidth = useMemo(() => {
      return webScreenAttribtues.includes(selectedAttributeProps?.attribute)
    }, [selectedAttributeProps?.attribute])

  const showThirdColumn = React.useMemo( () => 
    selectedAttributeProps?.attribute && clickedDropdownLevel === 'secondLevel' && ![ 'Cohorts', "Tara's watchlist batches", 'User Labels', 'Session Labels', 'Events' ].includes( selectedKey ),
  [ clickedDropdownLevel, selectedAttributeProps, selectedKey ] )

  return (
    <MenuStyled key='mega-filter' {...menuProps} onClick={handleMenuClick} hasWideWidth={hasWideWidth}>
      <ColumnWrapper data-name="column-wrapper" data-three-columns={ showThirdColumn }>
        { showMegaQuickFilter && (
          <>
            <MegaQuickFilters onVisibleChange={ onVisibleChange } />
            <Divider />
          </>
        ) }
        <RowWrapper>
          <InitialMenu
            categories={categories}
            selectedKey={selectedKey}
            segmentType={segmentType}
            parentType={parentType}
          />
          <SecondLevelMenu
            dropdownOptions={dropdownOptionsByType}
            selectedKey={selectedKey}
            pageType={pageType}
            segmentType={segmentType}
            selectedAttributeProps={selectedAttributeProps}
          />
          { showThirdColumn && (
              <ThirdLevelMenu
                callApi={callApi}
                onVisibleChange={onVisibleChange}
                resetCategorySelect={resetCategorySelect}
                pageType={pageType}
                handleOperatorSelect={handleOperatorSelect}
                selectedOperator={selectedOperator}
              />
            )}
        </RowWrapper>
      </ColumnWrapper>
    </MenuStyled>
)
})
export default withContextProps(MainMenu)
