/* eslint-disable @typescript-eslint/no-explicit-any */
import { capitalizeEnvString } from "components/features/setting/AppSetting/NewRecordingSection/DebounceSearch";
import { allFilters } from "../../../data-structures-v2";
import { StepType } from "../FunnelSequence/utils"
import { keyLabelMap } from "../../../utils";

export type OperatorType = 'less' | 'greater' | 'in' | 'not_in' | 'not_contains' | 'contains' | 'between';

interface FilterProps {
    attribute: string,
    operator: OperatorType,
    value: string[]
	property: {
		name: string,
		operator:OperatorType,
		value: string[]
	}
	occurrence_number?: {
		operator: string,
		value: string | number | (string | number)[]
	}
}

export interface StepProps {
    table: string,
    filters: FilterProps
    time_frame_sec: string
}

export interface IConversionStepFilter {
    attribute: 'action_sequence_conversion',
    table: 'session' | 'appuser',
    value: {
        initial_event: StepProps,
        conversion_events: StepProps[]
		conversion_analytics_filters: {
			attribute: string,
			operator: OperatorType,
			value: any,
			table: string,
			property_name?: string,
		}[]
    }
}
const DevicePlatformMap: Record<string, string> = {
    '1': 'Android',
    '2': 'iOS',
}

export const mapConversionFilterStep = ( step: IConversionStepFilter['value']['conversion_events'][0], renamedScreens: Record<string, string> ) => {
	if ( !step.filters || (step.filters.attribute === "previous_screen_name" && step.filters.value[0] === 'Launch') ) {
		return {
			type: StepType.APP_LAUNCH,
			name: null,
		}
	}

	const { filters } = step

	if ( filters && filters?.attribute === 'screen_name' ) {
		const {
			value: screenName,
			property,
			occurrence_number: occurrenceNumber,
		} = filters

		return {
			type: StepType.SCREEN,
			name: screenName?.map((val: string | number) => renamedScreens[ val ] || val),
			property: property?.name,
			operator: property?.operator,
			value: property?.value,
			occurrenceNumber,
		}
	}

	if ( filters && filters.attribute === 'event_name' ) {
		const {
			value: eventName,
			property,
			occurrence_number: occurrenceNumber,
		} = filters

		return {
			type: StepType.EVENT,
			name: eventName,
			property: property?.name,
			operator: property?.operator,
			value: property?.value,
			occurrenceNumber,
		}
	}

	if ( filters && filters.attribute === 'nce_name' ) {
		const {
			value: eventName,
			property,
			occurrence_number: occurrenceNumber,
		} = filters

		return {
			type: StepType.NO_CODE_EVENT,
			name: eventName,
			property: property?.name,
			operator: property?.operator,
			value: property?.value,
			occurrenceNumber,
		}
	}
	
	const {
		attribute,
		value,
	} = step.filters

	let type: StepType;

	if (attribute === 'event_name') {
		type = StepType.EVENT;
	} else if (attribute === 'nce_name') {
		type = StepType.NO_CODE_EVENT;
	} else {
		type = StepType.SCREEN;
	}

	if ( type === StepType.SCREEN ) {
		const screenName = value?.map((val) => renamedScreens[ val ] || val)

		return {
			type,
			name: screenName,
		}
	}

	return {
		type,
		name: value,
	}
}

export const mapConversionFilter = (
	filters: IConversionStepFilter['value']['conversion_analytics_filters'],
	renamedScreens: Record<string, string>,
	batchData: { batch_id: string; batch_name: string }[] = []
) => filters.map((filter) => {
	const { attribute, operator, value, table, property_name: propertyName } = filter;

	if (propertyName) {
		const mappedPropertyName = keyLabelMap[propertyName as keyof typeof keyLabelMap] ?? propertyName
		return { attribute: mappedPropertyName, operator, value, table };
	}

	const attributeMappings: Record<string, string> = {
		user_alias: 'User alias',
		user_identity: keyLabelMap['kUXCam_UserIdentity'],
		screen_name: 'Visited screen',
		session_recordedon: 'Recorded time',
		device_platform: 'Device platform',
		session_recorded_weekday: 'Day of the week',
		alias: 'Alias',
		kUXCam_UserIdentity: keyLabelMap['kUXCam_UserIdentity'],
		environment: 'Environment',
        session_user_experience: 'App familiarity',
        upload_time: 'Upload time'
	};

	if (attribute in attributeMappings) {
		if (attribute === 'screen_name') {
			const screenName = Array.isArray(value) ? value?.map((val: string | number) => renamedScreens[val] || val) : [renamedScreens[value] || value];
			return { attribute: attributeMappings[attribute], operator, value: screenName, table };
		} 
		if (attribute === 'device_platform') {
			if ( !Array.isArray(value) ){
                if( (typeof value === 'string' || typeof value === 'number') && value in DevicePlatformMap ) {
                    return { attribute: attributeMappings[attribute], operator, value: DevicePlatformMap[value], table };
                }
				return { attribute: attributeMappings[attribute], operator, value, table };
			}
			const platform = value?.map((val: string) => DevicePlatformMap[val] || val);
			return { attribute: attributeMappings[attribute], operator, value: platform, table };
		}
		if (attribute === 'session_recorded_weekday'){
			return { attribute: attributeMappings[attribute], operator, value: value?.map((val: string) => val.charAt(0).toUpperCase() + val.slice(1)), table };
		}
		if(attribute === 'environment'){
			return { attribute: attributeMappings[attribute], operator, value: value?.map((val: string) => capitalizeEnvString(val)), table };
		}
		return { attribute: attributeMappings[attribute], operator, value, table };
	}

	const currentFilterMap = Object.values(allFilters).flatMap(obj => Object.values(obj).flat());
	const currentAttributeMap = currentFilterMap.find((item) => item.attribute === attribute);

	const mappedValue = attribute === 'batch_id' && Array.isArray(value)
		? value.map((val: string) => {
			const match = batchData.find((b) => b.batch_id === val)
			return match ? match.batch_name : val
		})
		: value

	return {
		attribute: currentAttributeMap?.title || attribute,
		operator,
		value: mappedValue,
		table,
	};
});
  