import CommonApi from "services/commonApi";
import { useQuery } from "react-query";
import { useSelector } from "react-redux";

const useEventLimitStatus = () => {
  const { orgId } = useSelector(state => state.currentOrgReducer)
  const getEventLimit = async () => CommonApi.getEventLimitStatus(orgId);
  const { isLoading, isFetching, data } = useQuery(['event-limit-status', orgId], () => getEventLimit(), {
    retry: false,
    enabled: orgId !== undefined
  });

  if (!isLoading || !isFetching) {
    return data?.data;
  }
  return null;
}

export default useEventLimitStatus;