import { OperatorType } from "../ConversionSequence/utils"
import OperatorJSON from "../../../data-structures-v2/operator.json"
/* eslint-disable no-shadow */
export interface IFunnelStepFilter {
	attribute: 'action_sequence' | 'action_sequence_ordered', // unordered and ordered
	value: {
		completed_steps: {
			fb_l?: {
				attribute: string
				table: string,
				operator: 'less' | 'greater' | 'in' | 'not_in' | 'not_contains' | 'contains' | 'equal' | 'between' | 'label_map',
				value: string[]
				json_field?: string[]
				property_name?: string[]
			}[]
		}[],
		conversion_filter: {
			attribute: 'session_period_second' | 'session_period_minute' | 'session_period_hour' | 'session_period_day' | 'session_period_week',
			value: number,
			operator: 'less_or_equal',			
		}[],
		drop_off_step: {
			fb_l?: {
				attribute: string
				table: string,
				operator: 'less' | 'greater' | 'in' | 'not_in' | 'not_contains' | 'contains',
				value: string[]
				json_field?: string[]
				property_name?: string[]
			}[]
		},
        funnel_filter:{
            attribute: string,
			operator: OperatorType,
			value: any,
			table: string,
			property_name?: string,
        }[],
        grouping_funnel_filter: {
            attribute: string,
            operator: OperatorType,
            value: any,
            table: string,
            property_name?: string,
        }
	},
}

export const mapOperator = ( operator: NonNullable<IFunnelStepFilter[ 'value' ][ 'completed_steps' ][ 0 ]['fb_l']>[0]['operator' ] ) => {
    const operatorsArray = Object.values(OperatorJSON).flat().map(item => ({ ...item }));

    const found = operatorsArray.find((item) =>
        item.attribute === operator
    );

    return found?.title || '';
}

const occurrenceOperatorLabels: Record<string, string> = {
	in: 'equals',
	not_in: 'not equals',
	greater: 'greater than',
	greater_or_equal: 'greater or equals',
	less: 'less than',
	less_or_equal: 'less or equals',
}

export const mapOccurrenceOperator = (operator: string): string =>
	occurrenceOperatorLabels[operator] || operator

export enum StepType {
	APP_LAUNCH,
	EVENT,
	SCREEN,
	NO_CODE_EVENT,
}

export const mapFunnelFilterStep = ( step: IFunnelStepFilter['value']['completed_steps'][0] | IFunnelStepFilter['value']['drop_off_step'], renamedScreens: Record<string, string> ) => {
	if ( !step.fb_l ) {
		return {
			type: StepType.APP_LAUNCH,
			name: null,
		}
	}

	const filters = step.fb_l
	if ( filters.length > 1 && filters[ 0 ].attribute === 'screen_name' ) {
		const {
			value: screenName,
		} = filters[ 0 ]

		const {
			value,
			operator,
			property_name: jsonField = [],
		} = filters[ 1 ]

		return {
			type: StepType.SCREEN,
			name: screenName?.map((val) => renamedScreens[ val ] || val),
			property: jsonField,
			operator,
			value
		}
	}

	if ( filters.length > 1 && filters[ 0 ].attribute === 'event_name' ) {
		const {
			value: eventName,
		} = filters[ 0 ]

		const {
			value,
			operator,
			json_field: jsonField = [],
		} = filters[ 1 ]

		return {
			type: StepType.EVENT,
			name: eventName,
			property: jsonField,
			operator,
			value
		}
	}

	if ( filters.length > 1 && filters[ 0 ].attribute === 'nce_name' ) {
		const {
			value: eventName,
		} = filters[ 0 ]

		const {
			value,
			operator,
			json_field: jsonField = [],
		} = filters[ 1 ]

		return {
			type: StepType.NO_CODE_EVENT,
			name: eventName,
			property: jsonField,
			operator,
			value
		}
	}
	
	const {
		attribute,
		value,
	} = step.fb_l[ 0 ]

	let type: StepType;

	if (attribute === 'event_name') {
		type = StepType.EVENT;
	} else if (attribute === 'nce_name') {
		type = StepType.NO_CODE_EVENT;
	} else {
		type = StepType.SCREEN;
	}

	if ( type === StepType.SCREEN ) {
		const screenName = value?.map((val) => renamedScreens[ val ] || val)

		return {
			type,
			name: screenName,
		}
	}

	return {
		type,
		name: value,
	}
}