import { Button, Modal } from 'antd';
import styled from 'styled-components';
import React, { useCallback } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import type { IReduxState } from 'types/reduxStateTypes';
import Router from 'next/router';
import { trackPageViews } from 'redux/actions/trackingReport';
import { cohortFilterType, useMassUserIdFilterContext } from './MassUserIdFilterContext';

const StyledModal = styled(Modal)`
  .ant-modal-content {
    border-radius: 8px;
    padding: 32px;
    text-align: left;
  }
  .ant-modal-header {
    border-bottom: none;
    padding: 0;
  }
  .ant-modal-title {
      font-size: 18px;
      font-style: normal;
      color: #161e35;
      font-weight: 500;
      line-height: 24px; /* 133.333% */
      margin-bottom: 16px;
  }
  .ant-modal-body {
    padding: 0;
  }
  .ant-modal-footer {
    border-top: none;
    padding: 0;
  }
`;

const Description = styled.div`
    padding: 0;
    color: #454b5d;
    font-size: 12px;
    font-style: normal;
    font-weight: 400;
    line-height: 24px; /* 200% */
`;
const Highlight = styled.span`
  font-weight: 700;
`;

const NewButton = styled(Button)`
  border: none !important;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  box-shadow: none !important;
  color: #5D97FF !important;
  padding: 4px 29px;
`

const NewButtonPrimary = styled(NewButton)`
  height: 32px;
  padding: 4px 29px;
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
  line-height: 24px;
  > span {
    color: #ffffff !important;
  }
  &:hover {
    background-color: #4a79cb;
  }
  &:disabled > span {
    color: #828282 !important;
  }
`
const PartialCohortSavedModal: React.FC<{ onSave?: (cohortFilter: cohortFilterType) => void }> = ({ onSave }) => {
  const {
    showPartialCohortSaved,
    setShowPartialCohortSaved,
    totalIds,
    addedIds,
    cohortFilter
  } = useMassUserIdFilterContext();
  const notFoundIds = totalIds - addedIds;

  const { parentType, appId } = useSelector((state: IReduxState) => state.urlReducer)
const dispatch = useDispatch()
  
  const onApplyAsFilter = useCallback(() => {
    setShowPartialCohortSaved(false);
    onSave?.(cohortFilter);
    dispatch(trackPageViews(null, { 
            eventName: 'wa_create_mass_id_filter',
             eventProperty: {
                mass_id_count: cohortFilter[0]?.value.length 
             }
          }))
  }, [setShowPartialCohortSaved, onSave, cohortFilter, dispatch]);

  const onViewCohort = useCallback(() => {
    setShowPartialCohortSaved(false);
    const query = `appId=${appId}&parentType=retention`;
    const urlCohort = `/app/${appId}/retention/cohorts#manage?redirect_from_filter=${parentType}`;
    Router.push(`/integration?${query}`, urlCohort);
  }, [setShowPartialCohortSaved, appId, parentType]);


  return (
    <StyledModal
      visible={showPartialCohortSaved}
      onCancel={() => setShowPartialCohortSaved(false)}
      footer={null}
      centered
      width={570}
      closable={false}
      title={<span>Cohort saved</span>}
    >
      <Description>
        Cohort <Highlight>Returning customers</Highlight> has been saved
        successfully.
        <br />
        Of the <Highlight>{totalIds.toLocaleString()}</Highlight> user IDs
        provided, <Highlight>{addedIds.toLocaleString()}</Highlight> were added
        to the cohort, the remaining{' '}
        <Highlight>{notFoundIds.toLocaleString()}</Highlight> were not found in
        the UXCam database. You can continue to apply this cohort as a filter.
      </Description>
      <div
        style={{
          display: 'flex',
          justifyContent: 'flex-end',
          gap: 16,
          marginTop: 32,
        }}
      >
        <NewButton onClick={onViewCohort}>
          View cohort
        </NewButton>
        <NewButtonPrimary
          type="primary"
          onClick={onApplyAsFilter}
        >
          Apply as filter
        </NewButtonPrimary>
      </div>
    </StyledModal>
  );
};

export default PartialCohortSavedModal;
