import React, { memo, useMemo, useState } from "react";
import { Dropdown, Form, Menu } from 'antd';
import { PlusCircleOutlined } from "@ant-design/icons";
import { isEmpty } from 'lodash';

import useDebounce from 'hooks/useDebounce';
import { useIsAppType } from 'hooks/useIsAppType';
import { LoaderMenuItem, MenuItemGroupWrapper } from "components/shared/GlobalFilter/components/CommonComponentsV2";
import { EventNameIcon, HashTagSvg, RageGestureSvg, TimerGestureSvg } from "components/shared/GlobalFilter/components/FilterSvgs";
import { rollbar } from "components/common/rollbar";
import { AddConditionStyle, MenuItemWrap, NotFoundMessage, StyledSpace } from "../Style";
import GestureAttibute from './GestureAttribute.json'

export const GestureTypesEnum = (isWeb = false) => (
  {
    gesture_type: 'Gesture type',
    viewname: 'UI element name',
    viewid: isWeb ? 'Element ID' : 'UI element ID',
    viewtype: 'UI element type',
    x_bin: 'X position',
    y_bin: 'Y position',
    is_rage: 'rage tap',
    is_responsive: isWeb ? 'dead click' : 'unresponsive',
    is_first_gesture: 'first gesture in screen',
    is_first_screen: 'first gesture in session',
    screen_gesture_count: 'Gesture number in screen',
    is_last_gesture: 'last gesture in screen',
    is_last_screen: 'last gesture in session',
    gesture_time_on_screenvisit: 'Time until gesture'
  }
)

const handleIconType = (iconType) => {
  switch (iconType) {
    case 'gesture':
      return <EventNameIcon />

    case 'boolean':
      return <RageGestureSvg />

    case 'timer':
      return <TimerGestureSvg />

    default:
      return <HashTagSvg />
  }
}

const GestureAttributes = ({ id, form, name, addProperty }) => {
  // from form data 
  const formData = Form.useWatch('gestureProperties', form);
  const formDataIndex = name[1];
  const formProperty = formData?.[formDataIndex]?.['attribute'] ?? '';

  // app type detection
  const isWebSdk = useIsAppType('web');

  // local state
  const [visible, setVisibleChange] = useState(false);
  const [searchInput, setSearchInput] = useState('');
  const debouncedSearchValue = useDebounce(searchInput, 500);

  // Filter attributes based on app type
  const filteredAttributes = useMemo(() => {
    return GestureAttibute.filter(attr => {
      if (isWebSdk) {
        return attr.features.includes('websdk');
      }
      return attr.features.includes('default');
    });
  }, [isWebSdk]);

  const remoteData = useMemo(() => {
    const baseData = filteredAttributes;
    const filteredData = baseData.filter(data => data?.title?.toLowerCase()?.includes(debouncedSearchValue));
    return debouncedSearchValue ? filteredData : baseData;
  }, [debouncedSearchValue, filteredAttributes])

  const renderView = useMemo(() => remoteData?.length ? remoteData.map((data) => <MenuItemWrap
    key={data?.attribute}
    icon={handleIconType(data.icon)}>{data.title}</MenuItemWrap>) : <NotFoundMessage>No matching gesture properties found.</NotFoundMessage>, [remoteData]);

  const onVisibleChange = () => {
    setVisibleChange(!visible)
  }

  const gestureProperties = ['gesture_type', 'viewname', 'viewid', 'viewtype'];

  const handleMenuPropertyClick = (data) => {
    form.setFields([{ name, value: data.key }]);

    form.setFields([
      {
        name: ['gestureProperties', `${formDataIndex}`, 'value'],
        value: undefined,
      }
    ]);
    form.setFields([
      {
        name: ['gestureProperties', `${formDataIndex}`, 'operator'],
        // value: data?.key === 'gesture_type' ? 'in' : 'equal',
        value: gestureProperties.includes(data?.key) ? 'in' : 'equal',
      }
    ]);
    onVisibleChange(false);
  }

  const propertiesMenu =
    <Menu
      selectedKeys={[formProperty]}
      onClick={handleMenuPropertyClick}
    >
      <LoaderMenuItem
        spinning={false}
        style={{ left: 'unset' }}>
        <MenuItemGroupWrapper
          placeholder='Search gesture attribute'
          onChange={(e) => setSearchInput(e.target.value)}
        >
          {
            renderView
          }
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
    </Menu>
  return (
    <Dropdown
      overlay={propertiesMenu}
      overlayClassName='properties-segment-menu gesture-segment'
      onVisibleChange={async (v) => {
        if (id === 'property') {
          onVisibleChange(v);
          return;
        }
        const values = await form.validateFields();
        if (values) {
          onVisibleChange(v)
        }
      }}
      visible={visible}
      trigger={['click']}
    >
      {id === 'property' ?
        <span className='filter-spacing'>
          <a href="#!" onClick={(e) => e.preventDefault()}><StyledSpace isBold={formProperty}> {GestureTypesEnum(isWebSdk)[formProperty] || formProperty} </StyledSpace></a>
        </span>
        :
        <AddConditionStyle onClick={async () => {
          try {
            const values = await form.validateFields();
            if (values && !isEmpty(values.gestureProperties[formDataIndex])) addProperty();
          } catch (errorInfo) {
            rollbar.log('Failed:', errorInfo);
          }

        }} icon={<PlusCircleOutlined />}>
          Add condition
        </AddConditionStyle>}
    </Dropdown>
  )
}

export default memo(GestureAttributes);