import React from 'react'
import { useSelector, useDispatch } from 'react-redux'
import styled from 'styled-components'
import { StylesProvider } from 'uxcam-frontend-components'
import { useIsAppType } from 'hooks/useIsAppType'
import { IReduxState, IStatBoxes } from 'types/reduxStateTypes'
import { handleValuesByName } from 'redux/actions/sessionStatistics'
import useSessionAnalyticsAPI from 'components/features/sessions/SessionStatistics/hooks/useSessionAnalyticsAPI'
import { mapGraphDToAttribute } from 'Utils/helpers/SessionUtils'
import { graphTypeObj } from 'components/common/Customary/graphType'
import { fetchPlanHatApi } from 'redux/actions/common'
import OverviewBox from './OverviewBox'
import { mobileDummyBoxes, webDummyBoxes } from './dummyData'
import { useStatsBoxData } from './hooks/useStatisticBoxes'

const BoxesContainer = styled.div`
  display: flex;
  width: 100%;
  gap: 16px;
  overflow: auto;
`

const getData = ( data: IStatBoxes, isWebApp: boolean ) => {
  if ( !isWebApp ) {
    return {
      'Sessions': {
        Total: data?.Sessions?.count,
        'Avg. duration': data?.[ 'Time in App' ]?.Average
      },
      'Users': {
        Total: data?.Users?.Total,
        New: data?.Users?.New
      },
      'Rage taps': {
        Frequency: data?.[ 'Rage Taps' ]?.Frequency,
      },
      'Crashes': {
        Frequency: data?.[ 'Crashes' ]?.Frequency,
      },
      'UI freeze': {
        Frequency: data?.[ 'UI Freeze' ]?.Frequency,
      },
    }
  }

  return {
    'Sessions': {
      Total: data?.Sessions?.count,
      'Avg. duration': data?.[ 'Time in App' ]?.Average
    },
    'Users': {
      Total: data?.Users?.Total,
      New: data?.Users?.New
    },
    'Rage taps': {
      Frequency: data?.[ 'Rage Taps' ]?.Frequency,
    },
    'Dead click': {
      Frequency: data?.[ 'Dead Clicks' ]?.Frequency,
    },
    'Page refresh': {
      Frequency: data?.[ 'Page Refresh' ]?.Frequency,
    },
  }
}

const statBoxKeyMap: Record<string, Record<string, { mainKey: string; attrKey: string }>> = {
  'Sessions': {
    'Total': { mainKey: 'Sessions', attrKey: 'count' },
    'Avg. duration': { mainKey: 'Time in App', attrKey: 'Average' },
  },
  'Users': {
    'Total': { mainKey: 'Users', attrKey: 'Total' },
    'New': { mainKey: 'Users', attrKey: 'New' },
  },
  'Rage taps': {
    'Frequency': { mainKey: 'Rage Taps', attrKey: 'Frequency' },
  },
  'Crashes': {
    'Frequency': { mainKey: 'Crashes', attrKey: 'Frequency' },
  },
  'UI freeze': {
    'Frequency': { mainKey: 'UI Freeze', attrKey: 'Frequency' },
  },
  'Dead click': {
    'Frequency': { mainKey: 'Dead Clicks', attrKey: 'Frequency' },
  },
  'Page refresh': {
    'Frequency': { mainKey: 'Page Refresh', attrKey: 'Frequency' },
  },
}

const NewOverviewBoxes = () => {
  const dispatch = useDispatch()
  const isWebApp = useIsAppType( 'web' )
  const { callGraphApi } = useSessionAnalyticsAPI()

  const {
    currentAppReducer: {
      _id: appID
    },
    appFilter: {
      dateSegment,
      session: {
        segment: sessionSegment
      }
    },
    sessionStatisticsReducer: {
      selectedBox,
      selectedTab,
      graphSelectedVal,
    }
  } = useSelector( ( state: IReduxState ) => state )

  const isAnalyticsPage = selectedTab === 'aiSessionStatistics'

  const payload = React.useMemo( () => ( {
    appid: appID,
    table: 'session',
    filters: [ ...sessionSegment ],
    date_range: { ...dateSegment }
  } ), [ appID, sessionSegment, dateSegment ] )

  const { data: statBoxesData, isFetching } = useStatsBoxData( payload )

  const conditionalData = React.useMemo( () => {
    if ( !statBoxesData?.boxes || isFetching ) {
      return isWebApp ? webDummyBoxes : mobileDummyBoxes
    }

    return getData( statBoxesData.boxes, isWebApp )
  }, [ isWebApp, statBoxesData, isFetching ] )

  const boxes = statBoxesData?.boxes

  const handleSubBoxClick = React.useCallback( ( category: string, subCategory: string ) => {
    const mapping = statBoxKeyMap[ category ]?.[ subCategory ]
    if ( !mapping || !boxes ) return

    const { mainKey, attrKey } = mapping
    const boxData = boxes[ mainKey ]?.[ attrKey ]

    if ( !boxData?.agg_l?.[0] ) return

    const newSelectedBox = {
      attrOfSmallBox: attrKey,
      mainKey,
      tooltip: boxData?.tooltip_info,
      graph_info: boxData?.graph_name,
      graph_type: ( graphSelectedVal as Record<string, string> )?.display,
    }
    dispatch( handleValuesByName( { dropName: 'selectedBox', data: newSelectedBox } ) )

    const graphDisplayVal = newSelectedBox.graph_type as keyof typeof mapGraphDToAttribute
    const graphArr = mapGraphDToAttribute[ graphDisplayVal ]
    if ( graphArr ) {
      dispatch( handleValuesByName( { dropName: 'series_plot_options', data: graphTypeObj[ graphArr as keyof typeof graphTypeObj ] } ) )
    }
    dispatch( handleValuesByName( { dropName: 'aggregation_list', data: boxData.agg_l[0] } ) )

    callGraphApi( { agg_list: boxData.agg_l[0] } )

    dispatch( fetchPlanHatApi( {
      action: 'Metric checked on session analytics',
      info: {
        'Metric type': mainKey,
        description: 'when they click on one of the boxes at the top, e.g. users',
      },
    } ) )
  }, [ boxes, graphSelectedVal, dispatch, callGraphApi ] )

  return (
    <StylesProvider>
      <BoxesContainer>
        { Object.entries( conditionalData )?.map( data => {
          const [ category ] = data
          return (
            <OverviewBox
              key={ category }
              data={ data }
              hideTooltip={ !statBoxesData?.boxes }
              onSubBoxClick={ boxes && isAnalyticsPage ? handleSubBoxClick : undefined }
              selectedBox={ isAnalyticsPage ? selectedBox : undefined }
              statBoxKeyMapping={ statBoxKeyMap[ category ] }
            />
          )
        } ) }
      </BoxesContainer>
    </StylesProvider>
  )
}
export default NewOverviewBoxes
