import React, { useEffect } from 'react'
import { useSelector, useDispatch } from 'react-redux'
import { Layout, Menu } from 'antd'
import clone from 'lodash/clone'
import some from 'lodash/some'

import { useNoCodeEventsContext } from 'components/features/sessions/Context/NoCodeEventsContext'
import EventLimitStatusModal from 'Utils/helpers/EventLimitStatusModal'
import EventDropdown from 'components/features/events/EventTable/EventDropdown'
import { resetMegaFilterReduxStates, setFilterBarVisible } from 'redux/actions/megaFilter'
import EventNameDropdown from 'components/features/events/EventTable/EventNameDropdown'
import useEventLimitStatus from 'hooks/useEventLimitAPI'
import styled from 'styled-components'
import FiltersLockedModal from 'components/shared/GlobalFilter/components/MegaFilterDropdownV2/MainMenu/FiltersLockedModal'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext'
import AIChatToggle from 'components/common/AIAssistant/ChatTab/AIChatToggle'
import { useIsAppType } from 'hooks/useIsAppType'
import { useIsUserV2 } from 'hooks/useUserV2Filter'
import useAppFilter from './useAppFilter'
import FilterCountButton from './FilterCountButton'
import MegaFilterDropdown from './MegaFilterDropdownV2'
import FilterSearch from './FilterSearch'
import ConfigureNotificationsButton from './ConfigureNotificationsButton'
import AlertsButton from './AlertCreateButton'
import { showSegmentList } from './utils'
import UserAndSessionSelection from './UserAndSessionSelection'
import CalendarDateRangePicker from './CalendarDateRangePicker'
import NewSegmentMenu from './SegmentMenu'
import WebScreenSearch from './WebScreenSearch'

export const AIChatToggleLeftWrapper = styled.div`
  margin-right: 16px;
`

export const AIChatToggleRightWrapper = styled.div`
  margin-left: 16px;
`

export const MenuItem = Menu.Item;
export const MenuItemGroup = Menu.ItemGroup;
export const noMatchingFilterMenu = <span className="no-filter-text"> No matching filter </span>
const { Header } = Layout;
const MegaFilter = () => {
  const { pageType, segmentType } = useAppFilter()
  const dispatch = useDispatch();
  const { noCodeEventsFeatureFlag } = useNoCodeEventsContext()
  const { alertsFeatureAllowed, aiSessionFeatureAllowed } = useRestrictionContext()
  const isWebApp = useIsAppType( 'web' );
  const {
    urlReducer: { parentType, appId, screenname },
    selectedSessionReducer: selectedSession,
    selectedUserReducer: selectedUser,
    appFilter
  } = useSelector((state) => state)
  const isTaraEnabled = aiSessionFeatureAllowed
  const showAIToggle = aiSessionFeatureAllowed
  const isScreensListOnly = segmentType === 'screen' && !screenname
  let storeHideEventLimitReached = ''
  try {
    storeHideEventLimitReached = sessionStorage.getItem( 'storeHideEventLimitReached');
  } catch (err) {
    // silent fail
  }
  const filterSegmentCloned = clone(appFilter[segmentType]['segment'])
  const isUserV2 = useIsUserV2()

  const { isMobileEventLimitReached, isWebEventLimitReached } = useEventLimitStatus() || {};
  const hideAlertsParentTypes = ['issues', 'screenFlow', 'screenBurst']

  useEffect(() => {
    dispatch(resetMegaFilterReduxStates())
    return () => dispatch(resetMegaFilterReduxStates())
  }, [parentType, appId]);

  useEffect(() => {
    const hasSequence = some(filterSegmentCloned, { has_sequence: 'true' })
    if(hasSequence) dispatch(setFilterBarVisible(true))
  }, [])
  
  return (
    <Header className="global-menu">
        <div className="global-menu-container">
          <div className="global-left-wrapper">
            {selectedSession.length > 0 || selectedUser.length > 0 ? (
              <UserAndSessionSelection />
            ) : (
              <>
                {pageType === 'event' && (
                  <div className="filter-drop-item event-selector" data-intercom-target="Event Dropdown">
                    { noCodeEventsFeatureFlag ? (
                      <EventDropdown />
                    ) : <EventNameDropdown /> }
                  </div>
                )}
                {isScreensListOnly ? '' : <div className="filter-drop-item" data-intercom-target="Filter">
                  <MegaFilterDropdown id='topLevelFilterBtn'/>
                  <FiltersLockedModal />
                </div>}
                {isScreensListOnly ? '' : <FilterCountButton />}
                {showSegmentList.includes(pageType) && <span data-intercom-target="Segments">
                   <NewSegmentMenu />
                  </span>
                }
                {segmentType !== 'heatmap' && <FilterSearch />}
                { parentType === 'heatmapsList' && isWebApp && <WebScreenSearch /> }
                {/* removed as we won't show it in new design */}
              </>
            )}
          </div>
          <div className="global-right-wrapper">
            <div className="right-filter-wrap">
              {
                !isTaraEnabled && showAIToggle && (
                  <AIChatToggleLeftWrapper>
                    <AIChatToggle />
                  </AIChatToggleLeftWrapper>
                )
              }
              { !hideAlertsParentTypes.includes(parentType) && ( !isWebApp || ( isWebApp && alertsFeatureAllowed ) ) ? <AlertsButton /> : null }
              {segmentType === 'issue' && <ConfigureNotificationsButton />}
              <span data-intercom-target="DateBox">
                {!isUserV2 && <CalendarDateRangePicker />}
              </span>
              {
                isTaraEnabled && showAIToggle && (
                  <AIChatToggleRightWrapper>
                    <AIChatToggle />
                  </AIChatToggleRightWrapper>
                )
              }
            </div>
          </div>
        </div>
        {( isWebEventLimitReached || isMobileEventLimitReached ) && !storeHideEventLimitReached && <EventLimitStatusModal isMobileEventLimitReached={ isMobileEventLimitReached } isWebEventLimitReached={ isWebEventLimitReached }/>}
      </Header>
  );
};
export default MegaFilter
