
const secondsUnitAttributes = {
  sessionLength: 'sessionlength',
  sessionDuration: 'session_duration',
  screenVisitDuration: 'screen_visit_duration',
  userSessionDuration: 'user_session_duration'
}
const addSecondsSuffix = (id, value) => Object.values(secondsUnitAttributes).includes(id) && `second${parseFloat(value) !== 1 ? 's' : '' }`

export {
  secondsUnitAttributes,
  addSecondsSuffix
}
