import React, { memo, useCallback, useEffect, useMemo, useState } from 'react';
import { Button, Checkbox, Dropdown, Form, Menu } from 'antd';
import isArray from 'lodash/isArray';

import {
  LoaderMenuItem,
  MenuItemGroupWrapper,
  bringMissingItemsToTop,
  bringSelectedItemsToTop,
} from 'components/shared/GlobalFilter/components/CommonComponentsV2';
import { GestureViewType, showOverflowItems } from 'components/shared/GlobalFilter/components/utils';
import CellOverflowTooltip from 'Utils/helpers/CellOverflowTooltip';
import { useQuery } from 'react-query';
import FilterApi from 'services/filterApi';
import { useIsAppType } from 'hooks/useIsAppType';
import { useSelector } from 'react-redux';
import { isEmpty, isObject } from 'lodash';
import { useGestureAttribute } from '../hooks/useGestureAttribute';
import {
  MenuButton,
  MenuListItem,
  NotFoundMessage,
  StyledSpace,
} from '../Style';
import InputPropertiesValues from './InputPropertiesValues';

const gestureTypes = ( isWebSdk ) => {
	const allGestures = [
		{
      value: 0,
			title: 'Single tap',
		},
		{
      value: 1,
			title: 'Double tap',
		},
		{
      value: 2,
			title: 'Swipe up',
		},
		{
      value: 3,
			title: 'Swipe down',
		},
		{
      value: 4,
			title: 'Swipe left',
		},
		{
      value: 5,
			title: 'Swipe right',
		},
		{
      value: 6,
			title: 'Long press',
		},
		{
      value: 7,
			title: 'Zoom in',
		},
		{
      value: 8,
			title: 'Zoom out',
		},
		{
      value: 11,
			title: 'Trail',
		},
	];

	if ( isWebSdk ) {
		return allGestures.filter( ( gesture ) => gesture.value !== 7 && gesture.value !== 8 );
	}

	return allGestures;
}

const arrayObj = ['in', 'not_in'];
const acceptsAllInput = ['gesture_type', 'viewtype', 'viewname', 'viewid'];

const GestureValue = ({ form, name, handleApply }) => {
  const {
		currentAppReducer
	} = useSelector( ( state ) => state )

  const { _id: appId } = currentAppReducer;

  const isWebSdk = useIsAppType('web')
  // form data
  const formData = Form.useWatch('gestureProperties', form);
  const formDataIndex = name[1];
  const formPropertyValue = useMemo(
    () => formData?.[formDataIndex]?.['value'] ?? [],
    [formData, formDataIndex]
  );
  const formProperty = useMemo(
    () => formData?.[formDataIndex]?.['attribute'] ?? '',
    [formData, formDataIndex]
  );
  const formOperatorValue = useMemo(
    () => formData?.[formDataIndex]?.['operator'],
    [formData, formDataIndex]
  );

  const shouldCallApi = useMemo(
    () => !['gesture_type', 'viewtype'].includes(formProperty),
    [formProperty]
  );

  const newPropertyValue = useMemo(
    () =>
      formPropertyValue?.length && formPropertyValue instanceof Array
        ? formPropertyValue.map((valueData) => {
            if (formProperty === 'viewtype') {
              return GestureViewType.find((item) => item.value === valueData)?.title;
            }
            if (formProperty === 'gesture_type') {
              return gestureTypes(isWebSdk).find((item) => item.value === valueData)
                ?.title;
            }
            return valueData;
          })
        : [],
    [formProperty, formPropertyValue, isWebSdk]
  );

  // local state
  const [searchInput, setSearchInput] = useState('');

  // API call
  const { payload: viewNamePayload } = useGestureAttribute({
    attribute: formProperty,
    searchInput,
  });

  const { data: gesturePropertiesData, isLoading: loadingAPI } = useQuery(
    [`gesture-properties-values`, searchInput, formProperty, appId],
    () => FilterApi.getPropertiesWithCancelToken(viewNamePayload),
    {
      enabled: !isEmpty(formProperty) && shouldCallApi,
    }
  );

  const placeholderText = useMemo(() => {
    switch (formProperty) {
      case 'viewtype': {
        return 'Search UI element type';
      }
      case 'viewname': {
        return 'Search UI element name';
      }
      case 'viewid': {
        if ( isWebSdk ){
          return 'Search Element ID';
        }
        return 'Search UI element ID';
      }

      default: {
        return 'Search gesture type';
      }
    }
  }, [formProperty, isWebSdk]);

  const remoteData = useMemo(() => {
    switch (formProperty) {
      case 'viewtype': {
        const data = GestureViewType.filter((gesture) =>
          gesture?.title?.toLowerCase()?.includes(searchInput.toLowerCase())
        );
        return { data, isLoading: false };
      }
      case 'gesture_type': {
        const data = gestureTypes(isWebSdk).filter((gesture) =>
          gesture?.title?.toLowerCase()?.includes(searchInput.toLowerCase())
        );
        return { data, isLoading: false };
      }
      case 'viewname':
      case 'viewid': {
        const data = gesturePropertiesData?.data?.data.filter((item) =>
          item?.toLowerCase()?.includes(searchInput.toLowerCase())
        );
        return { data, isLoading: loadingAPI };
      }

      default: {
        return { data: [], isLoading: false };
      }
    }
  }, [
    formProperty,
    gesturePropertiesData?.data?.data,
    loadingAPI,
    searchInput,
    isWebSdk,
  ]);

  const [visible, setVisibleChange] = useState(false);
  const { isLoading, data: fetchedProperties } = useMemo(
    () => remoteData,
    [remoteData]
  );

  const fetchedPropertiesValues = useMemo(
    () =>
      visible &&
      bringSelectedItemsToTop(fetchedProperties, formPropertyValue, 'value'),
    [visible, fetchedProperties]
  );

  const handlePropertiesSelection = useCallback(
    (val) => {
      let selectedOptionsNew = [];
      if (formPropertyValue?.includes(val)) {
        selectedOptionsNew = formPropertyValue.filter((v) => v !== val);
      } else {
        selectedOptionsNew = [...formPropertyValue, val];
      }
      form.setFields([{ name, value: selectedOptionsNew }]);
      form.validateFields();
    },
    [formPropertyValue, form, name]
  );

  const handlePropertyValueInput = useCallback(
    (value) => {
      form.setFields([{ name, value }]);
      form.validateFields().then(() => {
        handleApply(value);
      });
    },
    [form, handleApply, name]
  );

  const renderView = useMemo(
    () => {
      let processedValues = fetchedPropertiesValues;

      if (processedValues?.length > 500 && !isObject(processedValues[0])) {
        processedValues = bringMissingItemsToTop(processedValues, formPropertyValue);
      }

      return(
      <ul>
        {!!processedValues?.length >= 1 ? (
          processedValues.map((data) => {
            const key = isObject(data) ? data?.value : data;
            const title = isObject(data) ? data?.title : data;
            return (
              <MenuListItem key={key}>
                <Checkbox
                  checked={
                    isArray(formPropertyValue) &&
                    formPropertyValue?.length &&
                    formPropertyValue?.includes(key)
                  }
                  onChange={() => handlePropertiesSelection(key)}
                >
                  <CellOverflowTooltip
                    width={195}
                    text={title}
                    value={title}
                    showTooltip
                  />
                </Checkbox>
              </MenuListItem>
            );
          })
        ) : (
          <NotFoundMessage>
            No matching gesture properties values found.
          </NotFoundMessage>
        )}
      </ul>
    )},
    [fetchedPropertiesValues, formPropertyValue, handlePropertiesSelection]
  );

  const onVisibleChange = useCallback(() => {
    setVisibleChange(!visible);
    if (!visible) {
      setSearchInput('');
    }
  }, [visible]);

  const propertiesValueMenu = (
    <Menu>
      <LoaderMenuItem spinning={isLoading}>
        <MenuItemGroupWrapper
          value={searchInput}
          placeholder={placeholderText}
          onChange={(e) => setSearchInput(e.target.value)}
        >
          {renderView}
        </MenuItemGroupWrapper>
      </LoaderMenuItem>
      <MenuButton key="button-bar">
        <Button
          type="primary-outline"
          onClick={() => {
            form.resetFields([`${name}`]);
            form.setFields([
              {
                name: ['gestureProperties', `${formDataIndex}`, 'value'],
                value: undefined,
              },
            ]);
          }}
        >
          Clear
        </Button>
        <Button
          disabled={!formPropertyValue?.length}
          type="primary"
          onClick={() => {
            handleApply();
            onVisibleChange();
          }}
        >
          Apply
        </Button>
      </MenuButton>
    </Menu>
  );

  useEffect(() => {
    const timer = setTimeout(() => {
      if (
        !['gesture_time_on_screenvisit', 'x_bin', 'y_bin'].includes(
          formProperty
        )
      ) {
        formPropertyValue?.length === 0 && setVisibleChange(true);
      }
    }, 500);

    return () => {
      clearInterval(timer);
    };
  }, [formPropertyValue, formProperty]);

  return arrayObj.includes(formOperatorValue) &&
    !['gesture_time_on_screenvisit', 'x_bin', 'y_bin'].includes(
      formProperty
    ) ? (
    <Dropdown
      overlay={propertiesValueMenu}
      overlayClassName="properties-segment-menu"
      onVisibleChange={(v) => {
        !v && handleApply();
        onVisibleChange(v);
      }}
      visible={visible}
      trigger={['click']}
    >
      <span className="filter-spacing">
        <a href="#!" onClick={(e) => e.preventDefault()}>
          <StyledSpace isBold={showOverflowItems(newPropertyValue)}>
            {showOverflowItems(newPropertyValue) || placeholderText}
          </StyledSpace>
        </a>
      </span>
    </Dropdown>
  ) : (
    <InputPropertiesValues
      option={formPropertyValue}
      placeholder="Enter value"
      suffix={
        ['gesture_time_on_screenvisit'].includes(formProperty) ? 'seconds' : ''
      }
      handlePropertyValueInput={handlePropertyValueInput}
      form={form}
      type={acceptsAllInput.includes(formProperty) ? undefined : 'number'}
    />
  );
};

export default memo(GestureValue);
